#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define structure for records
typedef struct {
    int value;
} Record;

// Initialize random number generator with custom seed
void init_random(int seed) {
    srand(seed);
}

// Generate a pseudo-random integer within the specified range
int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Create a new record with an initialized random value
Record* create_record(int min, int max) {
    Record* record = malloc(sizeof(Record));
    record->value = generate_random(min, max);
    return record;
}

// Delete a record and free its memory
void delete_record(Record* record) {
    free(record);
}

// Insert a new record into the collection
int insert_record(Record** records, int count, int min, int max) {
    Record* new_record = create_record(min, max);
    *records = realloc(*records, (count + 1) * sizeof(Record));
    (*records)[count] = *new_record;
    return count + 1;
}

// Delete a record from the collection
int delete_record_index(Record** records, int index) {
    if (index < 0 || index >= count) {
        return -1; // Invalid index
    }
    Record* temp = realloc(*records, (count - 1) * sizeof(Record));
    memmove(&temp[index], &temp[index + 1], (count - index - 1) * sizeof(Record));
    free(temp);
    return count - 1;
}

// Retrieve a record by its index
Record* get_record_by_index(Record** records, int index) {
    if (index < 0 || index >= count) {
        return NULL; // Invalid index
    }
    return &records[index];
}

// Perform batch operations on the collection
void batch_operation(Record** records, int operation, int min, int max) {
    switch (operation) {
        case INSERT:
            for (int i = 0; i < count; i++) {
                insert_record(records, i, min, max);
            }
            break;
        case DELETE:
            for (int i = 0; i < count; i++) {
                delete_record_index(records, i);
            }
            break;
    }
}

// Initialize the collection with random values and batch operations
void init_collection(Record** records, int count, int min, int max) {
    *records = malloc(count * sizeof(Record));
    for (int i = 0; i < count; i++) {
        (*records)[i] = create_record(min, max);
    }
}

// Validate the integrity of the data structures
void validate_collection(Record** records, int count) {
    if (count < 0) {
        printf("Invalid count: %d\n", count);
        return;
    }
    for (int i = 0; i < count; i++) {
        if ((*records)[i].value < min || (*records)[i].value > max) {
            printf("Invalid value at index %d: %d\n", i, (*records)[i].value);
            return;
        }
    }
}

// Define a lock for concurrent access
pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

// Perform concurrent batch operations on the collection
void* batch_operation_thread(void* arg) {
    int operation = *((int*)arg);
    Record** records = (Record**)pthread_getspecific(record_lock);
    if (operation == INSERT) {
        for (int i = 0; i < count; i++) {
            insert_record(records, i, min, max);
        }
    } else if (operation == DELETE) {
        for (int i = 0; i < count; i++) {
            delete_record_index(records, i);
        }
    }
}

// Start a new thread for concurrent batch operations
void start_batch_operation_thread(Record** records, int operation, int min, int max) {
    pthread_t thread;
    pthread_create(&thread, NULL, batch_operation_thread, &operation);
    pthread_setspecific(record_lock, (void*)records);
}

int main() {
    // Initialize the random number generator
    init_random(time(NULL));

    // Create a collection with initial records and batch operations
    Record* records = NULL;
    int count = 10;
    int min = 1;
    int max = 100;
    init_collection(&records, count, min, max);

    // Perform concurrent batch operations
    for (int i = 0; i < 5; i++) {
        start_batch_operation_thread(&records, INSERT, min, max);
        start_batch_operation_thread(&records, DELETE, min, max);
    }

    // Validate the integrity of the data structures
    validate_collection(&records, count);

    return 0;
}
