        // Parse the line to calculate the average of the last two numerical fields
        double avg = 0.0;
        int count = 0;
        char* token = strtok(line, ",");
        while (token) {
            if (sscanf(token, "%lf", &avg) == 1) {
                count++;
            }
            token = strtok(NULL, ",");
