#include <string.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* readIntegers() {
    Node* head = NULL;
    Node** tail = &head;

    int num;
    while (scanf("%d", &num) == 1) {
        if (num < -1000000 || num > 1000000) {
            fprintf(stderr, "Invalid integer %d. Skipping.\n", num);
            continue;
        }

        Node* newNode = (Node*) malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }

        newNode->data = num;
        newNode->next = *tail;
        *tail = newNode;
    }

    if (*tail == NULL) {
        printf("No valid integers provided.\n");
    } else {
        printf("Valid integers: ");
        Node* current = head;
        while (current != NULL) {
            printf("%d ", current->data);
            current = current->next;
        }
        printf("\n");
    }

    freeList(head);
    return head;
}

void freeList(Node* head) {
    Node* current = head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}
