#define MAX_LOG_LEVEL 100
#define LOG_FORMAT " [%d] %s: %s"

int log_error(int level, const char* file, int line, const char* fmt, ...) {
    static char buffer[1024];
    va_list ap;
    int len = snprintf(buffer, sizeof(buffer), LOG_FORMAT, level, file, __func__);

    va_start(ap, fmt);
    len += vsnprintf(buffer + len, sizeof(buffer) - len, fmt, ap);
    va_end(ap);

    printf("%s\n", buffer);

    return 0;
}

int main() {
    log_error(1, "main.c", __LINE__, "Error occurred: %s");

    for (int i = 0; i < MAX_LOG_LEVEL; i++) {
        log_error(i+1, "nested.c", __LINE__, "Nested error: %s", "test error");
    }

    return 0;
}
