// Define constants
#define AES_BLOCK_SIZE 16
#define PBKDF2_ITERATIONS 100000

// Structure to store encryption key and IV
typedef struct {
    unsigned char* key;
    unsigned char* iv;
    size_t key_len;
    size_t iv_len;
} EncryptionKey;

// Function to derive encryption key from password using PBKDF2
EncryptionKey* derive_key_from_password(const char* password, const char* salt, int salt_len) {
    // Create a new encryption key structure
    EncryptionKey* key = malloc(sizeof(EncryptionKey));

    // Derive the encryption key using PBKDF2
    unsigned char* derived_key = malloc(PBKDF2_KEYLEN);
    int rc = PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, salt_len, PBKDF2_ITERATIONS, 32, derived_key);

    // Extract the encryption key and IV from the derived key
    key->key = malloc(AES_BLOCK_SIZE);
    memcpy(key->key, &derived_key[0], AES_BLOCK_SIZE);
    key->key_len = AES_BLOCK_SIZE;
    key->iv = malloc(AES_BLOCK_SIZE);
    memcpy(key->iv, &derived_key[AES_BLOCK_SIZE], AES_BLOCK_SIZE);
    key->iv_len = AES_BLOCK_SIZE;

    // Free the derived key
    free(derived_key);

    return key;
}

// Function to encrypt file using AES-256-CBC
int encrypt_file(const char* input_file, const EncryptionKey* encryption_key, const char* output_file) {
    // Open the input and output files
    FILE* in = fopen(input_file, "rb");
    FILE* out = fopen(output_file, "wb");

    // Check if files were opened successfully
    if (!in || !out) {
        return -1;
    }

    // Read the file in chunks to avoid memory issues
    unsigned char buffer[AES_BLOCK_SIZE];
    while (fread(buffer, 1, AES_BLOCK_SIZE, in) > 0) {
        // Encrypt the chunk using AES-256-CBC
        unsigned char* encrypted = malloc(AES_BLOCK_SIZE);
        int rc = aes_cbc_encrypt(buffer, encrypted, AES_BLOCK_SIZE, encryption_key->key, encryption_key->iv);

        // Write the encrypted chunk to the output file
        fwrite(encrypted, 1, AES_BLOCK_SIZE, out);

        // Free the encrypted buffer
        free(encrypted);
    }

    // Close the files
    fclose(in);
    fclose(out);

    return 0;
}

// Function to decrypt file using AES-256-CBC
int decrypt_file(const char* input_file, const EncryptionKey* encryption_key, const char* output_file) {
    // Open the input and output files
    FILE* in = fopen(input_file, "rb");
    FILE* out = fopen(output_file, "wb");

    // Check if files were opened successfully
    if (!in || !out) {
        return -1;
    }

    // Read the file in chunks to avoid memory issues
    unsigned char buffer[AES_BLOCK_SIZE];
    while (fread(buffer, 1, AES_BLOCK_SIZE, in) > 0) {
        // Decrypt the chunk using AES-256-CBC
        unsigned char* decrypted = malloc(AES_BLOCK_SIZE);
        int rc = aes_cbc_decrypt(buffer, decrypted, AES_BLOCK_SIZE, encryption_key->key, encryption_key->iv);

        // Write the decrypted chunk to the output file
        fwrite(decrypted, 1, AES_BLOCK_SIZE, out);

        // Free the decrypted buffer
        free(decrypted);
    }

    // Close the files
    fclose(in);
    fclose(out);

    return 0;
}

int main() {
    // Example usage: derive key from password and encrypt/decrypt a file
    const char* password = "my_secret_password";
    const char* salt = "my_salt_string";
    int salt_len = strlen(salt);

    EncryptionKey* encryption_key = derive_key_from_password(password, salt, salt_len);

    const char* input_file = "example_input.txt";
    const char* output_file = "encrypted_example_output.txt";

    encrypt_file(input_file, encryption_key, output_file);

    // Example usage: decrypt the file
    const char* decrypted_file = "decrypted_example_output.txt";
    decrypt_file(output_file, encryption_key, decrypted_file);

    // Free the encryption key
    free(encryption_key->key);
    free(encryption_key->iv);
    free(encryption_key);

    return 0;
}
