void print_list(Node *list);

// Configuration option to prioritize specific algorithms
char *preferred_algorithms[] = {"SHA256", "AES"};

Node *init_list(void) {
    // Initialize the head of the linked list
    Node *head = NULL;
    return head;
}

int is_available(const char *algorithm_name, int *parameters) {
    // System probing mechanism to detect availability of algorithm on target system
    // For demonstration purposes only; replace with actual code for your system
    if (strcmp(algorithm_name, "SHA256") == 0)
        return 1;
    else if (strcmp(algorithm_name, "AES") == 0)
        return 1;
    else
        return 0;
}

Algorithm *get_algorithm(const char *algorithm_name, int *parameters) {
    // Implementation function pointers for each algorithm
    Algorithm *algorithms[] = {
        {"SHA256", &hash_sha256, 1},
        {"AES", &cipher_aes, 2},
        // Add more algorithms as needed
    };

    for (int i = 0; i < sizeof(algorithms) / sizeof(Algorithm); i++) {
        if (strcmp(algorithm_name, algorithms[i]->name) == 0)
            return algorithms[i];
    }

    return NULL;
}

void unload_algorithm(Node **head_ref, const char *name) {
    // Unload a specific algorithm when it is no longer needed
    Node *current = *head_ref;
    Node *prev = NULL;

    while (current != NULL && strcmp(current->algorithm->name, name) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL)
        return;

    if (prev == NULL)
        *head_ref = current->next;
    else
        prev->next = current->next;

    free(current);
}

void add_to_list(Node **head_ref, Algorithm *algorithm) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->algorithm = algorithm;
    new_node->next = (*head_ref);

    if (*head_ref == NULL)
        *head_ref = new_node;
    else {
        Node *current = *head_ref;

        while (current->next != NULL) {
            current = current->next;
        }

        current->next = new_node;
    }
}

void print_list(Node *list) {
    // Print the linked list for demonstration purposes only
    printf("Available algorithms:\n");

    Node *node = list;
    while (node != NULL) {
        printf("%s\n", node->algorithm->name);
        node = node->next;
    }
}

int main(void) {
    // Initialize the head of the linked list
    Node *head = init_list();

    Algorithm *algorithms[] = {
        {"SHA256", &hash_sha256, 1},
        {"AES", &cipher_aes, 2},
        // Add more algorithms as needed
    };

    for (int i = 0; i < sizeof(algorithms) / sizeof(Algorithm); i++) {
        if (!is_available(algorithms[i]->name, &(algorithms[i]->parameters)))
            continue;

        add_to_list(&head, algorithms[i]);
    }

    // Prioritize the preferred algorithms
    for (int i = 0; i < sizeof(preferred_algorithms) / sizeof(char *); i++) {
        Algorithm *algorithm = get_algorithm(preferred_algorithms[i], NULL);
        if (algorithm != NULL)
            add_to_list(&head, algorithm);
    }

    print_list(head);

    // Unload a specific algorithm when it is no longer needed
    unload_algorithm(&head, "AES");

    return 0;
}
