Session *initialize_session(const char *config_file_path, int protocol_version,
                              char *cipher_suite, char *key_exchange_method,
                              int num_command_line_options) {
    Session *session = (Session *)malloc(sizeof(struct Session));
    session->initialized = 0;

    // Initialize OpenSSL engine
    if (!ENGINE_init_all()) {
        free(session);
        return NULL;
    }

    // Load configuration file
    FILE *config_file = fopen(config_file_path, "r");
    if (!config_file) {
        ENGINE_free_all();
        free(session);
        return NULL;
    }
    fclose(config_file);

    session->version = protocol_version;
    session->cipher_suite = cipher_suite;
    session->key_exchange_method = key_exchange_method;

    // Initialize authentication service
    session->auth_service_handle = authenticate_service_init(num_command_line_options);
    if (!session->auth_service_handle) {
        ENGINE_free_all();
        free(session);
        return NULL;
    }

    // Initialize session state
    session->initialized = 1;

    return session;
}
