#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure to represent a semaphore pool
typedef struct {
    sem_t **semaphores;
    int size;
    int max_size;
} semaphore_pool;

// Function to create a new semaphore pool with the given initial and maximum sizes
semaphore_pool *create_semaphore_pool(int initial_size, int max_size);

// Function to add a new semaphore to the existing pool and resize it if necessary
void add_semaphore(semaphore_pool *pool, int size);

// Function to remove a semaphore from the pool and recycle resources if possible
void remove_semaphore(semaphore_pool *pool);

// Function to log semaphore usage for performance analysis and debugging purposes
void log_semaphore_usage(semaphore_pool *pool);

// Function to manage the semaphore pool and handle multiple threads safely
semaphore_pool *manage_semaphore_pool(int initial_size, int max_size);

int main() {
    // Example usage of the function
    int initial_size = 5;
    int max_size = 10;

    semaphore_pool *pool = manage_semaphore_pool(initial_size, max_size);

    // Use the pool to create and manipulate semaphores
    add_semaphore(pool, 3);
    log_semaphore_usage(pool);
    remove_semaphore(pool);

    // Clean up when done
    for (int i = 0; i < pool->size; i++) {
        sem_close(pool->semaphores[i]);
    }
    free(pool->semaphores);
    free(pool);

    return 0;
}

semaphore_pool *create_semaphore_pool(int initial_size, int max_size) {
    semaphore_pool *pool = malloc(sizeof(semaphore_pool));
    pool->size = initial_size;
    pool->max_size = max_size;

    pool->semaphores = malloc(initial_size * sizeof(sem_t *));
    for (int i = 0; i < initial_size; i++) {
        pool->semaphores[i] = sem_open("/my_semaphore", O_CREAT, SEMAPHORE_PERMISSIONS, 1);
    }

    return pool;
}

void add_semaphore(semaphore_pool *pool, int size) {
    if (pool->size + size > pool->max_size) {
        // Resize the pool if necessary
        int new_max_size = pool->size + size;
        pool->semaphores = realloc(pool->semaphores, new_max_size * sizeof(sem_t *));
        for (int i = pool->size; i < new_max_size; i++) {
            pool->semaphores[i] = sem_open("/my_semaphore", O_CREAT, SEMAPHORE_PERMISSIONS, 1);
        }
        pool->max_size = new_max_size;
    }

    for (int i = 0; i < size; i++) {
        // Add the new semaphore to the pool
        pool->semaphores[pool->size + i] = sem_open("/my_semaphore", O_CREAT, SEMAPHORE_PERMISSIONS, 1);
    }
    pool->size += size;
}

void remove_semaphore(semaphore_pool *pool) {
    if (pool->size > initial_size) {
        // Remove the last semaphore from the pool
        int size = pool->size - 1;
        for (int i = 0; i < size; i++) {
            sem_close(pool->semaphores[i]);
        }
        free(pool->semaphores);
        pool->semaphores = malloc(size * sizeof(sem_t *));
        pool->semaphores[pool->size - 1] = sem_open("/my_semaphore", O_CREAT, SEMAPHORE_PERMISSIONS, 1);
        pool->size = size;
    }
}

void log_semaphore_usage(semaphore_pool *pool) {
    // Log the current semaphore usage for performance analysis and debugging purposes
    printf("Semaphore usage: %d of %d\n", pool->size, pool->max_size);
}

semaphore_pool *manage_semaphore_pool(int initial_size, int max_size) {
    return create_semaphore_pool(initial_size, max_size);
}
