void insertOrAppend(std::vector<int>& vec, int target, int value) {
    std::vector<int> copiedVec = vec; // deep copy
    auto it = std::find(copiedVec.begin(), copiedVec.end(), target);
    if (it != copiedVec.end()) {
        copiedVec.insert(it + 1, value); // insert after the first occurrence of target
    } else {
        copiedVec.push_back(value); // append to the end of the vector
    }
