    beast::http::server srv(ioc, 8080);

    // Define endpoint handlers
    srv.get("/stats", [ioc](beast::http::request<> req, beast::http::response<> res) {
        // Get stats and logs from internal storage
        auto stats = get_stats();
        auto logs = get_logs();

        // Prepare response
        res.body = "Statistics: " + std::to_string(stats) + "\nLogs:\n" + logs;
        res.status_code = 200;
    });

    srv.post("/log", [ioc](beast::http::request<> req, beast::http::response<> res) {
        // Handle log post request
        auto data = req.body();
        process_log(data);

        // Prepare response
        res.body = "Log processed successfully";
        res.status_code = 201;
    });

    // Start server and listen for incoming connections
