#include <iostream>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <queue>
#include <string>
#include <fstream>

namespace Logging {

class Logger {
public:
    Logger(const std::string& filePath, size_t maxSize, int retention);
    ~Logger();
    Logger(Logger&& other);
    Logger& operator=(Logger&& other);

    void log(int level, const std::string& message);

private:
    class LogEntry {
    public:
        int level;
        std::string message;

        LogEntry(int level, const std::string& message) : level(level), message(message) {}
    };

    struct LogQueue {
        std::queue<LogEntry> entries;
        mutable std::mutex mutex;
        std::condition_variable cv;
    } logQueue;

    static std::atomic<size_t> fileIndex;
    size_t currentFileIndex = 0;
    size_t fileSize = 0;
    std::string filePath;
    int retention;
    std::ofstream currentLogFile;
};

} // namespace Logging

size_t Logging::Logger::fileIndex = 1;

Logging::Logger::Logger(const std::string& filePath, size_t maxSize, int retention)
    : filePath(filePath), retention(retention) {
    this->retention = retention;
    if (!currentLogFile.is_open()) {
        currentLogFile.open((filePath + ".log").c_str(), std::ios::app);
    }
}

Logging::Logger::~Logger() {
    closeFile();
}

Logging::Logger::Logger(Logger&& other)
    : filePath(std::move(other.filePath)), retention(std::move(other.retention)) {
    if (other.currentLogFile.is_open()) {
        this->currentLogFile = std::move(other.currentLogFile);
    }
}

Logging::Logger& Logging::Logger::operator=(Logger&& other) {
    filePath = std::move(other.filePath);
    retention = std::move(other.retention);
    closeFile();
    currentLogFile.close();
    if (other.currentLogFile.is_open()) {
        this->currentLogFile = std::move(other.currentLogFile);
    }
    return *this;
}

void Logging::Logger::log(int level, const std::string& message) {
    LogEntry entry(level, message);
    {
        std::unique_lock<std::mutex> lock(logQueue.mutex);
        logQueue.entries.push(entry);
    }
    cv.notify_one();
}

