using System;
using System.Collections.Generic;
using System.Threading;
using System.Net.Http;
using System.Linq;

public class HttpRequestSummary
{
    public List<HttpResponse> Responses { get; set; } = new List<HttpResponse>();
}

public class HttpResponse
{
    public string Url { get; set; }
    public HttpStatusCode StatusCode { get; set; }
    public Exception Error { get; set; }
}

public async Task<HttpRequestSummary> ProcessHttpRequestBatchAsync(
    IEnumerable<string> urls,
    TimeSpan timeout,
    HttpClient httpClient,
    CancellationToken cancellationToken)
{
    var summary = new HttpRequestSummary();
    var retryCount = 0;

    foreach (var url in urls)
    {
        while (true)
        {
            try
            {
                using (var request = new HttpRequestMessage(HttpMethod.Get, url))
                {
                    using (var response = await httpClient.SendAsync(request, timeout, cancellationToken))
                    {
                        if (response.IsSuccessStatusCode)
                        {
                            summary.Responses.Add(new HttpResponse { Url = url, StatusCode = response.StatusCode });
                        }
                        else
                        {
                            summary.Responses.Add(new HttpResponse { Url = url, StatusCode = response.StatusCode });
                        }

                        break;
                    }
                }
            }
            catch (HttpRequestException e) when (!cancellationToken.IsCancellationRequested)
            {
                if (++retryCount < 3)
                {
                    await Task.Delay(TimeSpan.FromMilliseconds(200 * (int)Math.Pow(2, retryCount)), cancellationToken);
                }
                else
                {
                    throw new Exception($"Failed to process {url}: {e.Message}");
                }
            }
        }
    }

    return summary;
}
