namespace SmartBuildingSystem
{
    public class WeatherDataRetriever
    {
        private readonly HttpClient _httpClient;
        private readonly IMemoryCache _cache;
        private readonly string[] _apiEndpoints = new[]
        {
            "https://weather-api.com/data",
            "https://enviro-api.com/realtime",
            "https://energy-api.com/consumption"
        };

        public WeatherDataRetriever(HttpClient httpClient, IMemoryCache cache)
        {
            _httpClient = httpClient;
            _cache = cache;
        }

        public async Task<WeatherData> GetWeatherDataAsync()
        {
            string cachedData = await _cache.GetString("weather-data");
            if (!string.IsNullOrEmpty(cachedData))
                return JsonConvert.DeserializeObject<WeatherData>(cachedData);

            WeatherData weatherData = null;

            foreach (string endpoint in _apiEndpoints)
            {
                try
                {
                    HttpResponseMessage response = await _httpClient.GetAsync(endpoint);
                    response.EnsureSuccessStatusCode();
                    string data = await response.Content.ReadAsStringAsync();

                    if (!string.IsNullOrEmpty(data))
                    {
                        weatherData = JsonConvert.DeserializeObject<WeatherData>(data);

                        // caching strategy: cache for 1 minute, refresh every 5 minutes
                        _cache.Set("weather-data", JsonConvert.SerializeObject(weatherData), new MemoryCacheEntryOptions()
                        {
                            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(1)
                        });
                    }
                }
                catch (HttpRequestException ex)
                {
                    // fallback mechanism: use a secondary API or cached data if available
                    if (_cache.TryGetValue("weather-data-fallback", out string fallbackData))
                    {
                        weatherData = JsonConvert.DeserializeObject<WeatherData>(fallbackData);
                    }
                    else
                    {
                        throw new Exception($"Failed to retrieve weather data from {_apiEndpoints[0]}: {ex.Message}");
                    }
                }
            }

            return weatherData;
        }
    }

    public class WeatherData
    {
        public string Temperature { get; set; }
        public string Humidity { get; set; }
        public string EnergyConsumption { get; set; }
    }
}
