import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

public class MD5HashGenerator {

    private static final int MAX_RETRIES = 3;
    private static final long TIMEOUT_MILLISECONDS = 5000; // 5 seconds
    private static final Pattern VALIDATION_PATTERN = Pattern.compile("^[a-zA-Z0-9_\\s]+$");

    public Map<String, String> generateMD5Hashes(List<String> inputStrings) {
        ConcurrentHashMap<String, String> result = new ConcurrentHashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(5); // adjust thread pool size as needed

        for (String input : inputStrings) {
            Future<Map.Entry<String, String>> future = executor.submit(() -> processInput(input));
            try {
                Map.Entry<String, String> entry = future.get(TIMEOUT_MILLISECONDS, TimeUnit.MILLISECONDS);
                if (entry != null) {
                    result.put(entry.getKey(), entry.getValue());
                }
            } catch (InterruptedException | ExecutionException e) {
                return generateTimeoutStatusMessage();
            }
        }

        executor.shutdown();
        return result;
    }

    private Map.Entry<String, String> processInput(String input) {
        if (!isValid(input)) {
            return null; // skip invalid inputs
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : bytes) {
                String.toHexString(Byte.toBytes(b)).toUpperCase().substring(0, 2).replaceFirst("(?!^)(?=.*)".toString(), ".");
                hexString.append(String.format("%02x", b));
            }
            return Map.entry(input, hexString.toString());
        } catch (NoSuchAlgorithmException e) {
            // handle error
        }

        return null;
    }

    private boolean isValid(String input) {
        return VALIDATION_PATTERN.matcher(input).matches();
    }

    private Map<String, String> generateTimeoutStatusMessage() {
        return new ConcurrentHashMap<>(Map.of("status", "TIMEOUT"));
    }
}
