const fs = require('fs');
const path = require('path');

function readDirectory(directoryPath) {
  return new Promise((resolve, reject) => {
    const summary = {};
    let totalSize = 0;

    fs.readdir(directoryPath, (err, files) => {
      if (err) {
        reject(err);
      } else {
        files.forEach(file => {
          const filePath = path.join(directoryPath, file);
          fs.stat(filePath, (err, stats) => {
            if (err) {
              // Handle missing or non-existent files
              summary[file] = { size: 0 };
            } else {
              const fileSize = stats.size;
              totalSize += fileSize;

              fs.createReadStream(filePath)
                .pipe(fs.readFileSync(0, 'utf8'))
                .on('data', chunk => {
                  const fileSummary = {};
                  fileSummary.size = fileSize;
                  fileSummary.content = chunk.toString();
                  summary[file] = fileSummary;
                })
                .on('error', err => {
                  reject(err);
                })
                .on('end', () => {
                  resolve({ summary, totalSize });
                });
            }
          });
        });
      }
    });
  });
}

module.exports = readDirectory;
