import re
from collections import defaultdict
from typing import Dict

def process_reviews(reviews: list) -> Dict[str, Dict]:
    category_map = {
        r'\b(product quality|high-quality product|good product)\b': 'Product Quality',
        r'\bcustomer (service|support|help)\b': 'Customer Service',
        r'\bshipping speed|quick shipping|fast delivery\b': 'Shipping Speed',
    }

    feature_map = defaultdict(dict)

    for review in reviews:
        categories = {}
        for pattern, category in category_map.items():
            matches = re.findall(pattern, review.lower())
            if matches:
                features = set()
                for match in matches:
                    if match.startswith('product quality'):
                        features.update(['quality', 'high-quality', 'good'])
                    elif match == 'customer service':
                        features.update(['service', 'support', 'help'])
                    else:
                        features.add(match.split()[-1])
                categories[category] = {feature: 1 for feature in features}

        if categories:
            category_report = defaultdict(int)
            for category, features in categories.items():
                for feature, _ in features.items():
                    category_report[category].update(features)

            return {**category_map, **{'Uncategorized': set(), 'Total': set()}, **category_report}

    return {'No Reviews Processed': []}
