function aggregateData(chunks, limit) {
  const buffers = [];
  let totalSize = 0;

  for (const chunk of chunks) {
    if (!chunk.includes(metadataMarker)) continue; // skip metadata marker

    while (totalSize + chunk.length > limit) {
      const diff = limit - totalSize;
      const leftChunk = chunk.slice(0, diff);
      buffers.push(leftChunk);
      totalSize += leftChunk.length;
      chunk = chunk.slice(diff);
    }

    buffers.push(chunk);
    totalSize += chunk.length;
  }

  return Buffer.concat(buffers).slice(0, buffers.reduce((acc, buf) => acc + buf.length, 0));
}
