function traverseDOM(selector) {
  return new Promise((resolve, reject) => {
    const elements = [];
    (function recursiveTraversal(node) {
      if (!node) return;
      Array.from(node.querySelectorAll(selector)).forEach((element) => {
        elements.push(element);
        recursiveTraversal(element);
      });
    })(document);

    // Handle concurrent changes to the DOM
    function handleDOMChanges() {
      const MutationObserver = window.MutationObserver;
      new MutationObserver(() => {
        recursiveTraversal(document);
      }).observe(document, { childList: true, subtree: true });

      // Remove observer when done
      setTimeout(() => {
        document.removeEventListener("DOMContentLoaded", handleDOMChanges, false);
      }, 0);

      // Observe the DOM for changes and re-run the traversal if necessary
      document.addEventListener("DOMContentLoaded", handleDOMChanges, false);
    }

    // Fetch metadata from an external API (e.g., asynchronous)
    async function fetchMetadata() {
      try {
        const response = await fetch('https://api.example.com/metadata');
        const data = await response.json();
        elements.forEach((element) => {
          element.metadata = data[element.id];
        });
      } catch (error) {
        reject(error);
      }
    }

    // Start the traversal and metadata fetching
    recursiveTraversal(document);
    fetchMetadata().then(() => resolve(elements)).catch(reject);
  });
}
