class FileManager {
  constructor() {
    this.filenames = new Map();
    this.dependencies = new Map();
    this.fileLoaders = [];
    this.loggers = [];
  }

  addFileLoader(loader) {
    this.fileLoaders.push(loader);
  }

  addLogger(logger) {
    this.loggers.push(logger);
  }

  registerFile(filename, dependencies = []) {
    this.filenames.set(filename, { file: null, loaded: false });
    this.dependencies.set(filename, dependencies);
  }

  loadFile(filename, callback) {
    if (!this.filenames.has(filename)) {
      console.error(`Unknown file: ${filename}`);
      return;
    }
    const file = this.filenames.get(filename).file;
    if (file) {
      callback(file);
    } else {
      this.fileLoaders.forEach(loader => loader.loadFile(filename, file => {
        this.filenames.get(filename).file = file;
        this.filenames.get(filename).loaded = true;
        callback(file);
      }));
    }
  }

  async loadFiles() {
    const promises = [];
    for (const filename of this.filenames.keys()) {
      promises.push(this.loadFile(filename, file => console.log(`Loaded ${filename}`)));
    }
    await Promise.all(promises);
  }

  handleDependencies(filename) {
    if (!this.filenames.has(filename)) {
      return;
    }
    const dependencies = this.dependencies.get(filename);
    for (const dependency of dependencies) {
      if (!this.filenames.has(dependency)) {
        console.error(`Unknown file: ${dependency}`);
      } else {
        if (!this.filenames.get(dependency).loaded) {
          await this.loadFile(dependency, () => {});
        }
      }
    }
  }

  logEvent(eventType, filename = '') {
    for (const logger of this.loggers) {
      logger.log(eventType, filename);
    }
  }
}
