        for (String filePath : filePaths) {
            try {
                File file = new File(filePath);
                String dirPath = getDirPath(file);

                if (!uniqueDirs.add(dirPath)) {
                    logTimeTaken("Duplicate directory found: " + dirPath);
                }
            } catch (Exception e) {
                logTimeTaken("Error processing path: " + filePath, e);
            }
