public class ThemeCacheManager {
    private Map<String, Bitmap> themeBitmaps;
    private CacheStorage cacheStorage;
    private int cacheSizeThreshold;

    public ThemeCacheManager(int cacheSizeThreshold) {
        this.themeBitmaps = new HashMap<>();
        this.cacheStorage = new ExternalCacheStorage();
        this.cacheSizeThreshold = cacheSizeThreshold;
    }

    public void putTheme(String themeId, Bitmap bitmap) {
        if (themeBitmaps.containsKey(themeId)) {
            themeBitmaps.remove(themeId);
        }
        themeBitmaps.put(themeId, bitmap);
    }

    public Bitmap getTheme(String themeId) {
        return themeBitmaps.getOrDefault(themeId, null);
    }

    public void evictOldThemes() {
        List<String> outdatedThemes = new ArrayList<>();
        for (Map.Entry<String, Bitmap> entry : themeBitmaps.entrySet()) {
            if (!cacheStorage.contains(entry.getKey())) {
                outdatedThemes.add(entry.getKey());
            }
        }
        for (String themeId : outdatedThemes) {
            themeBitmaps.remove(themeId);
        }
    }

    public void clearCache() {
        themeBitmaps.clear();
    }

    private class ExternalCacheStorage implements CacheStorage {
        @Override
        public boolean contains(String key) {
            // Implement external storage retrieval logic here
        }
    }

    interface CacheStorage {
        boolean contains(String key);
    }

    public void logPerformanceMetrics() {
        // Log cache size, theme count, and any other relevant metrics
    }
}

public class ThemeBitmapRecycler {
    private Map<Bitmap, Integer> bitmapCounts;

    public ThemeBitmapRecycler() {
        this.bitmapCounts = new HashMap<>();
    }

    public void recycle(Bitmap bitmap) {
        int count = bitmapCounts.getOrDefault(bitmap, 0);
        bitmapCounts.put(bitmap, count + 1);
    }

    public void reset(Bitmap bitmap) {
        bitmapCounts.remove(bitmap);
