<?php

class Configurator {
    private $configDir;
    private $cache;
    private $autoloader;
    private $logger;

    public function __construct($configDir) {
        $this->configDir = $configDir;
        $this->cache = new \Doctrine\Common\Cache\FilesystemCache();
        $this->autoloader = require_once __DIR__ . '/vendor/autoload.php';
        $this->logger = new \Monolog\Logger('Configurator');
    }

    public function configure() {
        // Detect current environment
        $environment = $this->detectEnvironment();

        // Load configuration files
        $configFiles = $this->loadConfigFiles($environment);

        // Set up autoloader
        $this->setupAutoloader();

        // Set up logging
        $this->setupLogging($environment);

        // Cache configurations
        $this->cacheConfigurations($configFiles);

        // Monitor configuration directory for changes
        $this->monitorConfigDir();
    }

    private function detectEnvironment() {
        if (isset($_ENV['APP_ENV'])) {
            return $_ENV['APP_ENV'];
        } elseif (file_exists(__DIR__ . '/.env')) {
            return 'development';
        } else {
            return 'production';
        }
    }

    private function loadConfigFiles($environment) {
        $configFiles = [];

        foreach (glob("{$this->configDir}/{$environment}/*.php") as $file) {
            if (!in_array($file, $configFiles)) {
                require_once $file;
                $configFiles[] = $file;
            }
        }

        return $configFiles;
    }

    private function setupAutoloader() {
        spl_autoload_register(function ($class) {
            $this->autoloader->loadClass($class);
        });
    }

    private function setupLogging($environment) {
        // Configure logging levels based on environment
        if ($environment == 'production') {
            $this->logger->setLevel(\Monolog\Logger::WARNING);
        } elseif ($environment == 'testing') {
            $this->logger->setLevel(\Monolog\Logger::ERROR);
        }
    }

    private function cacheConfigurations($configFiles) {
        // Cache configuration values
        foreach ($configFiles as $file) {
            $config = require_once $file;
            $this->cache->save('config_' . basename($file), serialize($config));
        }
    }

    private function monitorConfigDir() {
        if (!inotify_init(1)) {
            $this->logger->error("Failed to initialize inotify");
        } else {
            inotify_add_watch(inotify_init(), $this->configDir, IN_MODIFY);
        }
    }
}
