['```rust
use tokio::sync::{mpsc, oneshot};
use std::collections::HashMap;
use hyper::Client;

struct HttpClientPool {
    clients: HashMap<String, Client>,
}

impl HttpClientPool {
    async fn new(endpoints: Vec<String>) -> Self {
        let mut pool = Self { clients: HashMap::new() };
        for endpoint in endpoints {
            pool.clients.insert(endpoint.clone(), Client::new());
        }
        pool
    }

    async fn get_client(&mut self, endpoint: &str) -> Option<&Client> {
        self.clients.get(endpoint)
    }

    async fn send_request(
        &mut self,
        request: String,
        endpoint: &str,
    ) -> oneshot::Receiver<String> {
        let (tx, rx) = oneshot::channel();
        match self.get_client(endpoint).await {
            Some(client) => {
                client.request()
                    .post("http://example.com".parse().unwrap())
                    .header("Content-Type", "application/json")
                    .body(request.clone())
                    .send()
                    .await
                    .map(|res| res.text().unwrap_or_default())
                    .map_err(|err| err.to_string())
                    .into_parts()
                    .flatten()
                    .unwrap_or(tx.send("Request failed".to_string()))
                    .map(|result| tx.send(result)),
            None => {
                tx.send(format!("No client available for endpoint {}", endpoint)).await
            }
        };
        rx
    }
}

async fn process_request(
    pool: &mut HttpClientPool,
    request: String,
    endpoint: &str,
) -> oneshot::Receiver<String> {
    let (tx, rx) = oneshot::channel();
    match pool.send_request(request.clone(), endpoint).await {
        Ok(res) => res.then(|result| tx.send(result)).await,
        Err(err) => tx.send(format!("Error sending request: {}", err)).await,
    };
    rx
}

#[tokio::main]
async fn main() {
    let mut pool = HttpClientPool::new(vec!["http://endpoint1.com".to_string(), "http://endpoint2.com".to_string()]).await;
    for _ in 0..1000 {
        let request = "Hello, World!".to_string();
        let (tx, rx) = oneshot::channel();
        process_request(&mut pool, request, "http://endpoint1.com").await.unwrap_or(tx.send("Request failed".to_string()));
    }
}
