<?php

function generateRandomStringHash($length, $characterSet, $outputFormat) {
    if (!is_int($length) || $length <= 0) {
        return array(
            'error' => 'Length must be a positive integer.'
        );
    }
    if (!is_string($characterSet)) {
        return array(
            'error' => 'Character set must be a string.'
        );
    }
    if (!in_array($outputFormat, array('string', 'hex'))) {
        return array(
            'error' => 'Output format must be either "string" or "hex".'
        );
    }

    $randomString = substr(str_shuffle(str_repeat($characterSet, ceil($length / strlen($characterSet)))), 1, $length);
    $hashedString = hash('sha256', $randomString);

    if ($outputFormat == 'hex') {
        $hashedString = bin2hex($hashedString);
    }

    $uniqueIdentifier = microtime() . '-' . uniqid() . '-' . $randomString;
    return array(
        'randomString' => $randomString,
        'hashedString' => $hashedString,
        'uniqueIdentifier' => $uniqueIdentifier
    );
}

function readFileSync($filePath) {
    if (!is_string($filePath)) {
        throw new Exception('File path must be a string.');
    }

    try {
        $fileContent = file_get_contents($filePath);
        return $fileContent;
    } catch (Exception $e) {
        return array(
            'error' => 'An error occurred while reading the file: ' . $e->getMessage()
        );
    }
}

