<?php

function authenticateUser($clientId, $clientSecret, $redirectUri) {
    // Initialize OAuth 2.0 client
    $oauthClient = new GuzzleHttp\Client([
        'base_uri' => 'https://example.com/oauth/',
        'auth' => ['Bearer', $clientSecret]
    ]);

    // Get authorization code
    $authorizationCode = $_GET['code'];

    // Exchange authorization code for access token
    $response = $oauthClient->post('token', [
        'form_params' => [
            'grant_type' => 'authorization_code',
            'code' => $authorizationCode,
            'redirect_uri' => $redirectUri
        ]
    ]);

    // Get access token
    $accessToken = json_decode($response->getBody()->getContents(), true)['access_token'];

    // Store access token securely in session variable
    $_SESSION['access_token'] = $accessToken;

    // Retrieve user information using access token
    $userInfoResponse = $oauthClient->get('userinfo', [
        'headers' => ['Authorization' => 'Bearer ' . $accessToken]
    ]);

    // Get user information
    $userInfo = json_decode($userInfoResponse->getBody()->getContents(), true);

    // Limit function capabilities to prevent unauthorized access
    if (!isset($_SESSION['access_token']) || $_SESSION['access_token'] !== $accessToken) {
        return false;
    }

    return $userInfo;
}

