#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <arpa/inet.h>

u_char* dnsResolution(char* hostname, int* ipLength) {
    // Initialize DNS resolver structure
    struct hostent *he = gethostbyname(hostname);
    if (!he) {
        // Handle error
        return NULL;
    }

    // Get IP address from DNS response
    char* ipAddress = inet_ntoa(*((struct in_addr*)he->h_addr));
    int ipLengthVal = strlen(ipAddress);

    // Allocate memory for IP address array
    u_char* result = (u_char*)malloc(ipLengthVal + 1);
    memcpy(result, ipAddress, ipLengthVal);
    result[ipLengthVal] = '\0';

    *ipLength = ipLengthVal;

    return result;
}

int main() {
    // Example usage
    char* hostname = "example.com";
    int ipLength;
    u_char* ipAddress = dnsResolution(hostname, &ipLength);

    if (ipAddress) {
        printf("IP address: %s\n", ipAddress);
        free(ipAddress);
    } else {
        printf("Error: Unable to resolve DNS\n");
    }

    return 0;
}

