#include <stdlib.h>
#include <stdio.h>

struct State {
    int id;
    struct State* next;
};

struct FSA {
    int current_state;
    int num_states;
    struct State** states;
};

struct FSAStateList {
    struct State* head;
    int size;
};

void manage_state_list(struct FSA* fsa, int num_initial_states, int last_state) {
    // Check if there is insufficient memory
    if (num_initial_states > 0 && last_state < 0) {
        return;
    }

    // Create a new state list
    struct FSAStateList* new_list = (struct FSAStateList*)malloc(sizeof(struct FSAStateList));
    if (!new_list) {
        return;
    }

    new_list->head = NULL;
    new_list->size = 0;

    // Update the 'next' pointer of the last state in the list
    fsa->states[last_state].next = (struct State*)new_list;

    // Return the newly created state list or NULL if there is insufficient memory
    return new_list;
}

