class CharacterAttackManager {
public:
    enum AttackType { SimpleAttack, ComplexAttack };

    void setAttackPriority(AttackType type, int priority) {
        attackPriorities[static_cast<int>(type)] = priority;
    }

    void performAttack() {
        std::queue<std::pair<AttackType, std::chrono::time_point<std::chrono::steady_clock>>> available Attacks;

        // Update cooldown timers
        for (const auto& [type, cooldownTime] : cooldownTimers) {
            if (cooldownTime < std::chrono::steady_clock::now()) {
                availableAttacks.push({ type, cooldownTime });
            }
        }

        // Prioritize attacks based on priority levels and enemy AI difficulty level
        int enemyAIDifficulty = getEnemyAIDifficulty();
        AttackType selectedAttack;

        while (!availableAttacks.empty()) {
            const auto& [attackType, _] = availableAttacks.front();
            if (attackPriorities[static_cast<int>(attackType)] >= enemyAIDifficulty) {
                selectedAttack = attackType;
                break;
            }
            availableAttacks.pop();
        }

        // Perform the selected attack
        if (selectedAttack != AttackType::None) {
            executeAttack(selectedAttack);
            updateCooldownTimer(selectedAttack);

            std::cout << "Character attacks with a " << (selectedAttack == SimpleAttack ? "simple" : "complex") << " attack." << std::endl;
        }
    }

private:
    std::map<int, int> attackPriorities;
    std::map<AttackType, std::chrono::time_point<std::chrono::steady_clock>> cooldownTimers;

    void updateCooldownTimer(AttackType type) {
        switch (type) {
            case SimpleAttack: 
                cooldownTimers[SimpleAttack] = std::chrono::steady_clock::now() + std::chrono::seconds(5);
                break;
