using UnityEngine;

public class ValueGenerator
{
    private float minValue;
    private float maxValue;
    private int maxAttempts;
    private float tolerance;

    public ValueGenerator(float min, float max, int attempts, float tol)
    {
        minValue = min;
        maxValue = max;
        maxAttempts = attempts;
        tolerance = tol;
    }

    public float GenerateRandomFloat(bool includeMax)
    {
        if (includeMax)
        {
            return UnityEngine.Random.Range(minValue, maxValue + 1);
        }
        else
        {
            return UnityEngine.Random.Range(minValue, maxValue);
        }
    }

    public int GenerateRandomInt(bool includeMax)
    {
        if (includeMax)
        {
            return Mathf.RoundToInt(GenerateRandomFloat(includeMax));
        }
        else
        {
            return Mathf.FloorToInt(GenerateRandomFloat(includeMax));
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}], Tolerance: {tolerance}";
    }

    public float[] GenerateMultipleValues(int count, bool includeMax)
    {
        float[] generatedValues = new float[count];
        int attempts = 0;
        HashSet<float> uniqueValues = new HashSet<float>();

        while (attempts < maxAttempts && uniqueValues.Count < count)
        {
            float value = GenerateRandomFloat(includeMax);
            if (!uniqueValues.Contains(value))
            {
                uniqueValues.Add(value);
                generatedValues[generatedValues.Length - uniqueValues.Count] = value;
            }
            attempts++;
        }

        // Handle scenario where all values fall outside tolerance
        if (generatedValues.Any(v => Math.Abs(v - maxValue) > tolerance || Math.Abs(v - minValue) > tolerance))
        {
            Debug.LogWarning("Generated values exceed specified tolerance.");
        }

        return generatedValues;
    }
}
