function aggregateAsync(dataStream) {
  return new Promise((resolve, reject) => {
    let total = 0;
    const filters = ['filter1', 'filter2'];

    async function processChunk(chunk) {
      try {
        for (const item of chunk) {
          if (filters.includes(item.source)) {
            total += item.value;
          }
        }
      } catch (error) {
        reject(error);
      }
    }

    const processStream = () => {
      return new Promise((resolve, reject) => {
        let buffer = [];

        dataStream.on('data', chunk => {
          buffer.push(...chunk);
          if (buffer.length >= 1000) { // processing chunk size
            processChunk(buffer).then(() => {
              buffer = [];
            }).catch(reject);
          }
        });

        dataStream.on('end', () => {
          processChunk(buffer).then(() => {
            resolve(total);
          }).catch(reject);
        });

        dataStream.on('error', reject);

        dataStream.on('close', () => {
          if (buffer.length > 0) {
            processChunk(buffer).then(() => {
              resolve(total);
            }).catch(reject);
          } else {
            resolve(total);
          }
        });
      });
    };

    return processStream();
  });
}
