    int count;
    config_pair **pairs;
} config_section;

config_section *load_and_parse_config(const char *file_path) {
    FILE *fp = fopen(file_path, "r");
    if (fp == NULL) {
        return NULL;
    }

    json_object *json_data = json_object_from_file.fp(file_path);
    if (json_data == NULL) {
        fclose(fp);
        return NULL;
    }

    config_section *root_section = (config_section *)malloc(sizeof(config_section));
    root_section->count = 0;
    root_section->pairs = NULL;

    // Parse JSON data
    json_object *json_root = json_object_object_get(json_data, "root");
    if (json_root == NULL) {
        fclose(fp);
        free(root_section);
        return NULL;
    }

    config_pair **pairs = (config_pair **)malloc(sizeof(config_pair *) * 10);
    root_section->count = 1;
    root_section->pairs = pairs;

    // Add section and key-value pairs
    int i = 0;
    json_object_object_foreach(json_root, key, val) {
        config_pair *pair = (config_pair *)malloc(sizeof(config_pair));
        pair->key = strdup(key);
        if (json_is_string(val)) {
            pair->value = strdup(json_object_to_json_string(val));
        } else if (json_is_int(val)) {
            int value = json_object_get_int(val);
            pair->value = &value;
        } else {
            fclose(fp);
            free(root_section);
            return NULL;
        }

        pairs[i] = pair;
        i++;
    }

    // Add section to root
    config_pair *section_pair = (config_pair *)malloc(sizeof(config_pair));
    section_pair->key = strdup("section");
    section_pair->value = json_root;
    pairs[i] = section_pair;

    // Parse INI data (if available)
    if (fp != NULL) {
        fclose(fp);
    }

    return root_section;
}
