// Define the struct for log entry
typedef struct {
    char* id;
    int timestamp;
    double metric1;
    double metric2;
    double moving_average;
} LogEntry;

// Define the function to process a log file
void process_log_file(const char* log_path, const char* api_key) {
    // Initialize JSON object
    json_object* json_obj = json_object_new();

    FILE* file = fopen(log_path, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", log_path);
        return;
    }

    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    char line[1024];
    int line_num = 0;

    while (fgets(line, sizeof(line), file)) {
        // Process each log entry
        entry->id = malloc(strlen(line) + 1);
        strcpy(entry->id, line);

        // Extract timestamp and metrics from the entry
        char* token = strtok(line, ", ");
        sscanf(token, "%d", &entry->timestamp);
        token = strtok(NULL, ", ");
        entry->metric1 = atof(token);
        token = strtok(NULL, ", ");
        entry->metric2 = atof(token);

        // Calculate moving average
        double sum = (entry->metric1 + entry->metric2) / 2.0;
        entry->moving_average = sum;

        // Add the log entry to the JSON object
        json_object_object_add(json_obj, line_num++, json_object_new_object());
        json_object_object_add_value(json_obj, "id", entry->id);
        json_object_object_add_value(json_obj, "timestamp", entry->timestamp);
        json_object_object_add_value(json_obj, "metric1", entry->metric1);
        json_object_object_add_value(json_obj, "metric2", entry->metric2);
        json_object_object_add_value(json_obj, "moving_average", entry->moving_average);

        free(entry->id);
        free(entry);
    }

    fclose(file);

    // Convert JSON object to string
    char* json_str = json_object_to_json_string_ext(json_obj, 0);
    printf("%s\n", json_str);
    free(json_str);
    json_object_free(json_obj);
}

int main() {
    const char* log_path = getenv("LOG_FILE_PATH");
    if (log_path == NULL) {
        log_path = "path/to/log/file.log";
    }

    const char* api_key = getenv("API_KEY");
    if (api_key == NULL) {
        api_key = "YOUR_API_KEY_HERE";
    }

    process_log_file(log_path, api_key);

    return 0;
}

