#include <string.h>
#include <tiffio.h>
#include <md5.h>

typedef struct {
    int bitsPerSample;
    int samplePerPixel;
    int extraSamplesCount;
    unsigned char *extraSamplesData;
} ImageInfo;

ImageInfo processImageAndComputeHash(const char* filePath) {
    TIFF *tif = TIFFOpen(filePath, "r");
    if (tif == NULL) {
        return (ImageInfo){0, 0, 0, NULL};
    }

    uint16_t bitsPerSample = TIFFGetField(tif, TIFF_FIELD_BITSPERSAMPLE);
    uint16_t samplePerPixel = TIFFGetField(tif, TIFF_FIELD_SAMPLESPERPIXEL);
    int extraSamplesCount;
    unsigned char *extraSamplesData;

    // Parse image information
    if (bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 || bitsPerSample == 8 || bitsPerSample == 16) {
        switch (bitsPerSample) {
            case 1:
                extraSamplesCount = TIFFGetField(tif, TIFF_FIELD_EXTRA_SAMPLES_COUNT);
                break;
            default:
                // For now, assume no extra samples
                extraSamplesCount = 0;
                break;
        }
    } else {
        printf("Unsupported bits per sample: %d\n", bitsPerSample);
        return (ImageInfo){0, 0, 0, NULL};
    }

    // Compute MD5 hash of the input file's content
    uint8_t *fileContent = (uint8_t *)malloc(TIFFFileLength(tif));
    TIFFReadBuffer(tif, fileContent, TIFFFileLength(tif));

    uint32_t md5Hash[4];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, fileContent, TIFFFileLength(tif));
    MD5_Final(md5Hash, &ctx);

    free(fileContent);

    ImageInfo imageInfo = (ImageInfo){
        .bitsPerSample = bitsPerSample,
        .samplePerPixel = samplePerPixel,
        .extraSamplesCount = extraSamplesCount,
        .extraSamplesData = TIFFReadBuffer(tif, NULL, extraSamplesCount),
    };

    TIFFClose(tif);
    return imageInfo;
}
