    filename_parts parts;
    parts.base_name = malloc((base_name_length + 1) * sizeof(char));
    strcpy(parts.base_name, filename);
    for (size_t i = 0; i < base_name_length; i++) {
        if (parts.base_name[i] == '.') {
            parts.extension = malloc((base_name_length - i) * sizeof(char));
            strcpy(parts.extension, &parts.base_name[i]);
            parts.base_name[i] = '\0';
            break;
        }
    }
    return parts;
}

char *generate_filename(const char *input_filename) {
