    char *unique_identifier = malloc(MAX_IDENTIFIER_LENGTH + 1);
    generate_unique_identifier(unique_identifier, MAX_IDENTIFIER_LENGTH);
    int length = strlen(parts.base_name) + strlen(unique_identifier) + 2;
    char *filename = malloc(length * sizeof(char));
    snprintf(filename, length, "%s-%s", parts.base_name, unique_identifier);

    time_t current_time = time(NULL);
