```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <sys/resource.h>

#define MAX_CMD_LENGTH 1024
#define MONITORING_INTERVAL 10

int execute_command_background(char *cmd, int priority) {
    pid_t child_pid;
    FILE *log_file = fopen("command_execution.log", "a");
    FILE *resource_usage_file = fopen("resource_usage.log", "w");

    if (cmd == NULL || strlen(cmd) > MAX_CMD_LENGTH) {
        fprintf(log_file, "Invalid command\n");
        return 0;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Create a child process to execute the command in background
    child_pid = fork();

    if (child_pid == -1) {
        perror("fork");
        return 0;
    } else if (child_pid > 0) { // Parent process
        waitpid(child_pid, NULL, WNOHANG);

        while (true) {
            struct rusage resource_usage;
            getrusage(RUSAGE_CHILDREN, &resource_usage);

            if (resource_usage.ru_utime.tv_sec > 5 || resource_usage.ru_maxrss > 1000000) {
                kill(child_pid, SIGKILL);
                waitpid(child_pid, NULL, 0);
                break;
            }

            sleep(MONITORING_INTERVAL);
        }

    } else { // Child process
        int status = execvp(cmd, NULL);
        if (status < 0) {
            perror("execvp");
            exit(EXIT_FAILURE);
        }
    }

    fclose(log_file);
    fclose(resource_usage_file);

    return WEXITSTATUS(status);
}

void handle_sigint(int signal) {
    kill(getpid(), SIGINT);
}
