                _logger.Warning("Web configuration file not found: {0}", webConfigPath);
                return;
            }

            XDocument webConfig;
            try
            {
                webConfig = XDocument.Load(webConfigPath);
            }
            catch (XmlException ex)
            {
                _logger.Error("Invalid web configuration file: {0}", ex.Message);
                return;
            }

            try
            {
                StartWebsite(directoryPath, webConfig);
            }
            catch (Exception ex)
            {
                _logger.Error("Failed to start website: {0}", ex.Message);
            }
        }

        private bool ValidateDirectory(string directoryPath)
        {
            if (!Directory.Exists(directoryPath))
                return false;

            if (!Path.GetExtension(directoryPath).Equals("", StringComparison.OrdinalIgnoreCase))
                return false;

            return true;
        }

        private void StartWebsite(string directoryPath, XDocument webConfig)
        {
            _startInfo.FileName = "w3wp.exe"; // or your desired executable
            _startInfo.WorkingDirectory = directoryPath;
            _startInfo.Arguments = "--webconfig=" + webConfig.ToString();

            try
            {
                Process.Start(_startInfo);
            }
            catch (Exception ex)
            {
                _logger.Error("Failed to start website: {0}", ex.Message);
            }

            // Monitor and restart the process if it crashes
            using (Process process = Process.GetProcessesByName("w3wp").FirstOrDefault())
            {
                try
                {
                    while (process != null && !process.HasExited)
                    {
                        Thread.Sleep(1000); // adjust to your desired interval
                        if (!process.HasExited)
                            _logger.Debug("Website running...");
                    }
                }
                catch (Exception ex)
                {
                    _logger.Error("Failed to monitor website process: {0}", ex.Message);
                }
            }

            // Record the status of each website
            _logger.Information("Website started successfully.");
        }
    }
}
