#include <string.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    char* title;
    int active;
} connection_t;

typedef struct {
    char* password;
    connection_t* conn;
    void (*callback)(const char*);
    configuration_t;
} data_t;

int processAndHandleData(data_t* d, const char* base64_msg, void (*cb)(const char*), config_t* config, int timeout) {
    if (d->password == NULL || strlen(d->password) == 0) {
        return -1; // password error
    }

    if (!config->conn->title || !config->conn->active) {
        return -2; // connection error
    }

    if (!cb) {
        return -3; // callback error
    }

    if (!validateConfig(config)) {
        return -4; // config error
    }

    char* decrypted = NULL;
    int decrypted_len = 0;

    if (base64_decode(base64_msg, strlen(base64_msg), &decrypted, &decrypted_len) < 0) {
        log_error("Base64 decoding failed");
        return -5; // base64 error
    }

    char* decrypted_copy = NULL;
    int decrypted_copy_len = 0;

    if (des_decrypt(decrypted, decrypted_len, d->password, config->conn->iv, &decrypted_copy, &decrypted_copy_len) < 0) {
        log_error("Decryption failed");
        free(decrypted);
        return -6; // decryption error
    }

    int result = (*cb)(decrypted_copy);

    free(decrypted);
    free(decrypted_copy);

    return result;
}
