bool validateJsonConfig(const char* jsonConfig) {
    json_t *root = json_loads(jsonConfig, JSON_NONE);
    if (!root) {
        return false;
    }

    // Validate server section
    json_t *server = json_object_get(root, "server");
    if (!server || !json_is_object(server)) {
        json_decref(root);
        return false;
    }
    const char* host = json_string_value(json_object_get(server, "host"));
    int port = json_integer_value(json_object_get(server, "port"));
    int timeout = json_integer_value(json_object_get(server, "timeout"));
    int ssl = json_integer_value(json_object_get(server, "ssl"));

    // Validate services section
    json_t *services = json_object_get(root, "services");
    if (!services || !json_is_array(services)) {
        json_decref(root);
        return false;
    }
    for (int i = 0; i < json_array_size(services); i++) {
        json_t *service = json_array_get(services, i);
        if (!service || !json_is_object(service)) {
            json_decref(root);
            return false;
        }
        const char* serviceName = json_string_value(json_object_get(service, "name"));
        const char* serviceUrl = json_string_value(json_object_get(service, "url"));
        int latencyThreshold = json_integer_value(json_object_get(service, "latencyThreshold"));
    }

    // Validate routes section
    json_t *routes = json_object_get(root, "routes");
    if (!routes || !json_is_array(routes)) {
        json_decref(root);
        return false;
    }
    for (int i = 0; i < json_array_size(routes); i++) {
        json_t *route = json_array_get(routes, i);
        if (!route || !json_is_object(route)) {
            json_decref(root);
            return false;
        }
        const char* path = json_string_value(json_object_get(route, "path"));
        const char* serviceName = json_string_value(json_object_get(route, "serviceName"));
        int priority = json_integer_value(json_object_get(route, "priority"));
    }

    // Validate caching section
    json_t *caching = json_object_get(root, "caching");
    if (!caching || !json_is_object(caching)) {
        json_decref(root);
        return false;
    }
    int cacheDuration = json_integer_value(json_object_get(caching, "cacheDuration"));
    const char* evictionPolicy = json_string_value(json_object_get(caching, "evictionPolicy"));

    // If we've reached this point, the configuration is valid
    json_decref(root);
    return true;
}
