['```csharp
using System;
using System.Security.Cryptography;

public class Base64TripleDesDecryptor
{
    private readonly ICryptoTransform[] _transformChain;
    private readonly string _logSource;

    public Base64TripleDesDecryptor(string[] keyStrings, byte[][] ivs)
    {
        if (keyStrings.Length != ivs.Length)
            throw new ArgumentException("Number of keys and IVs must be the same");

        _logSource = typeof(Base64TripleDesDecryptor).Name;
        _transformChain = new ICryptoTransform[keyStrings.Length];

        for (int i = 0; i < keyStrings.Length; i++)
        {
            ValidateKeyAndIV(keyStrings[i], ivs[i]);
            _transformChain[i] = CreateCipherTransform(keyStrings[i], ivs[i]);
        }
    }

    public string DecryptBase64(string base64Encoded)
    {
        try
        {
            byte[] decodedBytes = Convert.FromBase64String(base64Encoded);
            for (int i = 0; i < _transformChain.Length; i++)
            {
                decodedBytes = TransformBlock(decodedBytes, _transformChain[i]);
            }
            return System.Text.Encoding.UTF8.GetString(decodedBytes);
        }
        catch (DecryptionFailedException ex)
        {
            throw;
        }
    }

    private ICryptoTransform CreateCipherTransform(string keyString, byte[] iv)
    {
        using (var tripleDes = TripleDES.Create())
        {
            tripleDes.Key = Convert.FromBase64String(keyString);
            tripleDes.IV = iv;
            return tripleDes.CreateEncryptor();
        }
    }

    private void ValidateKeyAndIV(string keyString, byte[] iv)
    {
        if (keyString.Length * 4 != 24) // 24 bytes for a 192-bit key
            throw new ArgumentException("Invalid key length");
        if (iv.Length != 8) // 8 bytes for an IV
            throw new ArgumentException("Invalid IV length");
    }

    private byte[] TransformBlock(byte[] input, ICryptoTransform transform)
    {
        using (var memoryStream = new MemoryStream(input))
        {
            using (var cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Write))
            {
                cryptoStream.FlushFinalBlock();
                return memoryStream.ToArray();
            }
        }
    }

    public void GenerateRandomKeysAndIVs(int count, out string[] keyStrings, out byte[][] ivs)
    {
        Random random = new Random();

        keyStrings = new string[count];
        ivs = new byte[count][];

        for (int i = 0; i < count; i++)
        {
            keyStrings[i] = Convert.ToBase64String(RandomBytes(24));
            ivs[i] = RandomBytes(8);
        }
    }

    private byte[] RandomBytes(int length)
    {
        var randomBytes = new byte[length];
        new Random().NextBytes(randomBytes);
        return randomBytes;
    }

    public class DecryptionFailedException : Exception
    {
        public DecryptionFailedException(string message) : base(message)
        {
        }
    }
}
