using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHasher
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly Dictionary<string, string> _fileCache = new Dictionary<string, string>();

    public async Task<Dictionary<string, string>> ComputeFileHashes(List<string> fileUrls)
    {
        var fileHashes = new Dictionary<string, string>();

        foreach (var fileUrl in fileUrls)
        {
            try
            {
                if (_fileCache.TryGetValue(fileUrl, out var cachedHash))
                {
                    fileHashes.Add(fileUrl, cachedHash);
                    continue;
                }

                using var httpClientHandler = new HttpClientHandler();
                using var requestStream = await _httpClient.GetStreamAsync(fileUrl);

                using var sha256 = SHA256.Create();
                using var ms = new MemoryStream();

                try
                {
                    await requestStream.CopyToAsync(ms);
                    ms.Position = 0;
                    var fileHash = Convert.ToBase64String(sha256.ComputeHash(ms));
                    fileHashes.Add(fileUrl, fileHash);

                    _fileCache.Add(fileUrl, fileHash);
                }
                catch (HttpRequestException ex)
                {
                    Console.WriteLine($"Error processing {fileUrl}: {ex.Message}");
                }
                catch (IOException ex)
                {
                    Console.WriteLine($"Error reading file {fileUrl}: {ex.Message}");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing file {fileUrl}: {ex.Message}");
            }
        }

        return fileHashes;
    }
}
