using System.Text;

public class CipherHelper
{
    public static string DecryptAEScbc(string ciphertext, string encryptionKey, string initializationVector)
    {
        try
        {
            using (Aes aes = Aes.Create())
            {
                byte[] keyBytes = Convert.FromBase64String(encryptionKey);
                aes.Key = keyBytes;
                byte[] ivBytes = Convert.FromBase64String(initializationVector);
                aes.IV = ivBytes;

                using (MemoryStream ms = new MemoryStream(Convert.FromBase64String(ciphertext)))
                {
                    using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        byte[] buffer = new byte[1024];
                        int read;
                        StringBuilder decryptedText = new StringBuilder();
                        while ((read = cs.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            decryptedText.Append(Encoding.UTF8.GetString(buffer, 0, read));
                        }
                        return decryptedText.ToString();
                    }
                }
            }
        }
        catch (CryptographicException e)
        {
            Console.WriteLine("Error decrypting AES-CBC ciphertext: " + e.Message);
            return null;
        }
    }
}
