public class DataLoader
{
    private readonly object _lock = new object();
    private readonly Dictionary<string, byte[]> _cache = new Dictionary<string, byte>();

    public async Task<MyDataStructure> LoadData(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("The file does not exist.", filePath);

        string cacheKey = $"{filePath}"; // Use a combination of the file path and its contents as the cache key
        byte[] cachedBytes;

        lock (_lock) // Synchronize access to the cache dictionary
        {
            if (_cache.TryGetValue(cacheKey, out cachedBytes))
                return Deserialize(cachedBytes);
        }

        try
        {
            using (FileStream fileStream = File.OpenRead(filePath))
            {
                cachedBytes = new byte[fileStream.Length];
                await fileStream.ReadAsync(cachedBytes.AsMemory(), 0, cachedBytes.Length);

                // Add the deserialized data to the cache for future use
                lock (_lock)
                {
                    _cache[cacheKey] = cachedBytes;
                }
            }

            return Deserialize(cachedBytes);
        }
        catch (IOException ex)
        {
            throw new Exception("Error reading or uncompressing the file.", ex);
        }
    }

    private MyDataStructure Deserialize(byte[] data)
    {
        using (MemoryStream stream = new MemoryStream(data))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            return (MyDataStructure)formatter.Deserialize(stream);
        }
    }
}

