public class TransactionEventAggregator {
    public List<EventSummary> aggregateEvents(byte[] serializedTransactions) {
        List<EventSummary> eventSummaries = new ArrayList<>();
        ByteArrayInputStream inputStream = new ByteArrayInputStream(serializedTransactions);

        try (ObjectInputStream objectStream = new ObjectInputStream(inputStream)) {
            while (inputStream.available() > 0) {
                Object transactionEvent;
                try {
                    transactionEvent = objectStream.readObject();
                    if (transactionEvent instanceof TransactionEvent) {
                        EventSummary summary = ((TransactionEvent) transactionEvent).getSummary();
                        eventSummaries.add(summary);
                    } else {
                        // Default placeholder event summary
                        eventSummaries.add(new DefaultEventSummary());
                    }
                } catch (ClassNotFoundException e) {
                    // Log a warning and skip processing this object
                    System.out.println("Warning: Unable to find class for deserialized object.");
                } catch (Exception e) {
                    // Log a warning and skip processing this object
                    System.out.println("Warning: Error processing transaction event. Skipping...");
                }
            }
        } catch (IOException e) {
            // Log an error and exit
            System.out.println("Error aggregating events: " + e.getMessage());
            return null;
        }

        return eventSummaries;
    }
}
