const { ChildProcess } = require('child_process');
const { PassThrough } = require('stream');

class CommandExecutor {
  constructor({
    commandPrefix,
    timeout = 30000, // default timeout in ms
    maxRetries = 3, // default max retries
  }) {
    this.commandPrefix = commandPrefix;
    this.timeout = timeout;
    this.maxRetries = maxRetries;
  }

  async executeCommand(command) {
    const childProcess = ChildProcess.spawn(this.commandPrefix, [command], {
      stdio: 'pipe',
    });

    const stream = new PassThrough();

    childProcess.stdout.pipe(stream);
    childProcess.stderr.pipe(stream);

    let retries = 0;

    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (retries >= this.maxRetries) {
          reject(new Error(`Command '${command}' timed out after ${this.timeout}ms`));
        }
      }, this.timeout);

      childProcess.on('exit', (code, signal) => {
        if (code !== 0 || signal) {
          reject(new Error(`Command '${command}' failed with exit code ${code}`));
        } else {
          resolve();
        }
      });

      stream.on('error', (err) => {
        reject(err);
      });
    }).then(() => {
      return stream;
    });
  }

  async executeCommands(commands, concurrency = 10) {
    const queue = [];
    let executingCount = 0;

    for (const command of commands) {
      queue.push(command);

      if (queue.length > concurrency) {
        this.waitForExecution();
      }
    }

    await this.waitForExecution();

    return queue.map((command) => this.executeCommand(command));
  }

  async waitForExecution() {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (executingCount < queue.length) {
          this.waitForExecution();
        } else {
          resolve();
        }
      }, 100);
    });
  }
}
