use log::{error, info};

pub fn init_config_dir(conf_service: &dyn Fn() -> Result<String, Box<dyn std::error::Error>>)
                       -> Result<PathBuf, Box<dyn std::error::Error>> {
    let mut dir_path = get_default_dir_path();
    if !dir_path.exists() && conf_service.is_ok() {
        match conf_service() {
            Ok(conf_path) => {
                if let Err(err) = fs::create_dir_all(&PathBuf::from(conf_path.clone())) {
                    error!("Failed to create config directory: {}", err);
                    dir_path = PathBuf::new();
                } else {
                    info!("Config directory initialized at: {}", conf_path);
                }
            },
            Err(err) => {
                error!("Error initializing config directory: {}", err);
                dir_path = PathBuf::new();
            }
        }
    }
    if let Err(err) = fs::read_dir(&dir_path) {
        error!("Failed to access initialized config directory: {}", err);
        cleanup(dir_path.clone())?;
        return Err(Box::new(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Directory initialization failed")));
    }
    Ok(dir_path)
}

fn get_default_dir_path() -> PathBuf {
    // Implement logic to get default directory path from command-line flags or environment variables
    // For demonstration purposes, we'll use a hardcoded value
    let dir_path = Path::new("config");
    if !dir_path.exists() {
