        Logger(int maxDepth = 5) : depth_(maxDepth), loggerId_(++loggerId_) {}

        ~Logger() { log::~log(); }

        void logError(const char* fmt, ...) {
            va_list args;
            va_start(args, fmt);
            int len = vsnprintf(nullptr, 0, fmt, args);
            if (len > 0) {
                char buffer[len + 1];
                vsnprintf(buffer, len + 1, fmt, args);
                std::cout << loggerId_ << ": " << buffer << std::endl;
            }
            va_end(args);
        }

    private:
        int depth_;
        static int loggerId_;
    };

    int Logger::loggerId_ = 0;

    std::mt19937 ErrorLogger::Logger::mt(std::random_device{}());
}

int main() {
    ErrorLogger::Logger log;
    log.logError("Error: %s", "Something went wrong");
    return 0;
