import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MD5Service {

    private static final int DEFAULT_CONCURRENCY = 10;
    private static final int MAX_CONCURRENCY = 1000;
    private ExecutorService executorService;
    private String validationSource;

    public MD5Service(String validationSource) {
        this.validationSource = validationSource;
        this.executorService = Executors.newFixedThreadPool(DEFAULT_CONCURRENCY);
    }

    public List<String> computeMD5Hashes(List<String> inputStrings) throws IOException, InterruptedException {

        List<String> result = new ArrayList<>();

        for (String str : inputStrings) {
            if (validateString(str)) {
                String md5Hash = computeMD5Hash(str);
                result.add(md5Hash);
            }
        }

        return result;
    }

    private boolean validateString(String str) throws IOException, InterruptedException {
        // Implement string validation logic here
        // For demonstration purposes, assume it's a simple validation
        return true;
    }

    private String computeMD5Hash(String str) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = str.getBytes();
        byte[] hashBytes = md.digest(bytes);

        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xFF & b);
            sb.append(hex);
        }

        return sb.toString();
    }

    public void shutdown() throws InterruptedException, IOException {
        executorService.shutdownNow();
    }
}
