    *total_records = 0;
    Record* records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Record* record = &records[(*total_records)++];
        sscanf(line, "%63s %31s %d %d", record->hostname, record->timestamp, &record->latency, &record->bandwidth);
    }
    fclose(file);
