}

int compute_average_latency(const Record* records, int total_records, char* hostname, int* average_latency) {
    int sum = 0;
    int count = 0;
    for (int i = 0; i < total_records; i++) {
        if (strcmp(records[i].hostname, hostname) == 0) {
            sum += records[i].latency;
            count++;
        }
    }
    *average_latency = sum / count;
    return 0;
}

