#include <sys/wait.h>
#include <semaphore.h>

#define MAX_TIMESTAMP 1000000
#define MAX_DATA_POINTS 10000
#define MIN_METADATA_SIZE 10

typedef struct {
    long timestamp;
    int value;
    char metadata[MIN_METADATA_SIZE];
} DataPoint;

DataPoint* data_points[MAX_DATA_POINTS];
sem_t sem;

void initialize_data_points();
void insert_data_point(long timestamp, int value, const char* metadata);
void delete_data_point(long timestamp);
DataPoint* get_data_point(long timestamp);
void update_metadata(long timestamp, const char* metadata);

int main() {
    // Initialize semaphore
    sem_init(&sem, 0, 1);

    initialize_data_points();

    // Start handling data points
    while (1) {
        int value = read_sensor_value(); // Read from external sensor network
        long timestamp = get_current_timestamp();
        const char* metadata = get_metadata_from_network();

        insert_data_point(timestamp, value, metadata);
    }

    return 0;
}

void initialize_data_points() {
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        data_points[i] = NULL;
    }
}

void insert_data_point(long timestamp, int value, const char* metadata) {
    // Acquire semaphore
    sem_wait(&sem);

    // Insert data point
    DataPoint* new_dp = (DataPoint*)malloc(sizeof(DataPoint));
    new_dp->timestamp = timestamp;
    new_dp->value = value;
    strcpy(new_dp->metadata, metadata);

    // Find the correct location to insert
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        if (data_points[i] == NULL) {
            data_points[i] = new_dp;
            break;
        }
    }

    // Release semaphore
    sem_post(&sem);
}

void delete_data_point(long timestamp) {
    // Acquire semaphore
    sem_wait(&sem);

    // Find the correct location to delete
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        if (data_points[i] && data_points[i]->timestamp == timestamp) {
            free(data_points[i]);
            data_points[i] = NULL;
            break;
        }
    }

    // Release semaphore
    sem_post(&sem);
}

DataPoint* get_data_point(long timestamp) {
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        if (data_points[i] && data_points[i]->timestamp == timestamp) {
            return data_points[i];
        }
    }

    return NULL;
}

void update_metadata(long timestamp, const char* metadata) {
    // Acquire semaphore
    sem_wait(&sem);

    // Find the correct location to update
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        if (data_points[i] && data_points[i]->timestamp == timestamp) {
            strcpy(data_points[i]->metadata, metadata);
            break;
        }
    }

    // Release semaphore
    sem_post(&sem);
}

void archive_data_points() {
    // Acquire semaphore
    sem_wait(&sem);

    // Find the correct location to archive old data points
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        if (data_points[i] && data_points[i]->timestamp <= ARCHIVE_TIMESTAMP) {
            DataPoint* dp = data_points[i];
            data_points[i] = NULL;

            // Save the archived data point to disk
            FILE* f = fopen("archive.log", "a");
            fwrite(dp, sizeof(DataPoint), 1, f);
            fclose(f);

            free(dp);
        }
    }

    // Release semaphore
    sem_post(&sem);
}

void read_archived_data_point(long timestamp) {
    // Acquire semaphore
    sem_wait(&sem);

    // Find the correct location to retrieve archived data point
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        if (data_points[i] && data_points[i]->timestamp == timestamp) {
            // Read the archived data point from disk
            FILE* f = fopen("archive.log", "r");
            fseek(f, sizeof(DataPoint), SEEK_SET);
            fread(data_points[i], sizeof(DataPoint), 1, f);
            fclose(f);

            break;
        }
    }

    // Release semaphore
    sem_post(&sem);
}
