DeviceRecord** devices = NULL;
int device_count = 0;

void add_device(int id, const char* gateway) {
    DeviceRecord* new_device = (DeviceRecord*)malloc(sizeof(DeviceRecord));
    new_device->device_id = id;
    new_device->gateway_info = (char*)malloc(strlen(gateway)+1);
    strcpy(new_device->gateway_info, gateway);
    new_device->num_sessions = 0;

    pthread_mutex_init(&new_device->lock, NULL);

    devices = realloc(devices, sizeof(DeviceRecord*) * (device_count + 1));
    devices[device_count] = new_device;
    device_count++;

    printf("Device %d added with gateway info: %s\n", id, gateway);
}

void remove_device(int id) {
    int i;
    for(i=0; i<device_count; i++) {
        if(devices[i]->device_id == id) {
            free(devices[i]->gateway_info);
            free(devices[i]);
            memmove(&devices[i], &devices[i+1], sizeof(DeviceRecord*) * (device_count - 1));
            device_count--;
            break;
        }
    }
}

void update_gateway(int id, const char* new_gateway) {
    int i;
    for(i=0; i<device_count; i++) {
        if(devices[i]->device_id == id) {
            free(devices[i]->gateway_info);
            devices[i]->gateway_info = (char*)malloc(strlen(new_gateway)+1);
            strcpy(devices[i]->gateway_info, new_gateway);
            printf("Gateway updated for device %d to: %s\n", id, new_gateway);
            break;
        }
    }
}

