#include <sys/wait.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>

int executeBackgroundTaskAndInitializeCryptoPrimitives(char* command) {
    int status = 1;
    pid_t pid;
    FILE* configFile;

    // Initialize logging mechanism
    OpenSSL_add_all_errors();
    OPENSSL_config(NULL);

    // Read configuration file and parse range for random values
    configFile = fopen("config.txt", "r");
    if (!configFile) {
        fprintf(stderr, "Error opening configuration file\n");
        return 0;
    }

    int lowerBound, upperBound;
    fscanf(configFile, "%d %d", &lowerBound, &upperBound);
    fclose(configFile);

    // Initialize arrays for 'long' offset values and 'int' keys
    long* offsets = (long*)malloc(sizeof(long) * 1000);
    int* keys = (int*)malloc(sizeof(int) * 1000);

    // Initialize array of record structures, each containing a single 'int' value
    struct {
        int value;
    }* records = (struct *)malloc(sizeof(struct) * 1000);

    for (int i = 0; i < 1000; i++) {
        records[i].value = (rand() % (upperBound - lowerBound)) + lowerBound;
    }

    // Run command in the background using fork and wait
    pid = fork();
    if (pid == 0) { // Child process
        system(command);
        return 1;
    } else {
        wait(&status);
    }

    // Initialize cryptographic operations for AES, Camellia, MD5, SHA, and RSA with SHA1
    if (!AES_new() || !Camellia_new() || !MD5_init() || !SHA_init(1) || !RSA_generate_key_ex(2048, RSA_F4, NULL, NULL)) {
        ERR_error();
        return 0;
    }

    // Clean up and exit with status
    free(offsets);
    free(keys);
    free(records);
    fclose(configFile);

    return status;
}']

