// Define maximum integers per stream and total integers
#define MAX_INTS_PER_STREAM 10000
#define TOTAL_INTS 20000

// Function to get the largest integer in an array
int findLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

// Function to process a single input stream
void processStream(char* filename, FILE* file) {
    int* ints = (int*)malloc(MAX_INTS_PER_STREAM * sizeof(int));
    int count = 0;
    char line[1024];

    // Read and clean each line from the input stream
    while (fgets(line, 1024, file)) {
        line[strcspn(line, "\n")] = 0; // Remove trailing newline
        for (char* p = line; *p; p++) {
            if (!isdigit(*p) && *p != '-') {
                printf("Invalid input: '%s'\n", line);
                free(ints);
                return;
            }
        }

        // Convert the cleaned line to an integer and store it
        char* endptr = NULL;
        int val = strtol(line, &endptr, 10);
        if (*endptr || val < -1000000 || val > 1000000) {
            printf("Invalid input: '%s'\n", line);
            free(ints);
            return;
        }
        ints[count] = val;
        count++;
    }

    // Find and print the largest integer in the array
    if (count == 0)
        printf("No valid integers found.\n");
    else {
        int max = findLargest(ints, count);
        printf("Largest integer in this stream: %d\n", max);

        // Shrink the dynamically allocated array to its minimum required size
        free(ints);
        ints = (int*)malloc(count * sizeof(int));
        memcpy(ints, &ints[0], count * sizeof(int));
    }
}

// Main function to read and process multiple input streams
int main() {
    int total_count = 0;
    FILE* files[] = {"input1.txt", "input2.txt", "input3.txt"};
    for (int i = 0; i < 3; i++) {
        FILE* file = fopen(files[i], "r");
        if (!file) {
            printf("Error opening file '%s'\n", files[i]);
            continue;
        }
        processStream(files[i], file);
        fclose(file);
    }

    return 0;
}

