#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000 // Initial capacity of the record store
#define GROWTH_FACTOR 2    // Factor for dynamic resizing

typedef struct {
    int key;
    long offset;
    double value;
} Record;

typedef struct {
    Record* records;
    size_t capacity, used;
    pthread_mutex_t mutex;
} RecordStore;

void init_record_store(RecordStore* store) {
    store->records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    store->capacity = MAX_RECORDS;
    store->used = 0;
    pthread_mutex_init(&store->mutex, NULL);
}

int record_store_insert(RecordStore* store, Record* new_record) {
    if (store->used >= store->capacity / GROWTH_FACTOR) {
        // Dynamic resizing - increase capacity when needed
        store->records = (Record*)realloc(store->records, 
            store->capacity * 2 * sizeof(Record));
        store->capacity *= 2;
    }

    pthread_mutex_lock(&store->mutex);
    Record* records = store->records + store->used++;
    memcpy(records, new_record, sizeof(Record));
    pthread_mutex_unlock(&store->mutex);

    return 0; // Success
}

void record_store_erase(RecordStore* store, int key) {
    // Find the record with the given key
    pthread_mutex_lock(&store->mutex);
    Record* records = store->records;
    size_t i;
    for (i = 0; i < store->used; ++i) {
        if (records[i].key == key) {
            memmove(records + i, records + i + 1, 
                (store->used - i - 1) * sizeof(Record));
            --store->used;
            break;
        }
    }
    pthread_mutex_unlock(&store->mutex);
}

int record_store_lookup(RecordStore* store, int key, Record** result) {
    // Find the record with the given key
    pthread_mutex_lock(&store->mutex);
    Record* records = store->records;
    size_t i;
    for (i = 0; i < store->used; ++i) {
        if (records[i].key == key) {
            *result = &records[i];
            pthread_mutex_unlock(&store->mutex);
            return 0; // Found
        }
    }
    pthread_mutex_unlock(&store->mutex);

    return -1; // Not found
}

void record_store_close(RecordStore* store) {
    free(store->records);
    pthread_mutex_destroy(&store->mutex);
}
