                if (Mathf.Abs(generatedValues[i] - generatedValues[j]) < tolerance)
                {
                    hasDuplicates = true;
                    break;
                }
            }
        }
    }

    public void IntegrateExternalData()
    {
        float externalMin = dataFetcher.GetMinValue();
        float externalMax = dataFetcher.GetMaxValue();

        if (externalMin != minValue || externalMax != maxValue)
