// Create a new memory pool with the given capacity
MemoryPool* create_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->buffer = malloc(capacity);
    pool->capacity = capacity;
    pool->used = 0;
    return pool;
}

// Free a memory pool and its contents
void free_memory_pool(MemoryPool* pool) {
    if (pool != NULL) {
        free(pool->buffer);
        free(pool);
    }
}

// Custom memory allocation function using the memory pool
void* my_malloc(size_t size, MemoryPool* pool) {
    void* ptr = NULL;
    size = sizeof(char) * size; // Assuming char-sized allocations

    if (pool != NULL && size <= pool->capacity - pool->used) {
        ptr = pool->buffer + pool->used;
        pool->used += size;
    } else {
        // Fall back to system malloc for large or out-of-pool requests
        ptr = malloc(size);
    }

    return ptr;
}

// Custom memory deallocation function using the memory pool
void my_free(void* ptr, MemoryPool* pool) {
    if (ptr != NULL) {
        size_t size = strlen(ptr); // Assuming char-sized allocations

        if (size <= pool->capacity - pool->used) {
            pool->used -= size;
            memmove(pool->buffer, ptr + size, pool->used);
        } else {
            // Free the pointer and reset the memory pool
            free(ptr);
            free_memory_pool(pool);
        }
    }
}

