    float value;
    struct record* next;
    struct record* prev;
} Record;

Record* records = NULL; // initialize the linked list of records
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // initialize semaphore

void* allocate_record() {
    return (void*)malloc(sizeof(Record));
}

float random_float(float min, float max) {
    static int seed = time(NULL);
    return (float)(rand_r(&seed) / (RAND_MAX + 1.0) * (max - min)) + min;
}

int init_records(int size, float min_value, float max_value) {
    pthread_mutex_init(&lock, NULL); // initialize semaphore

    for (int i = 0; i < size; i++) {
        Record* new_record = (Record*)allocate_record();
        if (!new_record) return -1;

        new_record->key = i;
        new_record->value = random_float(min_value, max_value);
        new_record->next = NULL;
        new_record->prev = NULL;

        pthread_mutex_lock(&lock); // lock for thread safety
        if (records == NULL) {
            records = new_record; // set the head of the linked list
        } else {
            Record* last_record = records;
            while (last_record->next) {
                last_record = last_record->next;
            }
            last_record->next = new_record;
            new_record->prev = last_record;
        }
        pthread_mutex_unlock(&lock); // unlock for thread safety
    }

    return 0;
}

void free_records() {
    Record* current = records;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    records = NULL; // set the head of the linked list to NULL

    pthread_mutex_destroy(&lock); // destroy semaphore
}

