        int rnti;
        do {
            rnti = rand() % MAX_STRUCTURES;
        } while ((cache_count > 0) && (rnti == cache[cache_count - 1]));

        nfaapi_crc_indication_pdu[i].ue_info = ...; // initialize ue_info
        nfaapi_crc_indication_pdu[i].rnti = rnti;
        nfaapi_crc_indication_pdu[i].crc_indication = ...; // initialize crc_indication
        nfaapi_crc_indication_pdu[i].crcflag = rand() % 2; // set CRCFLAG randomly

        if (cache_count < CACHE_SIZE) {
            cache[cache_count] = rnti;
            cache_count++;
        }
    }

    pthread_mutex_unlock(&cache_lock);
    return nfaapi_crc_indication_pdu;
}

void nfapi_crc_indication_pdu_free(NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_indication_pdu) {
    free(nfaapi_crc_indication_pdu);
}

void nfaapi_crc_indication_pdu_clear_cache() {
    pthread_mutex_lock(&cache_lock);
    cache_count = 0;
    pthread_mutex_unlock(&cache_lock);
