    Node* node = (Node*) malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to merge two sorted linked lists into one
Node* merge_lists(Node* list1, Node* list2) {
    // Base cases: If either list is empty, just return the other list
    if (list1 == NULL) return list2;
    if (list2 == NULL) return list1;

    Node* head = NULL;
    Node* current = &head;

    while (list1 != NULL && list2 != NULL) {
        // Compare timestamps and add the smaller one to the result
        if (((sensor_data*) list1->data)->timestamp <= ((extended_sensor_data*) list2->data)->timestamp) {
            current->next = list1;
            list1 = list1->next;
        } else {
            current->next = list2;
            list2 = list2->next;
        }
        current = current->next;
    }

    // Add the remaining nodes from one of the lists
    while (list1 != NULL) {
        current->next = list1;
        list1 = list1->next;
        current = current->next;
    }

    while (list2 != NULL) {
        current->next = list2;
        list2 = list2->next;
        current = current->next;
    }

    return head->next; // Return the merged list
}

// Function to print a linked list of sensor data records
void print_list(Node* list) {
    Node* current = list;
    while (current != NULL) {
        if ((sensor_data*) current->data)->humidity == -1.0) { // Handle missing humidity field
            printf("(Timestamp: %ld, Temperature: %.2f)\n", ((sensor_data*) current->data)->timestamp, ((sensor_data*) current->data)->temperature);
        } else {
            printf("(Timestamp: %ld, Temperature: %.2f, Humidity: %.2f)\n", ((sensor_data*) current->data)->timestamp, ((sensor_data*) current->data)->temperature, ((sensor_data*) current->data)->humidity);
        }
        current = current->next;
    }
}

int main() {
    // Create a linked list to store sensor data records
    Node* root = NULL;

    // Add some sample sensor data records
    root = create_node((void*) malloc(sizeof(sensor_data)));
    ((sensor_data*) (root)->data)->timestamp = 1643723400;
    ((sensor_data*) (root)->data)->temperature = 25.5f;
    ((sensor_data*) (root)->data)->humidity = -1.0f; // Missing humidity field

    root->next = create_node((void*) malloc(sizeof(extended_sensor_data)));
    ((extended_sensor_data*) (root->next)->data)->timestamp = 1643723500;
    ((extended_sensor_data*) (root->next)->data)->temperature = 26.2f;
    ((extended_sensor_data*) (root->next)->data)->humidity = 60.1f;
    ((extended_sensor_data*) (root->next)->data)->altitude = 1013.25f;

    // Merge two sorted linked lists into one
    Node* list2 = NULL;
    root->next->next = create_node((void*) malloc(sizeof(sensor_data)));
    ((sensor_data*) (root->next->next)->data)->timestamp = 1643723600;
    ((sensor_data*) (root->next->next)->data)->temperature = 27.8f;

    list2 = create_node((void*) malloc(sizeof(extended_sensor_data)));
