#define MAX_INT 1000000
#define MAX_BATCH 10000
#define LOG_FILE "processing_log.txt"

void print_largest(int** batches, int num_batches);
int is_valid_input(char* str);

int main() {
    FILE* input_files[MAX_BATCH];
    int batch_sizes[MAX_BATCH];
    char line[MAX_INT][32];

    // Open input files and read lines
    for (int i = 0; i < MAX_BATCH; i++) {
        input_files[i] = fopen("input_file_i.txt", "r");
        if (!input_files[i]) {
            printf("Error opening file %s\n", "input_file_i.txt");
            return 1;
        }

        int batch_size = 0;
        while (fgets(line[batch_size], sizeof(line[batch_size]), input_files[i])) {
            // Remove leading/trailing whitespace and validate integer
            char* str = line[batch_size];
            while (*str && isspace((int)*str)) {
                str++;
            }
            if (!is_valid_input(str)) {
                printf("Error: Invalid input in file %s at line %d\n", "input_file_i.txt", batch_size);
                fclose(input_files[i]);
                return 1;
            }

            batch_size++;
        }

        // Allocate memory for the current batch
        int* batch = (int*)malloc((batch_size + 1) * sizeof(int));
        if (!batch) {
            printf("Error: Memory allocation failed\n");
            fclose(input_files[i]);
            return 1;
        }

        // Convert strings to integers and store in the batch array
        for (int j = 0; j < batch_size; j++) {
            char* str = line[j];
            while (*str && isspace((int)*str)) {
                str++;
            }
            int num = atoi(str);
            if (num > MAX_INT || num < -MAX_INT) {
                printf("Error: Invalid integer in file %s at line %d\n", "input_file_i.txt", j);
                fclose(input_files[i]);
                free(batch);
                return 1;
            }

            batch[j] = num;
        }
        batch[batch_size] = '\0';

        // Store the batch and its size
        input_files[i] = NULL;  // Close file
        batch_sizes[i] = batch_size;

        printf("Batch %d: %s\n", i, (char*)batch);
    }

    print_largest(batch_sizes);

    for (int i = 0; i < MAX_BATCH; i++) {
        free((void*)input_files[i]);
    }

    return 0;
}

void print_largest(int** batches, int num_batches) {
    // Function to print the largest integer from each batch
    printf("Largest integers: ");
    for (int i = 0; i < num_batches; i++) {
        if (batches[i] == NULL || strlen((char*)batches[i]) <= 0) {
            printf("No valid inputs in batch %d\n", i);
        } else {
            int max_int = *(int*)batches[i];
            for (int j = 1; j <= strlen((char*)batches[i]); j++) {
                if (*(int*)batches[i] + j > max_int) {
                    max_int = *(int*)batches[i] + j;
                }
            }

            printf("%d ", max_int);
        }
    }
    printf("\n");
}

int is_valid_input(char* str) {
    // Helper function to validate input string
    int num = atoi(str);
    if (num > MAX_INT || num < -MAX_INT) {
        return 0;  // Invalid integer
    } else {
        return 1;  // Valid integer
    }
}
