    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = 0;
    ht->keys = (float**)malloc(sizeof(float*) * initial_capacity);
    ht->values = (Entry**)malloc(sizeof(Entry*) * initial_capacity);
