                temp->left = node;
            else
                temp->right = node;
        }
    }

    fclose(file);

    find_extremes(arr, arr_size);
    filter_entries(&root, ht, 0.5f); // Apply filtering based on a specified threshold

    // Free allocated memory to avoid potential resource leaks
    free(arr);
    for (int i = 0; i < ht->size; ++i) {
        free(ht->keys[i]);
        free(ht->values[i]);
    }
    free(ht->keys);
    free(ht->values);
    free(ht);

    return 0;
}
