#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define TIMESTAMP_SIZE 32

typedef struct {
    int time;
    char type;
    void* data;
} Event;

typedef struct record {
    int field;
    Event event;
} Record;

typedef struct metadata {
    int key;
    long offset;
    uint64_t timestamp;
} Metadata;

typedef struct node {
    Record record;
    struct node* prev;
    struct node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;

void add_record(Record record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record = record;
    new_node->prev = tail;
    if(tail != NULL)
        tail->next = new_node;
    else
        head = new_node;
    tail = new_node;
}

void delete_record(Record record) {
    Node* current = head;
    while(current != NULL && current->record != record) {
        current = current->next;
    }
    if(current == NULL)
        return; // Record not found
    if(current->prev != NULL)
        current->prev->next = current->next;
    else
        head = current->next;
    if(current->next != NULL)
        current->next->prev = current->prev;
    else
        tail = current->prev;
    free(current);
}

void insert_record(Event event) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record.field = rand() % 100; // Initialize field with pseudo-random value
    new_node->event = event;
    if(head == NULL)
        head = tail = new_node;
    else {
        new_node->next = head;
        head->prev = new_node;
        head = new_node;
    }
}

void flush_cache(char* filename) {
    FILE* file = fopen(filename, "wb");
    if(file == NULL)
        return; // Error opening file
    Node* current = head;
    while(current != NULL) {
        fwrite(&current->record, sizeof(Record), 1, file);
        current = current->next;
    }
    fclose(file);
}

int main() {
    srand(time(NULL)); // Seed random number generator
    Record record1 = {rand() % 100};
    Event event1 = {time(NULL), 'R', NULL};
    add_record(record1);
    insert_record(event1);
    flush_cache("cache.txt");
    return 0;
}
