void* my_malloc(size_t size) {
    return malloc(size);
}

void my_free(void* ptr) {
    free(ptr);
}

// Initialize metadata structure for tracking record statistics
metadata_t* init_metadata() {
    metadata_t* md = (metadata_t*)my_malloc(sizeof(metadata_t));
    if (!md) return NULL;

    md->num_records = 0;
    md->cumulative_sum = 0;
    md->average = 0.0;
    md->max_key = INT_MIN;

    return md;
}

// Add a new record to the storage system
int add_record(metadata_t* md, long value, int key, void* data) {
    // Update metadata statistics
    md->num_records++;
    md->cumulative_sum += value;
    if (key > md->max_key) md->max_key = key;

    // Calculate average value (optional)
    if (md->num_records > 0) {
        md->average = (double)md->cumulative_sum / md->num_records;
    }

    return 1; // successful addition
}

// Remove a record from the storage system
int remove_record(metadata_t* md, int key) {
    // Update metadata statistics
    if (key <= md->max_key) {
        md->num_records--;
        if (key == md->max_key) {
            md->max_key = INT_MAX;
        }
    }

    return 1; // successful removal
}

// Reset the metadata structure to its initial state
void reset_metadata(metadata_t* md) {
    my_free(md);
    md = init_metadata();
}
