```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_SET_SIZE 1000

typedef struct {
    int id;
    time_t timestamp;
    char *description;
} Item;

typedef struct {
    pthread_mutex_t mutex;
    size_t size;
    size_t capacity;
    Item **items;
} Set;

Set *create_set(size_t initial_capacity) {
    Set *set = (Set *)malloc(sizeof(Set));
    set->size = 0;
    set->capacity = initial_capacity;
    set->items = (Item **)calloc(initial_capacity, sizeof(Item *));
    pthread_mutex_init(&set->mutex, NULL);
    return set;
}

void destroy_set(Set **set) {
    if (*set == NULL) {
        free(*set);
        *set = NULL;
        return;
    }
    for (size_t i = 0; i < (*set)->size; i++) {
        free((*set)->items[i]->description);
        free((*set)->items[i]);
    }
    free((*set)->items);
    pthread_mutex_destroy(&(*set)->mutex);
    free(*set);
}

int insert_item(Set *set, int id, const char *description) {
    if (set->size >= set->capacity) {
        // Reallocate memory if the set is full
        size_t new_capacity = set->capacity * 2;
        Item **new_items = (Item **)realloc(set->items, new_capacity * sizeof(Item *));
        pthread_mutex_unlock(&set->mutex);
        for (size_t i = 0; i < set->size; i++) {
            new_items[i] = set->items[i];
        }
        free(set->items);
        set->items = new_items;
        set->capacity = new_capacity;
        pthread_mutex_lock(&set->mutex);
    }
    Item *item = (Item *)malloc(sizeof(Item));
    item->id = id;
    item->timestamp = time(NULL);
    item->description = (char *)malloc(strlen(description) + 1);
    strcpy(item->description, description);
    set->items[set->size] = item;
    set->size++;
    return 0;
}

void delete_item(Set *set, int id) {
    pthread_mutex_lock(&set->mutex);
    for (int i = 0; i < set->size; i++) {
        if (set->items[i]->id == id) {
            free(set->items[i]->description);
            free(set->items[i]);
            memmove(set->items + i, set->items + i + 1, (set->size - i - 1) * sizeof(Item *));
            set->size--;
            break;
        }
    }
    pthread_mutex_unlock(&set->mutex);
}

void iterate_set(Set *set, void (*callback)(Item *)) {
    pthread_mutex_lock(&set->mutex);
    for (int i = 0; i < set->size; i++) {
        callback(set->items[i]);
    }
    pthread_mutex_unlock(&set->mutex);
}
