#include <string.h>

typedef struct {
    long timestamp;
    char src_ip[16];
    int payload_len;
} packet_t;

typedef struct {
    packet_t *packets;
    size_t size, capacity;
    int checksum;
} network_collection_t;

void init_network_collection(network_collection_t *collection) {
    collection->size = 0;
    collection->capacity = 10; // initial capacity
    collection->packets = (packet_t *)malloc(collection->capacity * sizeof(packet_t));
    collection->checksum = 0;
}

int insert_packet(network_collection_t *collection, packet_t *new_packet) {
    if (collection->size >= collection->capacity) {
        // resize the array
        collection->capacity *= 2; // double capacity
        packet_t *new_packets = (packet_t *)realloc(collection->packets,
            collection->capacity * sizeof(packet_t));
        collection->packets = new_packets;
    }

    // find the correct position to insert based on src_ip
    int hash_value = MurmurHash(new_packet->src_ip, strlen(new_packet->src_ip), 0);
    int index = hash_value % (collection->size + 1);

    // move existing packets to make room for new packet
    memmove(&collection->packets[index], &collection->packets[index+1],
        (collection->size - index) * sizeof(packet_t));
    collection->packets[index] = *new_packet;
    collection->size++;

    return 0; // successful insertion
}

int remove_packet(network_collection_t *collection, char *src_ip) {
    int hash_value = MurmurHash(src_ip, strlen(src_ip), 0);
    int index = hash_value % collection->size;

    if (index >= collection->size || !strcmp(collection->packets[index].src_ip, src_ip)) {
        printf("Packet not found!\n");
        return -1; // packet not found
    }

    memmove(&collection->packets[index], &collection->packets[index+1],
        (collection->size - index - 1) * sizeof(packet_t));
    collection->size--;
    return 0; // successful removal
}

int update_packet(network_collection_t *collection, char *src_ip,
                  packet_t new_packet) {
    int hash_value = MurmurHash(src_ip, strlen(src_ip), 0);
    int index = hash_value % collection->size;

    if (index >= collection->size || !strcmp(collection->packets[index].src_ip, src_ip)) {
        printf("Packet not found!\n");
        return -1; // packet not found
    }

    memcpy(&collection->packets[index], &new_packet, sizeof(packet_t));
    return 0; // successful update
}

void free_network_collection(network_collection_t *collection) {
    if (collection) {
        free(collection->packets);
        collection->packets = NULL;
