record** manageArrays(int numRecords, int maxValRange) {
    // Dynamically allocate memory for array of long integers representing offsets
    long* offsets = (long*)malloc(numRecords * sizeof(long));

    // Allocate memory for array of int integers used as unique keys
    int* keys = (int*)malloc(numRecords * sizeof(int));

    // Calculate the keys by applying a simple arithmetic transformation to the offsets
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = (long)rand();
        keys[i] = (int)(offsets[i] * 2 + rand() % maxValRange);
    }

    // Allocate memory for array of custom record structures
    record** records = (record**)malloc(numRecords * sizeof(record*));

    // Initialize the int value in each record to a random number within the specified range
    for (int i = 0; i < numRecords; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->val = (int*)malloc(sizeof(int));
        *records[i]->val = rand() % maxValRange;
        records[i]->rep = (char)(rand() % 26 + 'a'); // random lowercase letter
    }

    return records;
}

// Custom error logging mechanism for memory allocation failures
void logError(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to manage memory cleanup when the function is no longer needed
void cleanUp(record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]->val);
        free(records[i]);
    }
    free(records);
}
