#define STRING_POOL_SIZE 1024
#define ITEM_COUNT 1000
#define RANDOM_RANGE 100

typedef struct {
    double value;
    int index;
    char* string;
} Item;

Item* items[ITEM_COUNT];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_once_t once = PTHREAD_ONCE_INIT;

char* string_pool[STRING_POOL_SIZE];

void item_init(int i) {
    Item* item = &items[i];
    item->value = (double)rand() / RAND_MAX * RANDOM_RANGE;
    pthread_once(&once, initialize_string_pool);
    item->string = get_string();
}

Item* item_get(int i) {
    return &items[i];
}

void initialize_string_pool() {
    for (int i = 0; i < STRING_POOL_SIZE; i++) {
        string_pool[i] = mmap(NULL, strlen("unique_string_") + 1, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
        strcpy(string_pool[i], "unique_string_");
        sprintf(string_pool[i] + strlen("unique_string_"), "%d", i);
    }
}

char* get_string() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < STRING_POOL_SIZE; i++) {
        if (!string_pool[i]) {
            string_pool[i] = mmap(NULL, strlen("unique_string_") + 1, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
            strcpy(string_pool[i], "unique_string_");
            sprintf(string_pool[i] + strlen("unique_string_"), "%d", i);
            pthread_mutex_unlock(&mutex);
            return string_pool[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void item_release(int i) {
    munmap(items[i].string, strlen(items[i].string) + 1);
}

int main() {
    srand(time(NULL));
    for (int i = 0; i < ITEM_COUNT; i++) {
        items[i] = malloc(sizeof(Item));
        item_init(i);
    }
    // usage code here
    for (int i = 0; i < ITEM_COUNT; i++) {
        item_release(i);
        free(items[i]);
    }
    return 0;
}
