#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <map>

namespace MemoryManager {

class Pool {
public:
    Pool(size_t initialSize, size_t maxSize) : pool_(new char[initialSize]), mutex_(), cond_(std::thread::id()), maxPoolSize_(maxSize), currentPoolSize_(initialSize) {}

    ~Pool() {
        std::unique_lock<std::mutex> lock(mutex_);
        delete[] pool_;
    }

    void* allocate(size_t size) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (currentPoolSize_ < size) {
            cond_.wait(lock);
        }
        if (size > maxPoolSize_) {
            throw std::runtime_error("Cannot allocate memory. Requested size exceeds maximum pool size.");
        }
        void* allocatedMemory = &pool_[0] + currentPoolSize_;
        currentPoolSize_ += size;
        return allocatedMemory;
    }

    void deallocate(void* ptr, size_t size) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (&pool_[0] <= static_cast<char*>(ptr) && static_cast<char*>(ptr) < &pool_[currentPoolSize_]) {
            currentPoolSize_ -= size;
            cond_.notify_all();
        } else {
            throw std::runtime_error("Invalid deallocation request. Memory not allocated by this pool.");
        }
    }

private:
    char* pool_;
    std::mutex mutex_;
    std::condition_variable cond_;
    size_t maxPoolSize_;
    size_t currentPoolSize_;
};

class MemoryPoolManager {
public:
    static void setGlobalConfig(size_t initialSize, size_t maxSize) { globalConfig_ = Pool(initialSize, maxSize); }

    static void* allocate(size_t size) { return globalConfig_.allocate(size); }

    static void deallocate(void* ptr, size_t size) { globalConfig_.deallocate(ptr, size); }

private:
    static Pool globalConfig_;
};

Pool MemoryPoolManager::globalConfig_(16 * 1024, 64 * 1024);

} // namespace MemoryManager

