EVP_CIPHER_CTX* encrypt_decrypt(const char* file_path, const char* password) {
    // Initialize OpenSSL context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Derive key using PBKDF2
    unsigned char derived_key[32];
    int derived_key_len;
    if (PBKDF2(password, strlen(password), derived_key, &derived_key_len)) {
        printf("Error deriving key\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set AES-256-CBC parameters
    unsigned char iv[16];
    memset(iv, 0x00, sizeof(iv));
    int iv_len = 16;

    // Initialize encryption context
    if (!EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, derived_key, derived_key_len)) {
        printf("Error initializing encryption context\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set IV and key for encryption
    if (!EVP_CipherSettings_set(ctx, iv, iv_len)) {
        printf("Error setting IV and key\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Perform encryption/decryption operation
    FILE* file = fopen(file_path, "rb+");
    if (file) {
        fseek(file, 0, SEEK_END);
        long size = ftell(file);
        rewind(file);

        char* buffer = malloc(size);
        fread(buffer, 1, size, file);
        fclose(file);

        int ret;
        unsigned char* out = buffer;

        // Encrypt/decrypt file contents
        while (*out) {
            ret = EVP_CipherUpdate(ctx, out, &size);
            if (ret <= 0) break;
            out += ret;
        }

        free(buffer);
    } else {
        printf("Error opening file\n");
    }

    // Get encryption status report
    long total_processing_time = EVP_CipherGetTotalProcessingTime(ctx);
    int successful_attempts = EVP_CipherGetSuccessfulAttempts(ctx);
    int failed_attempts = EVP_CipherGetFailedAttempts(ctx);

    // Print status report
    printf("Encryption/decryption operation completed in %ld seconds with %d successful and %d failed attempts.\n", total_processing_time, successful_attempts, failed_attempts);

    return ctx;
}

int main() {
    const char* file_path = "path/to/file";
    const char* password = "your_password";

    EVP_CIPHER_CTX* ctx = encrypt_decrypt(file_path, password);
    if (ctx) {
        // Use the context for encryption or decryption
        EVP_CIPHER_CTX_free(ctx);
    }

    return 0;
}

