#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>

typedef struct Node {
    char* path;
    int size;
    time_t mtime;
    struct Node* parent;
    struct Node* children;
    pthread_mutex_t lock;
} Node;

Node* create_node(char* path) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->path = strdup(path);
    node->size = 0;
    node->mtime = 0;
    node->parent = NULL;
    node->children = NULL;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void process_file_path(char* path) {
    Node* root = create_node("/");
    Node* current = root;

    char* token = strtok(path, "/");
    while (token != NULL) {
        Node* child = current->children;
        while (child != NULL && strcmp(token, child->path) < 0) {
            child = child->next;
        }

        if (child == NULL || strcmp(token, child->path) != 0) {
            child = create_node(token);
            child->parent = current;
            pthread_mutex_lock(&current->lock);
            if (!current->children)
                current->children = child;
            else {
                Node* temp = current->children;
                while (temp->next)
                    temp = temp->next;
                temp->next = child;
            }
            pthread_mutex_unlock(&current->lock);
        }

        token = strtok(NULL, "/");
        if (token != NULL) {
            current = child;
        } else {
            break;
        }
    }
}

void free_tree(Node* node) {
    if (!node)
        return;

    Node* temp = node->children;
    while (temp) {
        Node* next = temp->next;
        free_tree(temp);
        free(temp);
        temp = next;
    }

    pthread_mutex_destroy(&node->lock);
    free(node->path);
    free(node);
}

int main() {
    // Initialize the tree
    Node* root = create_node("/");

    // Process file paths
    char* path1[] = {"/dir1/file1.txt", "/dir2/file2.txt"};
    char* path2[] = {"/dir3/file3.txt", "/dir4/file4.txt"};

    process_file_path(path1[0]);
    process_file_path(path1[1]);
    process_file_path(path2[0]);
    process_file_path(path2[1]);

    // Free the tree
    free_tree(root);

    return 0;
}
