using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class ResourceHandler
{
    private readonly HttpClient _httpClient;
    private readonly Random _random = new Random();

    public ResourceHandler(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateResource([FromUri]int resourceId, [FromBody]JsonUpdateRequest request)
    {
        if (!ValidateRequest(request))
            return BadRequest("Invalid request");

        // Handle metadata and optional dependencies
        // ...

        try
        {
            var response = await _httpClient.PutAsync($"api/resources/{resourceId}", new StringContent(JsonConvert.SerializeObject(request), Encoding.UTF8, "application/json"));
            response.EnsureSuccessStatusCode();
            return Ok(new { message = $"Resource {resourceId} updated successfully" });
        }
        catch (HttpRequestException ex)
        {
            LogError(ex);
            // Fallback mechanism to use default values for missing dependencies
            // ...
            return InternalServerError("Failed to update resource");
        }
    }

    [HttpDelete]
    public async Task<IActionResult> DeleteResource([FromUri]int resourceId)
    {
        try
        {
            var response = await _httpClient.DeleteAsync($"api/resources/{resourceId}");
            response.EnsureSuccessStatusCode();
            // Return a new resource with default values upon successful deletion
            return Ok(new { message = $"Resource {resourceId} deleted successfully" });
        }
        catch (HttpRequestException ex)
        {
            LogError(ex);
            return InternalServerError("Failed to delete resource");
        }
    }

    private void LogError(Exception ex)
    {
        // Log the error with detailed information
        // ...

        if (_random.Next(0, 3) > 0)
        {
            // Retry the operation up to three times before failing permanently
            await Task.Delay(TimeSpan.FromMilliseconds(_random.Next(100, 500)));
            try
            {
                return UpdateResource(resourceId, request);
            }
            catch (Exception ex2)
            {
                LogError(ex2);
                throw;
            }
        }
        else
        {
            // Permanent failure
            throw;
        }
    }

    private bool ValidateRequest(JsonUpdateRequest request)
    {
        // Validate the incoming JSON structure
        // ...
        return true; // or false if invalid
    }
}

public class JsonUpdateRequest
{
    public int Id { get; set; }
    public Metadata Metadata { get; set; }
    public OptionalDependencies Dependencies { get; set; }
}

public class Metadata
{
    public string Key1 { get; set; }
    public string Key2 { get; set; }
}

public class OptionalDependencies
{
    public int DependencyId1 { get; set; }
    public int DependencyId2 { get; set; }
}
