#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct Record {
    int value;
    struct Record* prev;
    struct Record* next;
} Record;

Record* insert(Record** head, int value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if(new_record == NULL) {
        return NULL;
    }
    new_record->value = value;
    new_record->prev = NULL;
    new_record->next = *head;
    if(*head != NULL) {
        (*head)->prev = &new_record->next;
    } else {
        *head = &new_record->next;
    }
    *head = new_record;
    return *head;
}

void delete(Record** head, Record* node) {
    if(node == *head) {
        if(node->next != NULL) {
            node->next->prev = NULL;
            *head = node->next;
        } else {
            *head = NULL;
        }
    } else {
        node->prev->next = node->next;
        if(node->next != NULL) {
            node->next->prev = node->prev;
        } else {
            node->prev->next = NULL;
        }
    }
    free(node);
}

void init_records(Record** records, int size) {
    srand(time(NULL));
    *records = (Record*)malloc(sizeof(Record)*size);
    for(int i=0; i<size; i++) {
        (*records)[i].value = rand() % 100;
    }
}
