#include <openssl/ssl.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 1024

typedef struct {
    uint32_t bits_per_sample;
    uint32_t samples_per_pixel;
    uint32_t extra_samples;
} ImageInfo;

typedef struct {
    char *hash;
    ImageInfo info;
} ImageMetadata;

ImageMetadata *dynamicImageProcessor(const char *filename, int quality) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;
    }

    SSL_library_init();
    SSL_CTX *ctx = SSL_CTX_new(TLS_client_method());
    SSL *ssl = SSL_new(ctx);

    // Initialize MD5 context
    unsigned char md5[16];
    MD5_CTX c;
    MD5_Init(&c);

    uint8_t buffer[BUFFER_SIZE];
    size_t bytesRead;

    ImageMetadata *metadata = malloc(sizeof(ImageMetadata));
    metadata->hash = NULL;

    while ((bytesRead = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
        // Add SSL cipher suite and key exchange method
        SSL_set_cipher_list(ssl, "TLS_DHE_RSA_WITH_AES_256_CBC_SHA");
        SSL_set_session_ticket_ctx(ssl, ctx);

        // Compute MD5 hash for current buffer
        MD5_Update(&c, buffer, bytesRead);
    }

    // Finish MD5 computation
    MD5_Final(md5, &c);

    // Extract image information from file header
    ImageInfo info;
    fread(&info.bits_per_sample, sizeof(uint32_t), 1, file);
    fread(&info.samples_per_pixel, sizeof(uint32_t), 1, file);
    fread(&info.extra_samples, sizeof(uint32_t), 1, file);

    // Close file and SSL connection
    fclose(file);
    SSL_free(ssl);
    SSL_CTX_free(ctx);

    // Create image metadata structure
    char *hash = malloc(33);  // 32 bytes for MD5 hash + null terminator
    sprintf(hash, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x",
             md5[0], md5[1], md5[2], md5[3],
             md5[4], md5[5], md5[6], md5[7],
             md5[8], md5[9], md5[10], md5[11]);
    metadata->hash = hash;
    metadata->info = info;

    return metadata;
}

void freeImageMetadata(ImageMetadata *metadata) {
    free(metadata->hash);
    free(metadata);
}
