// Define a structure for a semaphore
typedef struct {
    int value;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} semaphore_t;

// Define a structure for the semaphore pool
typedef struct {
    int max_size;
    int current_size;
    semaphore_t* semaphores;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} semaphore_pool_t;

// Function to create a new semaphore
semaphore_t* create_semaphore(int value, int timeout) {
    semaphore_t* semaphore = (semaphore_t*)malloc(sizeof(semaphore_t));
    if (!semaphore) return NULL;

    semaphore->value = value;
    pthread_mutex_init(&semaphore->lock, NULL);
    pthread_cond_init(&semaphore->cond, NULL);

    // Add the semaphore to the pool
    semaphore_pool_t* pool = get_semaphore_pool();
    if (pool && pool->current_size < pool->max_size) {
        pool->semaphores[pool->current_size] = semaphore;
        pool->current_size++;
    }

    return semaphore;
}

// Function to delete a semaphore
void delete_semaphore(semaphore_t* semaphore) {
    // Release the semaphore from the pool
    semaphore_pool_t* pool = get_semaphore_pool();
    if (pool && pool->semaphores && pool->semaphores[pool->current_size-1] == semaphore) {
        pool->current_size--;
        free(semaphore);
    }
}

// Function to acquire a semaphore with timeout
int acquire_semaphore(semaphore_t* semaphore, int timeout) {
    // Acquire the mutex lock
    pthread_mutex_lock(&semaphore->lock);

    // Wait for the semaphore if necessary
    while (semaphore->value <= 0) {
        pthread_cond_wait(&semaphore->cond, &semaphore->lock);
        if (timeout && pthread_mutex_lock(&semaphore->lock)) return -1; // timed out
    }

    // Decrement the semaphore value
    semaphore->value--;

    // Release the mutex lock
    pthread_mutex_unlock(&semaphore->lock);

    return 0;
}

// Function to release a semaphore
void release_semaphore(semaphore_t* semaphore) {
    // Acquire the mutex lock
    pthread_mutex_lock(&semaphore->lock);

    // Increment the semaphore value
    semaphore->value++;

    // Signal any threads waiting for the semaphore
    pthread_cond_signal(&semaphore->cond);

    // Release the mutex lock
    pthread_mutex_unlock(&semaphore->lock);
}

// Function to get the current semaphore pool size
int get_semaphore_pool_size() {
    semaphore_pool_t* pool = get_semaphore_pool();
    return pool ? pool->current_size : 0;
}

// Function to get the current semaphore pool maximum size
int get_semaphore_pool_max_size() {
    semaphore_pool_t* pool = get_semaphore_pool();
    return pool ? pool->max_size : 0;
}

// Function to set the current semaphore pool maximum size
void set_semaphore_pool_max_size(int max_size) {
    semaphore_pool_t* pool = get_semaphore_pool();
    if (pool) pool->max_size = max_size;
}

