#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
} record_t;

record_t* init_records(int num_records, int min_val, int max_val) {
    record_t* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;

    // Allocate memory for arrays
    records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Error allocating memory for records\n");
        return NULL;
    }

    offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        free(records);
        fprintf(stderr, "Error allocating memory for offsets\n");
        return NULL;
    }

    keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        fprintf(stderr, "Error allocating memory for keys\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % (max_val - min_val + 1) + min_val;
        offsets[i] = i * sizeof(record_t);
        keys[i] = i;
    }

    return records;
}
