        max_dataset_size = size;
        dataset = (record*) realloc(dataset, sizeof(record) * size);
    }
}

void add_record(int offset, int key, int value) {
    record* new_dataset = NULL;
    int new_dataset_size;

    // Dynamically resize the dataset if necessary
    if (dataset_size + 1 > max_dataset_size) {
        max_dataset_size *= 2;
        new_dataset = (record*) realloc(dataset, sizeof(record) * max_dataset_size);
        if (!new_dataset) {
            printf("Memory allocation failed!\n");
            exit(1);
        }
    }

    // Add the new record
    dataset[dataset_size].offset = offset;
    dataset[dataset_size].key = key;
    dataset[dataset_size].value = value;

    // Update pointers and sizes
    if (new_dataset) {
        new_dataset_size = max_dataset_size;
        free(dataset);
        dataset = new_dataset;
        max_dataset_size = new_dataset_size;
    }

    dataset_size++;
}

int search_record(int key) {
    for (int i = 0; i < dataset_size; i++) {
        if (dataset[i].key == key) {
            return dataset[i].value;
        }
    }

    return -1; // Record not found
