public class DataLoader
{
    private readonly ILogger _logger;
    private readonly Settings _settings;

    public DataLoader(ILogger logger, Settings settings)
    {
        _logger = logger;
        _settings = settings;
    }

    public async Task LoadAndDeserializeDataAsync(string filePath)
    {
        using (FileStream fileStream = File.Open(filePath, FileMode.Open))
        {
            GZipStream gzipStream = new GZipStream(fileStream, CompressionMode.Decompress);
            BinaryFormatter formatter = new BinaryFormatter();

            while (await ReadChunkAsync(gzipStream, ref fileStream))
            {
                try
                {
                    DataSegment segment = (DataSegment)formatter.Deserialize(gzipStream);
                    ValidateSegment(segment);
                    await ProcessSegmentAsync(segment);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error deserializing data segment");
                }
            }

            fileStream.Dispose();
        }
    }

    private async Task<bool> ReadChunkAsync(GZipStream gzipStream, ref FileStream fileStream)
    {
        byte[] buffer = new byte[_settings.BufferSize];
        int bytesRead = await gzipStream.ReadAsync(buffer, 0, _settings.BufferSize);
        if (bytesRead == 0) return false;

        string hash = CalculateChecksum(gzipStream);
        if (!await ValidateHashAsync(hash)) continue;

        await gzipStream.FlushAsync();
        fileStream.Position += bytesRead;
        return true;
    }

