    public void ExecuteAttackWithCooldown()
    {
        int selectedAttack = new Random().Next(1, 4); // Select attack A, B or C
        XPathDocument doc = new XPathDocument("config.xml");
        XPathNavigator nav = doc.CreateNavigator();
        string attackName = $"attack{selectedAttack}";
        int cooldownAttempts = 0;
        bool subdirectoryCreated = false;

        while (cooldownAttempts < 3)
        {
            try
            {
                // Parse XML configuration file using XPath to find the first element matching a specific name
                XPathNodeIterator nodes = nav.Select("//attack[@name='" + attackName + "']");
                if (nodes.Count > 0)
                {
                    string configPath = nodes.Current.GetAttribute("config", "");
                    string newPath = Path.Combine("Data", attackName);
                    try
                    {
                        // Create subdirectory within the 'Data' folder
                        Directory.CreateDirectory(newPath);
                        subdirectoryCreated = true;
                    }
                    catch (Exception ex)
                    {
                        // Handle permissions issues
                        Console.WriteLine($"Error creating directory: {ex.Message}");
                        continue;
                    }

                    // Set environment variable to the path of the newly created subdirectory
                    Environment.SetEnvironmentVariable("SelectedAttack", newPath);

                    break;
                }
            }
            catch (XPathException ex)
            {
                // Handle XML parsing errors
                Console.WriteLine($"Error parsing XML: {ex.Message}");
            }
        }

        if (!subdirectoryCreated)
        {
            Console.WriteLine("Failed to create directory. Falling back to default attack.");
        }

        // Print the selected attack number to the console
        Console.WriteLine($"Selected Attack: {selectedAttack}");

        // Wait for 9 seconds before returning
        System.Threading.Thread.Sleep(9000);
    }
