import java.util.Random;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class RecordManager {
    private static final int MAX_RECORDS = 1000;
    private static final int MAX_MEMORY_BUDGET = 1024 * 1024; // 1MB
    private static final Random random = new Random();

    private long[] offsets;
    private int[] keys;
    private Lock lock = new ReentrantLock();
    private boolean serviceRunning = false;
    private int recordCount = 0;

    public void startService(int delayMin, int delayMax) {
        if (!serviceRunning) {
            try {
                Thread.sleep(random.nextInt(delayMax - delayMin) + delayMin);
                serviceRunning = true;
            } catch (InterruptedException e) {
                // Handle interrupt
            }
        }
    }

    public void stopService() {
        if (serviceRunning) {
            try {
                Thread.sleep(random.nextInt(1000)); // Random delay between 0-1 second
                sendStopMessage();
                serviceRunning = false;
            } catch (InterruptedException e) {
                // Handle interrupt
            }
        }
    }

    private void sendStopMessage() {
        // Code to send message to external messaging system goes here
    }

    public void addRecord(int value, int key) {
        lock.lock();
        try {
            if (recordCount >= MAX_RECORDS || offsetMemoryUsage() > MAX_MEMORY_BUDGET) {
                throw new RecordLimitExceededException("Maximum number of records exceeded");
            }
            offsets[recordCount] = random.nextInt(); // Initialize with a random value
            keys[recordCount++] = key;
        } finally {
            lock.unlock();
        }
    }

    private long offsetMemoryUsage() {
        return recordCount * Long.BYTES; // Calculate memory usage based on the number of records
    }

    public RecordManager() {
        offsets = new long[MAX_RECORDS];
        keys = new int[MAX_RECORDS];
    }
}

class RecordLimitExceededException extends RuntimeException {
    public RecordLimitExceededException(String message) {
        super(message);
    }
}
