    if (!record) {
        printf("Memory allocation failed\n");
        exit(-1);
    }
    record->value = value;
    record->prev = NULL;
    record->next = NULL;
    return record;
}

void destroy_record(Record* record) {
    free(record);
}

void print_list(Record* head) {
    Record* current = head;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }
    printf("\n");
}

int main() {
    int size, seed;
    scanf("%d %d", &size, &seed);

    if (size <= 0) {
        printf("Invalid size\n");
        return -1;
    }

    srand(seed);

    Record* head = NULL;
    Record* tail = NULL;

    for (int i = 0; i < size; i++) {
        int value = rand() % 100;
        Record* record = create_record(value);
        if (head == NULL) {
            head = record;
            tail = record;
        } else {
            record->prev = tail;
            tail->next = record;
            tail = record;
        }
    }

    print_list(head);

    return 0;
}
