using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace TripleDesEncryption
{
    public class DecryptionManager : IDisposable
    {
        private readonly object _lock = new object();
        private readonly Dictionary<string, Tuple<byte[], byte[]>> _keysAndIvs = new Dictionary<string, Tuple<byte[], byte[]>>(StringComparer.OrdinalIgnoreCase);
        private readonly ILogger _logger;
        private readonly IApiService _apiKeyService;

        public DecryptionManager(ILogger logger, IApiService apiKeyService)
        {
            _logger = logger;
            _apiKeyService = apiKeyService;
        }

        public void AddKeyAndIv(string keyName, byte[] key, byte[] iv)
        {
            if (key == null || iv == null)
                throw new ArgumentNullException("Both key and IV must be provided");

            if (key.Length != 192 / 8 && key.Length != 224 / 8 && key.Length != 256 / 8)
                throw new ArgumentException("Invalid key length. It should be 24 bytes for Triple DES 168, 28 bytes for Triple DES 224 or 32 bytes for Triple DES 256");

            if (iv.Length != 64 / 8)
                throw new ArgumentException("Invalid IV length. It should be 8 bytes for Triple DES");

            _keysAndIvs.Add(keyName, Tuple.Create(key, iv));
        }

        public byte[] Decrypt(string keyName, byte[] message)
        {
            lock (_lock)
            {
                if (!_keysAndIvs.ContainsKey(keyName))
                    throw new DecryptionFailedException("Key not found");

                var key = _keysAndIvs[keyName].Item1;
                var iv = _keysAndIvs[keyName].Item2;

                using (var ms = new MemoryStream(message))
                {
                    using (var cryptStream = new CryptoStream(ms, TripleDes.CreateDecryptor(key, iv), CryptoStreamMode.Read))
                    {
                        return cryptStream.ToArray();
                    }
                }
            }
        }

        public void Dispose()
        {
            _keysAndIvs.Clear();
        }
    }

    public class DecryptionFailedException : Exception
    {
        public DecryptionFailedException(string message) : base(message)
        {
        }
    }
}
