    for(int i = 0; i < num_records; i++) {
        time_t timestamp = time(NULL);
        int value = rand() % 100; // random value within [0, 99]
        records[i] = create_record(value, timestamp);
    }

    // Update record status based on conditions
    for(int i = 0; i < num_records; i++) {
        if(records[i]->timestamp < (time(NULL) - 60 * 60)) { // expired
            records[i]->status = 0;
