#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char* filename;
    time_t last_modified;
    bool is_open_for_writing;
    struct node* next;
} metadata_entry;

metadata_entry* metadata = NULL;
metadata_entry* head = NULL;

void add_metadata_entry(char* filename, time_t last_modified, bool is_open_for_writing) {
    metadata_entry* new_entry = (metadata_entry*)malloc(sizeof(metadata_entry));
    new_entry->filename = strdup(filename);
    new_entry->last_modified = last_modified;
    new_entry->is_open_for_writing = is_open_for_writing;
    new_entry->next = head;
    head = new_entry;
}

void update_metadata_entry(char* filename, time_t last_modified, bool is_open_for_writing) {
    metadata_entry* current = head;
    while (current != NULL) {
        if (strcmp(current->filename, filename) == 0) {
            current->last_modified = last_modified;
            current->is_open_for_writing = is_open_for_writing;
            break;
        }
        current = current->next;
    }
}

void remove_metadata_entry(char* filename) {
    metadata_entry* current = head;
    metadata_entry* previous = NULL;
    while (current != NULL) {
        if (strcmp(current->filename, filename) == 0) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->filename);
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
}

void iterate_metadata() {
    metadata_entry* current = head;
    while (current != NULL) {
        printf("Filename: %s, Last Modified: %ld, Is Open For Writing: %d\n", current->filename, current->last_modified, current->is_open_for_writing);
        current = current->next;
    }
}

void handle_collision(char* filename) {
    // separate chaining with linked lists
    metadata_entry* new_list_head = NULL;
    metadata_entry* new_list_tail = NULL;

    metadata_entry* current = head;
    while (current != NULL) {
        if (strcmp(current->filename, filename) == 0) {
            // collision detected
            metadata_entry* new_entry = (metadata_entry*)malloc(sizeof(metadata_entry));
            new_entry->filename = strdup(filename);
            new_entry->last_modified = time(NULL);
            new_entry->is_open_for_writing = false;
            if (new_list_tail != NULL) {
                new_list_tail->next = new_entry;
                new_list_tail = new_entry;
            } else {
                new_list_head = new_entry;
                new_list_tail = new_entry;
            }
        }
        current = current->next;
    }

    // merge the collision list with the original list
    metadata_entry* original_tail = NULL;
    current = head;
    while (current != NULL) {
        if (original_tail == NULL) {
            original_head = current;
            original_tail = current;
        } else {
            original_tail->next = current;
            original_tail = current;
        }
        current = current->next;
    }

    // merge the collision list with the original tail
    original_tail->next = new_list_head;
}

void log_system_behavior(char* message) {
    FILE* log_file = fopen("system_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int main() {
    // initialize the system
    metadata_entry* new_entry = (metadata_entry*)malloc(sizeof(metadata_entry));
    new_entry->filename = strdup("example.txt");
    new_entry->last_modified = time(NULL);
    new_entry->is_open_for_writing = false;
    head = new_entry;

    // add, update, and remove entries
    add_metadata_entry("file1.txt", 1643723400, true);
    update_metadata_entry("file2.txt", 1643760000, false);
    remove_metadata_entry("example.txt");

    // iterate over the metadata
    iterate_metadata();

    // handle collisions
    handle_collision("collision_file.txt");

    // log system behavior
    log_system_behavior("System initialized successfully");

    return 0;
}
