    // Sort points based on y-coordinate
    for (int i = 0; i < 5 - 1; i++) {
        for (int j = 0; j < 4; j++) {
            if (points[j].y > points[j + 1].y) {
                struct point temp = points[j];
                points[j] = points[j + 1];
                points[j + 1] = temp;
