    // Initialize array for 'struct metadata' objects
    Metadata *metadata = (Metadata *)malloc(*numPoints * sizeof(Metadata));

    // Populate floating-point array using provided timestamps and status flags
    for (int i = 0; i < *numPoints; i++) {
        points[i].x = sin(timestamps[i]);
        points[i].y = cos(timestamps[i]);

        metadata[i].timestamp = timestamps[i];
        metadata[i].statusFlags = statusFlags[i];

        // Process data through trigonometric functions
        floatValues[i] = sqrt(pow(points[i].x, 2) + pow(points[i].y, 2));
    }

    return (void *)floatValues;
}
