typedef struct {
    char* word;
    int count;
} string_entry;

// Define structure for word_node in binary search tree
typedef struct node {
    char* word;
    struct node* left;
    struct node* right;
} word_node;

// Function to process input strings and manage memory
void process_strings() {
    // Initialize variables
    int batch_size = 0;
    int total_size = 0;
    int count = 0;
    string_entry** hash_table = NULL;
    word_node* tree_root = NULL;
    json_object* config = NULL;

    // Parse configuration file
    config = json_object_from_file("config.json");
    if (json_object_get_type(config) != json_type_object) {
        printf("Error: Invalid or incomplete configuration file.\n");
        return;
    }

    batch_size = json_object_get_int(config, "batch_size");
    total_size = json_object_get_int(config, "total_size");

    // Initialize hash table
    hash_table = (string_entry**)malloc(batch_size * sizeof(string_entry*));
    for (int i = 0; i < batch_size; i++) {
        hash_table[i] = (string_entry*)malloc(sizeof(string_entry));
    }

    // Initialize binary search tree
    tree_root = malloc(sizeof(word_node));
    tree_root->word = NULL;
    tree_root->left = NULL;
    tree_root->right = NULL;

    // Process input strings in batches
    while (1) {
        char* line = NULL;
        int len = 0;

        // Read line from standard input
        printf("Enter a string (or press Ctrl+D to finish): ");
        if (!fgets(line, sizeof(char) * 1024, stdin)) {
            break;
        }

        // Process line and update hash table and binary search tree
        len = strlen(line);
        for (int i = 0; i < len; i++) {
            char c = tolower(line[i]);
            string_entry* entry = NULL;

            // Check if word is already in the hash table
            for (int j = 0; j < batch_size; j++) {
                if (!hash_table[j]->word) {
                    entry = hash_table[j];
                    break;
                }
            }

            // Add new word to hash table and binary search tree
            if (!entry->word) {
                entry->word = (char*)malloc((len + 1) * sizeof(char));
                strcpy(entry->word, line);
                entry->count++;

                // Balance the binary search tree
                tree_root = balance_tree(tree_root);

                // Update batch size and total size
                if (total_size < len) {
                    total_size = len;
                }
            } else if (strcmp(entry->word, line)) {
                // Update hash table and binary search tree for existing word
                entry->count++;
                tree_root = balance_tree(tree_root);
            }

            free(line);
        }
    }

    // Free memory allocated by the function
    for (int i = 0; i < batch_size; i++) {
        free(hash_table[i]->word);
        free(hash_table[i]);
    }
    free(hash_table);

    free(tree_root->word);
    free(tree_root);

    printf("Longest string: %s\n", get_longest_string());
}

