    int value;
    time_t timestamp;
} record_t;

// Doubly linked list node
typedef struct node {
    record_t *record;
    struct node *prev;
    struct node *next;
} node_t;

// Function to initialize metadata and allocate memory for components
metadata_t* init_metadata(int batch_size, int concurrency_level) {
    metadata_t *metadata = (metadata_t*)malloc(sizeof(metadata_t));
    if (!metadata) {
        printf("Error: Unable to allocate memory for metadata.\n");
        return NULL;
    }
    metadata->batch_size = batch_size;
    metadata->concurrency_level = concurrency_level;
    return metadata;
}

// Function to initialize and populate the doubly linked list
node_t* init_list(int size, int seed) {
    node_t *head = NULL;
    node_t *curr = NULL;
    for (int i = 0; i < size; i++) {
        record_t *record = (record_t*)malloc(sizeof(record_t));
        if (!record) {
            printf("Error: Unable to allocate memory for record.\n");
            return head;
        }
        record->value = rand_r(&seed) % 100 + 1; // Randomly generate an integer value
        time_t timestamp = time(NULL);
        record->timestamp = timestamp;

        node_t *node = (node_t*)malloc(sizeof(node_t));
        if (!node) {
            printf("Error: Unable to allocate memory for list node.\n");
            return head;
        }
        node->record = record;
        node->prev = NULL;
        node->next = NULL;

        if (head == NULL) {
            head = curr = node;
        } else {
            curr->next = node;
            node->prev = curr;
            curr = node;
        }
    }
    return head;
}

