    if (!metadata) {
        return -1;
    }

    node_t *list = init_list(metadata->batch_size, 0); // Initialize and populate the doubly linked list

    // Perform operations on the list...
    operate_list(&list, INSERTION); // Example: Insert a new record into the list

    // Release allocated memory
    for (node_t *curr = list; curr; curr = curr->next) {
        free(curr->record);
        free(curr);
    }

    return 0;
}

