    if (json_object_object_get_ex(config, "description_size", &json_object)) {
        *sizePtr = malloc(sizeof(int));
        **sizePtr = json_object_get_int(json_object);
    }
    if (json_object_object_get_ex(config, "log_file", &json_object)) {
        *logFile = malloc(strlen(json_object_get_string(json_object)) + 1);
        strcpy(*logFile, json_object_get_string(json_object));
    }
}

int main() {
    int numRecords;
    int* sizePtr;
    char** logFile;

    configureRecords(&numRecords, &sizePtr, &logFile);

    pthread_t threads[numRecords];
    for (int i = 0; i < numRecords; i++) {
        pthread_create(&threads[i], NULL, initializer, (void*)sizePtr);
    }
    for (int i = 0; i < numRecords; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close log file
    fclose(logFile);

    return 0;
}
