#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int priority;
    char name[20];
    float* data;
    size_t length;
} task;

task* create_tasks(size_t count, int start_value) {
    task* tasks = (task*)malloc(count * sizeof(task));
    if (!tasks) return NULL;

    pthread_mutex_lock(&global_resource_pool->mutex);

    for (size_t i = 0; i < count; i++) {
        task* task_ptr = &tasks[i];
        task_ptr->priority = i;
        sprintf(task_ptr->name, "Task %zu", i);
        task_ptr->length = i + 1;

        float* data = (float*)malloc((task_ptr->length) * sizeof(float));
        if (!data) {
            free(tasks);
            tasks = NULL;
            pthread_mutex_unlock(&global_resource_pool->mutex);
            return NULL;
        }

        for (int j = start_value; j < start_value + task_ptr->length; j++) {
            data[j - start_value] = (float)j;
        }
        task_ptr->data = data;
    }

    pthread_mutex_unlock(&global_resource_pool->mutex);

    return tasks;
}

void free_tasks(task* tasks, size_t count) {
    for (size_t i = 0; i < count; i++) {
        if (tasks[i].data) free(tasks[i].data);
    }
    free(tasks);
}
