```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define FLOATING_POINT_RANGE 10000.0

typedef struct {
    int offset;
    char* key;
    double* values;
    int length;
} Record;

Record** records = NULL;
int num_records = 0;
int active_readers = 0;
int active_writers = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int record_limit = MAX_RECORDS;
double floating_point_range = FLOATING_POINT_RANGE;

void* record_alloc(int length) {
    double* values = (double*)malloc(length * sizeof(double));
    if (!values) {
        perror("record_alloc");
        return NULL;
    }
    for (int i = 0; i < length; i++) {
        values[i] = (double)(rand() % (int)floating_point_range);
    }
    return values;
}

void record_free(Record* record) {
    if (record->values) {
        free(record->values);
        record->values = NULL;
    }
}

void add_record(int offset, char* key, int length) {
    pthread_mutex_lock(&mutex);
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        perror("add_record");
        return;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->values = record_alloc(length);
    new_record->length = length;
    records = (Record**)realloc(records, ++num_records * sizeof(Record*));
    if (!records) {
        perror("add_record");
        free(new_record);
        return;
    }
    records[num_records - 1] = new_record;
    pthread_mutex_unlock(&mutex);
}

void update_record(int offset, double value) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i]->offset == offset) {
            records[i]->values[0] = value;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void remove_record(int offset) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i]->offset == offset) {
            record_free(records[i]);
            memmove(records + i, records + i + 1, (num_records - i - 1) * sizeof(Record*));
            num_records--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void log_access(int type, char* user_id) {
    // implement logging mechanism here
}

int main() {
    // configure the system with desired parameters
    record_limit = 5000; // adjust the number of records
    floating_point_range = 10000.0; // adjust the range for random values

    pthread_t thread;
    pthread_create(&thread, NULL, &access_thread, "reader");
    pthread_join(thread, NULL);

    return 0;
}

void* access_thread(void* user_id) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (active_readers++ > record_limit / 2) { // implement the concurrency control mechanism here
            active_writers--;
            pthread_mutex_unlock(&mutex);
            log_access(0, (char*)user_id); // log access event
        } else {
            // perform read or write operations on records
            for (int i = 0; i < num_records; i++) {
                printf("%s: offset %d, values: ", (char*)user_id, records[i]->offset);
                for (int j = 0; j < records[i]->length; j++) {
                    printf("%.2f ", records[i]->values[j]);
                }
                printf("\n");
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}

