    time_t mod_time;
    struct Node** children;
    int num_children;
} Node;

// Create a new node with given metadata
Node* create_node(char* path, int size, time_t mod_time) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->path = strdup(path);
    node->size = size;
    node->mod_time = mod_time;
    node->children = NULL;
    node->num_children = 0;
    return node;
}

// Implement a balanced binary search tree for efficient operations
Node* bst_insert(Node* root, char* path) {
    if (root == NULL) {
        Node* new_node = create_node(path, 0, time(NULL));
        return new_node;
    }
    if (strcmp(path, root->path) < 0) {
        if (root->children[0] == NULL)
            root->children[0] = bst_insert(root->children[0], path);
        else
            bst_insert(root->children[0], path);
    } else if (strcmp(path, root->path) > 0) {
        if (root->children[1] == NULL)
            root->children[1] = bst_insert(root->children[1], path);
        else
            bst_insert(root->children[1], path);
    }
    return root;
}

// Function to process a continuously streaming list of file paths
void process_file_paths(char* input_stream) {
