#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int key;
    long offset;
    int value;
} Record;

typedef struct node {
    Record *record;
    struct node *prev;
    struct node *next;
} Node;

Node* create_node(Record *record) {
    Node *new_node = (Node*) malloc(sizeof(Node));
    new_node->record = record;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_record(Node **head, Record *record) {
    Node *new_node = create_node(record);
    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    }
}

void delete_record(Node **head, Record *record) {
    Node *curr = *head;
    while (curr != NULL && curr->record != record) {
        curr = curr->next;
    }
    if (curr == NULL) return; // not found
    if (curr->prev != NULL) {
        curr->prev->next = curr->next;
    } else {
        *head = curr->next;
    }
    if (curr->next != NULL) {
        curr->next->prev = curr->prev;
    }
    free(curr);
}

void print_largest(Node *head) {
    Record max_record = {0, 0, INT_MIN};
    Node *curr = head;
    while (curr != NULL) {
        if (curr->record->value > max_record.value) {
            max_record = *curr->record;
        }
        curr = curr->next;
    }
    printf("Largest value: %d\n", max_record.value);
}

void seed_rng(int seed) {
    srand(seed);
}

int get_random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

long* read_integers(int size, FILE *fp) {
    long *offsets = (long*) malloc(size * sizeof(long));
    int *keys = (int*) malloc(size * sizeof(int));
    Record **records = (Record**) malloc(size * sizeof(Record*));

    for (int i = 0; i < size; i++) {
        fscanf(fp, "%ld %d", &offsets[i], &keys[i]);
        records[i] = (Record*) malloc(sizeof(Record));
        records[i]->key = keys[i];
        records[i]->offset = offsets[i];
        records[i]->value = get_random_value(0, 100);
    }

    return offsets;
}

void process_integers(int size, long *offsets, int *keys) {
    Node *head = NULL;

    for (int i = 0; i < size; i++) {
        Record *record = records[i];
        insert_record(&head, record);
    }

    // print largest value
    print_largest(head);

    // free memory
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);
}

void concurrent_read(int size, FILE *fp) {
    long *offsets = read_integers(size, fp);

    // process integers
    process_integers(size, offsets, NULL); // no keys for concurrent read

    // free memory
    free(offsets);
}
