#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <json-c/json-c.h>

// Define a structure for a record
typedef struct {
    int key;
    int value;
} Record;

// Define a structure for the linked list node
typedef struct {
    Record data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize the random number generator
void init_rng(int seed) {
    srand(seed);
}

// Function to generate a random integer within a specified range
int rand_int(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Function to create a new record with a random value
Record* create_record(int key, int min_value, int max_value) {
    Record* record = malloc(sizeof(Record));
    record->key = key;
    record->value = rand_int(min_value, max_value);
    return record;
}

// Function to insert a new node into the linked list
void insert_node(Node** head, Node* newNode) {
    if (*head == NULL || (*head)->next == NULL) {
        *head = newNode;
        return;
    }

    newNode->next = (*head);
    (*head)->prev = newNode;
    *head = newNode;
}

// Function to delete a node from the linked list
void delete_node(Node** head, Node* node) {
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        *head = node->next;
    }

    if (node->next != NULL) {
        node->next->prev = node->prev;
    }
}

// Function to free all allocated memory
void cleanup(Node* head, Record* records, int num_records) {
    Node* current = head;
    while (current != NULL) {
        delete_node(&head, current);
        free(current);
        current = current->next;
    }

    for (int i = 0; i < num_records; i++) {
        free(records + i);
    }
}

// Function to find the largest integer in the array
void print_largest(int* numbers, int size) {
    int max = numbers[0];
    for (int i = 1; i < size; i++) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Function to parse the configuration file
void parse_config(json_object* config, int* min_value, int* max_value, int* seed) {
    json_object_obj_t* obj;
    json_object_array_t* array;

    // Parse the 'min' and 'max' values from the configuration file
    obj = json_object_object_get(config, "random_range");
    if (obj != NULL && json_object_object_size(obj) == 2) {
        *min_value = json_object_get_int(json_object_object_get(obj, "min"));
        *max_value = json_object_get_int(json_object_object_get(obj, "max"));
    } else {
        // Default values for 'min' and 'max'
        *min_value = 0;
        *max_value = 100;
    }

    // Parse the 'seed' value from the configuration file
    obj = json_object_object_get(config, "rng_seed");
    if (obj != NULL) {
        *seed = json_object_get_int(obj);
    } else {
        // Default seed value
        *seed = time(NULL);
    }
}

// Function to read integers from standard input and initialize the data structures
int main() {
    int num_records, min_value, max_value, seed;
    Record* records;
    Node* head;

    // Read the size of the input array
    scanf("%d", &num_records);

    // Allocate memory for the record array
    records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: Could not allocate memory for records.\n");
        return 1;
    }

    // Initialize the random number generator with a custom seed
    init_rng(seed);

    // Parse the configuration file and initialize the data structures
    json_object* config = json_object_from_file("config.json");
    parse_config(config, &min_value, &max_value, &seed);

    // Insert records into the linked list
    head = NULL;
    for (int i = 0; i < num_records; i++) {
        Record* record = create_record(i, min_value, max_value);
        insert_node(&head, record);
    }

    // Free all allocated memory
    cleanup(head, records, num_records);

    return 0;
}

