#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    int value;
    char status;  // 'A' for active, 'I' for inactive
    char* metadata;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DataStore;

DataStore* data_store_create(size_t initial_capacity) {
    DataStore* ds = (DataStore*)malloc(sizeof(DataStore));
    ds->records = (Record*)calloc(initial_capacity, sizeof(Record));
    ds->capacity = initial_capacity;
    ds->count = 0;
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

void data_store_insert(DataStore* ds, int key, int value, char status, const char* metadata) {
    pthread_mutex_lock(&ds->mutex);
    if (ds->count >= ds->capacity) {
        // Double capacity when needed
        size_t new_capacity = ds->capacity * 2;
        Record* new_records = (Record*)realloc(ds->records, new_capacity * sizeof(Record));
        ds->records = new_records;
        ds->capacity = new_capacity;
    }
    Record* record = &ds->records[ds->count];
    record->key = key;
    record->value = value;
    record->status = status;
    record->metadata = (char*)malloc(strlen(metadata) + 1);
    strcpy(record->metadata, metadata);
    ds->count++;
    pthread_mutex_unlock(&ds->mutex);
}

void data_store_delete(DataStore* ds, int key) {
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->records[i].key == key) {
            free(ds->records[i].metadata);
            memmove(&ds->records[i], &ds->records[i + 1], (ds->count - i - 1) * sizeof(Record));
            ds->count--;
            break;
        }
    }
    pthread_mutex_unlock(&ds->mutex);
}

void data_store_iterate(DataStore* ds, void (*callback)(const Record*)) {
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < ds->count; ++i) {
        callback(&ds->records[i]);
    }
    pthread_mutex_unlock(&ds->mutex);
}

void data_store_serialize(DataStore* ds, FILE* file) {
    pthread_mutex_lock(&ds->mutex);
    fwrite(&ds->capacity, sizeof(size_t), 1, file);
    fwrite(&ds->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < ds->count; ++i) {
        Record record;
        memcpy(&record, &ds->records[i], sizeof(Record));
        fwrite(&record, sizeof(Record), 1, file);
    }
    pthread_mutex_unlock(&ds->mutex);
}

DataStore* data_store_deserialize(FILE* file) {
    DataStore* ds = (DataStore*)malloc(sizeof(DataStore));
    size_t capacity;
    size_t count;
    fread(&capacity, sizeof(size_t), 1, file);
    fread(&count, sizeof(size_t), 1, file);
    ds->records = (Record*)calloc(capacity, sizeof(Record));
    ds->capacity = capacity;
    ds->count = count;
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

void data_store_cache(DataStore* ds, size_t max_size) {
    // Implement LRU cache eviction policy
}

void data_store_log(const char* message) {
    // Implement logging framework
}

void data_store_destroy(DataStore* ds) {
    pthread_mutex_unlock(&ds->mutex);
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i].metadata);
    }
    free(ds->records);
    free(ds);
}
