#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MAX_KEY 1000000
#define MAX_ID_LENGTH 256
#define MEMORY_POOL_SIZE 1024 * 1024 // 1MB memory pool

typedef struct {
    int key;
    char id[MAX_ID_LENGTH];
} Record;

Record* records = NULL;
int record_count = 0;
int memory_pool_index = 0;
int next_key = 0;
time_t last_flush = time(NULL) - 60; // Initial flush after 1 minute

void allocate_memory(int count) {
    int required_size = sizeof(Record) * count + MEMORY_POOL_SIZE;
    void* memory = malloc(required_size);
    if (!memory) {
        printf("Memory allocation failed!\n");
        exit(-1);
    }
    records = (Record*)(((char*)memory) + MEMORY_POOL_SIZE);
}

void initialize_memory(int count) {
    for (int i = 0; i < count; i++) {
        Record* record = &records[i];
        record->key = next_key++;
        int id_length = rand() % MAX_ID_LENGTH;
        char* id = (char*)record + sizeof(Record);
        for (int j = 0; j < id_length; j++)
            id[j] = 'a' + rand() % 26;
        id[id_length] = '\0';
    }
}

void add_record(int key, const char* id) {
    if (key >= MAX_KEY || strlen(id) >= MAX_ID_LENGTH) {
        printf("Invalid record data!\n");
        return;
    }
    Record* new_record = &records[record_count++];
    new_record->key = key;
    strcpy(new_record->id, id);
}

void flush_data() {
    if (time(NULL) - last_flush > 60) { // Flush every minute
        FILE* file = fopen("data.txt", "w");
        for (int i = 0; i < record_count; i++) {
            Record* record = &records[i];
            fprintf(file, "%d %s\n", record->key, record->id);
        }
        fclose(file);
        last_flush = time(NULL);
    }
}

void sort_records() {
    qsort(records, record_count, sizeof(Record), (int (*)(const void*, const void*))compareTo);
}

int compareTo(const void* a, const void* b) {
    Record* ra = (Record*)a;
    Record* rb = (Record*)b;
    if (ra->key < rb->key)
        return -1;
    else if (ra->key > rb->key)
        return 1;
    else
        return 0;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    allocate_memory(MAX_RECORDS);
    initialize_memory(MAX_RECORDS);

    while (true) {
        add_record(next_key++, "new_id");
        flush_data();
        sort_records();
    }

    return 0;
}
