#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define BUFFER_SIZE 1024

typedef struct {
    int value;
    char status;
    double timestamp;
    int event_type;
} record_t;

record_t* records = NULL;
int* keys = NULL;
long* offsets = NULL;
int* secondary = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;

void* malloc_helper(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_all() {
    pthread_mutex_lock(&mutex);
    if (records) free(records);
    if (keys) free(keys);
    if (offsets) free(offsets);
    if (secondary) free(secondary);
    pthread_mutex_unlock(&mutex);
}

int insert_record(int key, int value, char status, double timestamp, int event_type) {
    pthread_mutex_lock(&mutex);

    // Create a new record
    records = realloc(records, sizeof(record_t) * (MAX_RECORDS + 1));
    keys = realloc(keys, sizeof(int) * (MAX_RECORDS + 1));
    offsets = realloc(offsets, sizeof(long) * (MAX_RECORDS + 1));
    secondary = realloc(secondary, sizeof(int*) * (MAX_RECORDS + 1));

    // Initialize the record
    records[MAX_RECORDS].value = value;
    records[MAX_RECORDS].status = status;
    records[MAX_RECORDS].timestamp = timestamp;
    records[MAX_RECORDS].event_type = event_type;

    // Update keys, offsets, and secondary pointers
    keys[MAX_RECORDS] = key;
    offsets[MAX_RECORDS] = MAX_RECORDS;
    secondary[MAX_RECORDS] = &records[MAX_RECORDS];

    // Increment the record count
    MAX_RECORDS++;

    pthread_mutex_unlock(&mutex);

    // Log the insertion
    if (log_file) {
        char buffer[BUFFER_SIZE];
        sprintf(buffer, "Record inserted with key %d and value %d.\n", key, value);
        fwrite(buffer, 1, strlen(buffer), log_file);
    }

    return MAX_RECORDS;
}

int main() {
    // Initialize the logging system
    log_file = fopen("log.txt", "w");

    // Main loop: insert records concurrently from multiple threads
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, insert_thread, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    free_all();

    fclose(log_file);
    return 0;
}

void* insert_thread(void*) {
    // Generate random values within specified ranges
    int key = rand() % 10000;
    int value = rand() % 100;
    char status = (char)rand() % 2;
    double timestamp = (double)rand() / RAND_MAX;
    int event_type = rand() % 10;

    // Insert the record
    insert_record(key, value, status, timestamp, event_type);
}
