record* populate_records(int numOffsets, int numRecords, long minOffset, long maxOffset) {
    if (numOffsets <= 0 || numRecords <= 0) {
        return NULL;
    }

    record* offsets = (record*)malloc(numOffsets * sizeof(record));
    for (int i = 0; i < numOffsets; i++) {
        offsets[i].offset = random_in_range(minOffset, maxOffset);
    }

    record* keys = (record*)malloc(numOffsets * sizeof(record));
    for (int i = 0; i < numOffsets; i++) {
        keys[i].key = random_in_range(1, 100); // Assuming min and max values are from 1 to 100
    }

    record** recordsArr = (record**)malloc((numRecords + 1) * sizeof(record*));
    for (int i = 0; i < numRecords; i++) {
        recordsArr[i] = random_record(offsets, numOffsets);
    }
    recordsArr[numRecords] = NULL;

    free(offsets);
    free(keys);

    return recordsArr;
}

long random_in_range(long min, long max) {
    if (min > max) {
        return 0; // Edge case handling
    }

    return (rand() % ((max - min + 1) * sizeof(long))) + min;
}
