#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct for cache records
typedef struct {
    int key;
    long offset;
} CacheRecord;

// Define a struct for the custom hash table
typedef struct {
    CacheRecord** buckets;
    int capacity;
    int size;
    int (*hash_func)(int, int);
} CustomHashTable;

// Initialize the custom hash table with given capacity and hashing function
CustomHashTable* init_hash_table(int capacity, int (*hash_func)(int, int)) {
    CustomHashTable* table = (CustomHashTable*)malloc(sizeof(CustomHashTable));
    table->buckets = (CacheRecord**)calloc(capacity, sizeof(CacheRecord*));
    table->capacity = capacity;
    table->size = 0;
    table->hash_func = hash_func;
    return table;
}

// Resize the custom hash table when it reaches a certain load factor
void resize_hash_table(CustomHashTable* table) {
    int new_capacity = table->capacity * 2;
    CacheRecord** new_buckets = (CacheRecord**)calloc(new_capacity, sizeof(CacheRecord*));
    for (int i = 0; i < table->capacity; i++) {
        CacheRecord* bucket = table->buckets[i];
        while (bucket) {
            int index = table->hash_func(bucket->key, table->capacity);
            new_buckets[index] = bucket;
            bucket = bucket->next;
        }
    }
    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

// Insert a cache record into the hash table
void insert_record(CustomHashTable* table, int key, long offset) {
    int index = table->hash_func(key, table->capacity);
    CacheRecord* bucket = table->buckets[index];
    if (!bucket) {
        bucket = (CacheRecord*)malloc(sizeof(CacheRecord));
        bucket->key = key;
        bucket->offset = offset;
        table->buckets[index] = bucket;
    } else {
        while (bucket && bucket->next) {
            bucket = bucket->next;
        }
        bucket->next = (CacheRecord*)malloc(sizeof(CacheRecord));
        bucket->next->key = key;
        bucket->next->offset = offset;
    }
    table->size++;
}

// Delete a cache record from the hash table
void delete_record(CustomHashTable* table, int key) {
    int index = table->hash_func(key, table->capacity);
    CacheRecord* bucket = table->buckets[index];
    CacheRecord* prev = NULL;
    while (bucket && bucket->key != key) {
        prev = bucket;
        bucket = bucket->next;
    }
    if (!bucket) return; // Record not found
    if (prev) {
        prev->next = bucket->next;
    } else {
        table->buckets[index] = bucket->next;
    }
    free(bucket);
    table->size--;
}

// Retrieve a cache record from the hash table
CacheRecord* retrieve_record(CustomHashTable* table, int key) {
    int index = table->hash_func(key, table->capacity);
    CacheRecord* bucket = table->buckets[index];
    while (bucket && bucket->key != key) {
        bucket = bucket->next;
    }
    return bucket ? bucket : NULL; // Record not found
}

// Periodic background garbage collection to free unused memory
void gc(CustomHashTable* table) {
    for (int i = 0; i < table->capacity; i++) {
        CacheRecord* bucket = table->buckets[i];
        while (bucket) {
            CacheRecord* next = bucket->next;
            if (table->size <= table->capacity / 2) { // Low cache utilization
                free(bucket);
                bucket = next;
            } else {
                bucket = next;
            }
        }
    }
}

// Main function to demonstrate the cache management
int main() {
    int (*hash_func)(int, int) = (int key, int capacity) -> hash(key, capacity);

    CustomHashTable* table = init_hash_table(16, hash_func);

    insert_record(table, 1, 1000);
    insert_record(table, 2, 2000);
    insert_record(table, 3, 3000);

    CacheRecord* record = retrieve_record(table, 2);
    printf("Offset for key 2: %ld\n", record->offset);

    delete_record(table, 2);

    gc(table);

    return 0;
}

