typedef struct {
    int id;
    int priority;
    char* description;
} Task;

Task* task_list = NULL;
int task_count = 0;

void init_task_list(int max_id, int min_priority, int max_priority) {
    srand(time(NULL));
    for (int i = 1; i <= max_id; i++) {
        Task* new_task = malloc(sizeof(Task));
        new_task->id = i;
        new_task->priority = rand() % (max_priority - min_priority + 1) + min_priority;
        char buffer[100];
        sprintf(buffer, "Task %d", i);
        new_task->description = strdup(buffer);
        task_list = realloc(task_list, (task_count + 1) * sizeof(Task));
        task_list[task_count] = new_task;
        task_count++;
    }
}

void add_task(int id, int priority, char* description) {
    Task* new_task = malloc(sizeof(Task));
    new_task->id = id;
    new_task->priority = priority;
    new_task->description = strdup(description);
    task_list = realloc(task_list, (task_count + 1) * sizeof(Task));
    task_list[task_count] = new_task;
    task_count++;
}

void remove_task(int id) {
    for (int i = 0; i < task_count; i++) {
        if (task_list[i]->id == id) {
            free(task_list[i]->description);
            free(task_list[i]);
            memmove(&task_list[i], &task_list[i + 1], (task_count - i - 1) * sizeof(Task));
            task_count--;
            return;
        }
    }
}

void iterate_tasks() {
    for (int i = 0; i < task_count; i++) {
        printf("Task %d: Priority %d, Description: %s\n", task_list[i]->id, task_list[i]->priority, task_list[i]->description);
    }
}

void sort_tasks(int min_priority, int max_priority) {
    qsort(task_list, task_count, sizeof(Task), compare_tasks);
}

int compare_tasks(const void* a, const void* b) {
    Task* task1 = *(Task*)a;
    Task* task2 = *(Task*)b;
    if (task1->priority < task2->priority)
        return -1;
    else if (task1->priority > task2->priority)
        return 1;
    return 0;
}

void filter_tasks(int min_priority, int max_priority) {
    for (int i = 0; i < task_count; i++) {
        if (task_list[i]->priority < min_priority || task_list[i]->priority > max_priority) {
            free(task_list[i]->description);
            free(task_list[i]);
            memmove(&task_list[i], &task_list[i + 1], (task_count - i - 1) * sizeof(Task));
            task_count--;
            i--;
        }
    }
}

Task* get_task_list() {
    return task_list;
}
