    struct file_info** files = NULL;
    int num_files = 0;

    // Initialize the list of files
    while ((dent = readdir(dirp)) != NULL) {
        char path[1024];
        sprintf(path, "%s/%s", "./", dent->d_name);

        // Check if the file is a regular file and not a directory
        if (stat(path, &statbuf) == 0 && S_ISREG(statbuf.st_mode)) {
            struct file_info* file = (struct file_info*) malloc(sizeof(struct file_info));
            file->file_path = strdup(dent->d_name);
            file->file_size = statbuf.st_size;
            file->last_modified_time = statbuf.st_mtime;
            file->access_permissions = get_file_access_permissions(file->file_path);

            // Add the new file to the list
            files = (struct file_info**) realloc(files, sizeof(struct file_info*) * (num_files + 1));
            files[num_files++] = file;
        }
    }

    // Free all allocated resources before returning
    for (int i = 0; i < num_files; i++) {
        free(files[i]->file_path);
        free(files[i]);
    }
    free(files);

    closedir(dirp);
}

