#define MAX_FILE_ENTRIES 10000

typedef struct {
    char file_name[256];
    int content_length;
    time_t modification_time;
    int access_mode; // 0: read-only, 1: read-write
} file_entry;

file_entry* file_entries = NULL;
int num_file_entries = 0;

void add_file_entry(const char* file_name) {
    file_entry* new_entry = (file_entry*) malloc(sizeof(file_entry));
    strcpy(new_entry->file_name, file_name);
    new_entry->content_length = 0;
    new_entry->modification_time = time(NULL);

    if (strchr(file_name, 'log') != NULL) {
        new_entry->access_mode = 0; // read-only
    } else {
        new_entry->access_mode = 1; // read-write
    }

    file_entries = realloc(file_entries, (num_file_entries + 1) * sizeof(file_entry));
    file_entries[num_file_entries] = *new_entry;
    num_file_entries++;

    free(new_entry);
}

int serialize_file_entries(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return -1; // error
    }

    for (int i = 0; i < num_file_entries; i++) {
        fwrite(&file_entries[i], sizeof(file_entry), 1, file);
    }

    fclose(file);
    return 0;
}

int deserialize_file_entries(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // error
    }

    file_entries = (file_entry*) malloc(MAX_FILE_ENTRIES * sizeof(file_entry));
    num_file_entries = 0;

    while (fread(&file_entries[num_file_entries], sizeof(file_entry), 1, file) == 1) {
        num_file_entries++;
    }

    fclose(file);
    return 0;
}

void free_file_entries() {
    for (int i = 0; i < num_file_entries; i++) {
        free(&file_entries[i]);
    }
    free(file_entries);
}
