typedef struct {
    char* key;
    union {
        int integer_value;
        double floating_point_value;
        char* string_value;
        bool boolean_value;
    } value;
} configuration_pair;

typedef struct node {
    configuration_pair pair;
    struct node* next;
} node;

node* create_node(configuration_pair pair) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->pair = pair;
    new_node->next = NULL;
    return new_node;
}

void free_node(node* node_to_free) {
    if (node_to_free != NULL) {
        free(node_to_free);
    }
}

void parse_configuration(char* filename, node** head_ref) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        // Handle error
    }

    char line[1024];
    int nesting_level = 0;
    bool in_nested_config = false;
    node* current_node = NULL;

    while (fgets(line, sizeof(line), file)) {
        size_t i = 0;
        bool inside_quote = false;
        for (; i < strlen(line); i++) {
            if (!inside_quote && line[i] == '#') {
                break; // comment
            }
            else if (inside_quote && line[i] == '"') {
                inside_quote = false;
            }
            else if (!inside_quote && line[i] == '"') {
                inside_quote = true;
            }
        }

        char key[1024], value[1024];
        sscanf(line, "%*[^=]=%s", key);
        i++;
        for (; i < strlen(line); i++) {
            if (line[i] == '=') break;
        }
        for (++i; i < strlen(line); i++) {
            if (inside_quote) {
                value[i - i] = line[i];
                value[i - 1] = '\0';
            } else {
                if (line[i] == '"') inside_quote = !inside Quote;
                else value[i - i] = line[i];
                value[i - 1] = '\0';
            }
        }

        configuration_pair pair;
        pair.key = strdup(key);
        pair.value.integer_value = strtod(value, NULL);

        if (in_nested_config) {
            node* new_node = create_node(pair);
            current_node->next = new_node;
            current_node = new_node;
        } else {
            *head_ref = create_node(pair);
            current_node = *head_ref;
        }

        if (nested_level > 10 || count_nodes(*head_ref) > 1000) {
            // Handle error
        }
    }

    fclose(file);
}

void free_configuration(node* head) {
    node* temp = head;
    while (temp != NULL) {
        configuration_pair pair = temp->pair;
        free(pair.key);
        if (pair.value.integer_value) {
            // Free integer value memory
        } else if (pair.value.floating_point_value) {
            // Free floating point value memory
        } else if (pair.value.string_value) {
            // Free string value memory
        } else {
            // Free boolean value memory
        }
        free_node(temp);
        temp = temp->next;
    }
}
