#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

record* random_record(long numOffsets, long minOffset, long maxOffset) {
    if (numOffsets <= 0) return NULL;
    // Allocate memory for the arrays
    long* offsets = malloc(numOffsets * sizeof(long));
    int* keys = malloc(numOffsets * sizeof(int));

    // Initialize and fill the arrays
    for (long i = 0; i < numOffsets; ++i) {
        long offset = random_in_range(minOffset, maxOffset);
        offsets[i] = offset;
        keys[i] = rand() % ((maxOffset - minOffset + 1) / 2) + minOffset;
    }

    // Allocate memory for the records
    record* records = malloc(numOffsets * sizeof(record));
    for (long i = 0; i < numOffsets; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Free any partially allocated structures in case of an error
    if (!records || !keys || !offsets) {
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }
    return records;
}

long random_in_range(long min, long max) {
    long range = max - min + 1;
    if (range <= 0) return 0; // Edge case: all values the same
    double val = ((double)rand() / RAND_MAX) * range;
    return min + (long)val;
}

record* populate_records(long numOffsets, long numRecords, long minOffset, long maxOffset) {
    if (numOffsets <= 0 || numRecords <= 0 || minOffset > maxOffset) {
        // Handle edge cases
        printf("Invalid input. Setting all offsets to 0.\n");
        return random_record(1, minOffset, minOffset);
    }

    record* records = malloc(numRecords * sizeof(record));
    for (long i = 0; i < numRecords; ++i) {
        long offset;
        int key;
        do {
            long maxRandOffset = (maxOffset - minOffset + 1) / 2;
            long randOffset = random_in_range(minOffset, maxRandOffset);
            offset = randOffset + ((rand() % 2) * 2 - 1) * (maxRandOffset - minOffset);
            key = rand() % ((maxOffset - minOffset + 1) / 2) + minOffset;
        } while (offset < 0 || offset > maxOffset); // Ensure valid random values
        records[i].offset = offset;
        records[i].key = key;
    }

    return records;
}
