record* insertRecord(record** records, int* length, int newKey, long newOffset) {
    // Dynamically allocate a new record
    record* newRecord = (record*)malloc(sizeof(record));
    if (!newRecord) return NULL;  // Handle memory allocation failure

    newRecord->key = newKey;
    newRecord->offset = newOffset;

    // Create a string representation of the key followed by a random number
    srand(time(NULL));  // Initialize random seed
    int randomNumber = rand() % 1000 + 1;  // Random number within range [1, 1000]
    char dataBuffer[50];  // Buffer to store string representation
    sprintf(dataBuffer, "%d-%d", newKey, randomNumber);
    newRecord->data = (char*)malloc(strlen(dataBuffer) + 1);  // Allocate memory for data field
    strcpy(newRecord->data, dataBuffer);

    if (*length > 0) {
        record* tempRecords = (record*)realloc(*records, sizeof(record) * (*length + 1));
        if (!tempRecords) return NULL;  // Handle memory reallocation failure

        *records = tempRecords;
        (*records)[*length] = *newRecord;
        (*length)++;
    } else {
        *records = (record*)malloc(sizeof(record));  // Initialize array with a single record
        if (!*records) return NULL;  // Handle memory allocation failure
        **records = *newRecord;
        *length = 1;
    }

    return newRecord;
}

void updateRecordsTime(record** records, int length) {
    for (int i = 0; i < length; i++) {
        char dataBuffer[50];  // Buffer to store updated string representation
        sprintf(dataBuffer, "%d-%d (%ld)", ((record*)records[i])->key, rand() % 1000 + 1, time(NULL));
        free(((record*)records[i])->data);  // Free existing data field
        ((record*)records[i])->data = (char*)malloc(strlen(dataBuffer) + 1);  // Allocate memory for updated data field
        strcpy(((record*)records[i])->data, dataBuffer);
    }
}

void freeRecords(record** records, int length) {
    for (int i = 0; i < length; i++) {
        free(((record*)records[i])->data);  // Free data field
        free(records[i]);  // Free record structure
    }

    free(*records);  // Free array of records
}

int main() {
    int length = 0;
    record* records = NULL;

    for (int i = 0; i < 5; i++) {
        int newKey = i + 1;
        long newOffset = i * 1000L;
        insertRecord(&records, &length, newKey, newOffset);
    }

    updateRecordsTime(&records, length);

    freeRecords(&records, length);

    return 0;
}
