typedef struct Record {
    int value;
    int status;
    time_t timestamp;
} Record;

Record* create_record_array(int max_records, int min_value, int max_value) {
    // Create the record array
    Record* records = (Record*)malloc(max_records * sizeof(Record));

    if (!records) {
        return NULL;  // Memory allocation failed
    }

    // Initialize each record
    for (int i = 0; i < max_records; i++) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = value;
        records[i].status = value % 2;  // Set status based on parity
        records[i].timestamp = time(NULL);  // Update timestamp

        // Initialize locking mechanism and thread-safe data structure
        pthread_mutex_init(&records[i].mutex, NULL);
        records[i].cache = (int*)malloc(max_records * sizeof(int));
    }

    return records;
}

void free_record_array(Record* records) {
    for (int i = 0; i < max_records; i++) {
        // Free cache and mutex for each record
        free(records[i].cache);
        pthread_mutex_destroy(&records[i].mutex);
    }

    free(records);
}
