    store->records = (Record**)calloc(capacity, sizeof(Record*));
    store->size = 0;
    store->capacity = capacity;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

// Function to insert a new record into the dynamic store
void insertRecord(DynamicStore* store, int key, int value, int status, char* metadata) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    record->status = status;
    record->metadata = metadata;

    pthread_mutex_lock(&store->lock);
    store->records[store->size] = record;
    store->size++;
    if (store->size >= store->capacity) {
        // Resize the array
        int newCapacity = store->capacity * 2;
        Record** newRecords = (Record**)calloc(newCapacity, sizeof(Record*));
        memcpy(newRecords, store->records, store->size * sizeof(Record*));
        free(store->records);
        store->records = newRecords;
        store->capacity = newCapacity;
    }
    pthread_mutex_unlock(&store->lock);
}

// Function to delete a record from the dynamic store
void deleteRecord(DynamicStore* store, int key) {
    for (int i = 0; i < store->size; i++) {
        if (store->records[i]->key == key) {
            free(store->records[i]);
            memmove(&store->records[i], &store->records[i + 1], (store->size - i - 1) * sizeof(Record*));
            store->size--;
            return;
        }
    }
}

// Function to retrieve a record from the dynamic store
Record* getRecord(DynamicStore* store, int key) {
    for (int i = 0; i < store->size; i++) {
        if (store->records[i]->key == key) {
            return store->records[i];
        }
    }
    return NULL;
}

// Function to serialize the dynamic store to disk
void serialize(DynamicStore* store, FILE* file) {
    fwrite(&store->size, sizeof(int), 1, file);
    for (int i = 0; i < store->size; i++) {
        Record* record = store->records[i];
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->value, sizeof(int), 1, file);
        fwrite(&record->status, sizeof(int), 1, file);
        size_t metadataLength = strlen(record->metadata);
        fwrite(&metadataLength, sizeof(size_t), 1, file);
        fwrite(record->metadata, 1, metadataLength + 1, file);
    }
}

// Function to deserialize the dynamic store from disk
DynamicStore* deserialize(FILE* file) {
    DynamicStore* store = createDynamicStore(10); // Initialize with default capacity
    int size;
    fread(&size, sizeof(int), 1, file);

    for (int i = 0; i < size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(int), 1, file);
        fread(&record->status, sizeof(int), 1, file);
        size_t metadataLength;
        fread(&metadataLength, sizeof(size_t), 1, file);
        record->metadata = (char*)malloc(metadataLength + 1);
        fread(record->metadata, 1, metadataLength + 1, file);

        store->records[store->size] = record;
        store->size++;
    }

    return store;
}
