typedef struct {
    float reading;
    char device_id[16];
    time_t last_updated;
} sensor_t;

typedef struct {
    int size;
    float* temperature_readings;
    char** status_indicators;
    sensor_t** sensors;
    pthread_mutex_t lock;
} sensor_collection_t;

void initialize_sensor_collection(sensor_collection_t* collection, int size) {
    collection->size = size;
    collection->temperature_readings = (float*)malloc(size * sizeof(float));
    collection->status_indicators = (char**)malloc(size * sizeof(char*));
    collection->sensors = (sensor_t**)malloc(size * sizeof(sensor_t*));

    pthread_mutex_init(&collection->lock, NULL);
}

void free_sensor_collection(sensor_collection_t* collection) {
    for(int i = 0; i < collection->size; i++) {
        if(collection->sensors[i]) {
            free(collection->sensors[i]->device_id);
            free(collection->sensors[i]);
        }
    }

    free(collection->temperature_readings);
    free(collection->status_indicators);
    free(collection->sensors);
    pthread_mutex_destroy(&collection->lock);
}

void add_sensor(sensor_collection_t* collection, const char* device_id, float reading) {
    int i = 0;
    for(; i < collection->size; i++) {
        if(!collection->sensors[i]) {
            break;
        }
    }

    if(i == collection->size) {
        return; // No more space available
    }

    sensor_t* new_sensor = (sensor_t*)malloc(sizeof(sensor_t));
    strcpy(new_sensor->device_id, device_id);
    new_sensor->reading = reading;
    time(&new_sensor->last_updated);
    collection->sensors[i] = new_sensor;
}

void update_sensor_reading(sensor_collection_t* collection, const char* device_id, float reading) {
    pthread_mutex_lock(&collection->lock);

    int i = 0;
    for(; i < collection->size; i++) {
        if(strcmp(collection->sensors[i]->device_id, device_id) == 0) {
            break;
        }
    }

    if(i >= collection->size) {
        pthread_mutex_unlock(&collection->lock);
        return; // Sensor not found
    }

    collection->sensors[i]->reading = reading;
    time(&collection->sensors[i]->last_updated);

    pthread_mutex_unlock(&collection->lock);
}

float simulate_reading(sensor_collection_t* collection, int sensor_id) {
    if(sensor_id >= collection->size || !collection->sensors[sensor_id]) {
        return 0.0; // Invalid sensor ID
    }

    float reading = (rand() % 100 - 50) / 10.0 + 20.0;

    return reading;
}

void print_sensor_readings(sensor_collection_t* collection) {
    for(int i = 0; i < collection->size; i++) {
        printf("Device ID: %s, Reading: %.2f\n", collection->sensors[i]->device_id, collection->sensors[i]->reading);
    }
}
