// Define a structure for records
typedef struct {
    int key;
    int offset;
    int status;
} Record;

// Function to generate random number within a range
int getRandom(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to initialize and manage the record array and linked list
void* createRecordArray(size_t size) {
    // Check if size is zero or negative
    if (size <= 0) {
        printf("Invalid size. Size must be greater than zero.\n");
        return NULL;
    }

    // Initialize random number generator with a custom seed
    srand(time(NULL));

    // Dynamically allocate memory for arrays and linked list
    Record* records = malloc(size * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the status indicators
    for (size_t i = 0; i < size; i++) {
        records[i].key = getRandom(1, 100);
        records[i].offset = getRandom(1, 100);
        records[i].status = 1;  // Initially set all records as active

        // Create a new node for the linked list
        Record* newNode = malloc(sizeof(Record));
        if (!newNode) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        *newNode = records[i];

        // Add the new node to the front of the linked list
        Record** head = &records[0];
        while (*head != newNode && i < size - 1) {
            head = &(*head)->offset;
        }

        if (i == 0) {
            *head = newNode;  // Set the new node as the head of the linked list
        }
    }

    return records;
}

// Function to free the allocated memory and update the record array
void destroyRecordArray(void* ptr, size_t size) {
    Record* records = (Record*) ptr;

    // Traverse the linked list from the tail to the head
    for (size_t i = 0; i < size - 1; i++) {
        free(&records[i].offset);
    }

    // Free the allocated memory for arrays and linked list
    free(records);

    printf("Memory deallocation successful.\n");
}

int main() {
    int size = 10;
    Record* records = createRecordArray(size);

    if (!records) {
        return 1;  // Return with an error code if the function fails
    }

    // Perform operations on the record array and linked list

    destroyRecordArray(records, size);

    return 0;
}
