async function executeModuleTests(label, f, setup = () => {}) {
  const testConfig = await getTestConfiguration();

  let blueSlipReset = true;

  try {
    const module = require(label);
    if (!module) throw new Error(`Module "${label}" not found`);

    await setup();

    for (const testName of Object.keys(module)) {
      blueSlipReset = true;
      try {
        await f();
      } catch (err) {
        console.error(`Test "${testName}" failed: ${err}`);
        return Promise.reject(err);
      }

      console.log(`${module.name} - ${testName}: Passed`);
    }
  } catch (err) {
    console.error(`Error executing tests for module "${label}": ${err}`);
    return Promise.reject(err);
  } finally {
    blueSlipReset = false;
  }

  return Promise.resolve();
}

async function getTestConfiguration() {
  try {
    const config = await fetchConfig();
    if (!config) throw new Error('Failed to retrieve test configuration');
    return config;
  } catch (err) {
    console.error(`Error fetching test configuration: ${err}`);
    return {};
  }
}
