#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for records
typedef struct {
    int key;
    int value;
} Record;

// Define the structure for a linked list node
typedef struct Node {
    Record record;
    struct Node* next;
} Node;

// Define the hash table structure
typedef struct {
    int size;
    int capacity;
    Node** buckets;
} HashTable;

// Function to create and initialize a new hash table
HashTable* hashTableCreate(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = 0;
    table->capacity = capacity;
    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    return table;
}

// Function to insert a new record into the hash table
void hashTableInsert(HashTable* table, int key, int value) {
    int index = key % table->capacity;
    Node* node = (Node*)malloc(sizeof(Node));
    node->record.key = key;
    node->record.value = value;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->size++;
}

// Function to remove a record from the hash table
void hashTableRemove(HashTable* table, int key) {
    int index = key % table->capacity;
    Node* current = table->buckets[index];
    Node* previous = NULL;
    while (current != NULL) {
        if (current->record.key == key) {
            if (previous == NULL) {
                table->buckets[index] = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            table->size--;
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to retrieve the value of a record from the hash table
int hashTableGet(HashTable* table, int key) {
    int index = key % table->capacity;
    Node* current = table->buckets[index];
    while (current != NULL) {
        if (current->record.key == key) {
            return current->record.value;
        }
        current = current->next;
    }
    return -1; // Record not found
}

// Function to iterate over the records in the hash table using linear search
void hashTableLinearSearch(HashTable* table, void (*callback)(Record)) {
    for (int i = 0; i < table->capacity; i++) {
        Node* current = table->buckets[i];
        while (current != NULL) {
            callback(current->record);
            current = current->next;
        }
    }
}

// Function to iterate over the records in the hash table using binary search
void hashTableBinarySearch(HashTable* table, void (*callback)(Record)) {
    int low = 0;
    int high = table->size - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        Node* current = table->buckets[mid % table->capacity];
        while (current != NULL) {
            if (current->record.key == mid) {
                callback(current->record);
                low = mid + 1;
                break;
            }
            current = current->next;
        }
    }
}

// Function to free the memory allocated for the hash table
void hashTableDestroy(HashTable* table) {
    for (int i = 0; i < table->capacity; i++) {
        Node* current = table->buckets[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}

// Example usage:
int main() {
    HashTable* table = hashTableCreate(16);

    // Insert records
    hashTableInsert(table, 1, 10);
    hashTableInsert(table, 2, 20);
    hashTableInsert(table, 3, 30);
    hashTableInsert(table, 4, 40);
    hashTableInsert(table, 5, 50);

    // Retrieve a record
    int value = hashTableGet(table, 3);
    printf("Value for key 3: %d\n", value);

    // Iterate over records using linear search
    hashTableLinearSearch(table, (void (*)(Record))printf("Key: %d, Value: %d\n"));

    // Free the memory allocated for the hash table
    hashTableDestroy(table);
    return 0;
}
