    if (min > max) {
        return 0;
    }
    return rand() % ((max - min) + 1) + min;
}

void generate_and_populate_records(int numOffsets, int numRecords, long minOffset, long maxOffset) {
    srand(time(NULL));

    // Create arrays for offsets and keys
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    int* keys = (int*)malloc(numOffsets * sizeof(int));

    // Initialize random offsets and keys
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = random_in_range(minOffset, maxOffset);
        keys[i] = rand() % ((maxKey - minKey) + 1) + minKey;
    }

    // Create array of records
    record_t* records = (record_t*)malloc(numRecords * sizeof(record_t));

    // Populate the records with random offsets and keys
    for (int i = 0; i < numRecords; i++) {
        int randIndex = rand() % numOffsets;
        records[i].offset = offsets[randIndex];
        records[i].key = keys[randIndex];
    }

    // Free memory if allocation fails
    free(offsets);
    free(keys);

    // Print the generated and populated records
    printf("Generated and populated records:\n");
    for (int i = 0; i < numRecords; i++) {
        printf("%ld %d\n", records[i].offset, records[i].key);
