#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_SENSORS 1000
#define TABLE_SIZE 1024
#define SEED 42

typedef struct {
    int device_id;
    float temp_reading;
    time_t last_updated;
    int status;
} Sensor;

Sensor *hash_table[MAX_SENSORS];
int hash_values[TABLE_SIZE];

void init_hash_table() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        hash_values[i] = -1;
    }
}

int hash_function(int device_id) {
    return device_id % TABLE_SIZE;
}

Sensor *get_sensor(int device_id) {
    int index = hash_function(device_id);
    if (hash_values[index] == -1 || hash_table[hash_values[index]]->device_id != device_id) {
        return NULL;
    }
    return hash_table[hash_values[index]];
}

void update_sensor(int device_id, float temp_reading) {
    Sensor *sensor = get_sensor(device_id);
    if (sensor) {
        sensor->temp_reading = temp_reading;
        sensor->last_updated = time(NULL);
    }
}

void add_sensor(int device_id, int status) {
    Sensor *new_sensor = malloc(sizeof(Sensor));
    new_sensor->device_id = device_id;
    new_sensor->temp_reading = (float)rand() / RAND_MAX * 100.0f;
    new_sensor->last_updated = time(NULL);
    new_sensor->status = status;

    int index = hash_function(device_id);
    if (hash_values[index] == -1) {
        hash_table[index] = new_sensor;
        hash_values[index] = device_id;
    } else {
        printf("Sensor already exists\n");
    }
}

void remove_sensor(int device_id) {
    int index = hash_function(device_id);
    if (hash_values[index] == device_id) {
        free(hash_table[index]);
        hash_values[index] = -1;
    } else {
        printf("Sensor not found\n");
    }
}

int main() {
    srand(SEED);

    init_hash_table();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, (void *)add_sensor, i);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
