#include <pthread.h>

// Structure to represent a node in the BST
typedef struct Node {
    float pressure;
    int timestamp;
    char event_type;
    struct Node* left;
    struct Node* right;
} Node;

// Function to initialize and balance the BST
Node* init_BST(int size, pthread_mutex_t* lock) {
    // Initialize pseudo-random number generator with custom seed
    srand(time(NULL));

    // Allocate memory for arrays
    float* pressure = (float*)malloc(size * sizeof(float));
    int* timestamp = (int*)malloc(size * sizeof(int));
    char* event_type = (char*)malloc(size * sizeof(char));

    // Initialize arrays with random values
    for (int i = 0; i < size; i++) {
        pressure[i] = (float)rand() / RAND_MAX;
        timestamp[i] = rand();
        event_type[i] = 'A' + rand() % 26; // ASCII characters from A to Z
    }

    // Initialize BST with root node
    Node* root = (Node*)malloc(sizeof(Node));
    root->pressure = pressure[0];
    root->timestamp = timestamp[0];
    root->event_type = event_type[0];
    root->left = NULL;
    root->right = NULL;

    // Insert nodes into BST while maintaining balance
    for (int i = 1; i < size; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        node->pressure = pressure[i];
        node->timestamp = timestamp[i];
        node->event_type = event_type[i];

        // Balance the tree after each insertion
        pthread_mutex_lock(lock);
        root = balance_BST(root, node);
        pthread_mutex_unlock(lock);
    }

    // Free memory allocated for arrays and BST nodes
    free(pressure);
    free(timestamp);
    free(event_type);

    return root;
}

// Function to balance the BST after each insertion or deletion
Node* balance_BST(Node* node, Node* new_node) {
    if (node == NULL || new_node == NULL) {
        return node ? node : new_node;
    }

    // Left-left case: left subtree is too tall
    if (new_node->event_type < node->event_type && node->left != NULL && node->right != NULL) {
        // Rotate right to balance the tree
        Node* temp = node->right;
        node->right = new_node;
        new_node->parent = node;
        new_node->right = temp;

    } else if (new_node->event_type > node->event_type && node->left != NULL && node->right != NULL) {
        // Rotate left to balance the tree
        Node* temp = node->left;
        node->left = new_node;
        new_node->parent = node;
        new_node->left = temp;

    } else if (new_node->event_type < node->event_type && node->right != NULL) {
        // Rotate right to balance the tree
        Node* temp = node->right;
        node->right = new_node;
        new_node->parent = node;
        new_node->right = temp;

    } else if (new_node->event_type > node->event_type && node->left != NULL) {
        // Rotate left to balance the tree
        Node* temp = node->left;
        node->left = new_node;
        new_node->parent = node;
        new_node->left = temp;

    }

    return node;
}

// Function to search for a pressure reading in the BST
Node* search_BST(Node* root, float target_pressure) {
    if (root == NULL) {
        return NULL; // Pressure reading not found
    }

    if (target_pressure < root->pressure) {
        return search_BST(root->left, target_pressure);
    } else if (target_pressure > root->pressure) {
        return search_BST(root->right, target_pressure);
    } else {
        return root;
    }
}

int main() {
    // Initialize pseudo-random number generator with custom seed
    srand(time(NULL));

    // Allocate memory for arrays and BST nodes
    int size = 1000; // Adjust the size as needed
    pthread_mutex_t lock;

    // Initialize and balance the BST
    Node* root = init_BST(size, &lock);

    return 0;
}
