public class WeatherMonitoringService {
    private AVLTree<String, String> tree;
    private Object lock = new Object();
    private int temperatureSize;
    private double[] temperatures;
    private long[] timestamps;

    public WeatherMonitoringService() {
        tree = new AVLTree<>();
        temperatures = null;
        timestamps = null;
    }

    public void startService(int size) throws IOException {
        if (size <= 0) {
            System.out.println("Invalid input size. Please enter a positive integer.");
            return;
        }
        temperatureSize = size;

        // Dynamically allocate memory for arrays
        temperatures = new double[size];
        timestamps = new long[size];

        // Start data retrieval from external source
        retrieveData();
    }

    public void stopService() {
        if (temperatureSize > 0) {
            tree.clear();

            // Deallocate memory for arrays
            temperatureSize = 0;
            temperatures = null;
            timestamps = null;
        }
    }

    private void retrieveData() throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader("weather_data.txt"))) {
            String line;
            int i = 0;

            while ((line = reader.readLine()) != null && i < temperatureSize) {
                String[] data = line.split(",");
                double temp = Double.parseDouble(data[0]);
                long timestamp = Long.parseLong(data[1]);

                temperatures[i] = temp;
                timestamps[i] = timestamp;

                tree.put(String.valueOf(timestamp), String.valueOf(temp));

                i++;
            }
        } catch (IOException e) {
            // Handle data retrieval failure
            System.out.println("Error retrieving data: " + e.getMessage());

            // Fallback mechanism to continue operation in degraded mode
            if (!tree.isEmpty()) {
                System.out.println("Using cached data...");
            } else {
                System.out.println("No data available. Service unavailable.");
                return;
            }
        }
    }

    public void printData() {
        for (int i = 0; i < temperatureSize; i++) {
            System.out.println("Temperature: " + temperatures[i] + ", Timestamp: " + timestamps[i]);
        }
    }

    public static class AVLTree<K, V> extends AbstractMap<K, V> implements NavigableMap<K, V> {
        // AVL tree implementation
    }
}
