        rec->val = rand() % 100 + 1; // Initialize random value
        records[i] = rec;
        if (ll.size == ll.capacity) {
            ll.capacity *= 2;
            records = (record_t**)realloc(records, sizeof(record_t*) * ll.capacity);
        }
    }

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = (long)i;
    }

    // Print largest integer
    print_largest(data, size);

    // Free allocated memory
    for (size_t i = 0; i < size; ++i) free(records[i]);
    free(records);
    free(offsets);
    free(data);

    json_decref(config);
    fclose(fp);
    return 0;
}

