// Define the structure for a record
typedef struct {
    int value;
} Record;

// Define the structure for the doubly linked list node
typedef struct {
    Record* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize the random number generator
void srand_init(int seed) {
    srand(seed);
}

// Function to generate a random integer within a specified range
int rand_int(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Function to create a new record with a random value
Record* create_record(int min_value, int max_value) {
    Record* rec = malloc(sizeof(Record));
    rec->value = rand_int(min_value, max_value);
    return rec;
}

// Function to create a new linked list node
Node* create_node() {
    Node* node = malloc(sizeof(Node));
    node->data = NULL;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to add a record to the linked list
void add_record(Node** head, Record* rec) {
    Node* new_node = create_node();
    new_node->data = rec;

    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    }
}

// Function to delete a record from the linked list
void delete_record(Node** head, Record* rec) {
    if (*head == NULL || rec == NULL) return;

    Node* current = *head;
    while (current && current->data != rec) {
        current = current->next;
    }

    if (current) {
        if (current->prev) current->prev->next = current->next;
        else *head = current->next;

        if (current->next) current->next->prev = current->prev;
        free(rec);
        free(current);
    }
}

// Function to find the largest integer in the array
int find_largest(Record* records, int count) {
    int max_value = -1;
    for (int i = 0; i < count; i++) {
        if (records[i].value > max_value) max_value = records[i].value;
    }
    return max_value;
}

// Function to print the linked list
void print_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("%d\n", current->data->value);
        current = current->next;
    }
}

int main(int argc, char** argv) {
    // Initialize the random number generator with a custom seed
    int seed = 0; // default seed
    if (argc > 1) {
        seed = atoi(argv[1]);
    }
    srand_init(seed);

    // Define the input file name or standard input
    FILE* file = NULL;
    if (argc == 2) {
        file = fopen(argv[1], "r");
    } else {
        file = stdin;
    }

    // Read integers from the file or standard input
    int count = 0;
    Record* records = NULL;
    while (!feof(file)) {
        Record* rec = create_record(1, 100);
        fscanf(file, "%d", &rec->value);
        add_record(&records, rec);
        count++;
    }

    // Find and print the largest integer in the array
    int max_value = find_largest(records, count);

    printf("Largest value: %d\n", max_value);

    // Print the linked list
    print_list(records);

    // Free the memory allocated for the records and nodes
    Node* current_node = records;
    while (current_node) {
        Record* rec = current_node->data;
        delete_record(&records, rec);
        free(current_node);
        current_node = current_node->next;
    }

    return 0;
}
