#define RECORD_SIZE 16 // size of each record in bytes
#define CHUNK_SIZE 4096 // memory pool allocator chunk size

typedef struct Record {
    int value;
    struct Record* prev;
    struct Record* next;
} Record;

Record* record_new(int value) {
    Record* new_rec = (Record*)malloc(RECORD_SIZE);
    if (!new_rec) return NULL;
    new_rec->value = value;
    new_rec->prev = new_rec->next = NULL;
    return new_rec;
}

void record_free(Record* rec) {
    if (!rec) return;
    free(rec);
}

Record* record_insert(Record* head, Record* new_rec) {
    if (!head || !new_rec) return head;
    new_rec->prev = head;
    new_rec->next = head->next;
    if (head->next) head->next->prev = new_rec;
    else head->next = new_rec;
    head->prev = new_rec;
    return new_rec;
}

Record* record_remove(Record* rec) {
    if (!rec) return NULL;
    if (rec->prev) rec->prev->next = rec->next;
    if (rec->next) rec->next->prev = rec->prev;
    return rec;
}

int read_records(char* filename, int** keys, long** offsets, Record*** records) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1; // error opening file
    *keys = (int*)malloc(sizeof(int));
    *offsets = (long*)malloc(sizeof(long));
    *records = (Record**)malloc(sizeof(Record*));
    Record* head = NULL;
    int key = 0, offset = 0;
    while (fscanf(file, "%d %ld\n", &key, &offset) == 2) {
        Record* new_rec = record_new(rand() % (1 << 15)); // random value within range
        *records = record_insert(head, new_rec);
        head = new_rec;
        **keys = key;
        **offsets = offset;
    }
    fclose(file);
    return 0; // successful read
}

int main(int argc, char* argv[]) {
    int keys[1];
    long offsets[1];
    Record* records[1];
    if (argc > 1) {
        if (!read_records(argv[1], &keys, &offsets, &records)) {
            printf("File read successful!\n");
        } else {
            printf("Error reading file: %s\n", argv[1]);
            return -1;
        }
    } else {
        FILE* file = fopen("/dev/stdin", "rb");
        if (!file) {
            printf("Error opening standard input.\n");
            return -1;
        }
        // read from standard input
    }
    int max_key = *keys[0];
    Record* current_rec = *records[0];
    while (current_rec) {
        if (current_rec->value > max_key) max_key = current_rec->value;
        current_rec = current_rec->next;
    }
    printf("Largest key: %d\n", max_key);
    // free memory
    return 0;
}
