#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int value;
    struct record* prev;
    struct record* next;
} record;

record* createRecord(int val) {
    record* newRec = (record*)malloc(sizeof(record));
    newRec->value = val;
    newRec->prev = NULL;
    newRec->next = NULL;
    return newRec;
}

void freeRecords(record* head, int size) {
    record* temp = head;
    for(int i = 0; i < size; i++) {
        if(temp != NULL) {
            record* next = temp->next;
            free(temp);
            temp = next;
        } else break;
    }
}

int largestInt(record* records, int size) {
    int maxVal = -INT_MAX;
    record* current = records;
    for(int i = 0; i < size; i++) {
        if(current->value > maxVal)
            maxVal = current->value;
        current = current->next;
    }
    return maxVal;
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    int numInts, size;
    printf("Enter the number of integers: ");
    scanf("%d", &numInts);
    printf("Enter the size of each record (in bytes): ");
    scanf("%d", &size);

    int* keys = NULL;
    long* offsets = NULL;
    record* records = NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Read integers from network stream
    for(int i = 0; i < numInts; i++) {
        // Code to read integer from network stream goes here
        int val = rand() % (size - 1); // Randomly generate values within the range
        record* newRec = createRecord(val);
        if(records == NULL) {
            records = newRec;
            pthread_mutex_lock(&lock);
            records->prev = NULL;
            records->next = NULL;
            pthread_mutex_unlock(&lock);
        } else {
            record* current = records;
            while(current->next != NULL)
                current = current->next;
            current->next = newRec;
            newRec->prev = current;
            newRec->next = NULL;
        }
    }

    int largestVal = largestInt(records, numInts);
    printf("Largest integer: %d\n", largestVal);

    // Free all allocated memory
    freeRecords(records, numInts);
    free(keys);
    free(offsets);
    pthread_mutex_destroy(&lock);

    return 0;
}
