// Define the structure for a linked list node
typedef struct _node {
    char *data;
    struct _node *prev;
    struct _node *next;
} Node;

// Define the structure for a doubly linked list
typedef struct _list {
    Node *head;
    Node *tail;
    pthread_mutex_t lock; // Lock for thread safety
} List;

// Function to create a new node with dynamically allocated memory
Node* newNode(char *data) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->data = (char*)malloc(strlen(data) + 1);
    strcpy(node->data, data);
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to create a new linked list
List* newList() {
    List *list = (List*)malloc(sizeof(List));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to insert a new node at the end of the linked list
void insert(Node** headRef, Node* newNode) {
    if (*headRef == NULL) {
        *headRef = newNode;
        (*headRef)->prev = NULL;
        (*headRef)->next = NULL;
    } else {
        newNode->prev = (*headRef);
        newNode->next = NULL;
        (*headRef)->next = newNode;
        (*headRef) = newNode;
    }
}

// Function to delete a node from the linked list
void delete(Node** headRef, Node* node) {
    if (node == *headRef) {
        *headRef = node->next;
    }
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        *headRef = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        (*headRef)->next = NULL;
    }
    free(node->data);
    free(node);
}

// Function to print the linked list
void printList(List* list) {
    Node *curr = list->head;
    while (curr != NULL) {
        printf("%s\n", curr->data);
        curr = curr->next;
    }
}

int main() {
    // Initialize the linked list and create a new node
    List* list = newList();
    Node* newNode = newNode("Hello, World!");
    insert(&list->head, newNode);

    // Print the linked list
    printList(list);

    return 0;
}
