#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    int load_factor;
    int balancing_threshold;
} Config;

typedef struct node {
    char* str;
    int len;
    struct node* left;
    struct node* right;
    int height;
} Node;

Node* create_node(char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->str = strdup(str);
    node->len = strlen(str);
    node->left = NULL;
    node->right = NULL;
    node->height = 1;
    return node;
}

int max(int a, int b) {
    return (a > b)? a : b;
}

Node* left_rotate(Node* root) {
    Node* temp = root->right;
    root->right = temp->left;
    temp->left = root;
    return temp;
}

Node* right_rotate(Node* root) {
    Node* temp = root->left;
    root->left = temp->right;
    temp->right = root;
    return temp;
}

Node* insert_node(Node* root, char* str) {
    if (root == NULL) {
        return create_node(str);
    }
    int cmp = strcmp(str, root->str);
    if (cmp < 0) {
        if (root->left == NULL) {
            root->left = create_node(str);
        } else {
            root = insert_node(root->left, str);
            root->height = max(root->height, root->left->height + 1);
        }
    } else if (cmp > 0) {
        if (root->right == NULL) {
            root->right = create_node(str);
        } else {
            root = insert_node(root->right, str);
            root->height = max(root->height, root->right->height + 1);
        }
    }
    int balance_factor = root->left ? root->left->height : 0 - (root->right ? root->right->height : 0);
    if (balance_factor > 1) {
        if (strcmp(str, root->left->str) < 0) {
            return right_rotate(root);
        } else {
            root->left = left_rotate(root->left);
            return right_rotate(root);
        }
    }
    if (balance_factor < -1) {
        if (strcmp(str, root->right->str) > 0) {
            return left_rotate(root);
        } else {
            root->right = right_rotate(root->right);
            return left_rotate(root);
        }
    }
    return root;
}

Node* search_node(Node* root, char* str) {
    if (root == NULL || strcmp(str, root->str) == 0) {
        return root;
    }
    int cmp = strcmp(str, root->str);
    if (cmp < 0) {
        return search_node(root->left, str);
    } else {
        return search_node(root->right, str);
    }
}

Node* create_avl_tree(Node* root) {
    Node* node = NULL;
    while (root != NULL) {
        if (node == NULL || strcmp(str, root->str) < 0) {
            node = root;
            root = node->left;
        } else {
            node = root;
            root = node->right;
        }
    }
    return node;
}

