typedef struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} List;

void list_init(List* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int random_event_count(int min, int max, double tolerance) {
    int count = rand() % (max - min + 1) + min;
    if (rand() % 100 < (int)(tolerance * 100)) {
        while (count < min || count > max) {
            count = rand() % (max - min + 1) + min;
        }
    }
    return count;
}

void* record_allocator(void* data) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        return NULL;
    }
    record->count = random_event_count(min, max, tolerance);
    return record;
}

void list_add(List* list, Record* record) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        return;
    }
    node->record = record;
    node->prev = NULL;
    node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void list_free(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->record);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}
