#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a record structure
typedef struct {
    long offset;
    int key;
    int value;
    time_t timestamp;
    int ref_count;
} Record;

// Function to initialize and manage the linked list of records
Record* init_record_list(int size, int seed) {
    // Initialize pseudo-random number generator with custom seed
    srand(seed);

    // Create a new record
    Record* head = (Record*) malloc(sizeof(Record));
    if (head == NULL) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    head->offset = 0;
    head->key = rand() % 100; // Initialize key with random value within [0, 99]
    head->value = rand() % 10000; // Initialize value with random value within [0, 9999]
    head->timestamp = time(NULL);
    head->ref_count = 1;

    // Create a doubly linked list
    Record* current = head;
    for (int i = 1; i < size; i++) {
        // Allocate memory for the next record
        Record* temp = (Record*) malloc(sizeof(Record));
        if (temp == NULL) {
            printf("Memory allocation failed!\n");
            return NULL;
        }
        temp->offset = current->offset + sizeof(Record);
        temp->key = rand() % 100; // Initialize key with random value within [0, 99]
        temp->value = rand() % 10000; // Initialize value with random value within [0, 9999]
        temp->timestamp = time(NULL);
        temp->ref_count = 1;

        // Link the new record to the previous one
        current->next = temp;
        temp->prev = current;
        current = temp;
    }

    return head;
}

// Function to update a specific record's value and timestamp
void update_record(Record* head, int key, int value) {
    Record* current = head;
    while (current != NULL) {
        if (current->key == key) {
            // Update the record's value and timestamp
            current->value = value;
            current->timestamp = time(NULL);
            return;
        }
        current = current->next;
    }
}

// Function to delete a specific record from the linked list
void delete_record(Record* head, int key) {
    Record* current = head;
    while (current != NULL) {
        if (current->key == key) {
            // Decrease reference count before removing the record
            current->ref_count--;
            if (current->ref_count > 0) {
                return; // Record still has references, do not remove it
            }
            // Remove the record from the linked list and deallocate memory
            if (current->prev != NULL)
                current->prev->next = current->next;
            else
                head = current->next;
            if (current->next != NULL)
                current->next->prev = current->prev;
            free(current);
            return;
        }
        current = current->next;
    }
}

// Function to garbage collect unused records and reclaim memory
void gc(Record* head) {
    Record* current = head;
    while (current != NULL) {
        if (current->ref_count == 0) {
            // Remove the record from the linked list and deallocate memory
            if (current->prev != NULL)
                current->prev->next = current->next;
            else
                head = current->next;
            if (current->next != NULL)
                current->next->prev = current->prev;
            free(current);
        } else {
            // Update the next record's offset after removing the previous one
            current->offset = (current->next == NULL) ? 0 : current->next->offset + sizeof(Record);
        }
        current = current->next;
    }
}

int main() {
    Record* head = init_record_list(10, 42); // Initialize a record list with 10 records and seed 42
    update_record(head, 5, 12345); // Update the record with key 5 to have value 12345
    delete_record(head, 3); // Delete the record with key 3 from the linked list
    gc(head); // Perform garbage collection on the linked list

    return 0;
}
