#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
    char timestamp[64];
} record;

record* new_record(int seed) {
    record* r = (record*)malloc(sizeof(record));
    r->offset = rand_r(&seed);
    r->key = rand_r(&seed) % 100; // random key
    r->value = rand_r(&seed) % 1000; // random value
    time_t now = time(NULL);
    struct tm* timestamp = localtime(&now);
    sprintf(r->timestamp, "%02d:%02d:%02d", timestamp->tm_hour, timestamp->tm_min, timestamp->tm_sec);
    return r;
}

void free_record(record* r) {
    free(r);
}

typedef struct Node {
    record* data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* new_node(Node* head, record* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->prev = NULL;
    node->next = head;
    if(head) head->prev = &node->data;
    else node->data->next = NULL;
    return node;
}

void free_node(Node* node) {
    free(node->data);
    free(node);
}

typedef struct {
    Node* head;
    int size;
} List;

List* new_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    list->size = 0;
    return list;
}

void add_list(List* list, record* data) {
    if(list->head == NULL || data->offset < list->head->data->offset) {
        list->head = new_node(list->head, data);
    } else {
        Node* current = list->head;
        while(current->next && current->next->data->offset >= data->offset) current = current->next;
        current->next = new_node(current->next, data);
    }
    list->size++;
}

record* delete_list(List* list, long offset) {
    if(list->head == NULL || list->head->data->offset > offset) return NULL;
    record* deleted = list->head->data;
    Node* node = list->head;
    while(node && node->data->offset <= offset) {
        if(node->data->offset == offset) {
            if(node->prev) node->prev->next = node->next;
            else list->head = node->next;
            if(node->next) node->next->prev = node->prev;
            free_node(node);
            return deleted;
        }
        node = node->next;
    }
    return NULL;
}

void print_list(List* list) {
    Node* current = list->head;
    while(current) {
        printf("Offset: %ld, Key: %d, Value: %d, Timestamp: %s\n", current->data->offset, current->data->key, current->data->value, current->data->timestamp);
        current = current->next;
    }
}

int main() {
    List* list = new_list();
    srand(time(NULL)); // seed the random number generator
    for(int i = 0; i < 10; i++) {
        add_list(list, new_record(i));
    }
    print_list(list);
    record* deleted = delete_list(list, 5);
    if(deleted) printf("Deleted record: Offset: %ld\n", deleted->offset);
    free_list(list);
    return 0;
}
