```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    char path[256];
    int fileSize;
    time_t modificationTime;
} FileMetadata;

typedef struct Node {
    char path[256];
    FileMetadata metadata;
    struct Node* parent;
    struct Node* children;
} TreeNode;

void processFile(char* filePath, TreeNode** root) {
    // Implement file processing logic here
}

TreeNode* createNode(TreeNode* parent, char* childPath) {
    TreeNode* newNode = (TreeNode*) malloc(sizeof(TreeNode));
    strcpy(newNode->path, childPath);
    newNode->parent = parent;
    newNode->children = NULL;
    return newNode;
}

void buildTree(TreeNode** root, char* filePath) {
    // Traverse the directory hierarchy and process files
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        return;  // Handle error
    }

    DIR* dir = opendir(filePath);
    if (dir == NULL) {
        return;  // Handle error
    }

    TreeNode* current = *root;
    while ((dirent*) readdir(dir)) {
        char* childPath = malloc(strlen(filePath) + strlen((dirent*) readdir(dir))->d_name + 1);
        strcpy(childPath, filePath);
        strcat(childPath, (dirent*) readdir(dir)->d_name);

        if (S_ISDIR(((dirent*) readdir(dir))->d_type)) {
            TreeNode* child = createNode(current, childPath);
            buildTree(&child, childPath);
        } else {
            processFile(childPath, &current);
        }
    }

    closedir(dir);
    fclose(file);
}

void freeNode(TreeNode* node) {
    if (node == NULL) {
        return;
    }

    freeNode(node->children);
    free(node);
}
