int hash_function(char* str, int size) {
    int hash = 0;
    for (int i = 0; i < strlen(str); i++) {
        hash += tolower((unsigned char)str[i]);
    }
    return hash % size;
}

void insert_word(word_node** root, char* word) {
    if (*root == NULL) {
        *root = (word_node*)malloc(sizeof(word_node));
        (*root)->word = strdup(word);
        (*root)->count = 1;
        (*root)->left = NULL;
        (*root)->right = NULL;
    } else {
        int hash = hash_function(word, strlen(*root->word));
        if ((*root)->left == NULL && (*root)->right == NULL) {
            if (hash % 2 == 0) {
                (*root)->left = (word_node*)malloc(sizeof(word_node));
                (*root)->left->word = strdup(word);
                (*root)->left->count = 1;
                (*root)->left->left = NULL;
                (*root)->left->right = NULL;
            } else {
                (*root)->right = (word_node*)malloc(sizeof(word_node));
                (*root)->right->word = strdup(word);
                (*root)->right->count = 1;
                (*root)->right->left = NULL;
                (*root)->right->right = NULL;
            }
        } else {
            if (hash % 2 == 0) {
                insert_word(&((*root)->left), word);
            } else {
                insert_word(&((*root)->right), word);
            }
        }
    }
}

