#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Define a struct for word nodes in the binary search tree
typedef struct {
    char* value;
} word_node;

// Define a struct for hash table entries
typedef struct {
    char* key;
    int count;
} string_entry;

// Define a struct for the hash table
typedef struct {
    string_entry** entries;
    size_t size;
    size_t load_factor;
} hash_table;

// Function to initialize and return a new hash table
hash_table* init_hash_table(size_t size, size_t load_factor) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->entries = (string_entry**)calloc(size, sizeof(string_entry*));
    ht->size = size;
    ht->load_factor = load_factor;
    return ht;
}

// Function to insert a new entry into the hash table
void insert_hash_table_entry(hash_table* ht, char* key) {
    // Calculate the index for the given key using a simple hash function
    size_t index = strlen(key) % ht->size;

    // Find an empty slot or overwrite an existing entry with the same key
    string_entry** bucket = &ht->entries[index];
    while (*bucket) {
        if (strcmp((*bucket)->key, key) == 0) {
            (*bucket)->count++;
            return;
        }
        bucket = &(*bucket)[1];
    }

    // Insert a new entry into the hash table
    *bucket = (string_entry*)malloc(sizeof(string_entry));
    (*bucket)->key = strdup(key);
    (*bucket)->count = 1;
}

// Function to free memory allocated for the hash table
void free_hash_table(hash_table* ht) {
    for (size_t i = 0; i < ht->size; i++) {
        string_entry** bucket = &ht->entries[i];
        while (*bucket) {
            free((*bucket)->key);
            free(*bucket);
            bucket = &(*bucket)[1];
        }
        free(bucket);
    }
    free(ht->entries);
    free(ht);
}

// Define a struct for the binary search tree
typedef struct {
    word_node* root;
} bst;

// Function to initialize and return a new binary search tree
bst* init_bst() {
    bst* b = (bst*)malloc(sizeof(bst));
    b->root = NULL;
    return b;
}

// Function to insert a new node into the binary search tree
void insert_bst_node(bst* b, char* value) {
    // Create a new node with the given value and insert it into the tree
    word_node* node = (word_node*)malloc(sizeof(word_node));
    node->value = strdup(value);
    if (!b->root) {
        b->root = node;
    } else {
        // Insert the node into the correct position in the binary search tree
        word_node* current = b->root;
        while (1) {
            int cmp = strcmp(current->value, value);
            if (cmp < 0) {
                if (!current->right) {
                    current->right = node;
                    return;
                }
                current = current->right;
            } else if (cmp > 0) {
                if (!current->left) {
                    current->left = node;
                    return;
                }
                current = current->left;
            } else {
                free(node);
                return; // Node already exists in the tree
            }
        }
    }
}

// Function to free memory allocated for the binary search tree
void free_bst(bst* b) {
    if (b->root) {
        free_bst_node(b->root);
        free(b->root);
    }
    free(b);
}

// Helper function to recursively free nodes in the binary search tree
void free_bst_node(word_node* node) {
    if (!node) return;
    free_bst_node(node->left);
    free_bst_node(node->right);
    free(node->value);
    free(node);
}

// Function to read strings from standard input and initialize data structures
void process_input(int num_strings, char** strings, json_object* config) {
    hash_table* ht = init_hash_table(16, 0.7); // Initialize the hash table with a default size and load factor
    bst* b = init_bst(); // Initialize the binary search tree

    for (int i = 0; i < num_strings; i++) {
        char* str = strings[i];
        // Convert the input string to lowercase for case-insensitive comparison
        int len = strlen(str);
        char* lower_str = (char*)malloc((len + 1) * sizeof(char));
        strcpy(lower_str, str);
        for (int j = 0; j < len; j++) {
            lower_str[j] = tolower((unsigned char)str[j]);
        }
        lower_str[len] = '\0';

        // Insert the string into the hash table and binary search tree
        insert_hash_table_entry(ht, lower_str);
        insert_bst_node(b, str);

        free(lower_str);
    }

    // Free memory allocated for data structures
    free_hash_table(ht);
    free_bst(b);

    // Find and print the longest string in the array using a helper function
    int max_len = 0;
    char* longest_str = NULL;
    for (int i = 0; i < num_strings; i++) {
        if (strlen(strings[i]) > max_len) {
            max_len = strlen(strings[i]);
            longest_str = strings[i];
        }
    }
    printf("Longest string: %s\n", longest_str);
}

// Function to parse the configuration file and set parameters for data structures
void parse_config(json_object* config, hash_table* ht, bst* b) {
    // Read the load factor from the configuration file
    json_object* load_factor_obj = json_object_object_get(config, "load_factor");
    if (load_factor_obj && json_object_is_type(load_factor_obj, JSON_NUMBER)) {
        double load_factor = json_object_get_double(load_factor_obj);
        ht->load_factor = load_factor;
    }

    // Read the size from the configuration file
    json_object* size_obj = json_object_object_get(config, "size");
    if (size_obj && json_object_is_type(size_obj, JSON_NUMBER)) {
        double size = json_object_get_double(size_obj);
        ht->size = (size_t)size;
    }

    // Initialize the hash table with the parsed parameters
    init_hash_table(ht->size, ht->load_factor);

    // Read the balancing threshold from the configuration file
    json_object* balance_threshold_obj = json_object_object_get(config, "balance_threshold");
    if (balance_threshold_obj && json_object_is_type(balance_threshold_obj, JSON_NUMBER)) {
        double balance_threshold = json_object_get_double(balance_threshold_obj);
        // Set the balancing threshold for the binary search tree
    }
}

// Function to handle batch processing of input strings
void process_batch(char** batch_strings, int num_strings) {
    hash_table* ht = init_hash_table(16, 0.7); // Initialize the hash table with a default size and load factor
    bst* b = init_bst(); // Initialize the binary search tree

    for (int i = 0; i < num_strings; i++) {
        char* str = batch_strings[i];
        // Convert the input string to lowercase for case-insensitive comparison
        int len = strlen(str);
        char* lower_str = (char*)malloc((len + 1) * sizeof(char));
        strcpy(lower_str, str);
        for (int j = 0; j < len; j++) {
            lower_str[j] = tolower((unsigned char)str[j]);
        }
        lower_str[len] = '\0';

        // Insert the string into the hash table and binary search tree
        insert_hash_table_entry(ht, lower_str);
        insert_bst_node(b, str);

        free(lower_str);
    }

    // Free memory allocated for data structures
    free_hash_table(ht);
    free_bst(b);
}

int main() {
    int num_strings;
    char** strings;

    // Read the number of input strings and initialize arrays
    json_object* config = json_object_from_file("config.json");
    if (json_object_object_get(config, "num_strings")) {
        json_object* num_strings_obj = json_object_object_get(config, "num_strings");
        if (num_strings_obj && json_object_is_type(num_strings_obj, JSON_NUMBER)) {
            num_strings = json_object_get_int(num_strings_obj);
            strings = (char**)malloc((num_strings + 1) * sizeof(char*));
            for (int i = 0; i < num_strings; i++) {
                strings[i] = (char*)malloc(1024 * sizeof(char));
                // Read the input string from standard input
                json_object* str_obj = json_object_object_get(config, "strings");
                if (str_obj && json_object_is_type(str_obj, JSON_ARRAY)) {
                    for (int j = 0; j < json_object_array_length(str_obj); j++) {
                        json_object* str_elem = json_object_array_get(str_obj, j);
                        if (str_elem && json_object_is_type(str_elem, JSON_STRING)) {
                            strcpy(strings[i], json_object_get_string(str_elem));
                            break;
                        }
                    }
                }
            }
            strings[num_strings] = NULL;
        } else {
            printf("Invalid configuration file\n");
            return 1;
        }
    } else {
        printf("No configuration file provided\n");
        return 1;
    }

    // Process the input strings and initialize data structures
    process_input(num_strings, strings, config);

    // Free memory allocated for arrays and data structures
    for (int i = 0; i < num_strings; i++) {
        free(strings[i]);
    }
    free(strings);
    return 0;
}

