#include <time.h>

typedef struct node {
    double value;
    int id;
    struct node* left;
    struct node* right;
} Node;

Node* create_node(double value, int id) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->value = value;
    node->id = id;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void insert_node(Node** root, double value, int id) {
    if (*root == NULL) {
        *root = create_node(value, id);
        return;
    }

    Node* current = *root;
    Node* previous = NULL;

    while (current != NULL) {
        previous = current;
        if (value < current->value) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    Node* new_node = create_node(value, id);
    if (previous->value > value) {
        previous->left = new_node;
    } else {
        previous->right = new_node;
    }
}

Node* find_node(Node* root, double target_value) {
    while (root != NULL) {
        if (target_value < root->value) {
            root = root->left;
        } else if (target_value > root->value) {
            root = root->right;
        } else {
            return root;
        }
    }
    return NULL;
}

void print_bst(Node* root) {
    if (root == NULL) {
        return;
    }

    printf("%f ", root->value);
    print_bst(root->left);
    print_bst(root->right);
}

