        Node* node = createNode(offset, key, pressure, eventType);

        // Insert node into the BST
        Bst* bst = createBst();
        insertNode(bst, node);
        freeBst(bst);

        offsets[i] = offset;
        keys[i] = key;
        pressures[i] = pressure;
    }

    // Initialize logging mechanism and verbosity level
    int logVerbosity = 1; // Set the verbosity level to 1 for informational logs

    pthread_t thread;
    pthread_create(&thread, NULL, (void*)loggingThread, &logVerbosity);

    // Perform data processing tasks here
}

void* loggingThread(void* arg) {
    int* verbosityLevel = (int*)arg;
    while (*verbosityLevel > 0) {
        // Log messages or output data to console and/or file
        printf("Logging message\n");
        *verbosityLevel--;
    }
    return NULL;
}
