#include <time.h>

// Structure to hold an integer value
typedef struct {
    int value;
} Record;

// Thread-safe doubly linked list node
typedef struct Node {
    Record *record;
    struct Node *next, *prev;
} Node;

// Initialize the doubly linked list with a given size
Node* init_list(int size) {
    if (size <= 0) {
        printf("Invalid list size: %d\n", size);
        return NULL;
    }

    Node* head = NULL;
    for (int i = 0; i < size; i++) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            printf("Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
        record->value = rand() % 100; // Random value
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
        node->record = record;
        node->next = node->prev = NULL;
        if (head == NULL)
            head = node;
        else
            node->prev = head, head->next = node, head = node;
    }
    return head;
}

// Helper function to find the largest integer in the list
int largest_value(Node* head) {
    int max_val = INT_MIN;
    Node* curr = head;
    while (curr) {
        if (curr->record->value > max_val)
            max_val = curr->record->value;
        curr = curr->next;
    }
    return max_val;
}

int main() {
    // Read the list size from standard input
    int size;
    scanf("%d", &size);

    // Validate the size and initialize the list if valid
    Node* list = init_list(size);

    // Find and print the largest integer in the array
    printf("Largest value: %d\n", largest_value(list));

    return 0;
}
