int memory_limit = 1024 * 1024; // 1 MB

void init_record_collection(int capacity) {
    if (max_records > capacity) return;
    max_records = capacity;
    records = realloc(records, sizeof(Record*) * capacity);
    for (int i = 0; i < capacity; i++) {
        records[i] = malloc(sizeof(Record));
        record_count++;
    }
}

void clear_record_collection() {
    for (int i = 0; i < max_records; i++) {
        free(records[i]);
    }
    free(records);
    records = NULL;
    record_count = 0;
}

void set_record_value(int offset, int value) {
    if (offset >= record_count || offset < 0) return;
    if (value > INT_MAX || value < INT_MIN) return;
    records[offset]->value = value;
}

int find_record_offset(int target) {
    for (int i = 0; i < record_count; i++) {
        if (records[i]->value == target) return i;
    }
    return -1; // not found
}

void test() {
    srand(time(NULL));
    int capacity = 16;
    init_record_collection(capacity);
    for (int i = 0; i < capacity; i++) {
        records[i]->value = rand() % 100;
    }
    set_record_value(7, 42);
    printf("%d\n", find_record_offset(42));
}

void* operator new(size_t size) {
    if (record_count >= max_records || record_count > memory_limit / sizeof(Record*)) {
        // insufficient memory
        return NULL;
    }
    return records[record_count++];
}

void operator delete(void* ptr) {
    for (int i = 0; i < record_count - 1; i++) {
        if (&records[i]->value == ptr) {
            records[i] = records[record_count - 1];
            break;
        }
    }
    free(ptr);
}
