use reqwest::blocking::Client;
use std::time::{Duration, SystemTime};
use reqwest::proxy;

async fn create_http_client(disable_cert_validation: bool) -> reqwest::Client {
    let mut client = reqwest::Client::new();

    if disable_cert_validation {
        // Disable certificate validation for testing purposes
        client = client.ignore_ssl_errors(true);
    }

    // Set a reasonable timeout and maximum connections
    client.timeout(Duration::from_secs(30));
    client.max_connections(10);

    client
}

async fn send_request(client: &reqwest::Client, url: &str) -> Result<(), reqwest::Error> {
    let start = SystemTime::now();

    // Send the request and handle potential errors
    match client.get(url).send().await {
        Ok(response) => {
            if response.status().is_success() {
                println!("Request successful! Time taken: {}", start.elapsed().as_millis());
            } else {
                error!("Failed request with status code {}! Time taken: {}", response.status(), start.elapsed().as_millis());
            }
        },
        Err(err) => {
            error!("Error sending request: {}, Time taken: {}", err, start.elapsed().as_millis());
        }
    };

    Ok(())
}

fn main() {
    let client = create_http_client(true).await.unwrap();
    send_request(&client, "https://example.com").await.unwrap();
}
