    int i = 0;
    char line[128];
    while (fgets(line, sizeof(line), fp)) {
        // Parse line and initialize task object
        data_t *task = &(*data_array)[i++];
        task->timestamp = time(NULL);
        strcpy(task->status, "pending");
        task->priority = rand() % 100;

        printf("Loaded task: timestamp=%s, status=%s, priority=%d\n",
               TIMESTAMP_FORMAT, task->status, task->priority);
    }

    fclose(fp);

    return i;
}

