imageDataProcessorResponse imageDataProcessor(const char* inputFile, int rangeStart, int rangeEnd) {
    // Initialize SSL context
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());

    // Create SSL session
    SSL* ssl = SSL_new(ctx);

    // Connect to external metadata service
    if (connectToMetadataService(ssl)) {
        // Fetch image metadata
        char* metaData = fetchDataFromMetadataService(ssl, inputFile);

        // Initialize record array and count
        record_t* records = (record_t*)malloc(sizeof(record_t) * 10);
        int numRecords = 0;

        // Process image file
        for (int i = rangeStart; i <= rangeEnd; i++) {
            record_t record = {i, i};
            records[numRecords++] = record;
        }

        // Compute MD5 hash of file content
        char* md5Hash = computeMD5Hash(inputFile);

        // Disconnect from metadata service and close SSL session
        disconnectFromMetadataService(ssl);
        SSL_free(ssl);
        SSL_CTX_free(ctx);

        return (struct imageDataProcessorResponse) {
            0, "Page refreshed successfully",
            records, numRecords,
            md5Hash
        };
    } else {
        // Handle error
        return (struct imageDataProcessorResponse) {
            -1, "Failed to connect to metadata service",
            NULL, 0,
            NULL
        };
    }
}

int main() {
    const char* inputFile = "image.tiff";
    int rangeStart = 100;
    int rangeEnd = 200;

    struct imageDataProcessorResponse response = imageDataProcessor(inputFile, rangeStart, rangeEnd);

    if (response.status == 0) {
        printf("Status: %d\nMessage: %s\n", response.status, response.message);
        for (int i = 0; i < response.numRecords; i++) {
            record_t record = response.records[i];
            printf("Offset: %ld, Key: %d\n", record.offset, record.key);
        }
    } else {
        printf("Error: %s\n", response.message);
    }

    return 0;
}
