        record* record = records[i];
        if (record) {
            record->timestamp = time(NULL);
            free(record->html_content);
            record->html_content = strdup(content);
        }
    }

    // Scalability
    for (int i = 0; i < 1000; i++) {
        int chunk_size = 100;
        size_t start = i * chunk_size;
        size_t end = (i + 1) * chunk_size - 1;
        record* records_chunk = NULL;

        for (size_t j = start; j <= end; j++) {
            if (records[j]) {
                if (!records_chunk) {
                    records_chunk = malloc(sizeof(record));
                    offset += sizeof(record);
                }
                records_chunk->timestamp = time(NULL);
                free(records_chunk->html_content);
                records_chunk->html_content = strdup(content);
            }
        }

        if (records_chunk) {
            for (int k = 0; k < chunk_size; k++) {
                int index = rand() % chunk_size;
                record* temp = records[start + index];
                records[start + index] = NULL;
                free(temp->html_content);
                free(temp);
                temp = NULL;
            }
        }

        for (size_t j = start; j <= end; j++) {
            if (records[j]) {
                records[start + i] = NULL;
                free(records[start + i]->html_content);
                free(records[start + i]);
                offset -= sizeof(record);
            }
        }
    }

    // Usability
    printf("Metadata updated successfully!\n");

    // Maintainability
    for (int i = 0; i < 1000; i++) {
        if (!records[i]->html_content) {
            printf("Invalid HTML content!\n");
            return;
        }
    }

    free(memory_pool);
}
