void print_largest(int);

int load_resource_bundle(const char *path) {
    json_object *config = json_object_from_file(path);
    if (!config) {
        fprintf(stderr, "Failed to parse configuration file.\n");
        return -1;
    }

    int seed = json_object_get_int(config, "seed");
    int min_value = json_object_get_int(config, "min_value");
    int max_value = json_object_get_int(config, "max_value");

    // Initialize pseudo-random number generator
    srand(seed);

    // Dynamically allocate memory for arrays and linked list
    records = (record *)malloc(RECORD_SIZE * MAX_RECORDS);
    offsets = (long *)malloc(sizeof(long) * MAX_RECORDS);
    keys[0] = rand() % (max_value - min_value + 1) + min_value;

    // Initialize linked list and offset arrays
    for (int i = 1; i < MAX_RECORDS; i++) {
        record temp;
        temp.key = keys[i-1] + rand() % (max_value - min_value + 1);
        temp.value = rand() % (max_value - min_value + 1) + min_value;
        records[i].key = temp.key;
        records[i].value = temp.value;
        offsets[i] = i * RECORD_SIZE;
    }
    num_records = MAX_RECORDS;

    // Find and print the largest integer in the array
    int max_val = -INT_MAX;
    for (int i = 0; i < num_records; i++) {
        if (records[i].value > max_val) {
            max_val = records[i].value;
        }
    }
    print_largest(max_val);

    // Free allocated memory
    free(records);
    free(offsets);

    return num_records;
}

void print_largest(int max_val) {
    FILE *log_file = fopen("log.txt", "a");
    pthread_mutex_lock(&lock);
    fprintf(stdout, "Largest integer: %d\n", max_val);
    if (log_file) {
        fprintf(log_file, "Largest integer: %d\n", max_val);
        fclose(log_file);
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    int result = load_resource_bundle("config.json");
    return 0;
}
