    int event_count;
} Record;

// Define a linked list node
typedef struct Node {
    Record* data;
    struct Node* next;
    struct Node* prev;
} Node;

// Function to initialize the random number generator with a custom seed
void srand_init(long seed) {
    srand(seed);
}

// Helper function to generate a random integer within a specified range
int rand_int(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Function to read and process the input streams
int process_input_streams(FILE* config_file, long batch_size, long num_records) {
    // Read configuration file
    // ...

    // Initialize memory for arrays and linked list
    Record** records = (Record**)malloc(num_records * sizeof(Record));
    int* keys = (int*)malloc(batch_size * sizeof(int));
    long* offsets = (long*)malloc(batch_size * sizeof(long));

    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < batch_size; i++) {
        // Read input line, remove whitespace and parse integer
        char buffer[256];
        fgets(buffer, sizeof(buffer), config_file);
        int value = atoi(strtok(buffer, " \n"));

        if (value >= -1000000 && value <= 1000000) {
            keys[i] = value;
            offsets[i] = rand_long();
        } else {
            // Log error and skip invalid value
            // ...
            continue;
        }
    }

    for (int i = 0; i < batch_size; i++) {
        Record* record = records + i;
        record->offset = offsets[i];
        record->key = keys[i];
        record->event_count = rand_int(1, 100);

        Node* node = (Node*)malloc(sizeof(Node));
        node->data = record;
        node->next = NULL;
        node->prev = tail;
        if (tail) {
            tail->next = node;
        } else {
            head = node;
        }
        tail = node;
    }

    // Find and print the largest integer in the array
    int max_value = -1000000;
    Node* current = head;
    while (current) {
        if (current->data->event_count > max_value) {
            max_value = current->data->event_count;
        }
        current = current->next;
    }

    // Log statistics and print the largest value
    // ...

    // Clean up memory and return status code
    for (Node* node = head; node; ) {
        Node* next = node->next;
        free(node);
        node = next;
    }
    free(records);
    free(keys);
    free(offsets);

    return 0;
}

int main(int argc, char** argv) {
    // Read JSON configuration file
    FILE* config_file = fopen("config.json", "r");

    if (!config_file) {
        // Log error and exit
        // ...
        return 1;
    }

    long batch_size = 10000; // Default value
    long num_records = 0;

    // Read configuration file parameters
    // ...

    srand_init(time(NULL));
    int status_code = process_input_streams(config_file, batch_size, num_records);

    if (status_code) {
