uint32_t custom_hash(uint64_t offset, uint32_t key) {
    return (uint32_t)(offset * key % 4294967295ULL);
}

record* manage_memory(int* offsets, int* keys, int num_offsets, int num_keys) {
    // Check for valid inputs
    if (!offsets || !keys || num_offsets <= 0 || num_keys <= 0) return NULL;

    // Sort the arrays
    qsort(offsets, num_offsets, sizeof(int), comp);
    qsort(keys, num_keys, sizeof(int), comp);

    int* records = (int*)malloc(num_offsets * sizeof(int));
    if (!records) return NULL; // Handle memory allocation failure

    for (int i = 0; i < num_offsets; i++) {
        record temp;
        temp.value = custom_hash((uint64_t)offsets[i], keys[i]);
        records[i] = temp.value;
    }

    // Deallocate all memory
    free(records);

    return NULL;
}

int comp(const void* a, const void* b) {
    int* first = (int*)a;
    int* second = (int*)b;

    if (*first < *second) return -1;
    else if (*first > *second) return 1;
    else return 0;
}
