#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int key;
    int value;
} record_t;

typedef struct {
    long offset;
    int* keys;
    record_t** records;
    size_t num_records;
} data_container_t;

data_container_t* initialize_data(size_t size) {
    data_container_t* container = malloc(sizeof(data_container_t));

    if (container == NULL) {
        return NULL; // Memory allocation failed
    }

    container->num_records = size;
    container->keys = malloc(sizeof(int) * size);
    if (container->keys == NULL) {
        free(container); // Memory allocation for keys failed
        return NULL; 
    }

    container->records = malloc(sizeof(record_t*) * size);
    if (container->records == NULL) {
        free(container->keys); // Free previously allocated memory
        free(container); // Free the container itself
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        container->records[i] = malloc(sizeof(record_t));
        if (container->records[i] == NULL) {
            for (int j = 0; j <= i; j++) {
                free(container->keys);
                free(container->records[j]);
            }
            free(container->keys); // Free previously allocated memory
            free(container); // Free the container itself
            return NULL;
        }
    }

    return container;
}

void validate_records(data_container_t* container) {
    for (size_t i = 0; i < container->num_records; i++) {
        if (container->records[i]->key < 0 || container->records[i]->value < 0) {
            // Invalid record, reallocate memory and reinitialize records
            size_t new_size = i;
            data_container_t* new_container = initialize_data(new_size);

            if (new_container == NULL) {
                return; // Memory allocation failed
            }

            for (size_t j = 0; j < i; j++) {
                free(container->keys); 
                free(container->records[j]);
            }
            free(container->keys); // Free previously allocated memory
            free(container); // Free the container itself

            *container = *new_container;
        }
    }
}

int main() {
    size_t num_records = 10; // Specify the number of records
    data_container_t* container = initialize_data(num_records);

    if (container == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    validate_records(container);

    for (size_t i = 0; i < container->num_records; i++) {
        printf("Key: %d, Value: %d\n", container->records[i]->key, container->records[i]->value);
    }

    // Free the allocated memory
    for (size_t i = 0; i < container->num_records; i++) {
        free(container->records[i]);
    }
    free(container->keys);
    free(container->records);
    free(container);

    return 0;
}
