// Define structure for a record
typedef struct {
    int value;
} record;

// Function to manage memory allocation and execution of a SQL command
MYSQL_RES* processAndStoreRecords(int offsets_size, long *offsets, int keys_size, int *keys, record *records, int db_conn, char *sql_cmd, MYSQL *mysql_conn) {
    // Sort the offsets and keys arrays
    qsort(offsets, offsets_size, sizeof(long), compareOffsets);
    qsort(keys, keys_size, sizeof(int), compareKeys);

    // Check for duplicate keys and adjust accordingly
    int *unique_keys = (int *)malloc(keys_size * sizeof(int));
    int unique_keys_size = 0;
    for (int i = 0; i < keys_size; i++) {
        int found = 0;
        for (int j = 0; j < unique_keys_size; j++) {
            if (keys[i] == unique_keys[j]) {
                found = 1;
                break;
            }
        }
        if (!found) {
            unique_keys[unique_keys_size++] = keys[i];
        }
    }

    // Generate records using custom hashing function
    record *new_records = (record *)malloc((offsets_size + 1) * sizeof(record));
    for (int i = 0; i < offsets_size; i++) {
        uint32_t hash = custom_hash(offsets[i], unique_keys[i % unique_keys_size]);
        new_records[i].value = hash;
    }

    // Store records in the database
    mysql_query(mysql_conn, sql_cmd);
    MYSQL_RES *result = mysql_use_result(mysql_conn);

    free(unique_keys);
    free(records);
    return result;
}

// Custom comparison function for qsort
int compareOffsets(const void *a, const void *b) {
    long offset1 = *(const long *)a;
    long offset2 = *(const long *)b;
    if (offset1 < offset2)
        return -1;
    else if (offset1 > offset2)
        return 1;
    return 0;
}

// Custom comparison function for qsort
int compareKeys(const void *a, const void *b) {
    int key1 = *(const int *)a;
    int key2 = *(const int *)b;
    if (key1 < key2)
        return -1;
    else if (key1 > key2)
        return 1;
    return 0;
}

uint32_t custom_hash(uint64_t offset, uint32_t key) {
    return (uint32_t)(offset * key % 4294967295ULL);
}
