    // Allocate memory for arrays
    long* offsets = malloc(sizeof(long) * 10000);
    if (!offsets) return NULL;
    int* keys = malloc(sizeof(int) * 10000);
    if (!keys) {
        free(offsets);
        return NULL;
    }
    record** records = malloc(sizeof(record*) * 10000);
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize memory
    offsets[0] = 0;
    keys[0] = 1;

    // Initialize records with random values
