        record* rec = malloc(sizeof(record));
        if (!rec) return NULL;
        int key = rand() % 10000 + 1;
        long offset = (uint32_t)(i * key % 4294967295ULL);
        rec->value = rand() % 2000000 - 1000000; // Random value within range
        records[i] = rec;
    }

    // Validate keys for uniqueness and sort arrays
    int prev_key = keys[0];
    for (int i = 1; i < *size; i++) {
        if (keys[i] <= prev_key) return NULL; // Not unique
        prev_key = keys[i];
    }
    qsort(keys, *size, sizeof(int), (int (*)(const void*, const void*))NULL);
    for (int i = 0; i < *size; i++) {
        offsets[i] = (long)(i * keys[i] % 4294967295ULL);
    }

    // Deallocate memory
    free(records[*size - 1]);
    free(records);

    return NULL;
}

