#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define RECORDS_PER_BUCKET 10
#define BUCKETS 1000 // Initialize to a reasonable number

typedef struct record {
    char status;
    float value;
    int key;
} Record;

Record* hash_table[BUCKETS];
int bucket_count = 0; // Keep track of the current number of buckets used

void initialize_hash_table() {
    for (int i = 0; i < BUCKETS; i++) {
        hash_table[i] = NULL;
    }
}

// Hash function to map a record's key to its corresponding bucket
int hash_function(int key) {
    return key % BUCKETS;
}

// Insert a new record into the hash table, handling collisions by linear probing
void insert_record(int key, char status, float value) {
    int index = hash_function(key);
    Record* current_bucket = hash_table[index];
    if (current_bucket == NULL || bucket_count < RECORDS_PER_BUCKET) {
        // Create a new bucket or extend the existing one
        bucket_count++;
        hash_table[index] = (Record*)malloc(sizeof(Record) * RECORDS_PER_BUCKET);
        current_bucket = hash_table[index];
    }

    for (int i = 0; i < RECORDS_PER_BUCKET; i++) {
        if (current_bucket[i].key == -1) { // Find an empty slot
            current_bucket[i].status = status;
            current_bucket[i].value = value;
            current_bucket[i].key = key;
            return;
        }
    }

    printf("Error: Hash table full!\n");
}

// Retrieve a record by its unique key, handling collisions by linear probing
Record* get_record(int key) {
    int index = hash_function(key);
    Record* current_bucket = hash_table[index];
    if (current_bucket == NULL) return NULL;

    for (int i = 0; i < RECORDS_PER_BUCKET; i++) {
        if (current_bucket[i].key == key) {
            return &current_bucket[i];
        }
    }

    printf("Error: Record not found!\n");
    return NULL;
}

void free_hash_table() {
    for (int i = 0; i < BUCKETS; i++) {
        if (hash_table[i] != NULL) {
            free(hash_table[i]);
        }
    }
}
