    int num_records = 5; // adjust this as needed
    struct record* records = malloc(num_records * sizeof(struct record));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 100;
        records[i].offset = rand();
        records[i].value = rand() % 256;
    }

