    int num_keys = 10; // adjust this as needed
    long* keys = malloc(num_keys * sizeof(long));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i * 100;
    }

    // Initialize u_char array
    size_t buffer_size = 1024; // adjust this as needed
    unsigned char* ip_addresses = malloc(buffer_size);
    int ip_count = 0;

    // Perform DNS resolution
    struct hostent* result = gethostbyname(hostname);
    if (result == NULL) {
        free(ip_addresses);
        return -1;
    }

    // Iterate over the resulting IP addresses
    for (int i = 0; i < result->h_length; i++) {
        const char* ip = inet_ntoa(*(struct in_addr*)result->h_addr_incl[i]);
        if (ip != NULL) {
            // Add IP address to buffer and increment count
            size_t len = strlen(ip);
            if (len + 1 > buffer_size) {
                // Dynamically resize the buffer as needed
                ip_addresses = realloc(ip_addresses, buffer_size * 2);
                buffer_size *= 2;
            }
            memcpy(ip_addresses + ip_count * len + 1, ip, len);
            ip_count++;
        }
    }

    free(result->h_aliases);

    // Clean up and return
    free(records);
    free(keys);
    return ip_count;
}

int main() {
    int ret = get_ip_addresses("example.com");
    printf("%d", ret);
    return 0;
}
