void insert_node(Node** head, Record* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = *data;
    if (*head == NULL || (*head)->prev == NULL) {
        new_node->next = NULL;
        new_node->prev = NULL;
        *head = new_node;
    } else {
        new_node->next = (*head);
        new_node->prev = NULL;
        (*head)->prev = new_node;
        *head = new_node;
    }
}

// Function to delete a node from the doubly linked list
