#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <time.h>

typedef struct record {
    int value;
    struct record *prev;
    struct record *next;
} Record;

Record* create_record(int value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;
    new_record->value = value;
    new_record->prev = NULL;
    new_record->next = NULL;
    return new_record;
}

void free_records(Record* head) {
    while (head) {
        Record* temp = head;
        head = head->next;
        free(temp);
    }
}

int create_config_file(json_object *config, int* size, long** offset_values, int** keys, Record*** records) {
    if (!config || !size || !offset_values || !keys || !records) return -1;

    json_object_iter_t iter;
    json_object_object_foreach(config, iter.key, iter.val) {
        if (json_object_get_type(iter.val) == json_type_array) {
            *size = json_object_array_length(iter.val);
            *offset_values = (long*)malloc(*size * sizeof(long));
            *keys = (int*)malloc(*size * sizeof(int));
            for (int i = 0; i < *size; i++) {
                json_object *val = json_object_array_get(iter.val, i);
                if (!val) continue;
                long offset_value = json_object_get_int(val);
                int key = json_object_get_int(val);
                (*offset_values)[i] = offset_value;
                (*keys)[i] = key;
            }
        } else if (json_object_get_type(iter.val) == json_type_object && json_object_object_get(iter.val, "records")) {
            json_object *records_obj = json_object_object_get(iter.val, "records");
            if (!records_obj || !json_object_array_length(records_obj)) continue;

            *records = (Record**)malloc(json_object_array_length(records_obj) * sizeof(Record*));
            for (int i = 0; i < json_object_array_length(records_obj); i++) {
                json_object *record_obj = json_object_array_get(records_obj, i);
                if (!record_obj) continue;
                Record *record = create_record(json_object_get_int(record_obj));
                (*records)[i] = record;
            }
        }
    }

    return 0;
}

int main() {
    // Load config file
    FILE* fptr = fopen("config.json", "r");
    if (!fptr) return -1;

    json_object *config = json_object_from_file(fptr);
    fclose(fptr);

    int size;
    long* offset_values;
    int* keys;
    Record* records;

    create_config_file(config, &size, &offset_values, &keys, &records);

    // Process log file
    FILE* fptr2 = fopen("log.json", "r");
    if (!fptr2) return -1;

