void srand_custom(int seed) {
    // Seed the random number generator using the provided seed
    srand(seed);
}

// Function to generate a random integer within the range -1,000,000 to 1,000,000
int rand_int() {
    return (rand() % (2 * 1000000)) - 1000000;
}

// Function to process the input dataset and validate each integer
void process_dataset(int** array_sizes, int num_arrays) {
    // Initialize linked list and arrays for storing records
    LinkedListNode* head = NULL;
    Record** records = (Record**)malloc(num_arrays * sizeof(Record*));

    for (int i = 0; i < num_arrays; ++i) {
        // Dynamically allocate memory for the array of records
        int* offsets = (int*)malloc(array_sizes[i] * sizeof(int));
        int* keys = (int*)malloc(array_sizes[i] * sizeof(int));

        // Process each input line, removing leading and trailing whitespace characters
        FILE* file;
        if ((file = fopen("input.txt", "r")) != NULL) {
            char buffer[1000];
            while (fgets(buffer, 1000, file)) {
                // Tokenize the input line to extract integers
                int count = 0;
                char* token = strtok(buffer, " ");
                while (token) {
                    // Validate each integer and handle invalid inputs gracefully
                    int value = atoi(token);
                    if (value >= -1000000 && value <= 1000000) {
                        // Initialize the record with a random integer value
                        Record* record = (Record*)malloc(sizeof(Record));
                        record->value = rand_int();
                        // Insert the record into the linked list
                        LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
                        node->record = *record;
                        node->next = head;
                        head = node;

                        records[i] = record;
                    } else {
                        // Log invalid inputs and skip processing further
                        printf("Invalid input: %s\n", token);
                    }
                }
            }
        }

        // Clean up memory allocated for the array of records
        free(offsets);
        free(keys);
    }

    // Helper function to find and print the largest integer in the array
    void find_largest() {
        Record* max_record = head;
        int max_value = max_record->value;

        LinkedListNode* current = head;
        while (current) {
            if (current->record.value > max_value) {
                max_record = &current->record;
                max_value = current->record.value;
            }
            current = current->next;
        }

        printf("Largest integer: %d\n", max_record->value);
    }

    find_largest();

    // Log the number of valid and invalid inputs processed
    printf("Total valid inputs: %d\n", array_sizes[0]);

    // Close files and clean up memory allocated for linked list and arrays
    fclose(file);
    free(records);

}

int main() {
    // Initialize random number generator with a custom seed
    srand_custom(1234);

    int num_arrays = 3;
    int** array_sizes = (int**)malloc(num_arrays * sizeof(int));

    for (int i = 0; i < num_arrays; ++i) {
        array_sizes[i] = &num_arrays;
    }

    process_dataset(array_sizes, num_arrays);

    return 0;
}

