#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define node structure for binary search tree (BST)
typedef struct Node {
    double value;
    struct Node* left;
    struct Node* right;
} Node;

// Define hash table structure with custom hash function
typedef struct HashEntry {
    char* key;
    double value;
    struct HashEntry* next;
} HashEntry;

typedef struct HashTable {
    int size;
    HashEntry** entries;
} HashTable;

// Custom hash function for string keys
unsigned int hash_function(const char* str) {
    unsigned int hash = 0;
    while (*str != '\0') {
        hash = (hash * 31 + *str) % 127;
        str++;
    }
    return hash;
}

// Function to process streaming data feed and manage memory for arrays, hash table, and BST
void process_data_feed(double* arr, int arr_len, char** str_keys, int str_key_len, Node** root) {
    // Initialize hash table with initial size
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->size = 128;
    hash_table->entries = (HashEntry**)calloc(hash_table->size, sizeof(HashEntry*));

    // Iterate through data feed and insert values into BST and hash table
    for (int i = 0; i < arr_len; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        node->value = arr[i];
        node->left = NULL;
        node->right = NULL;

        // Insert node into BST
        *root = insert_node(root, &node);

        // Insert string key into hash table using custom hash function
        HashEntry* entry = (HashEntry*)malloc(sizeof(HashEntry));
        entry->key = str_keys[i];
        entry->value = arr[i];
        entry->next = NULL;

        int index = hash_function(str_keys[i]) % hash_table->size;
        if (hash_table->entries[index] == NULL) {
            hash_table->entries[index] = entry;
        } else {
            HashEntry* temp = hash_table->entries[index];
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = entry;
        }
    }

    // Validate integrity of data structures and log any errors or warnings
    validate_data_structures(root);

    // Find and print maximum value in BST using helper function
    double max_value = find_max_value(root);
    printf("Maximum value: %f\n", max_value);

    // Serialize BST to disk for later use
    serialize_BST(*root, "data.bst");

    // Deallocate memory allocated for arrays, hash table, and BST
    free(arr);
    free(str_keys);
    free(hash_table->entries);
    free(hash_table);
    free_node(root);
}

// Helper function to find maximum value in BST
double find_max_value(Node* root) {
    if (root == NULL || root->right == NULL)
        return root->value;
    else
        return find_max_value(root->right);
}

// Function to insert node into BST while maintaining balance
Node* insert_node(Node** root, Node** node) {
    if (*root == NULL) {
        *node = *root;
        return *node;
    }

    if ((*node)->value < (*root)->value) {
        if ((*root)->left == NULL) {
            (*root)->left = *node;
            return *root;
        } else {
            *root = &((*root)->left);
            insert_node(root, node);
        }
    } else {
        if ((*root)->right == NULL) {
            (*root)->right = *node;
            return *root;
        } else {
            *root = &((*root)->right);
            insert_node(root, node);
        }
    }

    return *root;
}

// Function to serialize BST to disk
void serialize_BST(Node* root, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL)
        return;

    // Traverse BST and write nodes to file
    Node* current = root;
    while (current != NULL) {
        fwrite(&current->value, sizeof(double), 1, file);
        current = current->right;
    }

    fclose(file);
}

// Function to deallocate memory allocated for node
void free_node(Node** node) {
    if (*node == NULL)
        return;

    free_node(&((*node)->left));
    free_node(&((*node)->right));

    free(*node);
    *node = NULL;
}
