#define MAX_RECORDS 1000
#define MIN_STRING_LENGTH 10
#define MAX_STRING_LENGTH 50

typedef struct record {
    char* data;
    size_t length;
} Record;

Record** records = NULL;
size_t recordCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeRecords(size_t count) {
    if (count > MAX_RECORDS) {
        fprintf(stderr, "Error: Too many records requested.\n");
        return;
    }

    records = (Record**)malloc(count * sizeof(Record*));
    recordCount = 0;
}

void freeRecords() {
    for (size_t i = 0; i < recordCount; i++) {
        if (records[i]->data != NULL) {
            free(records[i]->data);
        }
        free(records[i]);
    }
    free(records);
    records = NULL;
    recordCount = 0;
}

void* generateRandomString(size_t length) {
    char* string = malloc(length + 1);
    for (size_t i = 0; i < length; i++) {
        int c = rand() % 26 + 'a';
        *(string + i) = c;
    }
    *(string + length) = '\0';
    return string;
}

void addRecord(size_t length) {
    pthread_mutex_lock(&lock);
    if (recordCount >= MAX_RECORDS) {
        fprintf(stderr, "Error: Too many records already allocated.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Record* record = malloc(sizeof(Record));
    record->data = generateRandomString(length);
    record->length = length;
    records[recordCount++] = record;
    pthread_mutex_unlock(&lock);
}

void findLongestString() {
    size_t maxLength = 0;
    char* longestString = NULL;

    for (size_t i = 0; i < recordCount; i++) {
        if (records[i]->length > maxLength) {
            maxLength = records[i]->length;
            longestString = records[i]->data;
        }
    }

    printf("Longest string: %s\n", longestString);
}

int main() {
    srand(time(NULL));

    size_t recordCountInput;
    while (scanf("%zu", &recordCountInput) != 1 || recordCountInput <= 0) {
        fprintf(stderr, "Error: Invalid input. Please enter a positive integer.\n");
    }

    initializeRecords(recordCountInput);

    size_t lengthInput;
    while (scanf("%zu", &lengthInput) != 1 || lengthInput < MIN_STRING_LENGTH || lengthInput > MAX_STRING_LENGTH) {
        fprintf(stderr, "Error: Invalid string length. Please enter an integer between %d and %d.\n", MIN_STRING_LENGTH, MAX_STRING_LENGTH);
    }

    for (size_t i = 0; i < recordCountInput; i++) {
        addRecord(lengthInput);
    }

    findLongestString();

    freeRecords();
    return 0;
}

