#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SIZE 1000
#define TABLE_SIZE 256
#define BUCKET_SIZE 10
#define MIN_LOAD_FACTOR 0.7
#define MAX_LOAD_FACTOR 0.8
#define RANDOM_SEED 42

typedef struct record {
    int value;
} Record;

typedef struct bucket {
    Record* records;
    size_t size;
    size_t capacity;
} Bucket;

typedef struct hash_table {
    Bucket** buckets;
    size_t table_size;
    size_t capacity;
    size_t load_factor;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->table_size = size;
    table->capacity = TABLE_SIZE * BUCKET_SIZE;
    table->load_factor = 0.5;
    table->buckets = (Bucket**)calloc(TABLE_SIZE, sizeof(Bucket*));
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        table->buckets[i] = (Bucket*)malloc(sizeof(Bucket));
        table->buckets[i]->records = (Record*)malloc(BUCKET_SIZE * sizeof(Record));
        table->buckets[i]->size = 0;
        table->buckets[i]->capacity = BUCKET_SIZE;
    }
    return table;
}

void insert_record(HashTable* table, const char* key) {
    size_t hash = ((size_t)key[0] + RANDOM_SEED) % TABLE_SIZE;
    Bucket* bucket = &table->buckets[hash];
    Record record;
    record.value = (int)(rand() / (RAND_MAX / 1000));
    if (bucket->size < bucket->capacity) {
        bucket->records[bucket->size++] = record;
    } else {
        resize_bucket(bucket);
        insert_record(table, key);
    }
}

void delete_record(HashTable* table, const char* key) {
    size_t hash = ((size_t)key[0] + RANDOM_SEED) % TABLE_SIZE;
    Bucket* bucket = &table->buckets[hash];
    for (size_t i = 0; i < bucket->size; i++) {
        if (strcmp(key, "") == 0 || strcmp(&key, bucket->records[i].value) == 0) {
            Record temp = bucket->records[--bucket->size];
            memcpy(&bucket->records[i], &temp, sizeof(Record));
            break;
        }
    }
}

int get_record_value(const HashTable* table, const char* key) {
    size_t hash = ((size_t)key[0] + RANDOM_SEED) % TABLE_SIZE;
    Bucket* bucket = &table->buckets[hash];
    for (size_t i = 0; i < bucket->size; i++) {
        if (strcmp(key, "") == 0 || strcmp(&key, "") == 0) {
            return bucket->records[i].value;
        }
    }
    return -1;
}

void resize_bucket(Bucket* bucket) {
    size_t new_capacity = bucket->capacity * 2;
    Record* new_records = (Record*)realloc(bucket->records, new_capacity * sizeof(Record));
    if (new_records == NULL) {
        printf("Memory allocation failure.\n");
        exit(-1);
    }
    bucket->records = new_records;
    bucket->capacity = new_capacity;
}

void compact_table(HashTable* table) {
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        Bucket* bucket = &table->buckets[i];
        size_t j = 0;
        while (j < bucket->size) {
            Record temp = bucket->records[j++];
            while (j < bucket->size && strcmp(&bucket->records[j - 1].value, "") == 0) {
                j++;
            }
            if (j > bucket->size || memcmp(&temp.value, &bucket->records[j - 1].value, sizeof(temp)) != 0) {
                break;
            }
        }
        bucket->size = j;
    }
}

void rehash_table(HashTable* table) {
    size_t new_size = table->table_size * 2;
    HashTable* new_table = create_hash_table(new_size);
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        Bucket* bucket = &table->buckets[i];
        size_t j = 0;
        while (j < bucket->size) {
            Record record = bucket->records[j++];
            size_t new_hash = ((size_t)&record.value[0] + RANDOM_SEED) % new_size;
            Bucket* new_bucket = &new_table->buckets[new_hash];
            if (new_bucket->size >= new_bucket->capacity / 2) {
                resize_bucket(new_bucket);
            }
            memcpy(&new_bucket->records[new_bucket->size++], &record, sizeof(Record));
        }
    }
    free(table->buckets);
    table = new_table;
}

void print_health_status(const HashTable* table) {
    size_t load_factor = (table->load_factor * 100.0);
    printf("Load factor: %d%%, Table size: %zu, Bucket capacity: %zu\n", (int)load_factor, TABLE_SIZE, BUCKET_SIZE);
}

void print_statistics(HashTable* table) {
    size_t total_records = 0;
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        Bucket* bucket = &table->buckets[i];
        total_records += bucket->size;
    }
    printf("Total records: %zu, Table capacity: %zu\n", total_records, table->capacity);
}

int main() {
    HashTable* table = create_hash_table(TABLE_SIZE);
    srand(RANDOM_SEED);
    for (int i = 0; i < MAX_SIZE; i++) {
        char key[] = "key";
        insert_record(table, key);
    }
    compact_table(table);
    rehash_table(table);
    print_health_status(table);
    print_statistics(table);
    return 0;
}

