    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    double* timestamps = (double*)malloc(MAX_RECORDS * sizeof(double));
    size_t* sizes = (size_t*)malloc(MAX_RECORDS * sizeof(size_t));

    // Initialize hash table
    HashTable* hashTable = (HashTable*)malloc(sizeof(HashTable));
    hashTable->buckets = (Node**)malloc(MAX_KEY * sizeof(Node*));
    for (int i = 0; i < MAX_KEY; i++) {
        hashTable->buckets[i] = NULL;
    }

    // Initialize doubly linked list
    Record* head = NULL;
    Record* tail = NULL;

