    fclose(file);
}

// Function to insert a new record into the doubly linked list and hash table
void insertRecord(Record* record) {
    // Insert record into doubly linked list
    if (head == NULL) {
        head = tail = record;
    } else {
        Record* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
        tail = record;
    }

    // Insert record into hash table
    int key = record->key % MAX_KEY;
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->value = record;
    if (hashTable->buckets[key] == NULL) {
        hashTable->buckets[key] = node;
    } else {
        Node* current = hashTable->buckets[key];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

// Function to delete a record from the doubly linked list and hash table
void deleteRecord(int key) {
    // Delete record from doubly linked list
    Record* current = head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Record not found\n");
        return;
    }
    if (head == tail && head == current) {
        head = tail = NULL;
    } else if (head == current) {
        head = current->next;
    } else if (tail == current) {
        tail = current->prev;
    } else {
        Record* prev = head;
        while (prev->next != current) {
            prev = prev->next;
        }
        prev->next = current->next;
        if (current->next == NULL) {
            tail = prev;
        }
    }

    // Delete record from hash table
    int bucketIndex = key % MAX_KEY;
    Node* node = hashTable->buckets[bucketIndex];
    while (node != NULL && node->key != key) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Record not found\n");
        return;
    }
    if (node == hashTable->buckets[bucketIndex]) {
        hashTable->buckets[bucketIndex] = node->next;
    } else {
        Node* prevNode = hashTable->buckets[bucketIndex];
        while (prevNode->next != node) {
            prevNode = prevNode->next;
        }
        prevNode->next = node->next;
    }
}

