// Initialize the linked list with a given size
Node* init_list(int size) {
    if (size <= 0) return NULL; // Handle edge case: zero or negative size

    Node* head = NULL;
    Node* curr = NULL;

    for (int i = 0; i < size; i++) {
        Record* record = malloc(sizeof(Record));
        record->value = rand() % 100; // Initialize with random values
        record->offset = i;
        record->key = i;

        if (!head) head = curr = record;
        else {
            Node* node = (Node*)malloc(sizeof(Node));
            node->record = record;
            node->prev = NULL;
            node->next = curr;
            curr->prev = node;
            curr = node;
        }
    }

    return head;
}

// Insert a new record at the beginning of the linked list
void insert_start(Node** head, Record* record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record = record;
    new_node->prev = NULL;

    if (*head) {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    } else {
        *head = new_node;
    }
}

// Delete a node from the linked list
void delete_node(Node** head, Node* node) {
