#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define a struct for record
typedef struct {
    int value;
    long offset;
    int key;
} Record;

// Define a struct for the doubly linked list node
typedef struct Node {
    Record data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to create a new record with random values
Record* createRecord(int min, int max) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->value = rand() % (max - min + 1) + min;
    record->offset = rand();
    record->key = rand() % 100;
    return record;
}

// Function to create a new node in the linked list
Node* createNode(Record* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = *data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to insert a record at the beginning of the linked list
void insertAtBeginning(Node** head, Record* data) {
    Node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        newNode->next = *head;
        (*head)->prev = newNode;
        *head = newNode;
    }
}

// Function to delete a record from the linked list
void deleteRecord(Node** head, Record* data) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data.value == data->value &&
            current->data.offset == data->offset &&
            current->data.key == data->key) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                *head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }
            free(current);
            return;
        }
        current = current->next;
    }
}

// Function to print the linked list
void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Value: %d, Offset: %ld, Key: %d\n", 
            current->data.value, current->data.offset, current->data.key);
        current = current->next;
    }
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    // Create the linked list head
    Node* head = NULL;

    // Insert records into the linked list
    for (int i = 0; i < 10; i++) {
        Record* data = createRecord(1, 100);
        insertAtBeginning(&head, data);
        free(data); // Free the temporary record
    }

    // Print the linked list
    printList(head);

    return 0;
}
