#include <time.h>

typedef struct {
    int key;
    int value;
    char* metadata;
} Record;

Record** hashTable = NULL;
Record*** recordsArray = NULL;

int createHashTable(int size) {
    // Initialize hash table and record arrays with requested size
    hashTable = (Record**)malloc(size * sizeof(Record*));
    if (!hashTable) return -1;  // Handle memory allocation failure

    for (int i = 0; i < size; i++) {
        hashTable[i] = NULL;
    }

    recordsArray = (Record***)malloc(size * sizeof(Record**));
    if (!recordsArray) return -2;  // Handle memory allocation failure

    for (int i = 0; i < size; i++) {
        recordsArray[i] = NULL;
    }

    return 1;
}

void initRecords(int size, int keyRangeStart, int keyRangeEnd) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) return;  // Handle memory allocation failure

        record->key = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;
        record->value = rand() % 100;
        char metadata[10];
        sprintf(metadata, "Metadata for key %d", record->key);
        record->metadata = malloc(strlen(metadata) + 1);
        strcpy(record->metadata, metadata);

        // Insert record into hash table
        int hashValue = myHashFunction(record->key, size);
        if (hashTable[hashValue] == NULL) {
            hashTable[hashValue] = (Record*)malloc(sizeof(Record));
            hashTable[hashValue]->key = record->key;
            hashTable[hashValue]->value = record->value;
            hashTable[hashValue]->metadata = record->metadata;

            recordsArray[hashValue] = (Record**)realloc(recordsArray[hashValue], sizeof(Record*));
            recordsArray[hashValue][0] = record;

        } else {
            // Handle collision by rehashing or quadratic probing
            int j = 1;
            while (recordsArray[hashValue][j]) {
                j++;
            }
            recordsArray[hashValue] = (Record**)realloc(recordsArray[hashValue], (j + 1) * sizeof(Record*));
            recordsArray[hashValue][j] = record;
        }
    }
}

int myHashFunction(int key, int size) {
    return key % size;
}

void freeHashTable() {
    for (int i = 0; i < size; i++) {
        if (recordsArray[i]) {
            for (int j = 0; j < recordsArray[i]; j++) {
                Record* record = recordsArray[i][j];
                if (record) {
                    free(record->metadata);
                    free(record);
                }
            }
            free(recordsArray[i]);
        }
    }

    for (int i = 0; i < size; i++) {
        if (hashTable[i]) {
            free(hashTable[i]->metadata);
            free(hashTable[i]);
        }
    }
}

Record** createHashTableAndInitRecords(int size, int keyRangeStart, int keyRangeEnd) {
    // Create hash table and record arrays
    int result = createHashTable(size);
    if (result < 0) return NULL;  // Handle memory allocation failure

    // Initialize records with unique keys and metadata
    initRecords(size, keyRangeStart, keyRangeEnd);

    // Return pointers to hash table and record array
    return hashTable;
}

int main() {
    int size = 10000;
    int keyRangeStart = 0;
    int keyRangeEnd = 100000;

    Record** result = createHashTableAndInitRecords(size, keyRangeStart, keyRangeEnd);

    // Use the hash table for lookups and updates
    printf("Hash table created with %d records.\n", size);

    // Don't forget to free allocated memory when done!
    freeHashTable();

    return 0;
}

