typedef struct record {
    long offset;
    int key;
    int value;
} Record;

typedef struct hash_table_node {
    int key;
    Record* data;
    struct hash_table_node* next;
} HashTableNode;

typedef struct hash_table {
    int size;
    HashTableNode** buckets;
} HashTable;

HashTable* hash_table_init(int size) {
    HashTable* table = malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = calloc(size, sizeof(HashTableNode*));
    return table;
}

void hash_table_free(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            HashTableNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

int hash_function(int key, int size) {
    return key % size;
}

void insert_record(HashTable* table, int key, long offset, int value) {
    HashTableNode* node = malloc(sizeof(HashTableNode));
    node->key = key;
    node->data = malloc(sizeof(Record));
    node->data->offset = offset;
    node->data->key = key;
    node->data->value = value;
    node->next = table->buckets[hash_function(key, table->size)];
    table->buckets[hash_function(key, table->size)] = node;
}

void delete_record(HashTable* table, int key) {
    for (int i = 0; i < table->size; i++) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            if (node->key == key) {
                table->buckets[i] = node->next;
                free(node);
                return;
            }
            node = node->next;
        }
    }
}

Record* find_record(HashTable* table, int key) {
    for (int i = 0; i < table->size; i++) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            if (node->key == key) {
                return node->data;
            }
            node = node->next;
        }
    }
    return NULL;
}

void serialize_records(HashTable* table, FILE* file) {
    for (int i = 0; i < table->size; i++) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            Record* record = node->data;
            fwrite(&record->offset, sizeof(long), 1, file);
            fwrite(&record->key, sizeof(int), 1, file);
            fwrite(&record->value, sizeof(int), 1, file);
            node = node->next;
        }
    }
}

void deserialize_records(HashTable* table, FILE* file) {
    Record record;
    for (int i = 0; i < table->size; i++) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            fread(&record.offset, sizeof(long), 1, file);
            fread(&record.key, sizeof(int), 1, file);
            fread(&record.value, sizeof(int), 1, file);
            insert_record(table, record.key, record.offset, record.value);
            node = node->next;
        }
    }
}

void log_event(const char* event) {
    printf("Event: %s\n", event);
}

int main() {
    srand(time(NULL));
    HashTable* table = hash_table_init(1024);
    for (int i = 0; i < 10000; i++) {
