    // Calculate memory size needed for arrays
    int total_size = sizeof(Record) * num_records + sizeof(long) * num_records + sizeof(int) * num_records;

    // Allocate memory for arrays
    if ((records = (Record*)malloc(total_size)) == NULL || 
