        (keys = (int*)malloc(sizeof(int) * num_records)) == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(mutex);
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records
    for (int i = 0; i < num_records; i++) {
        records[i].value = i;
        offsets[i] = i * sizeof(int);
        keys[i] = i % 10;
    }

    pthread_mutex_unlock(mutex);

    return records;
}

void free_records(Record* records, long* offsets, int* keys) {
    free(offsets);
    free(keys);
    free(records);
}

