#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>

#define RANDOM_SEED 42
#define MEMORY_THRESHOLD 0.75
#define RECORD_SIZE sizeof(record)

typedef struct {
    int value;
    long* offset;
    int* key;
} record;

record* create_record(pthread_mutex_t* lock, pthread_mutexattr_t attr) {
    record* r = (record*)malloc(RECORD_SIZE);
    if (!r) return NULL;

    r->value = rand() % 100; // Generate random value within range
    r->offset = (long*)malloc(sizeof(long));
    r->key = (int*)malloc(sizeof(int));

    pthread_mutex_init(lock, &attr); // Initialize lock

    return r;
}

void* allocate_memory(pthread_mutex_t* lock) {
    size_t available_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    size_t limit = (size_t)(available_memory * MEMORY_THRESHOLD);

    size_t total_allocated = 0;
    record** records = NULL;

    for (int i = 0; i < 10000; i++) {
        record* r = create_record(lock, PTHREAD_MUTEX_INITIALIZER);
        if (!r) break;

        records = (record**)realloc(records, sizeof(record*) * (i + 1));
        if (!records) break;

        records[i] = r;
        total_allocated += RECORD_SIZE;

        if (total_allocated > limit) {
            for (int j = i; j >= 0; j--) {
                free(records[j]->offset);
                free(records[j]->key);
                free(records[j]);
            }
            free(records);
            return NULL;
        }
    }

    pthread_mutex_destroy(lock);

    return records;
}

void sort_records(record** records, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (records[i]->value > records[j]->value) {
                record* temp = *records++;
                *records-- = temp;
            }
        }
    }
}

void print_records(record** records, int n) {
    for (int i = 0; i < n; i++) {
        printf("(%d, %ld, %d)\n", records[i]->value, *records[i]->offset, *(records[i]->key));
    }
}

int main() {
    pthread_mutex_t lock;
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_DEFAULT);

    record** records = allocate_memory(&lock);

    if (!records) return 1;

    sort_records(records, 10000);
    print_records(records, 10000);

    for (int i = 0; i < 10000; i++) {
        free(records[i]->offset);
        free(records[i]->key);
        free(records[i]);
    }
    free(records);

    return 0;
}
