#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define TABLE_SIZE 1024
#define BUCKET_SIZE (TABLE_SIZE / 2)
#define MIN_BUCKET_SIZE 8
#define MAX_BUCKET_SIZE 16
#define MIN_LOAD_FACTOR 0.5
#define MAX_LOAD_FACTOR 1.0

typedef struct {
    int offset;
    int key;
    int record[1024];
    int size;
} Record;

typedef struct {
    Record* records;
    int table_size;
    int load_factor;
    pthread_mutex_t lock;
} HashTable;

void* hash_table_allocate(void* ptr, size_t size) {
    return realloc(ptr, size);
}

HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->records = (Record*)calloc(size, sizeof(Record));
    table->table_size = size;
    table->load_factor = 0.5;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void hash_table_free(HashTable* table) {
    free(table->records);
    free(table);
}

int hash(int key, int table_size) {
    return key % table_size;
}

int probe(int index, int bucket_size) {
    return (index + 1) % bucket_size;
}

Record* find_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    Record* record = &table->records[hash(key, table->table_size)];
    while (record->size == 0 || memcmp(&record->key, &key, sizeof(int)) != 0) {
        index = probe(index, BUCKET_SIZE);
        if (index >= MIN_BUCKET_SIZE && index < MAX_BUCKET_SIZE) {
            record = &table->records[index];
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&table->lock);
    return record;
}

void insert_record(HashTable* table, Record* record) {
    int key = record->key;
    int bucket = hash(key, table->table_size);
    while (table->records[bucket].size > 0 && memcmp(&table->records[bucket].key, &key, sizeof(int)) != 0) {
        bucket = probe(bucket, BUCKET_SIZE);
    }
    table->records[bucket] = *record;
}

void delete_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    int index = hash(key, table->table_size);
    while (table->records[index].size > 0 && memcmp(&table->records[index].key, &key, sizeof(int)) != 0) {
        index = probe(index, BUCKET_SIZE);
    }
    if (table->records[index].size > 0) {
        table->records[index] = (Record){0};
    }
    pthread_mutex_unlock(&table->lock);
}

void log_error(const char* message) {
    // External logging and monitoring service
}

int main() {
    HashTable* table = create_hash_table(MAX_RECORDS);

    // Initialize records with random values
    for (int i = 0; i < MAX_RECORDS; i++) {
        Record record;
        record.offset = rand();
        record.key = rand();
        record.size = sizeof(record.record) / sizeof(record.record[0]);
        insert_record(table, &record);
    }

    // Periodic updates from external data source
    for (int i = 0; i < MAX_RECORDS; i++) {
        Record record;
        record.offset = rand();
        record.key = rand();
        record.size = sizeof(record.record) / sizeof(record.record[0]);
        insert_record(table, &record);
    }

    // Handle edge cases and optimizations
    if (table->load_factor > MAX_LOAD_FACTOR || table->load_factor < MIN_LOAD_FACTOR) {
        log_error("Load factor out of bounds");
    }

    return 0;
}
