#define MAX_SIZE 10
#define MAX_STR_LEN 20
#define MIN_INT_VAL 0
#define MAX_INT_VAL 100

typedef struct {
    char* str;
    int value;
    time_t timestamp;
} Structure;

Structure** array = NULL;
int array_size = 0;

void my_realloc(void** ptr, size_t new_size) {
    void* new_ptr = realloc(*ptr, new_size * sizeof(Structure*));
    if (!new_ptr) {
        free(*ptr);
        return NULL;
    }
    *ptr = new_ptr;
    return *ptr;
}

int log_array_state() {
    FILE* file = fopen("array_state.log", "a");
    if (!file) {
        printf("Error: Unable to open array_state.log for logging.\n");
        return -1;
    }

    fprintf(file, "Array size: %d\n", array_size);
    for (int i = 0; i < array_size; i++) {
        fprintf(file, "Structure %d: str='%s', value=%d, timestamp=%ld\n", i, array[i]->str, array[i]->value, array[i]->timestamp);
    }
    fclose(file);

    return 0;
}

int init_array(int new_size) {
    void* new_ptr = my_realloc(&array, new_size * sizeof(Structure**));
    if (!new_ptr) {
        printf("Error: Unable to allocate memory for array initialization.\n");
        return -1;
    }
    array = new_ptr;

    for (int i = 0; i < new_size; i++) {
        Structure* struc = malloc(sizeof(Structure));
        if (!struc) {
            printf("Error: Unable to allocate memory for structure initialization.\n");
            return -1;
        }

        char* str = malloc((MAX_STR_LEN + 1) * sizeof(char));
        if (!str) {
            free(struc);
            return -1;
        }
        sprintf(str, "Random_string_%d", i);

        int value = rand() % (MAX_INT_VAL - MIN_INT_VAL + 1) + MIN_INT_VAL;

        time_t timestamp = time(NULL);

        struc->str = str;
        struc->value = value;
        struc->timestamp = timestamp;

        array[i] = struc;
    }

    return 0;
}

int cleanup() {
    for (int i = 0; i < array_size; i++) {
        if (array[i]->str) free(array[i]->str);
        free(array[i]);
    }
    free(array);

    return 0;
}

int main() {
    srand(time(NULL)); // seed random number generator

    int init_size = 5;
    while (1) {
        init_array(init_size);
        if (init_array == -1) break;

        array_size = init_size;
        log_array_state();

        // simulate work with the array...
        for (int i = 0; i < array_size; i++) {
            printf("Working with structure %d...\n", i);
        }

        cleanup();
    }

    return 0;
}

