public class DynamicRecordProcessor
{
    private readonly TripleDESCryptoServiceProvider _cryptoService = new TripleDESCryptoServiceProvider();

    public void Initialize(string key, byte[] iv)
    {
        if (key.Length != 16) throw new ArgumentException("Key must be 128 bits long");
        if (iv.Length != 8) throw new ArgumentException("Initialization vector must be 64 bits long");

        _cryptoService.Key = Convert.FromBase64String(key);
        _cryptoService.IV = iv;
    }

    public byte[] Decrypt(byte[] data)
    {
        return _cryptoServiceDecryptTransform.TransformFinalBlock(data, 0, data.Length);
    }

    private ICryptoTransform _cryptoServiceDecryptTransform
    {
        get { return _cryptoService.CreateDecryptor(); }
    }

    public void SetRecordValue(record r, int min, int max)
    {
        r.Value = new Random().Next(min, max + 1);
    }

    [Obsolete]
    internal static byte[] GenerateKey()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var keyBytes = new byte[16];
            rng.GetBytes(keyBytes);
            return keyBytes;
        }
    }

    [Obsolete]
    internal static byte[] GenerateIV()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var ivBytes = new byte[8];
            rng.GetBytes(ivBytes);
            return ivBytes;
        }
    }

    [Obsolete]
    internal record record(int Value)
    {
    }
