    for (size_t i = 0; i < initial_capacity; i++) {
        (*collection)[i] = NULL;
    }
}

int concat_strings(const data_entry* entries, int entry_count, char* buffer, char delimiter) {
    size_t total_length = 0;
    for (int i = 0; i < entry_count; i++) {
        if (entries[i]->data != NULL && *entries[i]->data != '\0') {
            total_length += strlen(entries[i]->data) + 1; // +1 for delimiter
        }
    }

    buffer = realloc(buffer, total_length + 1); // Add extra byte for null termination

    char* current_position = buffer;
    for (int i = 0; i < entry_count; i++) {
        if (entries[i]->data != NULL && *entries[i]->data != '\0') {
            strcpy(current_position, entries[i]->data);
            current_position += strlen(entries[i]->data);
            *current_position = delimiter;
            current_position++;
        }
    }

    *current_position = '\0';
    return total_length;
}

void free_data_collection(data_entry** collection, size_t capacity) {
    for (size_t i = 0; i < capacity; i++) {
        if (collection[i] != NULL) {
            free(collection[i]->data);
            free(collection[i]);
        }
    }

    free(collection);
}
