#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <queue>
#include <algorithm>

using namespace std;

class Resource {
public:
    string name;
    int type;
    float availability;
};

class ResourceManager {
private:
    struct Node {
        Resource resource;
        Node* left, *right;
    };

    map<string, Node*> resources;
    priority_queue<float> availabilityQueue;
    float totalAvailability = 0.0f;

    void rebalance(Node* node) {
        if (node == nullptr)
            return;
        int heightDiff = get_height(node->left) - get_height(node->right);
        if (heightDiff > 1) {
            // Left-heavy
            if (get_height(node->left->left) >= get_height(node->left->right))
                rotate_left(node);
            else
                rotate_right(node);
        }
        else if (heightDiff < -1) {
            // Right-heavy
            if (get_height(node->right->right) >= get_height(node->right->left))
                rotate_right(node);
            else
                rotate_left(node);
        }
    }

    void rotate_left(Node* node) {
        Node* pivot = node->right;
        node->right = pivot->left;
        pivot->left = node;
        if (resources.find(pivot->resource.name) != resources.end())
            resources[pivot->resource.name] = pivot;
        rebalance(pivot);
    }

    void rotate_right(Node* node) {
        Node* pivot = node->left;
        node->left = pivot->right;
        pivot->right = node;
        if (resources.find(pivot->resource.name) != resources.end())
            resources[pivot->resource.name] = pivot;
        rebalance(pivot);
    }

    int get_height(Node* node) {
        return node == nullptr ? 0 : max(get_height(node->left), get_height(node->right)) + 1;
    }

public:
    ResourceManager() {
        // Initialize the BST with an initial capacity of 32
        Node* root = new Node();
        resources[""] = root;
        totalAvailability += 1.0f; // dummy resource availability for initialization
    }

    void addResource(const string& name, int type, float availability) {
        Resource resource = {name, type, availability};
        Node* newNode = new Node();
        newNode->resource = resource;

        if (resources.empty()) {
            resources[name] = newNode;
            totalAvailability += availability;
            availabilityQueue.push(availability);
        }
        else {
            Node* current = root;
            while (true) {
                if (newNode->resource.name < current->resource.name)
                    current = current->left;
                else
                    current = current->right;

                // If the new resource's name is in the middle, split the node and insert
                if (current->resource.name == newNode->resource.name) {
                    // Handle duplicate names gracefully
                    // For simplicity, assume this is not possible
                    assert(false);
                    return;
                }

                if (newNode->resource.name < current->resource.name)
                    current = current->left;
                else
                    current = current->right;

                if (!current || newNode->resource.name == current->resource.name) {
                    // Insert at the correct position
                    new Node* temp = current;
                    current = new Node();
                    current->left = temp;
                    resources[newNode->resource.name] = current;
                    totalAvailability += availability;
                    availabilityQueue.push(availability);
                    return;
                }
            }
        }
    }

    void updateResource(const string& name, float newAvailability) {
        if (resources.find(name) != resources.end()) {
            Node* node = resources[name];
            node->resource.availability = newAvailability;
            totalAvailability += newAvailability - node->resource.availability;
            availabilityQueue.push(newAvailability);
        }
    }

    void removeResource(const string& name) {
        if (resources.find(name) != resources.end()) {
            Node* node = resources[name];
            rebalance(node);
            totalAvailability -= node->resource.availability;
            // Remove the node and update the map
            resources.erase(name);

            if (!node->left && !node->right)
                delete node;
            else if (node->left) {
                node->name = node->left->resource.name;
                node = node->left;
                rebalance(node);
            }
            else {
                // node has a right child, so copy the contents to this node
                node->name = node->right->resource.name;
                node = node->right;
                rebalance(node);
            }

            availabilityQueue.pop();
        }
    }

    void monitorAvailability(float threshold) {
        while (!availabilityQueue.empty() && totalAvailability < threshold) {
            // Notify the system or trigger an action based on low resource availability
            cout << "Low resource availability: " << totalAvailability << endl;
        }
    }
};
