#define MAX_FILE_OFFSETS 1000
#define MIN_IDENTIFIER 0

typedef struct {
    long *file_offset;
    int *identifier;
} Record;

Record* manage_memory(int num_file_offsets, int num_identifiers) {
    if (num_file_offsets > MAX_FILE_OFFSETS || num_identifiers > MAX_FILE_OFFSETS) {
        return NULL; // Error: size exceeds maximum
    }

    Record* records = (Record*)malloc(sizeof(Record));
    if (!records) {
        return NULL; // Memory allocation failure
    }

    records->file_offset = (long*)malloc(num_file_offsets * sizeof(long));
    if (!records->file_offset) {
        free(records);
        return NULL; // Memory allocation failure
    }
    memset(records->file_offset, 0, num_file_offsets * sizeof(long));

    records->identifier = (int*)malloc(num_identifiers * sizeof(int));
    if (!records->identifier) {
        free(records->file_offset);
        free(records);
        return NULL; // Memory allocation failure
    }
    memset(records->identifier, MIN_IDENTIFIER, num_identifiers * sizeof(int));

    for (int i = 0; i < num_file_offsets; i++) {
        records->file_offset[i] = (long)i;
    }
    for (int i = 0; i < num_identifiers; i++) {
        records->identifier[i] = MIN_IDENTIFIER + i;
    }

    return records;
}

void free_memory(Record* records) {
    if (records) {
        free(records->file_offset);
        free(records->identifier);
        free(records);
    }
}
