typedef struct {
    time_t timestamp;
    float reading;
    char status;
    int value;
} SensorRecord;

// Define the structure for the doubly linked list node
typedef struct Node {
    SensorRecord* record;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the structure for the cache (thread-safe hash table)
typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    void** keys;
    void** values;
} Cache;

// Function to create a new SensorRecord
