    SensorRecord* record = (SensorRecord*)malloc(sizeof(SensorRecord));
    record->timestamp = timestamp;
    record->reading = reading;
    record->status = status;
    record->value = value;
    return record;
}

// Function to create a new Node
Node* node_create(SensorRecord* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to create a new Cache
Cache* cache_create(size_t capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->keys = (void**)calloc(capacity, sizeof(void*));
    cache->values = (void**)calloc(capacity, sizeof(void*));
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Function to add a record to the doubly linked list
void sensor_list_add(Node** head, SensorRecord* record) {
    Node* node = node_create(record);
    if (*head == NULL) {
        *head = node;
    } else {
        node->next = *head;
        (*head)->prev = node;
        *head = node;
    }
}

// Function to remove a record from the doubly linked list
void sensor_list_remove(Node** head, SensorRecord* record) {
    Node* current = *head;
    while (current != NULL && current->record != record) {
        current = current->next;
    }
    if (current == NULL) return;
    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        *head = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    free(current);
}

// Function to update a record in the doubly linked list
void sensor_list_update(Node** head, SensorRecord* record) {
    Node* current = *head;
    while (current != NULL && current->record != record) {
        current = current->next;
    }
    if (current == NULL) return; // Record not found
    current->record = record;
}

// Function to get a record from the cache
SensorRecord* cache_get(Cache* cache, time_t timestamp) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->capacity; i++) {
        if (cache->keys[i] != NULL && *(time_t*)cache->keys[i] == timestamp) {
            SensorRecord* record = (SensorRecord*)cache->values[i];
            pthread_mutex_unlock(&cache->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL; // Cache miss
}

// Function to put a record in the cache
void cache_put(Cache* cache, time_t timestamp, SensorRecord* record) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->capacity; i++) {
        if (cache->keys[i] == NULL) {
            cache->keys[i] = &timestamp;
            cache->values[i] = record;
            cache->size++;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Function to read data from a file
void read_file(char* filename, Node** head, Cache* cache) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return; // File not found

    SensorRecord record;
    while (fscanf(file, "%ld %f %c %d", &record.timestamp, &record.reading, &record.status, &record.value) == 4) {
        sensor_list_add(head, &record);
        cache_put(cache, record.timestamp, &record);
    }
}

// Function to update data from multiple threads
void* update_thread(void* arg) {
    // Update logic goes here
    return NULL;
}

int main() {
    Node* head = NULL;
    Cache* cache = cache_create(100);

    read_file("data.txt", &head, cache);

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, update_thread, NULL);
    pthread_create(&thread2, NULL, update_thread, NULL);

    // Wait for threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
