int pool_size = POOL_SIZE;
int string_pool_used = 0;
int integer_pool_used = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

CustomStruct* allocate_custom_struct(char* str, int val) {
    pthread_mutex_lock(&lock);

    if (string_pool_used >= STRING_POOL_SIZE || integer_pool_used >= INTEGER_POOL_SIZE) {
        // Resource exhausted
        printf("Resource exhaustion detected.\n");
    }

    for (int i = 0; i < pool_size; i++) {
        if (!custom_struct_pool[i]->str && !integer_pool_used[i]) {
            custom_struct_pool[i]->str = str;
            custom_struct_pool[i]->val = val;
            string_pool_used++;
            return custom_struct_pool[i];
        }
    }

    // No available resources
    CustomStruct* new_alloc = (CustomStruct*)malloc(sizeof(CustomStruct));
    new_alloc->str = str;
    new_alloc->val = val;

    if (!custom_struct_pool) {
        custom_struct_pool = (CustomStruct**)malloc((pool_size + 1) * sizeof(CustomStruct*));
        for (int i = 0; i < pool_size; i++) {
            custom_struct_pool[i] = &new_alloc;
        }
    } else {
        if (string_pool_used >= POOL_SIZE) {
            // Realloc
            custom_struct_pool = (CustomStruct**)realloc(custom_struct_pool, (pool_size * 2 + 1) * sizeof(CustomStruct*));
            for (int i = pool_size; i < pool_size * 2; i++) {
                custom_struct_pool[i] = &new_alloc;
            }
        } else {
            custom_struct_pool[string_pool_used] = &new_alloc;
            string_pool_used++;
        }
    }

    return new_alloc;
}

void deallocate_custom_struct(CustomStruct* cs) {
    pthread_mutex_lock(&lock);

    if (cs->str) {
        free(cs->str);
    }
    free(cs);

    pthread_mutex_unlock(&lock);
}
