#define BUCKET_SIZE 16
#define MAX_ENTRIES 1024
#define MAX_NAME_LENGTH 256

typedef struct {
    char* name;
    double value;
} entry_t;

typedef struct {
    entry_t** entries;
    size_t size;
    pthread_mutex_t lock;
} hash_table_t;

hash_table_t* hash_table_create() {
    hash_table_t* table = (hash_table_t*)malloc(sizeof(hash_table_t));
    table->entries = (entry_t**)calloc(BUCKET_SIZE, sizeof(entry_t*));
    table->size = BUCKET_SIZE;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void hash_table_destroy(hash_table_t* table) {
    for (int i = 0; i < table->size; i++) {
        free(table->entries[i]);
    }
    free(table->entries);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

entry_t* hash_table_get_entry(hash_table_t* table, const char* name) {
    size_t hash = 0;
    for (int i = 0; i < strlen(name); i++) {
        hash += name[i];
    }
    return table->entries[hash % table->size][hash % table->size * 2 + 1];
}

void hash_table_add_entry(hash_table_t* table, const char* name, double value) {
    entry_t* entry = (entry_t*)malloc(sizeof(entry_t));
    entry->name = strdup(name);
    entry->value = value;
    size_t hash = 0;
    for (int i = 0; i < strlen(name); i++) {
        hash += name[i];
    }
    int bucket_index = hash % table->size;
    if (table->entries[bucket_index] == NULL) {
        table->entries[bucket_index] = (entry_t**)calloc(1, sizeof(entry_t*));
    }
    table->entries[bucket_index][hash % table->size * 2 + 1] = entry;
}

void hash_table_update_entry(hash_table_t* table, const char* name, double value) {
    entry_t* entry = hash_table_get_entry(table, name);
    if (entry != NULL) {
        free(entry->name);
        entry->name = strdup(name);
        entry->value = value;
    }
}

void hash_table_remove_entry(hash_table_t* table, const char* name) {
    size_t hash = 0;
    for (int i = 0; i < strlen(name); i++) {
        hash += name[i];
    }
    int bucket_index = hash % table->size;
    entry_t** entries = &table->entries[bucket_index];
    for (int i = 0; i < table->size; i++) {
        if (entries[i] != NULL) {
            if (entries[i][hash % table->size * 2 + 1]->name != NULL) {
                free(entries[i][hash % table->size * 2 + 1]->name);
            }
            free(entries[i]);
        }
    }
}

void hash_table_purge_old_entries(hash_table_t* table, size_t max_entries) {
    for (int i = 0; i < table->size; i++) {
        entry_t** entries = &table->entries[i];
        int j = 0;
        while (j < table->size * 2 && entries[j] != NULL) {
            if (j >= max_entries) {
                free(entries[j]->name);
                free(entries[j]);
            }
            j++;
        }
    }
}

int main() {
    // Create the hash table
    hash_table_t* table = hash_table_create();

    // Add some entries
    hash_table_add_entry(table, "entry1", 10.5);
    hash_table_add_entry(table, "entry2", 20.3);
    hash_table_add_entry(table, "entry3", 30.7);

    // Update an entry
    hash_table_update_entry(table, "entry2", 21.4);

    // Remove an entry
    hash_table_remove_entry(table, "entry1");

    // Purge old entries
    hash_table_purge_old_entries(table, 2);

    // Clean up
    hash_table_destroy(table);
}
