    static void* heap = NULL;
    if (!heap) {
        heap = malloc(4096);  // initial allocation
    }

    // Try to find a suitable block in the existing heap
    for (void* p = heap; p < (void*) ((char*) heap + size); p += getpagesize()) {
        if (((char*) p + size) <= (char*) heap + 4096) {
            return p;
