// Custom memory pool structure
typedef struct {
    void** mem_pool;
    size_t capacity;
    size_t used;
} mem_pool_t;

mem_pool_t* create_mem_pool(size_t capacity) {
    mem_pool_t* pool = (mem_pool_t*)malloc(sizeof(mem_pool_t));
    pool->mem_pool = (void**)malloc(capacity * sizeof(void*));
    pool->capacity = capacity;
    pool->used = 0;
    return pool;
}

void free_mem_pool(mem_pool_t* pool) {
    for (size_t i = 0; i < pool->used; i++) {
        free((void*)pool->mem_pool[i]);
    }
    free(pool->mem_pool);
    free(pool);
}

// Function to initialize and allocate a new node
node_t* create_node(mem_pool_t* pool, const char* str) {
    node_t* node = (node_t*)malloc(sizeof(node_t));
    record_t* rec = (record_t*)malloc(sizeof(record_t));

    // Initialize record fields
    rec->str = strdup(str);
    rec->val = rand() % 100; // Generate a random int value within the range [0, 100)
    rec->next = NULL;

    node->rec = rec;
    pool->mem_pool[pool->used++] = node;
    return node;
}

// Function to print all nodes and their respective records
void print_nodes(node_t* head) {
    node_t* current = head;
    while (current != NULL) {
        record_t* rec = current->rec;
