// Array of entries with dynamic memory allocation
entry **entries = NULL;
size_t num_entries = 0;
size_t max_entries = MAX_ARRAY_SIZE;

// Validate data sizes and prevent exceeding maximum limit
int validate_data_sizes(size_t *data_sizes, size_t num_data_sizes) {
    for (size_t i = 0; i < num_data_sizes; i++) {
        if (data_sizes[i] > MAX_DATA_SIZE || data_sizes[i] == 0) {
            return -1;
        }
    }
    return 0;
