    entry **new_entries = realloc(entries, sizeof(entry *) * new_num_entries);
    if (!new_entries) {
        return NULL;
    }
    memset(new_entries, 0, sizeof(entry *) * new_num_entries);
    return new_entries;
}

// Resize array of entries
void resize_entries(size_t new_size) {
    pthread_mutex_lock(&mtx);
    entry **new_entries = reallocate_entries(new_size);
