    new_entry->key = 0;
    new_entry->offset = 0;
    new_entry->data_size = data_size;
    return new_entry;
}

// Allocate and initialize multiple entries
entry **allocate_entries(size_t num_entries, size_t *data_sizes) {
    pthread_mutex_lock(&mtx);
    entry **new_entries = realloc(entries, sizeof(entry *) * (num_entries + 1));
    if (!new_entries) {
        printf("Failed to reallocate memory!\n");
        exit(1);
    }
    for (size_t i = 0; i < num_entries; i++) {
        entry *new_entry = allocate_entry(data_sizes[i]);
        if (!new_entry) {
            printf("Failed to allocate memory!\n");
            exit(1);
        }
        new_entries[i] = new_entry;
    }
    free(entries);
    entries = new_entries;
    num_entries++;
    pthread_mutex_unlock(&mtx);
    return new_entries;
}

