#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define MEM_BUDGET (1024 * 1024) // adjust this value based on your system's memory constraints

typedef struct {
    long offset;
    int key;
    time_t timestamp;
} Record;

Record* record_pool = NULL; // initialize the memory pool
int record_count = 0; // keep track of allocated records

void init_record_pool(int budget) {
    if (record_pool != NULL) return; // ensure pool is not already initialized

    // calculate the required amount of memory for each record, considering system and process usage
    int record_size = sizeof(Record);
    int mem_limit = (int)((double)budget * 0.8); // adjust this factor based on your application's requirements

    if ((record_pool = (Record*)malloc(mem_limit)) == NULL) {
        printf("Error: Out of memory.\n");
        exit(EXIT_FAILURE);
    }

    record_count = 0;
}

void free_record_pool() {
    if (record_pool != NULL) {
        free(record_pool);
        record_pool = NULL;
        record_count = 0;
    }
}

Record* create_random_record(int seed, int key_range) {
    Record* record = &record_pool[record_count];
    srand(seed + record_count); // update the random number generator

    record->offset = (long)srand() % 100000; // generate a random offset value
    record->key = rand() % key_range;
    record->timestamp = time(NULL);

    return record;
}

void add_record(int seed, int key_range) {
    if (record_count >= MAX_RECORDS) {
        printf("Error: Record limit exceeded.\n");
        return; // prevent excessive memory allocation
    }

    create_random_record(seed, key_range);
    record_count++;
}

int update_record(long offset, int new_key) {
    for (int i = 0; i < record_count; i++) {
        if (record_pool[i].offset == offset) {
            record_pool[i].key = new_key;
            return 1; // successful update
        }
    }

    printf("Error: Record not found.\n");
    return -1; // failed to find the record
}

int delete_record(long offset) {
    for (int i = 0; i < record_count; i++) {
        if (record_pool[i].offset == offset) {
            memmove(&record_pool[i], &record_pool[i + 1], sizeof(Record) * (record_count - i));
            record_count--;
            return 1; // successful deletion
        }
    }

    printf("Error: Record not found.\n");
    return -1; // failed to find the record
}

int main(int argc, char** argv) {
    int seed = time(NULL); // use current timestamp as default seed

    if (argc > 1) {
        seed = atoi(argv[1]); // override with command-line argument
    }

    init_record_pool(MEM_BUDGET);

    add_record(seed, 1000);
    add_record(seed + 10, 2000);
    update_record(123456789, 3000);
    delete_record(987654321);

    free_record_pool();

    return EXIT_SUCCESS;
}
