#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    struct record* next;
    struct record* prev;
} record;

record* create_record() {
    record* new_rec = (record*)malloc(sizeof(record));
    if(new_rec == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    new_rec->value = rand() % 100; // set to a random value
    new_rec->next = NULL;
    new_rec->prev = NULL;
    return new_rec;
}

void free_records(record* head) {
    record* curr = head;
    while(curr != NULL) {
        record* next = curr->next;
        free(curr);
        curr = next;
    }
}

int filter_transactions(record* transactions, int threshold_age, int threshold_count, int threshold_sum) {
    int max_weighted_sum = 0;
    int max_id = -1;
    record* curr = transactions;

    while(curr != NULL) {
        if(curr->value > threshold_age && curr->value < 3 && (curr->next == NULL || curr->next->value < 3) && curr->value + rand() % 100 <= threshold_sum) {
            int weighted_sum = curr->value;
            // update metrics
            printf("Transaction ID: %p, Weighted Sum: %d\n", &curr, weighted_sum);
            if(weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_id = (int)&curr;
            }
        }
        curr = curr->next;
    }

    return max_id;
}

record* init_transactions(int size) {
    record* head = NULL;
    for(int i = 0; i < size; i++) {
        record* new_rec = create_record();
        if(head == NULL) {
            head = new_rec;
        } else {
            head->prev = new_rec;
            new_rec->next = head;
            head = new_rec;
        }
    }

    return head;
}

void free_all(record* transactions, int size) {
    for(int i = 0; i < size; i++) {
        record* curr = transactions;
        for(int j = 0; j <= i; j++) {
            record* next = curr->next;
            free(curr);
            curr = next;
        }
    }
}

int main() {
    srand(time(NULL)); // initialize pseudo-random number generator

    int size = 100; // adjust as needed
    record* transactions = init_transactions(size);

    int max_id = filter_transactions(transactions, 10, 5, 500);
    printf("Maximum Weighted Sum ID: %d\n", max_id);

    free_all(transactions, size);

    return 0;
}

