#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int key;
    long offset;
    int value;
} Record;

// Function to manage a collection of records
Record** allocateRecords(int numRecords) {
    if (numRecords <= 0) return NULL;

    // Dynamically allocate memory for arrays and structures
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    long* offsets = (long*)malloc(numRecords * sizeof(long));

    // Initialize arrays with zeros or default values
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->key = 0;
        records[i]->offset = 0;
        records[i]->value = 0;
    }

    // Return pointers to arrays and structures
    return records;
}

// Function to update a specific record's value based on index, offset, and new value
void updateRecord(Record** records, int numRecords, int idx, long off, int newValue) {
    if (idx >= 0 && idx < numRecords && off == records[idx]->offset) {
        records[idx]->value = newValue;
    }
}

// Function to perform batch operations (bulk updates or deletions)
void batchOperations(Record** records, int numRecords, int start, int end, int operationType) {
    for (int i = start; i <= end; i++) {
        if (i >= 0 && i < numRecords) {
            // Perform update or deletion based on operation type
            switch (operationType) {
                case 1: // Update value
                    records[i]->value++;
                    break;
                case 2: // Delete record
                    free(records[i]);
                    for (int j = i; j < numRecords - 1; j++) {
                        records[j] = records[j + 1];
                    }
                    numRecords--;
                    break;
            }
        }
    }
}

// Function to deallocate memory when exiting the program
void deallocateMemory(Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(keys);
    free(offsets);
    free(records);
}
