    size_t count;
    bool sorted;
} Metadata;

Item* createItem(char* name, double value) {
    Item* item = (Item*)malloc(sizeof(Item));
    if (!item) return NULL;
    item->name = malloc(strlen(name) + 1);
    strcpy(item->name, name);
    item->value = value;
    return item;
}

Metadata* createMetadata() {
    Metadata* metadata = (Metadata*)malloc(sizeof(Metadata));
    if (!metadata) return NULL;
    metadata->count = 0;
    metadata->sorted = false;
    return metadata;
}

void freeItem(Item* item) {
    free(item->name);
    free(item);
}

void freeMetadata(Metadata* metadata) {
    free(metadata);
}

int addItem(Item** items, Metadata* metadata, char* name, double value) {
    Item* item = createItem(name, value);
    if (!item) return -1;
    *items = realloc(*items, (metadata->count + 1) * sizeof(Item));
    (*items)[metadata->count++] = *item;
    return 0;
}

int sortItems(Item** items, Metadata* metadata) {
    qsort(*items, metadata->count, sizeof(Item), itemComparator);
    metadata->sorted = true;
    return 0;
}

int itemComparator(const void* a, const void* b) {
    Item* ia = *(Item*)a;
    Item* ib = *(Item*)b;
    if (ia->value < ib->value) return -1;
    else if (ia->value > ib->value) return 1;
    return 0;
}

void printItems(Item* items, Metadata metadata) {
    for (size_t i = 0; i < metadata.count; ++i) {
        printf("Name: %s, Value: %f\n", items[i].name, items[i].value);
    }
}
