// Function to create and initialize a new polygon with random points within the given range
Polygon* create_polygon(int min_x, int min_y, int max_x, int max_y) {
    Polygon* poly = (Polygon*)malloc(sizeof(Polygon));
    poly->size = 0;
    poly->points = NULL;

    // Ensure no two consecutive points share the same x-coordinate to prevent degenerate polygons
    for(int i = 0; i < 3; i++) { // Initialize with at least 3 points
        Point* new_point = (Point*)malloc(sizeof(Point));
        new_point->x = rand() % (max_x - min_x + 1) + min_x;
        new_point->y = rand() % (max_y - min_y + 1) + min_y;

        // Update the polygon's points and size
        if(poly->size == 0) {
            poly->points = (Point*)malloc(sizeof(Point));
            poly->points[0] = *new_point;
            poly->size++;
        } else {
            Point* prev = &poly->points[poly->size - 1];
            new_point->x += rand() % (max_x - min_x + 1) + min_x; // Ensure no consecutive points have the same x-coordinate
            poly->points = (Point*)realloc(poly->points, (poly->size + 1) * sizeof(Point));
            poly->points[poly->size++] = *new_point;
        }
    }

    return poly;
}

// Function to validate a polygon and check for non-degeneracy and self-intersection
int is_valid_polygon(Polygon* poly) {
    // Check for non-degeneracy (at least 3 points)
    if(poly->size < 3) return 0;

    // Check for self-intersection
    for(int i = 0; i < poly->size - 2; i++) {
        Point* p1 = &poly->points[i];
        Point* p2 = &poly->points[i + 1];
        Point* p3 = &poly->points[i + 2];

        // Calculate the cross product of vectors (p2, p3) and (p1, p2)
        int cross_product = (p2->x - p1->x) * (p3->y - p2->y) - (p2->y - p1->y) * (p3->x - p2->x);

        if(cross_product == 0) return 0; // Self-intersection detected
    }

    return 1;
}

// Function to add a new polygon to the collection, ensuring thread safety with a lock
void add_polygon(Polygon** polygons, int* size, Polygon* new_poly) {
    pthread_mutex_lock(&lock); // Lock for concurrent access

    (*size)++;
    (*polygons) = (Polygon*)realloc(*polygons, *size * sizeof(Polygon));
    (*polygons)[*size - 1] = *new_poly;

    pthread_mutex_unlock(&lock); // Unlock
}

// Function to remove a polygon from the collection, ensuring thread safety with a lock
void remove_polygon(Polygon** polygons, int* size) {
    if(*size > 0) {
        (*size)--;
        Polygon* temp = (Polygon*)malloc(sizeof(Polygon));
        *temp = (**polygons);
        free(**polygons);
        **polygons = NULL;
        free(temp);
    }
}

// Function to query the collection of polygons
void query_polygons(Polygon** polygons, int size) {
    for(int i = 0; i < size; i++) {
        printf("Polygon %d:\n", i + 1);
        Polygon* poly = &polygons[i];
        for(int j = 0; j < poly->size; j++) {
            Point* point = &poly->points[j];
            printf("(%d, %d)\n", point->x, point->y);
        }
    }
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    Polygon* polygons = NULL;
    int size = 0;

    for(int i = 0; i < 10; i++) { // Create and add 10 random polygons to the collection
        Polygon* new_poly = create_polygon(0, 0, 100, 100);
        add_polygon(&polygons, &size, new_poly);
    }

    printf("Polygons:\n");
    query_polygons(polygons, size);

    // Validate each polygon and remove any invalid ones
    for(int i = 0; i < size; i++) {
        if(!is_valid_polygon(&polygons[i])) {
            remove_polygon(&polygons, &size);
            i--;
        }
    }

    printf("Valid Polygons:\n");
    query_polygons(polygons, size);

    return 0;
}
