Record *records = NULL;
int size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    if (LOG_LEVEL > 1) {
        printf("INFO: %s\n", message);
    }
}

void init_records() {
    pthread_mutex_lock(&lock);
    records = (Record *)malloc(MAX_SIZE * sizeof(Record));
    size = 0;
    log_message("Records initialized");
    pthread_mutex_unlock(&lock);
}

int insert_record(long offset, int key) {
    Record *new_record;
    pthread_mutex_lock(&lock);
    if (size >= MAX_SIZE) {
        log_message("Maximum size reached; truncating records");
        for (int i = 0; i < size; i++) {
            free(records[i].value);
        }
        size = 0;
    }
    new_record = &records[size];
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = (int *)malloc(sizeof(int));
    *new_record->value = 0;
    size++;
    log_message("Record inserted");
    pthread_mutex_unlock(&lock);
    return 0;
}

int delete_record(int key) {
    int i, j;
    pthread_mutex_lock(&lock);
    for (i = 0; i < size; i++) {
        if (records[i].key == key) {
            free(records[i].value);
            for (j = i + 1; j < size; j++) {
                records[j-1] = records[j];
            }
            size--;
            log_message("Record deleted");
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }
    log_message("Key not found in record set");
    pthread_mutex_unlock(&lock);
    return -1;
}

void iterate_records(void (*callback)(Record *)) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < size; i++) {
        callback(records[i]);
    }
    pthread_mutex_unlock(&lock);
}
