#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

#define RECORDS_MAX 1000
#define MOVING_AVERAGE_WINDOW 20
#define PERSISTENCY_THRESHOLD 50

typedef struct {
    int key;
    long offset;
} Record;

Record *records = NULL;
int records_count = 0;
int record_capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *persistency_file = NULL;

void* update_records(void* arg) {
    Record new_record = *(Record*)arg;
    pthread_mutex_lock(&mutex);
    if (records_count >= record_capacity) {
        record_capacity *= 2;
        records = realloc(records, sizeof(Record) * record_capacity);
    }
    records[records_count] = new_record;
    records_count++;
    pthread_mutex_unlock(&mutex);

    // Calculate moving average
    double sum = 0.0;
    int count = 0;
    for (int i = 0; i < MOVING_AVERAGE_WINDOW && i < records_count; i++) {
        sum += (double)records[i].offset / (i + 1);
        count++;
    }
    double moving_average = sum / count;

    // Persist updated records
    if (++records_count % PERSISTENCY_THRESHOLD == 0) {
        pthread_mutex_lock(&mutex);
        fseek(persistency_file, 0, SEEK_END);
        fwrite(records, sizeof(Record), record_capacity, persistency_file);
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

void init_persistency() {
    persistency_file = fopen("persistency.bin", "wb");
    if (persistency_file == NULL) {
        printf("Error: unable to create persistency file.\n");
        exit(1);
    }
}

int main() {
    init_persistency();

    // Create initial capacity for records
    record_capacity = RECORDS_MAX;
    records = malloc(sizeof(Record) * record_capacity);

    pthread_t threads[RECORDS_MAX];
    int i;

    for (i = 0; i < RECORDS_MAX; i++) {
        Record new_record;
        new_record.key = i;
        new_record.offset = rand() % 1000;
        pthread_create(&threads[i], NULL, update_records, &new_record);
    }

    for (i = 0; i < RECORDS_MAX; i++)
        pthread_join(threads[i]);

    fclose(persistency_file);

    return 0;
}
