        json_object_object_add(entry_obj, "priority", json_object_new_int(priorities[i]));
        json_object_object_add(entry_obj, "message", json_string_copy(messages[i], -1));

        // Serialize log entry to JSON
        json_object_object_add(jobj, json_object_get_string(json_object_to_json_string_ext(entry_obj, JSON_TYPE_OBJECT)), NULL);
    }

    // Stream output to file descriptor or network socket
    fwrite(json_object_to_json_string_ext(jobj, JSON_TYPE_OBJECT), 1, strlen(json_object_to_json_string_ext(jobj, JSON_TYPE_OBJECT)), fd);
    json_decref(jobj);

    // Free allocated memory
    for(i = 0; i < num_entries; i++) {
        free(messages[i]);
        free(priorities[i]);
        free(timestamps[i]);
    }
    free(priorities);
    free(timestamps);
    free(messages);
    free(entries[0]);

    return entries;
}
