// Define a structure for 'task' objects
typedef struct {
    time_t timestamp;
    char status[10];
    int priority;
    struct record *records;
} task;

// Define a structure for individual records within a task
typedef struct {
    long *offsets_ptr;
    int *keys_ptr;
    int random_value;
} record;

// Function to manage dynamic collection of 'task' objects
task* manage_tasks(int num_tasks, int max_offsets, int max_keys) {
    // Initialize an array of tasks
    task *tasks = (task*)malloc(num_tasks * sizeof(task));

    // Set timestamp, status, and priority for each task
    time_t current_time = time(NULL);
    char pending_status[] = "pending";
    srand(time(NULL));  // Seed random number generator

    for(int i = 0; i < num_tasks; i++) {
        tasks[i].timestamp = current_time;
        strcpy(tasks[i].status, pending_status);
        tasks[i].priority = rand() % 1000001;

        // Initialize an array of records within each task
        int num_records = (rand() % 10) + 1;
        tasks[i].records = (record*)malloc(num_records * sizeof(record));

        for(int j = 0; j < num_records; j++) {
            // Allocate memory for offsets and keys arrays
            long *offsets = (long*)malloc(max_offsets * sizeof(long));
            int *keys = (int*)malloc(max_keys * sizeof(int));

            // Populate offsets and keys arrays
            for(int k = 0; k < max_offsets; k++) {
                offsets[k] = rand() % 10000;
            }
            for(int k = 0; k < max_keys; k++) {
                keys[k] = rand() % 5000;
            }

            // Initialize a new record with allocated memory
            tasks[i].records[j].offsets_ptr = offsets;
            tasks[i].records[j].keys_ptr = keys;
            tasks[i].records[j].random_value = rand() % 1000001;
        }
    }

    return tasks;
}

// Function to free all allocated memory when the task is completed
void free_tasks(task *tasks, int num_tasks) {
    for(int i = 0; i < num_tasks; i++) {
        // Free each record's offsets and keys arrays
        for(int j = 0; j < (rand() % 10) + 1; j++) {
            free(tasks[i].records[j].offsets_ptr);
            free(tasks[i].records[j].keys_ptr);
        }

        // Free the array of records within each task
        free(tasks[i].records);
    }

    // Free the main array of tasks
    free(tasks);
}
