const { spawn } = require('child_process');
const { promisify } = require('util');
const { setTimeout, setInterval, clearInterval } = require('timers');
const axios = require('axios');
const { EventEmitter } = require('events');

class ShellCommandExecutor {
  constructor({ apiEndpoint, maxConcurrency, commandTimeout }) {
    this.apiEndpoint = apiEndpoint;
    this.maxConcurrency = maxConcurrency;
    this.commandTimeout = commandTimeout;
    this.commands = [];
    this.runningCommands = [];
    this.eventEmitter = new EventEmitter();

    // Initialize the executor with a circuit breaker
    const { circuitBreaker } = require('./circuit-breaker');
    this.circuitBreaker = circuitBreaker(this.apiEndpoint, maxConcurrency);

    // Create a function to execute shell commands concurrently
    this.executeCommands = promisify(executeCommands);
  }

  async executeCommand(command) {
    try {
      const { command, parameters } = await this.getCommandParameters();
      const output = await this.executeShellCommand(command, parameters);
      return output;
    } catch (error) {
      this.eventEmitter.emit('error', error);
    }
  }

  async getCommandParameters() {
    try {
      const response = await axios.get(`${this.apiEndpoint}/commands`);
      return response.data;
    } catch (error) {
      throw new Error(`Failed to retrieve command parameters: ${error}`);
    }
  }

  async executeShellCommand(command, parameters) {
    try {
      const { stdout, stderr } = await spawn(command, parameters, {
        timeout: this.commandTimeout,
      });
      return [stdout.toString(), stderr.toString()];
    } catch (error) {
      throw new Error(`Failed to execute command: ${error}`);
    }
  }

  async startExecution() {
    // Start executing commands concurrently
    const executionLoop = setInterval(() => {
      if (this.commands.length > 0) {
        const command = this.commands.shift();
        this.runningCommands.push(command);
        this.executeCommand(command).then((output) => {
          this.runningCommands.splice(this.runningCommands.indexOf(command), 1);
          // Handle the output
        }).catch((error) => {
          this.eventEmitter.emit('error', error);
        });
      } else if (this.runningCommands.length > 0) {
        // Check for completed commands and emit events
        const completedCommand = this.runningCommands.find((command) => command.output !== null);
        if (completedCommand) {
          this.runningCommands.splice(this.runningCommands.indexOf(completedCommand), 1);
          this.eventEmitter.emit('output', completedCommand.output);
        }
      } else {
        // No more commands to execute, stop the loop
        clearInterval(executionLoop);
      }
    }, 10);

    return executionLoop;
  }

  async stopExecution() {
    // Stop the command execution loop
    clearInterval(this.executionLoop);
  }
}

// Helper function to execute shell commands concurrently
async function executeCommands(commands) {
  try {
    const results = await Promise.all(
      commands.map((command) => this.executeCommand(command))
    );
    return results;
  } catch (error) {
    throw new Error(`Failed to execute commands: ${error}`);
  }
}

module.exports = ShellCommandExecutor;
