["```
const { Transform } = require('stream');
const Buffer = require('buffer').Buffer;

class DataProcessor extends Transform {
  constructor(options) {
    super({
      writableObjectMode: true,
      readableObjectMode: false,
    });
    this.bufferSize = options.bufferSize || 1024 * 1024; // default buffer size is 1MB
    this.retainData = options.retainData !== undefined ? options.retainData : true;
    this.metrics = {
      bytesProcessed: 0,
      bytesRetained: 0,
      latency: 0,
    };
  }

  _transform(chunk, encoding, callback) {
    const buffer = Buffer.allocUnsafe(this.bufferSize);
    let bytesRead = 0;

    function readBuffer() {
      return new Promise((resolve, reject) => {
        this.push(buffer.slice(0, Math.min(this.bufferSize - bytesRead, chunk.length)));
        bytesRead += chunk.length;
        resolve();
      });
    }

    function readData() {
      return new Promise((resolve, reject) => {
        const data = Buffer.allocUnsafe(chunk.length);
        chunk.copy(data, 0);
        this.push(data);
        resolve();
      });
    }

    if (this.retainData) {
      readBuffer().then(() => {
        bytesRead = 0;
      }).catch((err) => {
        callback(err);
      });
    } else {
      readData().then(() => {
        bytesRead = 0;
      }).catch((err) => {
        callback(err);
      });
    }
  }

  _flush(callback) {
    if (this.retainData) {
      this.push(Buffer.alloc(0));
    }
    callback();
  }

  getMetrics() {
    return this.metrics;
  }
}

module.exports = DataProcessor;
