const fs = require('fs');
const https = require('https');
const crypto = require('crypto');
const sqlite3 = require('sqlite3').verbose();
const request = require('request');

class RecordManager {
  constructor(url, config) {
    this.records = [];
    this.config = config;
    this.db = new sqlite3.Database(config.database);
    this.cache = {};
    this.auditInterval = setInterval(() => this.auditRecords(), config.auditInterval);

    fs.readFile(`${url}.json`, (err, data) => {
      if (!err) {
        const records = JSON.parse(data);
        records.forEach((record) => this.addRecord(record));
      }

      request({
        method: 'GET',
        url,
        headers: { 'User-Agent': config.userAgent },
      }, (error, response, body) => {
        if (!error && response.statusCode === 200) {
          const seed = crypto.randomBytes(4).toString('hex', 0, 2);
          this.config.seed = seed;
          this.config.range = JSON.parse(body).range;

          setInterval(() => this.updateSeed(), config.seedUpdateInterval);
        }
      });
    });

    this.db.run(`CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, value INTEGER)`);
  }

  addRecord(record) {
    const id = Math.floor(Math.random() * 1000 + 1);
    record.id = id;
    record.value = Math.floor(Math.random() * this.config.range[1] - this.config.range[0]);
    this.records.push(record);

    this.db.run(`INSERT INTO records VALUES (${id}, ${record.value})`);
  }

  getRecord(id) {
    const cachedRecord = this.cache[id];
    if (cachedRecord) return cachedRecord;

    const record = this.records.find((r) => r.id === id);
    if (!record) return null;

    this.cache[id] = record;
    return record;
  }

  deleteRecord(id) {
    const index = this.records.findIndex((r) => r.id === id);
    if (index === -1) return;

    this.records.splice(index, 1);

    this.db.run(`DELETE FROM records WHERE id = ${id}`);
  }

  updateSeed() {
    const seed = crypto.randomBytes(4).toString('hex', 0, 2);
    this.config.seed = seed;
  }

  auditRecords() {
    this.db.all(`SELECT * FROM records`, (err, rows) => {
      if (err) return;

      rows.forEach((row) => {
        const record = this.getRecord(row.id);
        if (!record) {
          console.log(`Record ${row.id} not found`);
          return;
        }

        if (record.value !== row.value) {
          console.log(`Record ${row.id} has been tampered with`);
          // Handle integrity violation
        }
      });
    });
  }

  trackAccess(id) {
    const record = this.getRecord(id);
    if (!record) return;

    setTimeout(() => {
      this.db.run(`UPDATE records SET access_count = access_count + 1 WHERE id = ${id}`);
    }, config.accessUpdateInterval);
  }

  bulkInsert(records) {
    this.records.push(...records);

    const batch = [];
    for (const record of records) {
      batch.push(`INSERT INTO records VALUES (${record.id}, ${record.value})`);
    }

    this.db.run(batch.join(';'));
  }

  bulkDelete(ids) {
    this.records = this.records.filter((r) => !ids.includes(r.id));

    const batch = [];
    for (const id of ids) {
      batch.push(`DELETE FROM records WHERE id = ${id}`);
    }

    this.db.run(batch.join(';'));
  }
}

module.exports = RecordManager;
