        if (strcmp(key, "port") != 0 || !json_object_is_int(val)) {
            return 0;
        }
        if (strcmp(key, "timeout") != 0 || !json_object_is_int(val)) {
            return 0;
        }
    }

    json_object_object_foreach(services, key, val) {
        json_object *service = val;
        json_object_object_foreach(service, service_key, service_val) {
            if (strcmp(service_key, "name") != 0 || !json_object_is_string(service_val)) {
                return 0;
            }
            if (strcmp(service_key, "tags") != 0 || !json_object_is_array(service_val)) {
                return 0;
            }
        }
    }

    json_object_object_foreach(endpoints, key, val) {
        json_object *endpoint = val;
        json_object_object_foreach(endpoint, endpoint_key, endpoint_val) {
