use log::log_enabled;
use std::path::{Path, PathBuf};
use std::process::{exit, Command};

struct Config {
    directory_name: String,
    base_path: String,
    default_env_var_value: String,
}

impl Config {
    fn new(directory_name: &str, base_path: &str, default_env_var_value: &str) -> Self {
        let config = Self {
            directory_name: directory_name.to_string(),
            base_path: base_path.to_string(),
            default_env_var_value: default_env_var_value.to_string(),
        };
        if !config.is_valid() {
            panic!("Invalid configuration");
        }
        config
    }

    fn is_valid(&self) -> bool {
        let base_path = Path::new(&self.base_path);
        self.directory_name.contains('/')
            || self.directory_name.starts_with(self.base_path.as_os_str())
            && base_path.is_dir()
    }
}

fn create_directory(config: &Config, attempts: u32) -> Result<String, String> {
    let mut pathbuf = PathBuf::from(&config.base_path);
    pathbuf.push(&config.directory_name);

    if pathbuf.exists() {
        if !pathbuf.read_dir().is_ok() {
            return Err("Directory exists but is not readable".to_string());
        }
    } else {
        for i in 0..attempts {
            match Command::new("mkdir").arg(&pathbuf.to_str().unwrap()).output() {
                Ok(output) => {
                    if output.status.success() {
                        println!("Created directory at path {}", &pathbuf.display());
                        return Ok(pathbuf.to_str().unwrap().to_string());
                    } else if i < attempts - 1 {
                        println!("Attempt {} failed, trying again...", i + 1);
                        std::thread::sleep(std::time::Duration::from_millis(100));
                    } else {
                        Err("Failed to create directory after multiple attempts".to_string())
                    }
                }
                Err(_) => return Err("mkdir command failed to execute".to_string()),
            }
        }
    }

    Err("Failed to create directory".to_string())
}

fn main() {
    env_logger::init();

    let config = Config::new("mydir", "/usr/local/", "default");
    match create_directory(&config, 5) {
        Ok(path) => println!("Directory created: {}", path),
        Err(err) => println!("Error creating directory: {}", err),
    }
}
