    for (int i = 0; i < size; i++)
        records[i] = (int*)malloc(sizeof(record));
    for (int i = 0; i < size; i++) {
        records[i][0].value = rand() % 10000;
        records[i][1].timestamp = time(NULL);
        records[i][2].status = rand() % 2;
    }

    // Allocate memory for timestamp values
    time_t* timestamps = (time_t*)malloc(size * sizeof(time_t));
    for (int i = 0; i < size; i++)
        timestamps[i] = time(NULL);

    // Allocate memory for linked list of records
    record** record_list = (record**)malloc(size * sizeof(record));
    for (int i = 0; i < size; i++) {
        record_list[i] = (record*)malloc(sizeof(record));
        record_list[i][0].value = rand() % 10000;
        record_list[i][1].timestamp = time(NULL);
        record_list[i][2].status = rand() % 2;
    }

    // Allocate memory for hash table
    int** hashtable = (int**)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++)
        hashtable[i] = (int*)malloc(sizeof(record));
    for (int i = 0; i < size; i++) {
        hashtable[i][0].value = rand() % 10000;
        hashtable[i][1].timestamp = time(NULL);
        hashtable[i][2].status = rand() % 2;
    }

    // Custom garbage collector
    void* (*gc)(void*) = malloc;
    gc(&offsets);
    gc(&records);
    gc(&timestamps);
    gc(&record_list);
    gc(&hashtable);

