void readIntegersFromStream(int *offsetValues, int **keys, Record ***records, int *size) {
    // Read the size of the input data
    scanf("%d", size);

    // Dynamically allocate memory for arrays and linked list
    *offsetValues = (long *)malloc((*size) * sizeof(long));
    *keys = (int **)malloc((*size) * sizeof(int *));
    *records = (Record **)malloc((*size) * sizeof(Record *));

    // Read the offset values, keys, and records from the network stream
