        scanf("%ld %d", &(*offsetValues)[i], &(*keys)[i]);

        (*records)[i] = (Record *)malloc(sizeof(Record));
        (*records)[i]->key = rand() % 100;
        (*records)[i]->value = rand() % 100;

        // Initialize the linked list
        if (i == 0) {
            // Set the head of the linked list
            head = (*records)[i];
        } else {
            // Link the current record to the previous one
            (*records)[i - 1]->next = (*records)[i];
        }
    }
}

// Function to implement a memory management strategy that properly frees all allocated memory upon function return
void freeMemory(int *size) {
    for (int i = 0; i < *size; i++) {
        // Free the offset values, keys, and records
        free((void *)(&(*offsetValues)[i]));
        free((void *)((*keys)[i]));
        free((void *)(*records)[i]);
