#include <time.h>
#include <string.h>

// Define a structure for a 'transaction' object
typedef struct {
    int id;
    time_t timestamp;
    double amount;
    char status[10];
} Transaction;

// Define a hash table structure using separate chaining
typedef struct {
    int size;
    Transaction** buckets;
    unsigned long seed;
    srand(seed);
} HashTable;

void init_hash_table(HashTable* ht, int size) {
    ht->size = size;
    ht->buckets = (Transaction**)malloc(sizeof(Transaction*) * size);
    for (int i = 0; i < size; i++) {
        ht->buckets[i] = NULL;
    }
}

void free_hash_table(HashTable* ht) {
    for (int i = 0; i < ht->size; i++) {
        Transaction* node = ht->buckets[i];
        while (node != NULL) {
            Transaction* next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->buckets);
}

// Function to dynamically allocate memory and initialize a collection of 'transaction' objects
HashTable* init_transactions(int size, int min_amount_range, int max_amount_range) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    init_hash_table(ht, size);

    for (int i = 0; i < size; i++) {
        Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
        transaction->id = rand() % 100000;
        transaction->timestamp = time(NULL);
        transaction->amount = (double)rand() / RAND_MAX * (max_amount_range - min_amount_range) + min_amount_range;
        strcpy(transaction->status, "PENDING");

        // Insert into hash table using separate chaining
        int index = transaction->id % ht->size;
        Transaction* node = ht->buckets[index];
        while (node != NULL) {
            node = node->next;
        }
        transaction->next = node;
        ht->buckets[index] = transaction;
    }

    return ht;
}

void free_transactions(HashTable* ht) {
    free_hash_table(ht);
    free(ht);
}
