#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Task structure
typedef struct {
    int priority;
    time_t deadline;
    enum { PENDING, RUNNING, DONE } status;
} task_t;

// Dynamic collection of tasks
task_t **tasks = NULL;
size_t task_count = 0;

// Mutex for thread safety
pthread_mutex_t task_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the task collection
void init_tasks() {
    // Allocate memory for up to 100,000 tasks
    tasks = (task_t **)malloc(100000 * sizeof(task_t *));
}

// Function to insert a new task into the collection
int insert_task(int priority, time_t deadline) {
    task_t *new_task;

    // Allocate memory for the new task
    new_task = (task_t *)malloc(sizeof(task_t));
    if (!new_task) return -1;  // Out of memory

    new_task->priority = priority;
    new_task->deadline = deadline;
    new_task->status = PENDING;

    // Insert the new task into the collection
    pthread_mutex_lock(&task_mutex);
    tasks[task_count++] = new_task;
    pthread_mutex_unlock(&task_mutex);

    return 0;  // Success
}

// Function to remove a task from the collection
int remove_task(size_t index) {
    if (index >= task_count) return -1;  // Task not found

    // Remove the task from the collection
    pthread_mutex_lock(&task_mutex);
    free(tasks[index]);
    tasks[index] = NULL;
    for (size_t i = index + 1; i < task_count; ++i)
        tasks[i - 1] = tasks[i];
    --task_count;
    pthread_mutex_unlock(&task_mutex);

    return 0;  // Success
}

// Function to query the status of a task
int get_task_status(size_t index) {
    if (index >= task_count) return -1;  // Task not found

    // Query the status of the task
    pthread_mutex_lock(&task_mutex);
    task_t *task = tasks[index];
    int status = task->status;
    pthread_mutex_unlock(&task_mutex);

    return status;  // The status of the task
}

// Function to update the status of a task
int set_task_status(size_t index, enum { PENDING, RUNNING, DONE } status) {
    if (index >= task_count) return -1;  // Task not found

    // Update the status of the task
    pthread_mutex_lock(&task_mutex);
    task_t *task = tasks[index];
    task->status = status;
    pthread_mutex_unlock(&task_mutex);

    return 0;  // Success
}
