    new_task->priority = 0;
    new_task->deadline = time(NULL);
    new_task->status = PENDING;
    new_task->data = malloc(1);  // Initial data size is 1 byte
    new_task->data_size = 1;

    return new_task;
}

void free_task(task_t* task) {
    if (!task) return;  // Handle null pointer error

    if (task->data) free(task->data);
    free(task);
