public class FileProcessor
{
    private readonly int _concurrentOperationsLimit = 10;
    private readonly string _logFilePath;
    private readonly int _timeoutInMilliseconds = 5000; // 5 seconds

    public Dictionary<string, (string hash, Metadata metadata)> ProcessFiles(List<string> filePaths)
    {
        var result = new Dictionary<string, (string hash, Metadata metadata)>();

        if (_logFilePath == null || string.IsNullOrEmpty(_logFilePath))
            throw new ArgumentException("Log file path is required.");

        using (var logFile = File.AppendText(_logFilePath, append: true))
        {
            // Start a thread pool to concurrently process files
            var taskList = new List<Task>();
            var semaphore = new SemaphoreSlim(_concurrentOperationsLimit);

            foreach (var filePath in filePaths)
            {
                if (!ValidateFile(filePath, logFile))
                    continue;

                using (var fileStream = File.OpenRead(filePath))
                {
                    using (var hashAlgorithm = SHA256.Create())
                    {
                        // Compute the SHA-256 hash
                        var hashBytes = new byte[hashAlgorithm.HashSize / 8];
                        using (var hashStream = new MemoryStream())
                        {
                            hashAlgorithm.ComputeHash(hashStream, fileStream);
                            hashStream.Position = 0;
                            hashAlgorithm.TransformFinalBlock(hashBytes, 0, hashBytes.Length);

                            // Get the external metadata service
                            var metadataService = GetMetadataService();

                            if (metadataService != null)
                            {
                                try
                                {
                                    // Retrieve additional attributes from the metadata service
                                    var metadata = metadataService.GetAttributes(filePath);
                                    result.Add(filePath, (Convert.ToBase64String(hashBytes), metadata));
                                }
                                catch (Exception ex)
                                {
                                    logFile.WriteLine($"Error retrieving metadata for {filePath}: {ex.Message}");
                                    continue;
                                }
                            }

                            // Release the semaphore to allow other threads to proceed
                            semaphore.Release();
                        }
                    }
                }
            }

            // Wait for all tasks to complete
            Task.WaitAll(taskList.ToArray());
        }

        return result;
    }

    private bool ValidateFile(string filePath, TextWriter log)
    {
        try
        {
            if (!File.Exists(filePath))
            {
                log.WriteLine($"File not found: {filePath}");
                return false;
            }

            if (!File.GetAccessControl(filePath).GetAccessRule(null).AccessControlType == FileSecurityAccessControlType.ReadWrite)
            {
                log.WriteLine($"Read-only access to file: {filePath}");
                return false;
            }

            var fileSize = new FileInfo(filePath).Length;

            if (fileSize > 500 * 1024 * 1024) // 500 MB
            {
                log.WriteLine($"File size exceeds 500 MB: {filePath}");
                return false;
            }
        }
        catch (Exception ex)
        {
            log.WriteLine($"Error validating file: {ex.Message}");
            return false;
        }

        return true;
    }

    private IMetadataService GetMetadataService()
