use reqwest::blocking::{get, post};
use tokio::{sync::mpsc, task};

async fn create_http_client(
    disable_cert_validation: bool,
    custom_headers: Vec<(String, String)>,
    timeout: u64,
) -> reqwest::Client {
    let client = reqwest::Builder::new()
        .timeout(std::time::Duration::from_millis(timeout as u128))
        .danger_accept_invalid_certs(!disable_cert_validation);

    for (key, value) in custom_headers {
        client.header(key, value);
    }

    client
}

async fn handle_request(
    url: &str,
    client: &reqwest::Client,
    retries: u32,
    max_latency_ms: u64,
) -> Result<String, reqwest::Error> {
    let mut attempts = 0;
    let mut latency_us = 0;

    while attempts < retries {
        let start = std::time::Instant::now();

        match client.get(url).send().await {
            Ok(response) => {
                if response.status().is_success() {
                    return Ok(response.text().await.unwrap());
                } else {
                    return Err(reqwest::Error::from_response(response, "Failed request"));
                }
            }
            Err(err) => {
                if let reqwest::ErrorKind::Timeout = err.kind() {
                    if latency_us >= max_latency_ms * 1000 {
                        return Err(reqwest::Error::new(err, "Request timed out after multiple attempts"));
                    }
                } else if attempts < retries - 1 {
                    // exponential backoff
                    task::sleep(std::time::Duration::from_millis(2_u32.pow(attempts as u32) as u128)).await;
                    latency_us += (std::time::Instant::now().duration_since(start).as_millis() * 1000) as usize;
                } else {
                    return Err(reqwest::Error::new(err, "Too many failed requests"));
                }
            }
        }

        attempts += 1;
    }

    Err(reqwest::Error::new(reqwest::ErrorKind::Other, "Request failed after multiple attempts"))
}

async fn main() {
    let client = create_http_client(true, Vec::new(), 5000);

    for _ in 0..10 {
        match handle_request("https://example.com/api/endpoint", &client, 3, 1000).await {
            Ok(response) => println!("{}", response),
            Err(err) => eprintln!("Error: {}", err),
        }
    }
}

async fn send_requests() -> mpsc::Receiver<String> {
    let (tx, rx) = mpsc::channel(10);

    for _ in 0..10 {
        tx.send("Hello, World!".to_string()).await.unwrap();
    }

    rx
}

fn main() {
    tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(async move {
            let receiver = send_requests().await;

            for message in receiver.recv_until(std::time::Duration::from_millis(5000)) {
                println!("{}", message);
            }
        });
}
