class Node:
    def __init__(self, name):
        self.name = name
        self.status = "standby"
        self.latency = 0
        self.last_check = time.time()

class ReplicationService:
    def __init__(self):
        self.nodes = []
        self.active_node = None

    def add_node(self, node):
        self.nodes.append(node)

    def check_status(self):
        for node in self.nodes:
            if node.status == "active":
                self.latency = max(self.latency, random.randint(1, 100))
                node.last_check = time.time()
                if node.latency > 50:
                    node.status = "standby"
                    self.active_node = None
                else:
                    self.active_node = node.name

    def failover(self):
        for node in self.nodes:
            if node.status == "standby" and node.name != self.active_node:
                self.active_node = node.name
                return

def check_latency(node):
    try:
        urlopen(f"http://{node.name}.com:8080", timeout=1)
        return 0
    except:
        return random.randint(1, 100)

def main():
    replication_service = ReplicationService()

    with ThreadPoolExecutor() as executor:
        for node in replication_service.nodes:
            executor.submit(check_latency, node)

    replication_service.check_status()
    if replication_service.active_node is None:
        replication_service.failover()
