#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <limits.h>

#define MAX_COMMANDS 5
#define LOG_INTERVAL 5 // seconds
#define CPU_THRESHOLD 50.0 // %
#define MEMORY_THRESHOLD 100.0 // %

int execute_commands(char **commands, char *env_vars[]) {
    pid_t child_pids[MAX_COMMANDS];
    int command_index = 0;
    int child_count = 0;

    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    FILE *log_file = fopen("resource_usage.log", "w");
    if (log_file == NULL) {
        return -1; // failed to open log file
    }

    while (command_index < MAX_COMMANDS && commands[command_index]) {
        child_pids[child_count++] = fork();
        if (child_pids[child_count - 1] == 0) {
            // child process
            setenv("CMD_ENV_VAR", env_vars[command_index], 1);
            execvp(commands[command_index], &commands[command_index][0]);
            return -2; // command not found or invalid arguments
        }
        command_index++;
    }

    int status;
    while (child_count--) {
        waitpid(child_pids[child_count], &status, 0);
        if (WEXITSTATUS(status)) {
            return 0; // at least one child process failed
        }
    }

    // monitor resource usage and log every LOG_INTERVAL seconds
    double cpu_usage = 0.0;
    double memory_usage = 0.0;

    while (1) {
        sleep(LOG_INTERVAL);
        for (int i = 0; i < child_count; i++) {
            FILE *file = fopen("/proc/self/stat", "r");
            if (!file) {
                continue; // failed to read process statistics
            }
            char buffer[PATH_MAX];
            fgets(buffer, PATH_MAX, file);
            fclose(file);

            int pid = atoi(strtok(buffer, " "));
            if (pid == child_pids[i]) {
                double cpu = 0.0;
                double memory = 0.0;

                file = fopen("/proc/self/comm", "r");
                fgets(buffer, PATH_MAX, file);
                fclose(file);

                file = fopen("/proc/self/statm", "r");
                if (file) {
                    fscanf(file, "%*s %lf", &memory);
                    fclose(file);
                }

                cpu_usage += memory;
                memory_usage += memory;

                // check for resource limits exceeded
                if (cpu_usage > CPU_THRESHOLD || memory_usage > MEMORY_THRESHOLD) {
                    kill(child_pids[i], SIGINT); // send signal to child process
                    waitpid(child_pids[i], &status, 0);
                    return 0; // at least one child process failed
                }
            }
        }
    }

    return 1; // all child processes completed successfully
}

int main() {
    char *commands[] = {"command1", "command2", "command3"};
    char *env_vars[] = {"CMD_ENV_VAR1=var1", "CMD_ENV_VAR2=var2"};

    if (execute_commands(commands, env_vars)) {
        printf("All commands executed successfully.\n");
    } else {
        printf("At least one command failed.\n");
    }

    return 0;
}
