['```
#include <vector>
#include <algorithm>

void insertAfter(std::vector<int>& vec, int target, int value) {
    if (vec.empty()) return;

    size_t left = 0, right = vec.size() / 2;
    while (left <= right) {
        size_t mid = (left + right) / 2;
        if (vec[mid] == target) {
            vec.insert(vec.begin() + mid + 1, value);
            return;
        } else if (vec[mid] < target) left = mid + 1;
        else right = mid - 1;
    }

    size_t pos = std::lower_bound(vec.begin(), vec.begin() + vec.size() / 2, target);
    vec.insert(pos, value);
}
