from uvloop import create_event_loop

class WebSocketServer:
    def __init__(self):
        self.pool = await websockets.create_pool(max_size=10000)

    async def handle_connection(self, conn):
        try:
            while True:
                message = await conn.recv()
                print(f"Received message: {message}")
                # Handle client messages here
        except asyncio.CancelledError:
            pass

        finally:
            await self.pool.release(conn)
            print("Connection closed")

    async def broadcast(self, message):
        for conn in list(self.pool.connections):
            try:
                await conn.send(message)
            except (websockets.ConnectionClosed, asyncio.CancelledError):
                self.pool.release(conn)

    async def start(self):
        while True:
            await asyncio.sleep(1)
            await self.broadcast("Hello, clients!")

    @classmethod
    async def create(cls):
        return cls()

class ConnectionPool:
    def __init__(self):
        self.connections = []

    async def connect(self, host, port):
        conn = await websockets.connect(f"ws://{host}:{port}")
        self.connections.append(conn)

    async def release(self, conn):
        if conn in self.connections:
            self.connections.remove(conn)
        else:
            print("Invalid connection")

class RestEndpoint:
    @classmethod
    async def get_active_connections(cls):
