    @classmethod
    async def get_performance_metrics(cls):
        # Return recent performance metrics, including average response time and peak load capacity

async def main():
    server = await WebSocketServer.create()
    pool = ConnectionPool()

    while True:
        try:
            await asyncio.gather(
                server.start(),
                *[pool.connect("localhost", 8765) for _ in range(10000)]
            )
        except asyncio.CancelledError:
            pass
        finally:
