        try {
            // Run convert command with retry mechanism
            if (!std::system((("convert " + inputFilePath + " " + outputDir + "/temp.pdf") + " && mv " + outputDir + "/temp.pdf " + outputDir + "/" + inputFilePath).c_str())) {
                break;
