            logger->logError("Failed to convert file type: ", e.what());
            attempts++;
            if (attempts == 3) {
                return false;
            }
        }
    }

    // Step 2: Deserialize serializedData
    try {
        // Load serializer library
        std::string libPath = "serializer.dll";  // or "serializer.so" on Unix-like systems
        void* handle = dlopen(libPath.c_str(), RTLD_LAZY);
        if (!handle) {
            logger->logError("Failed to load serializer library: ", dlerror());
            handle = dlopen(libPath.c_str(), RTLD_GLOBAL | RTLD_NOW);
            if (!handle) {
                // Fallback mechanism
                handle = dlopen(libPath.c_str(), RTLD_GLOBAL | RTLD_LAZY);
            }
        }

        // Get class from loaded library
        void* clazz = dlsym(handle, className.c_str());
        if (!clazz) {
            logger->logError("Failed to find class: ", dlerror());
            // Fallback mechanism using default class
            clazz = dlsym(handle, "DefaultClass");  // Replace with actual default class name
        }

        // Deserialize serializedData into class instance
        // ...

        // Clean up
        dlclose(handle);
    } catch (const std::runtime_error& e) {
        logger->logError("Failed to deserialize: ", e.what());
        return false;
    }

    // Step 3: Validate output directory and create if necessary
    try {
        if (!std::filesystem::exists(outputDir)) {
            if (!std::filesystem::create_directory(outputDir)) {
                logger->logError("Failed to create directory: ");
                // Fall back to temporary directory
                outputDir = "/tmp";
