    for (i = 0; i < 3; i++) {
        total_connections += regions[i].connections;
        if (regions[i].response_time > max_response_time)
            max_response_time = regions[i].response_time;
        if (fewest_connections_region == -1 || regions[fewest_connections_region].connections > regions[i].connections)
            fewest_connections_region = i;
    }

    // Process failed connections
    int* failed_connections = (int*)malloc(3 * sizeof(int));
    for (i = 0; i < 3; i++) {
        printf("Failed connections in region %d: %d\n", i, regions[i].failures);
        failed_connections[i] = regions[i].failures;
