    // Calculate average connection health score per region
    double* avg_health_scores = (double*)malloc(3 * sizeof(double));
    for (i = 0; i < 3; i++) {
        avg_health_scores[i] = (regions[i].connections > 0) ? regions[i].response_time / regions[i].connections : 0.0;
