} TaskStatus;

typedef struct {
    int priority;
    time_t deadline;
    TaskStatus status;
} Record;

Record* queue = NULL;
int size = 0;
int capacity = 100000; // Adjust according to memory availability

void insertTask(int priority, time_t deadline) {
    Record* newTask = (Record*)malloc(sizeof(Record));
    if (newTask == NULL) {
        perror("Memory allocation failed");
        return;
    }

    newTask->priority = priority;
    newTask->deadline = deadline;
    newTask->status = PENDING;
    // Time stamp can be updated here if required

    if (size >= capacity) {
        printf("Queue full. Cannot insert task.\n");
        free(newTask);
        return;
    }

    queue[size] = *newTask;
    size++;
}

void removeTask() {
    if (size > 0) {
        // Implementation for removing a task goes here
        // For simplicity, let's assume the last task is removed
        Record* removedTask = &queue[--size];
        free(removedTask);
    }
}

int main() {
    srand(time(NULL)); // Seed for generating pseudo-random numbers

    insertTask(rand(), time(NULL));

    return 0;
}
