#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the node structure
typedef struct Node {
    char* string;
    int* data;
    struct Node* next;
} Node;

// Define a lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new node
Node* newNode(char* str, int val) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->string = (char*)malloc(strlen(str) + 1);
    strcpy(node->string, str);
    node->data = (int*)malloc(sizeof(int));
    *node->data = val;
    node->next = NULL;
    return node;
}

// Function to insert a new node
void insertNode(Node** head, Node* newNode) {
    pthread_mutex_lock(&lock);
    if (*head == NULL || (*head)->string > newNode->string) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next && strcmp(current->next->string, newNode->string) < 0) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
    pthread_mutex_unlock(&lock);
}

// Function to traverse the nodes and print their contents
void traversal(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("String: %s, Data: %d\n", current->string, *current->data);
        current = current->next;
    }
}

// Main function
int main() {
    // Create a new node
    Node* head = newNode("Node1", 10);

    // Insert more nodes
    insertNode(&head, newNode("Node2", 20));
    insertNode(&head, newNode("Node3", 30));

    // Travers the nodes and print their contents
    traversal(head);
    return 0;
}

