          return callback(currentAccumulator, num);
        }));
      } catch (error) {
        console.error("Error validating and reducing:", error);
        return null;
      }
    }

    let reducedValue = currentAccumulator;
    for (const result of validatedNumbers) {
      if (result === null) continue; // skip invalid numbers
      reducedValue = callback(reducedValue, result);
    }
    return reducedValue;
  }

  async function processChunk(chunks) {
    const promises = chunks.map((chunk, i) => {
      if (i % concurrencyLimit === 0 && i > 0) { // parallel processing
        pendingPromises.push(validateAndReduce(chunks.slice(i - concurrencyLimit)));
      }
      return validateAndReduce([chunk]);
    });

    try {
      const results = await Promise.all(promises);
      validatedNumbers.push(...results.flat());
    } catch (error) {
      console.error("Error processing chunk:", error);
    }

    if (pendingPromises.length > 0) { // sequential processing
      while (pendingPromises.length > 0) {
        try {
          const result = await pendingPromises.shift();
          validatedNumbers.push(...result);
        } catch (error) {
          console.error("Error processing chunk:", error);
        }
      }
    }

    return validateAndReduce(validatedNumbers.map((num) => [num]));
  }

  async function reduce() {
    if (arr.length === 0) return initialValue;

    const chunks = [];
    for (let i = 0; i < arr.length; i += concurrencyLimit) {
      chunks.push(arr.slice(i, i + concurrencyLimit));
    }

    try {
      const result = await processChunk(chunks);
      return result;
    } catch (error) {
      console.error("Error reducing array:", error);
      throw error;
    }
  }

  return reduce();
}
