import requests
from threading import Semaphore, Lock
from queue import Queue
from json import dumps, loads
from time import sleep
from logging import getLogger, DEBUG

logger = getLogger()

class WeatherAPI:
    def __init__(self, api_key):
        self.api_key = api_key
        self.retry_delay = 1  # seconds
        self.max_retries = 5
        self.rate_limit_queue = Queue()
        self.semaphore = Semaphore(5)  # concurrent API requests

    def fetch_weather(self, location):
        headers = {'Authorization': f'Bearer {self.api_key}'}
        try:
            response = requests.get(f'https://weather-api.com/{location}', headers=headers)
            response.raise_for_status()
            return loads(response.content)
        except (requests.RequestException, json.JSONDecodeError) as e:
            logger.error(f"Failed to fetch weather for {location}: {e}")
            return None

class WeatherCache:
    def __init__(self):
        self.cache = {}

    def get_weather(self, location):
        with Lock():
            return self.cache.get(location)

    def set_weather(self, location, data):
        with Lock():
            self.cache[location] = data

    def serialize_cache(self):
        return dumps(self.cache)

    def deserialize_cache(self, serialized_data):
        self.cache = loads(serialized_data)

def update_weather_cache(api, cache, locations):
    weather_api = WeatherAPI(api)
    failed_updates = []
    successful_updates = 0
    for location in locations:
        while True:
            try:
                response = weather_api.fetch_weather(location)
                if response:
                    cache.set_weather(location, response)
                    successful_updates += 1
                    break
                else:
                    sleep(weather_api.retry_delay)
                    if weather_api.max_retries <= 0:
                        failed_updates.append(location)
                        break
                    weather_api.max_retries -= 1
            except Exception as e:
                logger.error(f"Error updating weather for {location}: {e}")
                failed_updates.append(location)
                break

    return successful_updates, len(locations) - successful_updates, failed_updates

def main(api_key, locations):
    cache = WeatherCache()
    serialized_cache = cache.serialize_cache()

    try:
        with open('weather_cache.json', 'w') as f:
            f.write(serialized_cache)
    except Exception as e:
        logger.error(f"Failed to write cache to file: {e}")

    successful_updates, failed_updates, _ = update_weather_cache(api_key, cache, locations)

    report = f'Successful updates: {successful_updates}, Failed updates: {failed_updates}'
    logger.info(report)

if __name__ == "__main__":
    api_key = "YOUR_API_KEY"
    locations = ["LOCATION1", "LOCATION2", ...]
    main(api_key, locations)
