int string_pool_used = 0;

// Mutex for concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Array to track current usage of items and strings
item* items;
int item_count = 0;
int max_item_count = 0;

void init_string_pool(int initial_size) {
    string_pool = (char**)malloc(initial_size * sizeof(char*));
    for (int i = 0; i < initial_size; i++) {
        string_pool[i] = NULL;
    }
}

void resize_string_pool() {
    int new_size = string_pool_size + (string_pool_size / 2);
    char** new_pool = (char**)realloc(string_pool, new_size * sizeof(char*));
    for (int i = string_pool_size; i < new_size; i++) {
        new_pool[i] = NULL;
    }
    free(string_pool);
    string_pool = new_pool;
}

item* get_item() {
    item* item = (item*)malloc(sizeof(item));
    return item;
}

void put_item(item* item) {
    pthread_mutex_lock(&mutex);
    if (item_count < max_item_count) {
        items[item_count] = *item;
        item_count++;
    } else {
        // Resize the array if necessary
        max_item_count *= 2;
        item_count = 1;
        items = (item*)realloc(items, max_item_count * sizeof(item));
        items[0] = *item;
    }
    pthread_mutex_unlock(&mutex);
}

void free_items() {
    for (int i = 0; i < item_count; i++) {
        if (items[i].string != NULL) {
            free(items[i].string);
        }
    }
    free(items);
}
