                MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

void deallocate_memory(void* ptr, size_t size) {
    munmap(ptr, size);
}

int main() {
    // Allocate memory for arrays
    long* offset_array = allocate_memory(sizeof(long) * OFFSET_ARRAY_SIZE);
    int* key_array = allocate_memory(sizeof(int) * KEY_ARRAY_SIZE);
    record_t* records = allocate_memory(sizeof(record_t) * RECORDS_COUNT);

    // Initialize offset and key arrays from configuration file
    FILE* config_file = fopen("config.txt", "r");
    if (config_file == NULL) {
        printf("Error: Unable to open configuration file.\n");
        exit(1);
    }
    for (int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
        fscanf(config_file, "%ld", &offset_array[i]);
    }
    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        fscanf(config_file, "%d", &key_array[i]);
    }
    fclose(config_file);

    // Randomly initialize record structures
    for (int i = 0; i < RECORDS_COUNT; i++) {
        records[i].value = rand() % RANDOM_INITIALIZER_RANGE;
    }

    // Deallocate memory
    deallocate_memory(offset_array, sizeof(long) * OFFSET_ARRAY_SIZE);
