log_entry** manageMemoryAllocation(float timestamps[], int* timestampCount, char* userIds[], int* userIdCount) {
    // Allocate memory for the timestamp array
    log_entry** logEntries = (log_entry**)malloc(MAX_TIMESTAMP_ARRAY_SIZE * sizeof(log_entry*));
    if (!logEntries) return NULL;

    // Allocate memory for each log entry based on the provided data
    for (int i = 0; i < *timestampCount; i++) {
        log_entries[i] = (log_entry*)malloc(sizeof(log_entry));
        if (!log_entries[i]) {
            free(logEntries);
            return NULL;
        }
    }

    // Initialize each log entry with the corresponding timestamp and user ID
    for (int i = 0; i < *timestampCount; i++) {
        log_entries[i]->timestamp = timestamps[i];
        log_entries[i]->userId = (char*)malloc((strlen(userIds[i]) + 1) * sizeof(char));
        strcpy(log_entries[i]->userId, userIds[i]);
    }

    // Check for invalid or null user IDs and handle accordingly
    for (int i = 0; i < *timestampCount; i++) {
        if (!log_entries[i]->userId || strlen(log_entries[i]->userId) > MAX_USER_ID_LENGTH) {
            // Handle error: corrupted data or exceeded maximum length
            free(logEntries);
            return NULL;
        }
    }

    return logEntries;
}
