// Define a structure to hold file metadata
typedef struct {
    char* path;
    int size;
    time_t modified_time;
    bool is_accessed;
} file_info;

// Function to process dynamic list of file paths
void process_file_paths() {
    // Initialize variables and data structures
    int num_files = 0;
    file_info** files = NULL;
    char* line = NULL;
    size_t line_len = 0;
    ssize_t read_size;

    // Read input from standard input
    while ((read_size = getline(&line, &line_len, stdin)) != -1) {
        num_files++;
        // Dynamically allocate memory for file metadata array
        files = realloc(files, (num_files + 1) * sizeof(file_info*));
        files[num_files - 1] = malloc(sizeof(file_info));

        // Initialize file metadata with default values
        files[num_files - 1]->path = strdup(line);
        files[num_files - 1]->size = 0;
        files[num_files - 1]->modified_time = time(NULL);
        files[num_files - 1]->is_accessed = false;

        // Update last modified time and size using system APIs
        struct stat sb;
        if (stat(files[num_files - 1]->path, &sb) == 0) {
            files[num_files - 1]->size = sb.st_size;
            files[num_files - 1]->modified_time = sb.st_mtime;
        }

        // Release resources for previous iteration
        free(line);
    }
    free(line);

    // Print largest file size and files being accessed
    int max_size = 0, num_accessed = 0;
    printf("Largest file size: %d bytes\n", max_size);
    printf("Files being accessed:\n");
    for (int i = 0; i < num_files; i++) {
        if (files[i]->is_accessed) {
            printf("%s\n", files[i]->path);
            num_accessed++;
        }
    }

    // Release all allocated resources
    for (int i = 0; i < num_files; i++) {
        free(files[i]->path);
        free(files[i]);
    }
    free(files);

    return;
}
