class EventProcessor {
  constructor(maxEventsPerSecond) {
    this.maxEventsPerSecond = maxEventsPerSecond;
    this.eventsStorage = [];
    this.pauseProcessing = false;
    this.backPressure = 0;
    this.processingRate = 0;
    this.eventQueue = [];

    setInterval(() => {
      if (this.pauseProcessing || this.eventsStorage.length >= Math.floor(this.maxEventsPerSecond * 1000 / 1000)) {
        return;
      }

      const chunkSize = Math.min(100, this.maxEventsPerSecond);
      const chunk = [];
      let remainingTime = 0;

      while (this.eventQueue.length > 0 && remainingTime < chunkSize) {
        const event = this.eventQueue.shift();
        if (!event) break;
        chunk.push(event);
        remainingTime++;
      }

      this.processChunk(chunk);

      this.processingRate = this.eventsStorage.length / (new Date().getTime() - this.startTime);
    }, 1000 / 30); // 30 FPS

    setInterval(() => {
      if (!this.pauseProcessing && this.processingRate > this.maxEventsPerSecond) {
        this.backPressure++;
      } else {
        this.backPressure = Math.max(0, this.backPressure - 1);
      }
    }, 1000 / 10); // 10 FPS

    this.startTime = new Date().getTime();
  }

  processChunk(events) {
    events.forEach(event => {
      // Process the event
      // ...
      this.eventsStorage.push(event);
    });
  }

  enqueueEvent(event) {
    this.eventQueue.push(event);
  }

  pauseProcessing() {
    this.pauseProcessing = true;
  }

  resumeProcessing() {
    this.pauseProcessing = false;
  }

  resetBackPressure() {
    this.backPressure = 0;
  }
}
