    // Add the node to the list
    if(metadata->count == 0) {
        metadata->prev = node;
        metadata->next = node;
    } else {
        node->next = metadata->head;
        metadata->head->prev = node;
        node->prev = NULL;
        metadata->head = node;
    }

    // Update the count
    metadata->count++;
}

void free_list(struct Metadata *metadata) {
    Node* current = metadata->head;
    while(current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
