#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define structure for record
typedef struct Record {
    int value;
    char* metadata;
    time_t timestamp;
} Record;

// Define doubly linked list node
typedef struct Node {
    Record* data;
    struct Node* next;
    struct Node* prev;
} Node;

// Function to create a new record with random value and metadata
Record* create_record(int min_value, int max_value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->value = rand() % (max_value - min_value + 1) + min_value;
    new_record->metadata = (char*)malloc((strlen("Metadata: ") + 1) * sizeof(char));
    strcpy(new_record->metadata, "Metadata: ");
    time_t timestamp = time(NULL);
    new_record->timestamp = timestamp;
    return new_record;
}

// Function to insert a record into the doubly linked list
void insert_record(Node** head, Record* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    if (*head == NULL || data->timestamp > (*head)->data->timestamp) {
        new_node->next = *head;
        if (*head != NULL)
            (*head)->prev = &new_node->next;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && data->timestamp <= current->next->data->timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        if (current->next)
            current->next->prev = &new_node->next;
        current->next = &new_node->next;
        new_node->prev = current;
    }
}

// Function to delete a record from the doubly linked list
void delete_record(Node** head, Record* data) {
    if (*head == NULL || data != (*head)->data)
        return;

    if (data == (*head)->data) {
        *head = (*head)->next;
        if ((*head))
            (*head)->prev->next = NULL;
    } else {
        Node* current = *head;
        while (current->next && data != current->next->data)
            current = current->next;

        if (current->next) {
            current->next->prev = current->prev;
            current->prev->next = &current->next;
        }
    }

    free(data->metadata);
    free(data);
}

// Function to perform garbage collection
void garbage_collection(Node** head, int threshold) {
    Node* current = *head;
    while (current) {
        if (current->data->timestamp < time(NULL) - threshold) {
            delete_record(head, current->data);
        } else {
            current = current->next;
        }
    }
}

// Function to manage the record storage system
void* record_storage_system(int min_value, int max_value, int min_timestamp, int max_timestamp, int garbage_collection_threshold) {
    srand(time(NULL)); // Set custom random seed for reproducibility

    Node* head = NULL;

    while (1) {
        Record* new_record = create_record(min_value, max_value);
        insert_record(&head, new_record);

        // Periodic garbage collection
        if (time(NULL) % 1000 < garbage_collection_threshold) {
            garbage_collection(&head, 60); // Adjust frequency based on system load and resources
        }
    }

    return NULL;
}

// Configuration interface to set parameters
void configure(int min_value, int max_value, int min_timestamp, int max_timestamp, int garbage_collection_threshold) {
    // Set configuration parameters
}

int main() {
    // Initialize record storage system with custom seed for reproducibility
    record_storage_system(1, 1000, time(NULL), time(NULL) + 3600, 5);

    return 0;
}
