class CharacterAttackManager {
public:
    enum class AttackType { Simple, Complex, Special };

    struct AttackData {
        std::chrono::time_point<std::chrono::system_clock> cooldownUntil;
        AttackType type;
    };

    void setAttackPriority(AttackType attackType, int priority) {
        // Implement priority management here
    }

    void resetCooldowns() {
        for (auto& pair : attacks_) {
            pair.second.cooldownUntil = std::chrono::system_clock::now();
        }
    }

    AttackData performAttack() {
        auto now = std::chrono::system_clock::now();

        if (attacks_.empty()) return { now, AttackType::Simple };

        std::priority_queue<AttackData*, std::vector<AttackData*>, std::greater<AttackData*>> priorityQueue;

        for (auto& pair : attacks_) {
            auto data = &pair.second;
            if (data->cooldownUntil < now) {
                switch (data->type) {
                    case AttackType::Special:
                        return { now, AttackType::Special };
                    case AttackType::Complex:
                        return { now, AttackType::Complex };
                    default:
                        break;
                }
            } else {
                priorityQueue.push(data);
            }
        }

        if (!priorityQueue.empty()) {
            auto selectedAttack = priorityQueue.top();
            attacks_.erase(std::remove_if(attacks_.begin(), attacks_.end(),
                                          [selectedAttack](const auto& pair) {
                                              return &pair.second == selectedAttack;
                                          }),
                attacks_.end());
            return *selectedAttack;
        } else {
            return { now, AttackType::Simple };
        }
    }

private:
    std::map<AttackType, AttackData> attacks_;
};

