void insert(node_t** head, node_t** tail, record_t record, metadata_t metadata, timestamp_t timestamp) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    new_node->record = record;
    new_node->metadata = metadata;
    new_node->timestamp = timestamp;

    if (*head == NULL) {
        *head = new_node;
        *tail = new_node;
    } else {
        new_node->prev = *tail;
        (*tail)->next = new_node;
        *tail = new_node;
    }
}

void delete(node_t** head, node_t* node) {
    if (node == *head) {
        *head = node->next;
    }

    if (node == *tail) {
        *tail = node->prev;
    }

    node->prev->next = node->next;
    node->next->prev = node->prev;

    free(node);
}

record_t search(node_t* head, int key) {
    node_t* current = head;
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }

    if (current == NULL || current->record.key != key) {
        return record_t{0}; // handle the case where the record is not found
    }

    return current->record;
}

void log_error(char* message) {
    pthread_mutex_lock(&lock);
    printf("Error: %s\n", message);
    pthread_mutex_unlock(&lock);
}
