typedef struct Collection {
    Node* head;
    Node* tail;
    size_t size;
} Collection;

Collection* collection_create() {
    Collection* col = (Collection*)malloc(sizeof(Collection));
    col->head = NULL;
    col->tail = NULL;
    col->size = 0;
    return col;
}

void collection_insert(Collection* col, Record record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = record;
    node->next = NULL;

    if (col->head == NULL) {
        col->head = node;
        col->tail = node;
    } else {
        node->next = col->head;
        col->head = node;
    }

    col->size++;
}

void collection_destroy(Collection* col) {
    Node* current = col->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(col);
}
