    for (int i = 0; i < max_records; i++) {
        records[i].key = rand() % 1000;
        records[i].timestamp = time(NULL);
    }
    offsets = (long*)malloc((max_records + 1) * OFFSET_SIZE);
    keys = (int*)malloc(max_records * KEY_SIZE);
}

void free_system() {
    // Free allocated memory
    if (records) {
        free(records);
    }
    if (offsets) {
        free(offsets);
    }
    if (keys) {
        free(keys);
    }
}

void update_record(int idx, int new_key, long new_timestamp) {
