    gc_threshold = threshold;
}

// Main function to manage the system
void* thread_func(void* arg) {
    // Handle asynchronous updates and garbage collection
    while (1) {
        // Perform some processing or I/O operations
        // ...

        // Run garbage collector periodically
        if ((rand() % 1000 < gc_interval) && (gc_threshold > get_memory_usage(0))) {
            gc_thread();
        }
    }
}

int main(int argc, char** argv) {
    int max_records = RECORD_MAX;
    int memory_budget = sizeof(record) * max_records;

    init_system(max_records, memory_budget);

