typedef struct {
    int time;
    double latitude;
    double longitude;
    int severity;
} Event;

typedef struct {
    char serial[20];
    char manufacturer[20];
    char firmware_version[20];
} SensorMetadata;

typedef struct {
    char* context_string;
} Context;

Event* create_event() {
    srand(time(NULL));
    Event* event = (Event*)malloc(sizeof(Event));
    event->time = time(NULL) % 1000; // generate random time in milliseconds
    event->latitude = (double)(rand() / (RAND_MAX / 1.0)) * 180.0; // generate random latitude between 0 and 180 degrees
    event->longitude = (double)(rand() / (RAND_MAX / 1.0)) * 360.0; // generate random longitude between 0 and 360 degrees
    event->severity = rand() % 5 + 1; // generate random severity level from 1 to 5
    return event;
}

SensorMetadata* create_sensor_metadata(char* serial) {
    SensorMetadata* sensor = (SensorMetadata*)malloc(sizeof(SensorMetadata));
    if (!serial) {
        strcpy(sensor->serial, "Unknown");
        strcpy(sensor->manufacturer, "Unknown");
        strcpy(sensor->firmware_version, "Unknown");
    } else {
        strncpy(sensor->serial, serial, 20);
        strcpy(sensor->manufacturer, "Default");
        strcpy(sensor->firmware_version, "1.0");
    }
    return sensor;
}

Context* create_context_string() {
    Context* context = (Context*)malloc(sizeof(Context));
    int length = rand() % 40 + 10; // generate random string length between 10 and 50 characters
    char* buffer = (char*)malloc(length * sizeof(char));
    for (int i = 0; i < length; i++) {
        if (rand() % 2) {
            buffer[i] = (char)(rand() % 26 + 'a'); // random lowercase letter
        } else {
            buffer[i] = (char)(rand() % 26 + 'A'); // random uppercase letter
        }
    }
    buffer[length] = '\0';
    context->context_string = buffer;
    return context;
}

void free_event(Event* event) {
    if (!event) return;
    free(event);
}

void free_sensor_metadata(SensorMetadata* sensor) {
    if (!sensor) return;
    free(sensor->serial);
    free(sensor);
}

void free_context(Context* context) {
    if (!context) return;
    free(context->context_string);
    free(context);
}

int main() {
    // create a hash table with 10 slots
    HT *ht = htable_create(10);

    for (int i = 0; i < 10000; i++) {
        Event* event = create_event();
        SensorMetadata* sensor = create_sensor_metadata((i % 2) ? "ABC123" : NULL);
        Context* context = create_context_string();

        // insert the event into the hash table
        void *val = NULL;
        int result = htable_put(ht, (void*)event, &val);

        if (result < 0) {
            printf("Error: unable to put event %d in hash table\n", i);
        } else {
            printf("Event %d inserted successfully into the hash table\n", i);
        }

        // free memory allocated for this event
        free_event(event);
        free_sensor_metadata(sensor);
        free_context(context);
    }

    // iterate over all events in the hash table and print their details
    for (int i = 0; i < htable_size(ht); i++) {
        Event* event = (Event*)htable_get(ht, i);
        if (!event) continue;
        printf("Event time: %d, latitude: %.2f, longitude: %.2f, severity: %d\n", event->time, event->latitude, event->longitude, event->severity);
    }

    // free the hash table
    htable_destroy(ht);

    return 0;
}
