record* read_files(const char** file_paths, int num_files) {
    // Initialize memory for arrays
    int* keys = (int*)malloc(num_files * sizeof(int));
    long* offsets = (long*)malloc(num_files * sizeof(long));
    record* records = (record*)malloc((num_files + 1) * sizeof(record));

    // Initialize random seed and generator
    srand(time(NULL));

    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(file_paths[i], "r");
        if (!file) {
            // Handle error
            printf("Error reading file %s\n", file_paths[i]);
            return NULL;
        }

        int key, offset;
        fscanf(file, "%d %ld", &key, &offset);

        keys[i] = key;
        offsets[i] = offset;

        record* current = records + i;
        current->key = rand() % (key - 1) + 1;
        current->offset = rand() % (offset - 1) + 1;

        fclose(file);
    }

    // Initialize linked list
    record* head = records;
    for (int i = 0; i < num_files; i++) {
        if (i > 0) {
            head->next = records + i;
            head = head->next;
        }
    }

    return head;
}

void check_integrity(record* head, const char** file_paths, int num_files) {
    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(file_paths[i], "r");
        if (!file) {
            // Handle error
            printf("Error reading file %s\n", file_paths[i]);
            return;
        }

        int expected_key, expected_offset;
        fscanf(file, "%d %ld", &expected_key, &expected_offset);

        record* current = head;
        while (current) {
            if (current->key != expected_key || current->offset != expected_offset) {
                // Log integrity issue
                printf("Integrity issue at file %s: key=%d, offset=%ld\n", file_paths[i], current->key, current->offset);
            }
            current = current->next;
        }

        fclose(file);
    }
}

void export_to_db(record* head) {
    // Initialize database connection
    // ...

    record* current = head;
    while (current) {
        // Insert data into database
        // ...
        current = current->next;
    }

    // Commit changes to database
    // ...
}

int main() {
    const char* file_paths[] = {"file1.txt", "file2.txt", "file3.txt"};
    int num_files = sizeof(file_paths) / sizeof(file_paths[0]);

    record* head = read_files(file_paths, num_files);
    if (!head) return 1;

    check_integrity(head, file_paths, num_files);

    export_to_db(head);

    // Free memory
    free((void*)head);
    for (int i = 0; i < num_files; i++) {
        free((void*)&keys[i]);
        free((void*)&offsets[i]);
    }
    free((void*)records);

    return 0;
}
