#include <stdlib.h>
#include <string.h>

typedef struct {
    int* value;
    size_t key_index;
    size_t offset_index;
} record;

typedef struct {
    record** records;
    size_t capacity;
    size_t size;
    size_t (*hash_function)(const char*);
} hashtable;

void init_hashtable(hashtable* table, size_t initial_capacity) {
    table->records = (record**)malloc(initial_capacity * sizeof(record));
    table->capacity = initial_capacity;
    table->size = 0;
}

int insert_record(hashtable* table, const char* key, int value, int offset) {
    // Calculate hash value for the given key
    size_t index = table->hash_function(key) % table->capacity;

    if (table->records[index] == NULL) {
        // If slot is empty, allocate and initialize a new record
        table->records[index] = malloc(sizeof(record));
        ((record*)table->records[index])->key_index = strlen((char*)key);
        ((record*)table->records[index])->offset_index = offset;
        ((record*)table->records[index])->value = &value;
    } else {
        // If slot is not empty, update the existing record
        ((record*)table->records[index])->key_index = strlen((char*)key);
        ((record*)table->records[index])->offset_index = offset;
        ((record*)table->records[index]->value) = &value;
    }

    table->size++;
    return 0;
}

int find_record(hashtable* table, const char* key) {
    // Calculate hash value for the given key
    size_t index = table->hash_function(key) % table->capacity;

    if (table->records[index] != NULL) {
        // If record is found at this slot, return its value
        return *(int*)(((record*)table->records[index])->value);
    } else {
        // If record not found at this slot, try next slots until empty or found
        for (size_t i = 0; i < table->capacity; ++i) {
            if (table->records[i] != NULL && memcmp((char*)key, ((record*)table->records[i])->key_index) == 0) {
                return *(int*)(((record*)table->records[i])->value);
            }
        }
    }

    // If record not found after searching entire table
    return -1;
}

void free_hashtable(hashtable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i] != NULL) {
            free(table->records[i]);
        }
    }

    free(table->records);
    table->records = NULL;
}

void resize_hashtable(hashtable* table, size_t new_capacity) {
    hashtable temp_table;

    init_hashtable(&temp_table, new_capacity);

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i] != NULL) {
            int key_index = ((record*)table->records[i])->key_index;
            int offset = ((record*)table->records[i])->offset_index;
            insert_record(&temp_table, (char*)malloc(key_index + 1), *(int*)(((record*)table->records[i])->value), offset);
        }
    }

    free_hashtable(table);

    table->records = temp_table.records;
    table->capacity = new_capacity;
}

size_t simple_hash(const char* key) {
    size_t hash_value = 0;
    for (char c : (char*)key) {
        hash_value += c;
    }
    return hash_value % 256; // or any other prime number
}
