typedef struct {
    int key;
    long offset;
    float weight;
} Record;

typedef struct {
    int *keys;
    long *offsets;
    float *weights;
    Record **records;
    unsigned int size, capacity;
    double loadFactor;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Dataset;

Dataset* dataset_init(unsigned int initialCapacity) {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    dataset->keys = (int*)malloc(initialCapacity * sizeof(int));
    dataset->offsets = (long*)malloc(initialCapacity * sizeof(long));
    dataset->weights = (float*)malloc(initialCapacity * sizeof(float));
    dataset->records = (Record**)calloc(initialCapacity, sizeof(Record*));
    dataset->size = 0;
    dataset->capacity = initialCapacity;
    dataset->loadFactor = 0.75;
    pthread_mutex_init(&dataset->mutex, NULL);
    pthread_cond_init(&dataset->cond, NULL);
    return dataset;
}

void dataset_free(Dataset* dataset) {
    free(dataset->keys);
    free(dataset->offsets);
    free(dataset->weights);
    for (int i = 0; i < dataset->capacity; i++) {
        if (dataset->records[i] != NULL) {
            free(dataset->records[i]);
        }
    }
    free(dataset->records);
    pthread_mutex_destroy(&dataset->mutex);
    pthread_cond_destroy(&dataset->cond);
    free(dataset);
}

int dataset_getKey(Dataset* dataset, int key) {
    // implement custom hash function
    unsigned int index = (key * 0xfeeefee + 1) % dataset->capacity;
    while (dataset->records[index] != NULL && dataset->records[index]->key != key) {
        index = (index + 1) % dataset->capacity;
    }
    return dataset->records[index]->key;
}

void dataset_addRecord(Dataset* dataset, int key, long offset, float weight) {
    if (dataset->size >= dataset->capacity * dataset->loadFactor) {
        // resize the hash table
        unsigned int newCapacity = dataset->capacity * 2;
        Dataset* tempDataset = dataset_init(newCapacity);
        for (int i = 0; i < dataset->capacity; i++) {
            if (dataset->records[i] != NULL) {
                Record* record = dataset->records[i];
                // rehash the record
                unsigned int newIndex = (record->key * 0xfeeefee + 1) % newCapacity;
                while (tempDataset->records[newIndex] != NULL) {
                    newIndex = (newIndex + 1) % newCapacity;
                }
                tempDataset->records[newIndex] = record;
            }
        }
        // transfer ownership
        dataset_free(dataset);
        *dataset = *tempDataset;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->weight = weight;
    unsigned int index = (key * 0xfeeefee + 1) % dataset->capacity;
    while (dataset->records[index] != NULL) {
        index = (index + 1) % dataset->capacity;
    }
    dataset->records[index] = record;
    dataset->size++;
}

void dataset_validate() {
    // implement periodic pointer validation
}
