#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORD_SIZE sizeof(struct Record)
#define TABLE_SIZE 1024
#define LOAD_FACTOR 0.75f
#define PRIME_NUMBER 31

typedef struct {
    int key;
    uint16_t offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity, size;
    float load_factor;
} HashTable;

HashTable *create_hash_table(size_t initial_capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    table->records = malloc(initial_capacity * RECORD_SIZE);
    table->capacity = initial_capacity;
    table->size = 0;
    table->load_factor = LOAD_FACTOR;
    return table;
}

void free_hash_table(HashTable *table) {
    free(table->records);
    free(table);
}

size_t hash_function(uint16_t key) {
    return (key * PRIME_NUMBER) % TABLE_SIZE;
}

int insert_record(HashTable *table, int key, uint16_t offset) {
    size_t index = hash_function(key);
    size_t i = 0;
    while (i < table->size && 
           memcmp(&table->records[index].key, &key, sizeof(int))) {
        if (!memcmp(&table->records[index].offset, &offset, sizeof(uint16_t)))
            return -1; // duplicate key
        index = (index + 1) % table->capacity;
    }
    if (i == table->size) {
        if (table->size * table->load_factor > table->capacity)
            resize_table(table);
        memcpy(&table->records[table->size], &key, sizeof(int));
        memcpy(&table->records[table->size + 1], &offset, sizeof(uint16_t));
        table->size++;
    } else {
        // collision handling
        size_t j = 0;
        while (j < i && 
               memcmp(&table->records[index].key, &key, sizeof(int))) {
            index = (index + 1) % table->capacity;
            j++;
        }
        if (j == i)
            memcpy(&table->records[table->size], &key, sizeof(int));
        else
            memcpy(&table->records[index], &key, sizeof(int));
        table->size++;
    }
    return 0; // success
}

int delete_record(HashTable *table, int key) {
    size_t index = hash_function(key);
    size_t i = 0;
    while (i < table->size && 
           memcmp(&table->records[index].key, &key, sizeof(int))) {
        index = (index + 1) % table->capacity;
        i++;
    }
    if (i == table->size)
        return -1; // key not found
    else {
        // remove the record and rehash the rest
        size_t j = i;
        while (++j < table->size) {
            Record *record = &table->records[index];
            index = hash_function(record->key);
            memcpy(&table->records[j], &record, RECORD_SIZE);
        }
        table->size--;
    }
    return 0; // success
}

void print_records(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i)
        printf("(%d, %u)\n", table->records[i].key, table->records[i].offset);
}
