void generate_and_populate_records(int numOffsets, int numRecords, int minOffset, int maxOffset) {
    // Validate inputs
    if (numOffsets <= 0 || numRecords <= 0 || minOffset > maxOffset) {
        printf("Invalid input: numOffsets = %d, numRecords = %d, minOffset = %d, maxOffset = %d\n", 
               numOffsets, numRecords, minOffset, maxOffset);
        return;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Generate and store offsets
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed for offsets.\n");
        return;
    }
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = random_in_range(minOffset, maxOffset);
    }

    // Generate and store keys
    int* keys = (int*)malloc(numOffsets * sizeof(int));
    if (!keys) {
        printf("Memory allocation failed for keys.\n");
        free(offsets);
        return;
    }
    for (int i = 0; i < numOffsets; i++) {
        keys[i] = random_in_range(1, 100); // Assume key range is 1-100
    }

    // Initialize and populate records array
    struct record* records = (struct record*)malloc(numRecords * sizeof(struct record));
    if (!records) {
        printf("Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return;
    }
    for (int i = 0; i < numRecords; i++) {
        int randIndex = rand() % numOffsets;
        records[i].offset = offsets[randIndex];
        records[i].key = keys[randIndex];
    }

    // Free memory
    free(offsets);
    free(keys);

    // Verify integrity of data structures
    for (int i = 0; i < numRecords; i++) {
        printf("Record %d: offset = %ld, key = %d\n", i + 1, records[i].offset, records[i].key);
    }
}

long random_in_range(long min, long max) {
    return min + rand() % ((max - min) + 1);
}
