    array[capacity-1]->string = malloc(strlen(string) + 1);
    strcpy(array[capacity-1]->string, string);

    return capacity;
}

void float_string_array_free(FloatString **array, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (array[i] != NULL) {
            free(array[i]->string);
            free(array[i]);
        }
    }
    free(*array);
}

