typedef struct {
    double value;
    char* string;
} DataElement;

typedef struct {
    int count;
    int isValid;
} Metadata;

Metadata* allocateMetadata() {
    Metadata* metadata = (Metadata*)malloc(sizeof(Metadata));
    if (!metadata) {
        logError("Failed to allocate memory for metadata");
        return NULL;
    }
    metadata->count = 0;
    metadata->isValid = 1; // assume data is valid initially
    return metadata;
}

DataElement** allocateArray(int size, Metadata* metadata) {
    DataElement** array = (DataElement**)malloc(sizeof(DataElement*) * size);
    if (!array) {
        logError("Failed to allocate memory for array");
        free(metadata);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        array[i] = (DataElement*)malloc(sizeof(DataElement));
        if (!array[i]) {
            logError("Failed to allocate memory for data element");
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(metadata);
            return NULL;
        }
    }

    metadata->count = size;
    return array;
}

void deallocateArray(DataElement** array, Metadata* metadata) {
    for (int i = 0; i < metadata->count; i++) {
        free(array[i]->string);
        free(array[i]);
    }
    free(metadata);
    free(array);
}

Metadata* loadAndProcessData(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        logError("Failed to open file");
        return NULL;
    }

    Metadata* metadata = allocateMetadata();
    if (!metadata) {
        fclose(file);
        return NULL;
    }

    *size = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // handle missing or malformed data entries
        DataElement* element = (DataElement*)malloc(sizeof(DataElement));
        if (!element) {
            logError("Failed to allocate memory for data element");
            deallocateArray(NULL, metadata);
            fclose(file);
            return NULL;
        }

        // parse line and update element values
        element->value = atof(strtok(line, ","));
        char* token = strtok(NULL, ",");
        int len = strlen(token);
        element->string = (char*)malloc(len + 1);
        strcpy(element->string, token);
        element->string[len] = '\0';

        DataElement** array = allocateArray(*size + 1, metadata);
        if (!array) {
            deallocateArray(array, metadata);
            fclose(file);
            return NULL;
        }

        array[*size] = element;
        *size += 1;
    }

    fclose(file);
    return metadata;
}

int main() {
    int size;
    Metadata* metadata = loadAndProcessData("data.csv", &size);
    if (!metadata) {
        logError("Failed to load and process data");
        return 1;
    }

    // use the allocated array and metadata
    deallocateArray(metadata->array, metadata);
    free(metadata);

    return 0;
}
