record_t* create_record(int seed) {
    record_t* record = (record_t*)malloc(sizeof(record_t));
    record->value = rand_r(&seed);
    char str[16];
    sprintf(str, "%d", record->value);
    record->data = strdup(str);
    return record;
}

// Function to check if string exceeds size limit and append slash if necessary
char* validate_string(char* str) {
    int len = strlen(str);
    if (len > 15) {
        char* new_str = (char*)malloc((len + 2) * sizeof(char));
        strcpy(new_str, str);
        strcat(new_str, "/");
        return new_str;
    }
    return NULL;
}

// Function to create a new doubly linked list node
Node* create_node(record_t* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->prev = NULL;
    node->next = NULL;
    return node;
}
