{
    private static readonly object _lock = new();
    private static readonly Random _random = new();
    private static readonly TimeSpan _cacheTimeWindow = TimeSpan.FromMinutes(1);
    private static readonly Dictionary<string, Tuple<int[], int[], Record[]>> _cache = new();

    public static (int[], int[], Record[]) ProcessString(string input)
    {
        if (_cache.TryGetValue(input, out var cachedValues))
            return cachedValues;

        lock (_lock)
        {
            if (_cache.TryGetValue(input, out cachedValues))
                return cachedValues;
        }

        int[] longOffsets = new int[10]; // allocate and initialize array
        int[] intKeys = new int[20]; // allocate and initialize array

        Record[] records = new Record[30]; // allocate and initialize array

        for (int i = 0; i < records.Length; i++)
        {
            int recordValue = _random.Next(100, 200); // generate random value
            records[i] = new Record { Value = recordValue };
        }

        MD5 md5 = MD5.Create();
        byte[] hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
        string hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

        // caching mechanism
        _cache.Add(input, (longOffsets, intKeys, records));

        return (longOffsets, intKeys, records);
    }
