bool allocateDataStructures(size_t numOffsets, size_t numKeys, size_t numRecords, int minValue, int maxValue, void** baseAddress) {
    if (numOffsets == 0 || numKeys == 0 || numRecords == 0) return false; // Handle edge cases for zero or negative input sizes

    record* records = NULL;
    records = (record*)malloc((numOffsets + numKeys + numRecords) * sizeof(record)); // Allocate memory block
    if (!records) {
        free(records);
        return false; // Check for allocation failure
    }

    srand(time(NULL)); // Seed random number generator

    // Initialize record values within specified range
    for (size_t i = 0; i < numOffsets + numKeys + numRecords; i++) {
        records[i].offset = rand() % ((maxValue - minValue) + 1) + minValue;
        if (i >= numOffsets && i < numOffsets + numKeys) {
            records[i].key = rand() % ((maxValue - minValue) + 1) + minValue;
        }
    }

    *baseAddress = records; // Store the base address of allocated memory block
    return true;
}
