void gc() {
    for (int i = 0; i < entry_count; i++) {
        if ((time(NULL) - entries[i]->temperature_time) > timeout) {
            free(entries[i]);
            memmove(&entries[i], &entries[i + 1], (entry_count - i - 1) * sizeof(Entry*));
            entry_count--;
            if (entry_count < max_size / 2) {
                max_size = entry_count * 2;
            }
        }
    }
}

