#define MAX_RECORDS 1000000
#define BUFFER_SIZE 256

typedef struct {
    char buffer[BUFFER_SIZE];
    int key;
    float value;
} Record;

Record* records = NULL;
int num_records = 0;
float average_value = 0.0f;

void add_record(const char* buffer, int key, float value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    strcpy(new_record->buffer, buffer);
    new_record->key = key;
    new_record->value = value;

    if (!records) {
        records = new_record;
    } else {
        Record* current = records;
        while (current) {
            Record* next = current->next;
            current->next = new_record;
            new_record = next;
        }
    }

    num_records++;
}

void update_record(int key, float value) {
    Record* current = records;
    while (current) {
        if (current->key == key) {
            current->value = value;
            break;
        }
        current = current->next;
    }
}

void remove_record(int key) {
    Record** record_ptrs = &records;
    while (*record_ptrs) {
        if ((*record_ptrs)->key == key) {
            *record_ptrs = (*record_ptrs)->next;
            free(*record_ptrs);
            break;
        }
        record_ptrs = &((*record_ptrs)->next);
    }
}

float calculate_average_value() {
    float sum = 0.0f;
    Record* current = records;
    while (current) {
        sum += current->value;
        current = current->next;
    }

    return sum / num_records;
}

void update_buffers(float average_value) {
    Record* current = records;
    while (current) {
        int diff = (int)((average_value - current->value) * 100.0f);
        if (diff > 10 || diff < -10) {
            // Update buffer based on the average value
            sprintf(current->buffer, "Value: %f", average_value);
        }
        current = current->next;
    }
}

void print_records() {
    Record* current = records;
    while (current) {
        printf("%s\n", current->buffer);
        current = current->next;
    }
}
