from multiprocessing import Pool
from blueslip import MockingLibrary

def run_tests():
    # Load test modules dynamically
    test_modules = []
    for file in os.listdir('tests'):
        if file.endswith('.py'):
            test_modules.append(file[:-3])

    # Execute tests in parallel using multiprocessing pool
    with Pool() as pool:
        results = pool.map(test_run, test_modules)

    # Log test execution and outcomes
    print("Test Results:")
    for result in results:
        print(f"{result[0]}: {result[1]}")

def test_run(module):
    # Run individual test module using subprocess
    command = f"python -m unittest discover tests.{module}"
    output = subprocess.run(command, capture_output=True)

    # Reset blueslip mocking library after each test run
    mocking_library.reset()

    return (f"{module}", output.returncode == 0)
