// Define a struct to represent metadata structures
typedef struct {
    int lifecycle;
} Metadata;

// Define a struct to represent record structures
typedef struct {
    int value;
    Metadata metadata;
} Record;

// Define a struct to represent the data storage system
typedef struct {
    // Offset data structure (long integer offsets)
    long *offsets;
    size_t offset_size;

    // Key data structure (integer keys)
    int *keys;
    size_t key_size;

    // Record data structure (record structures containing an integer value)
    Record *records;
    size_t record_size;

    // Metadata data structure (metadata structures detailing each record's lifecycle)
    Metadata *metadata;
    size_t metadata_size;

    // Doubly linked list for efficient insertion, deletion, and modification operations
    struct Node {
        void *data;
        struct Node *prev;
        struct Node *next;
    } head, tail;

    // Caching mechanism to enhance read performance
    Record *cache_records;
    size_t cache_size;
} DataStorageSystem;

// Function to initialize the data storage system
DataStorageSystem* init_data_storage_system(size_t offset_capacity, size_t key_capacity, size_t record_capacity, size_t metadata_capacity) {
    // Initialize data structures with dynamic allocation
    DataStorageSystem *system = (DataStorageSystem*)malloc(sizeof(DataStorageSystem));
    system->offsets = (long*)malloc(OFFSET_SIZE * sizeof(long));
    system->keys = (int*)malloc(KEY_SIZE * sizeof(int));
    system->records = (Record*)malloc(RECORD_SIZE * sizeof(Record));
    system->metadata = (Metadata*)malloc(METADATA_SIZE * sizeof(Metadata));

    // Initialize caching mechanism
    system->cache_records = (Record*)malloc(record_capacity * sizeof(Record));
    system->cache_size = record_capacity;

    // Initialize doubly linked list
    system->head.prev = &system->tail;
    system->tail.next = &system->head;

    return system;
}

// Function to release memory and resources upon function exit
void cleanup(DataStorageSystem* system) {
    free(system->offsets);
    free(system->keys);
    free(system->records);
    free(system->metadata);
    free(system->cache_records);
    free(system);
}
