#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct record {
    int key;
    long timestamp;
    enum { active, inactive, expired } state;
    struct record *prev, *next;
} record;

record *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int cleanup_frequency = 1000; // in milliseconds
int error_log_count = 0;

void *malloc_r(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Out of memory.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_r(void *ptr) {
    free(ptr);
}

record *create_record(int key, long timestamp, enum { active, inactive, expired } state) {
    record *new_record = (record *)malloc_r(sizeof(record));
    new_record->key = key;
    new_record->timestamp = timestamp;
    new_record->state = state;
    new_record->prev = NULL;
    new_record->next = NULL;
    return new_record;
}

void insert_record(record *new_record) {
    pthread_mutex_lock(&lock);
    if (head == NULL || new_record->timestamp < head->timestamp) {
        new_record->next = head;
        if (head != NULL)
            head->prev = &new_record;
        head = new_record;
    } else {
        record *current = head;
        while (current->next != NULL && current->next->timestamp >= new_record->timestamp)
            current = current->next;
        new_record->next = current->next;
        if (current->next != NULL) {
            current->next->prev = &new_record;
            new_record->next = current->next;
        } else
            current->next = new_record;
        new_record->prev = &current;
    }
    pthread_mutex_unlock(&lock);
}

void delete_record(record *old_record) {
    pthread_mutex_lock(&lock);
    if (old_record->prev != NULL)
        old_record->prev->next = old_record->next;
    else
        head = old_record->next;

    if (old_record->next != NULL)
        old_record->next->prev = old_record->prev;
    free_r(old_record);
    pthread_mutex_unlock(&lock);
}

void cleanup_records() {
    record *current = head;
    int count = 0;
    while (current != NULL) {
        if ((int)(current->timestamp / 1000) % cleanup_frequency == 0) {
            record *temp = current;
            current = current->next;
            free_r(temp);
            count++;
        } else
            current = current->next;
    }
}

void transition_records() {
    pthread_mutex_lock(&lock);
    record *current = head;
    while (current != NULL) {
        switch (current->state) {
        case active:
            if ((int)(current->timestamp / 1000) % cleanup_frequency == 0)
                current->state = inactive;
            break;
        case inactive:
            if ((int)(current->timestamp / 1000) % cleanup_frequency == 0)
                current->state = expired;
            break;
        default:
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void print_records() {
    record *current = head;
    while (current != NULL) {
        printf("%d %ld %s\n", current->key, current->timestamp, current->state == active ? "active" : current->state == inactive ? "inactive" : "expired");
        current = current->next;
    }
}

int main() {
    int i;
    for (i = 0; i < 10000; i++) {
        insert_record(create_record(i, (long)time(NULL), active));
    }

    while (1) {
        transition_records();
        sleep(1);
    }

    return 0;
}
