void log_message(const char *message) {
    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->message = strdup(message);

    // Add log entry to priority queue
    if (queue_size < max_queue_size) {
        queue[queue_size++] = entry;
    } else {
        // Rotate and store log messages in circular buffer
        char *tmp_buffer = buffer;
        buffer = (char *)malloc(buffer_size);
        memcpy(buffer, tmp_buffer + buffer_read_index, BUFFER_SIZE - buffer_read_index);
        free(tmp_buffer);

        // Add new log entry to circular buffer
        strcpy(buffer + BUFFER_SIZE - buffer_write_index, message);
        buffer_write_index += strlen(message) + 1;
    }
}

// Function for periodic cleanup of expired sessions and unused log entries
void *cleanup_thread_func(void *arg) {
    while (1) {
        // Check for expired sessions and remove them from the hash table
