    cache_entry_t entry;
    pthread_mutex_t lock;
} cache_node_t;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

cache_entry_t** cache = NULL;
int cache_size = 0;

void insert_cache_entry(char* filename, int size) {
    pthread_mutex_lock(&cache_lock);

    // Insert the new entry into the hash table
    int index = strlen(filename) % MAX_CACHE_SIZE;
    if (cache[index] == NULL) {
        cache[index] = malloc(sizeof(cache_entry_t));
    } else {
        for (int i = 0; i < MAX_ENTRY_SIZE; i++) {
            if (cache[index][i].entry.filename[i] == '\0') {
                break;
            }
        }
    }

    // Initialize the new entry
    cache_entry_t* new_entry = malloc(sizeof(cache_entry_t));
    strcpy(new_entry->filename, filename);
    new_entry->size = size;
    new_entry->state = STATE_VALID;

    if (cache[index] != NULL) {
        for (int i = 0; i < MAX_ENTRY_SIZE; i++) {
            if (cache[index][i].entry.filename[i] == '\0') {
                break;
            }
        }
    }

    // Insert the new entry into the linked list
    cache_node_t* new_node = malloc(sizeof(cache_node_t));
    new_node->entry = *new_entry;
    new_node->prev = NULL;
    new_node->next = NULL;

    if (cache[index] != NULL) {
        for (int i = 0; i < MAX_ENTRY_SIZE; i++) {
            if (cache[index][i].entry.filename[i] == '\0') {
                break;
            }
        }
    }

    // Update the linked list
    if (cache_size > 0) {
        cache_node_t* temp = cache[0];
        for (int i = 0; i < cache_size - 1; i++) {
            temp->next = temp->next->next;
            temp = temp->next;
        }
        temp->next = new_node;
    } else {
        cache[0] = new_node;
    }

    // Update the hash table
    for (int i = 0; i < MAX_ENTRY_SIZE; i++) {
        if (cache[index][i].entry.filename[i] == '\0') {
            break;
        }
    }

    cache_size++;
    pthread_mutex_unlock(&cache_lock);
}

void lookup_cache_entry(char* filename) {
    pthread_mutex_lock(&cache_lock);

    // Find the entry in the hash table
    int index = strlen(filename) % MAX_CACHE_SIZE;
    for (int i = 0; i < MAX_ENTRY_SIZE; i++) {
        if (cache[index][i].entry.filename[i] == '\0') {
            break;
        }
    }

    // Check if the entry exists in the linked list
    cache_node_t* temp = cache[0];
    for (int i = 0; i < cache_size - 1; i++) {
        if (strcmp(temp->entry.filename, filename) == 0) {
            break;
        }
        temp = temp->next;
    }

    // Check the state of the entry
    if (temp != NULL && temp->entry.state == STATE_VALID) {
        // Perform actions on the valid entry
    } else if (temp != NULL && temp->entry.state == STATE_STALE) {
        // Perform actions on the stale entry
    } else if (temp != NULL && temp->entry.state == STATE_EVICTED) {
        // Perform actions on the evicted entry
    }

    pthread_mutex_unlock(&cache_lock);
}

void cleanup_cache() {
    pthread_mutex_lock(&cache_lock);

    // Find all entries with state EVICTED and remove them from the linked list
    for (int i = 0; i < cache_size - 1; i++) {
        if (cache[0].next->entry.state == STATE_EVICTED) {
            // Remove the entry from the linked list
            cache_node_t* temp = cache[0];
            while (temp.next != NULL && temp.next->entry.state == STATE_EVICTED) {
                temp.next = temp.next.next;
            }
        }
    }

    // Update the hash table
    for (int i = 0; i < MAX_ENTRY_SIZE; i++) {
        if (cache[0].next[i].entry.filename[i] == '\0') {
            break;
        }
    }

    // Periodically clean up stale entries based on their age and state
    for (int i = 0; i < cache_size - 1; i++) {
        if (cache[0].next[i].entry.state == STATE_STALE) {
            // Remove the entry from the linked list
            cache_node_t* temp = cache[0];
            while (temp.next != NULL && temp.next->entry.state == STATE_STALE) {
                temp.next = temp.next.next;
            }
        }
    }

    pthread_mutex_unlock(&cache_lock);
}

void evict_cache_entry(char* filename) {
    pthread_mutex_lock(&cache_lock);

    // Find the entry in the hash table
    int index = strlen(filename) % MAX_CACHE_SIZE;
    for (int i = 0; i < MAX_ENTRY_SIZE; i++) {
        if (cache[index][i].entry.filename[i] == '\0') {
            break;
        }
    }

    // Check if the entry exists in the linked list
    cache_node_t* temp = cache[0];
    for (int i = 0; i < cache_size - 1; i++) {
        if (strcmp(temp->entry.filename, filename) == 0) {
            break;
        }
        temp = temp->next;
    }

    // Set the state of the entry to EVICTED
    if (temp != NULL) {
        temp->entry.state = STATE_EVICTED;
    }

    pthread_mutex_unlock(&cache_lock);
}

void* periodic_cleanup(void* arg) {
    // Periodically clean up stale entries based on their age and state
    for (int i = 0; i < cache_size - 1; i++) {
        if (cache[0].next[i].entry.state == STATE_STALE) {
            // Remove the entry from the linked list
            cache_node_t* temp = cache[0];
            while (temp.next != NULL && temp.next->entry.state == STATE_STALE) {
                temp.next = temp.next.next;
            }
        }
    }

    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, periodic_cleanup, NULL);

    // Initialize the cache
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        cache[i] = malloc(sizeof(cache_entry_t));
    }

    // Insert entries into the cache
    insert_cache_entry("file1", 1024);
    insert_cache_entry("file2", 2048);
    insert_cache_entry("file3", 4096);

    // Perform operations on the cache
    lookup_cache_entry("file1");
    evict_cache_entry("file2");
    cleanup_cache();

    return 0;
}
