typedef struct {
    int key;
    long offset;
    time_t timestamp;
    char status;
    char metadata[256];
} record;

record *records = NULL;
int records_count = 0;
int max_records = 1000;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int refs = 0;

void init_records() {
    srand(time(NULL));
    for (int i = 0; i < max_records; i++) {
        record *r = malloc(sizeof(record));
        r->key = rand() % 10000;
        r->offset = -1;
        r->timestamp = time(NULL);
        strcpy(r->metadata, "");
        pthread_mutex_lock(&lock);
        records = realloc(records, (records_count + 1) * sizeof(record *));
        records[records_count] = r;
        records_count++;
        pthread_mutex_unlock(&lock);
    }
}

void* thread_func(void* arg) {
    while(1) {
        pthread_mutex_lock(&lock);
        if(refs > 0) {
            pthread_cond_signal(&cond);
        } else {
            pthread_cond_wait(&cond, &lock);
        }
        pthread_mutex_unlock(&lock);

        // periodic update and modification
        for(int i = 0; i < records_count; i++) {
            record *r = records[i];
            r->key = rand() % 10000;
            r->timestamp = time(NULL);
        }
    }
    return NULL;
}

int main() {
    pthread_t thread;
    init_records();
    pthread_create(&thread, NULL, &thread_func, NULL);

    // handling read and write operations
    while(1) {
        // read operation
        for(int i = 0; i < records_count; i++) {
            record *r = records[i];
            printf("Key: %d Offset: %ld Timestamp: %lu Status: %c Metadata: %s\n", r->key, r->offset, r->timestamp, r->status, r->metadata);
        }

        // write operation
        for(int i = 0; i < records_count; i++) {
            record *r = records[i];
            printf("Enter new key and metadata for record %d: ", i);
            scanf("%d %s", &r->key, r->metadata);
            r->timestamp = time(NULL);
            refs++;
        }

        pthread_mutex_lock(&lock);
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
    }

    return 0;
}
