        (*point_array)[i].x = (float)rand() / RAND_MAX;
        (*point_array)[i].y = (float)rand() / RAND_MAX;
    }

    // Validate memory integrity and alignment
    if((*double_array + *size/2) % 8 != 0) {
        printf("Double array not aligned.\n");
    }
    for(int i = 0; i < *size; i++) {
        if(((char*)*point_array)[i].x % 4 != 0 || ((char*)*point_array)[i].y % 4 != 0) {
            printf("Point array not aligned.\n");
            break;
        }
    }

    // Release resources in case of error
    if(*double_array) free(*double_array);
    if(*char_array) free(*char_array);
    if(*point_array) free(*point_array);

    return;
}
