#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    int key;
    long timestamp;
    char state[10];
} Record;

typedef struct _node {
    Record data;
    struct _node* prev;
    struct _node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int cleanup_freq;
    int max_age;
    void (*callback)(Record*);
} Collection;

void init_collection(Collection* col, int size) {
    if (size < 0) return;
    col->head = NULL;
    col->tail = NULL;
    pthread_mutex_init(&col->lock, NULL);
    pthread_cond_init(&col->cond, NULL);
    col->cleanup_freq = 10; // default value
}

void insert_collection(Collection* col, Record record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = record;
    new_node->prev = NULL;
    new_node->next = col->head;

    if (col->head != NULL)
        col->head->prev = &new_node->data;
    else
        col->tail = &new_node->data;

    col->head = new_node;
    pthread_mutex_lock(&col->lock);
    pthread_cond_signal(&col->cond);
    pthread_mutex_unlock(&col->lock);
}

void remove_collection(Collection* col, Record record) {
    Node* current = col->head;
    while (current != NULL) {
        if (memcmp(&current->data, &record, sizeof(Record)) == 0) {
            if (current->prev != NULL)
                current->prev->next = current->next;
            else
                col->head = current->next;

            if (current->next != NULL)
                current->next->prev = current->prev;
            else
                col->tail = current->prev;

            free(current);
            return;
        }
        current = current->next;
    }
}

void* record_callback(void* arg) {
    Collection* col = (Collection*)arg;
    pthread_mutex_lock(&col->lock);
    while (1) {
        Node* current = col->head;
        while (current != NULL) {
            if (/* check for expired state */) {
                Record record = current->data;
                free(current);
                col->head = current->next;
                col->tail->prev = &record;
                col->tail = &record;
                pthread_cond_signal(&col->cond);
                break;
            }
            current = current->next;
        }
        pthread_cond_wait(&col->cond, &col->lock);
    }
}

void* data_source_thread(void* arg) {
    // fetch periodic updates from external data source
    Collection* col = (Collection*)arg;

    while (1) {
        // fetch updated records and merge with existing collection
        // handle transient network failures and ensure data consistency

        pthread_mutex_lock(&col->lock);
        for (Node* current = col->head; current != NULL; current = current->next) {
            if (/* check for outdated records */) {
                remove_collection(col, current->data); // update and remove outdated records
            }
        }
        pthread_mutex_unlock(&col->lock);

        usleep(1000000);
    }
}

int main() {
    Collection col;
    init_collection(&col, 10);

    pthread_t callback_thread, data_source_thread;

    pthread_create(&callback_thread, NULL, record_callback, &col);
    pthread_create(&data_source_thread, NULL, data_source_thread, &col);

    for (int i = 0; i < 100; i++) {
        Record record;
        // generate records with random key, timestamp, and state
        insert_collection(&col, record);
    }

    // wait for threads to finish
    pthread_join(callback_thread, NULL);
    pthread_join(data_source_thread, NULL);

    return 0;
}
