#define MAX_RECORDS 1000000
#define RECORD_SIZE sizeof(record_t)
#define LOG_LEVEL 1

typedef struct record {
    int value;
    time_t timestamp;
} record_t;

record_t* create_record() {
    record_t* rec = (record_t*)malloc(RECORD_SIZE);
    rec->value = rand() % 100; // Set a random value between 0 and 99
    rec->timestamp = time(NULL); // Get the current system time
    return rec;
}

struct node {
    record_t* data;
    struct node* next;
};

typedef struct node* node_ptr;

node_ptr create_node(record_t* data) {
    node_ptr new_node = (node_ptr)malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_node(node_ptr node) {
    if (node == NULL)
        return;
    free(node);
}

node_ptr insert_node(node_ptr head, record_t* data) {
    node_ptr new_node = create_node(data);
    if (head == NULL)
        return new_node;
    new_node->next = head;
    return new_node;
}

void delete_node(node_ptr node) {
    if (node == NULL)
        return;
    free_node(node);
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    int max_size = 1000; // Define the maximum size of the linked list
    record_t* offset_values = (record_t*)malloc(sizeof(record_t) * max_size);
    int* keys = (int*)malloc(sizeof(int) * max_size);
    node_ptr head = NULL;

    for (int i = 0; i < max_size; i++) {
