        records[i] = record;
    }

    // Implement a doubly linked list to efficiently manage the records
    struct node* head = NULL;
    for (int i = 0; i < numRecords; i++) {
        struct node* newNode = (struct node*)malloc(sizeof(struct node));
        newNode->data = &records[i];
        newNode->prev = NULL;
        newNode->next = head;
        if (head != NULL) head->prev = &newNode->prev;
        else head = newNode;
    }

    // Free all allocated memory upon the function's completion
    free(offsets);
    free(keys);
    free(records);
    for (int i = 0; i < numRecords; i++) {
        if (&records[i]->offset != NULL) free(&records[i]->offset);
        if (&records[i]->key != NULL) free(&records[i]->key);
    }
}
