#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int integer;
    float floating_point;
    char* character_array;
} record;

record* create_record(int integer_value, float floating_point_value, const char* character_array) {
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        return NULL;
    }
    new_record->integer = integer_value;
    new_record->floating_point = floating_point_value;
    new_record->character_array = strdup(character_array);
    return new_record;
}

int random_integer(int min, int max) {
    static int seed = time(NULL);
    int result = (seed * 1103515245 + 12345) % (max - min + 1) + min;
    return result;
}

typedef struct node {
    record* data;
    struct node* next;
    struct node* prev;
} node;

node* insert_node(node** head, record* new_record) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        return NULL;
    }
    new_node->data = new_record;
    new_node->next = (*head);
    new_node->prev = NULL;
    if (*head != NULL) {
        (*head)->prev = &new_node->next;
    } else {
        *head = new_node;
    }
    return new_node;
}

node* delete_node(node** head, node* target) {
    if (target->next != NULL) {
        target->next->prev = target->prev;
    } else {
        *head = target->next;
    }
    if (target->prev != NULL) {
        target->prev->next = target->next;
    } else {
        *head = target->next;
    }
    free(target);
    return *head;
}

int search_node(node* head, int integer_value) {
    node* current = head;
    while (current != NULL && current->data->integer != integer_value) {
        current = current->next;
    }
    if (current == NULL || current->data->integer != integer_value) {
        return -1; // not found
    } else {
        return 0; // found
    }
}

void garbage_collection(node** head, int threshold) {
    node* current = *head;
    while (current != NULL) {
        if (current->next == NULL && current->prev == NULL) {
            free(current);
            current = current->next;
        } else {
            current = current->next;
        }
    }
}

void cache_eviction_policy(node** head, int threshold) {
    node* current = *head;
    while (current != NULL) {
        if (current->next == NULL && current->prev == NULL) {
            free(current);
            current = current->next;
        } else {
            current = current->next;
        }
    }
}

void thread_safe_function(node** head, int integer_value) {
    pthread_mutex_lock(&mutex);
    node* current = *head;
    while (current != NULL && current->data->integer != integer_value) {
        current = current->next;
    }
    if (current == NULL || current->data->integer != integer_value) {
        // not found
    } else {
        // found
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL));
    node* head = NULL;
    pthread_mutex_t mutex;

    for (int i = 0; i < 10; i++) {
        record* new_record = create_record(random_integer(1, 100), (float)i / 10.0f, "hello");
