#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to hold record metadata
typedef struct {
    int offset;
    int key;
    int value;
} RecordMeta;

// Define a struct to hold the flexible data storage system
typedef struct {
    // Cache mechanism
    pthread_mutex_t cache_lock;
    size_t cache_size;
    RecordMeta *cache_records;

    // Main data structure
    pthread_mutex_t data_lock;
    size_t record_count;
    RecordMeta **records;

} DataStorageSystem;

// Function to initialize the data storage system
DataStorageSystem* init_data_storage_system(size_t size) {
    DataStorageSystem *system = (DataStorageSystem*)malloc(sizeof(DataStorageSystem));
    system->cache_size = 0;
    system->cache_records = NULL;

    system->record_count = 0;
    system->records = (RecordMeta**)calloc(size, sizeof(RecordMeta*));

    pthread_mutex_init(&system->data_lock, NULL);
    pthread_mutex_init(&system->cache_lock, NULL);

    return system;
}

// Function to create a new record and initialize its fields
void* create_record(int offset, int key) {
    RecordMeta *record = (RecordMeta*)malloc(sizeof(RecordMeta));
    record->offset = offset;
    record->key = key;
    record->value = rand() % 100; // Initialize with pseudo-random value

    return record;
}

// Function to add a new record to the data storage system
void add_record(DataStorageSystem *system, int offset) {
    pthread_mutex_lock(&system->data_lock);
    RecordMeta *record = create_record(offset, system->record_count + 1);

    // Handle edge case: if adding a record would exceed the maximum size
    if (system->record_count >= system->cache_size) {
        // Expand cache and data structures as needed
        system->cache_size *= 2;
        system->records = (RecordMeta**)realloc(system->records, system->cache_size * sizeof(RecordMeta*));
    }

    // Add record to cache if necessary
    pthread_mutex_lock(&system->cache_lock);
    if (system->record_count < system->cache_size) {
        system->cache_records[system->record_count] = record;
    }
    pthread_mutex_unlock(&system->cache_lock);

    system->records[system->record_count] = record;
    system->record_count++;

    pthread_mutex_unlock(&system->data_lock);
}

// Function to get a record from the data storage system
RecordMeta* get_record(DataStorageSystem *system, int key) {
    // Check cache first
    for (int i = 0; i < system->cache_size; i++) {
        if (system->cache_records[i]->key == key) {
            return system->cache_records[i];
        }
    }

    // If not in cache, search main data structure
    pthread_mutex_lock(&system->data_lock);
    for (int i = 0; i < system->record_count; i++) {
        if (system->records[i]->key == key) {
            return system->records[i];
        }
    }
    pthread_mutex_unlock(&system->data_lock);

    // If not found, return NULL
    return NULL;
}

// Function to free the data storage system's resources
void free_data_storage_system(DataStorageSystem *system) {
    for (int i = 0; i < system->record_count; i++) {
        free(system->records[i]);
    }
    free(system->records);
    pthread_mutex_destroy(&system->data_lock);
    pthread_mutex_destroy(&system->cache_lock);
    free(system);
}

// Example usage
int main() {
    DataStorageSystem *system = init_data_storage_system(16);

    // Add records to the system
    add_record(system, 0);
    add_record(system, 1);
    add_record(system, 2);

    // Get a record from the system
    RecordMeta *record = get_record(system, 1);
    if (record != NULL) {
        printf("Record with key %d found: offset=%d, value=%d\n", record->key, record->offset, record->value);
    } else {
        printf("Record not found!\n");
    }

    // Free the system's resources
    free_data_storage_system(system);

    return 0;
}
