typedef struct {
    int val;
} record_t;

int processAndStoreRecords(long offset, int range) {
    // Initialize arrays
    long *offsets = malloc(sizeof(long));
    int *keys = malloc(sizeof(int));

    // Initialize records array
    record_t *records = malloc(range * sizeof(record_t));
    for (int i = 0; i < range; i++) {
        records[i].val = rand() % range;
    }

    // Initialize ConcurrentHashMap
    void **entries = NULL;
    int size = 0, capacity = 16;
    ConcurrentHashMap(String, String) hash;

    // Initialize doubly linked list
    record_t *head = NULL, *tail = NULL;
    for (int i = 0; i < range; i++) {
        record_t *new_node = malloc(sizeof(record_t));
        new_node->val = records[i].val;
        if (!head) head = tail = new_node;
        else {
            new_node->prev = tail;
            tail->next = new_node;
            tail = new_node;
        }
    }

    // Initialize MD5 context
    md5_context md5ctx;

    // Set timeout mechanism
    clock_t start_time = clock();
    int max_timeout = 30; // seconds

    while (1) {
        // Process records
        for (int i = 0; i < range; i++) {
            // Compute MD5 hash
            md5_starts(&md5ctx);
            char buf[16];
            sprintf(buf, "%d", records[i].val);
            md5_update(&md5ctx, buf, strlen(buf));
            char *hash_str = malloc(33);
            md5_finish(&md5ctx, hash_str);
            hash.put(String.valueOf(i), new String(hash_str));

            // Free memory
            free(hash_str);
        }

        // Check timeout
        clock_t end_time = clock();
        if (difftime(end_time, start_time) > max_timeout) {
            free(entries);
            free(keys);
            free(offsets);
            free(records);
            return new HashMap<>();
        }
    }

    // Clean up
    free(entries);
    free(keys);
    free(offsets);
    free(records);

    return hash;
}
