#include <string.h>
#include <pthread.h>

// Structure definition for record
typedef struct {
    int value;
} record;

// Structure definition for data structures management
typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t size;
    pthread_mutex_t mutex;
} memory_manager;

// Function to initialize the memory manager with random records
memory_manager* init_memory_manager(size_t capacity) {
    memory_manager *manager = (memory_manager*)malloc(sizeof(memory_manager));
    manager->offsets = (long*)malloc(capacity * sizeof(long));
    manager->keys = (int*)malloc(capacity * sizeof(int));
    manager->records = (record**)malloc(capacity * sizeof(record*));

    // Initialize records with random values
    for(size_t i = 0; i < capacity; i++) {
        record *r = (record*)malloc(sizeof(record));
        r->value = rand() % 100;
        manager->records[i] = r;
    }

    manager->size = capacity;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

// Function to free the memory manager
void free_memory_manager(memory_manager *manager) {
    for(size_t i = 0; i < manager->size; i++) {
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

// Function to allocate a record
record* alloc_record(memory_manager *manager) {
    // Check if the manager has space left before allocating
    for(size_t i = 0; i < manager->size; i++) {
        if(manager->records[i] == NULL) {
            return manager->records[i];
        }
    }

    // If no space is available, resize the memory manager and allocate new record
    size_t newSize = manager->size * 2;
    memory_manager* resizedManager = (memory_manager*)malloc(sizeof(memory_manager));
    resizedManager->offsets = (long*)realloc(manager->offsets, newSize * sizeof(long));
    resizedManager->keys = (int*)realloc(manager->keys, newSize * sizeof(int));
    resizedManager->records = (record**)realloc(manager->records, newSize * sizeof(record*));

    for(size_t i = manager->size; i < newSize; i++) {
        record *r = (record*)malloc(sizeof(record));
        r->value = rand() % 100;
        resizedManager->records[i] = r;
    }

    resizedManager->size = newSize;
    pthread_mutex_init(&resizedManager->mutex, NULL);
    free_memory_manager(manager);
    return resizedManager->records[newSize - 1];
}

// Function to deallocate a record
void dealloc_record(record* record) {
    // Deallocate the record and its data
    if(record != NULL) {
        free(record);
    }
}
