    return 0;
}

void freeMemory() {
    if(records != NULL) {
        free(records);
    }
    if(offsets != NULL) {
        free(offsets);
    }
}

int verifyDataStructure() {
    for(int i = 0; i < numRecords; i++) {
        if(records[i].key < 1 || records[i].key > 1000) {
            printf("Error: record key out of range.\n");
            return -1;
        }
    }
    return 0;
}

void* handleMemoryFailure() {
    if(records != NULL) {
        free(records);
    }
    if(offsets != NULL) {
        free(offsets);
    }
    return NULL;
}

record* processRecords(int numThreads, int totalRecords) {
