        resizeRecordArray(numRecords + 500);
        numRecords += 500;
    }

    // Set record values
    setRecordValues();

    // Verify data structure integrity
    int errCode = verifyDataStructure();
    if(errCode < 0) {
        handleMemoryFailure();
        return NULL;
    }

    // Release memory
    freeMemory();

