#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum {
    ADD,
    SUBTRACT,
    MULTIPLY,
    DIVIDE
} operation;

typedef struct node {
    int value;
    struct node* next;
    operation op;
} node;

typedef struct event {
    time_t timestamp;
    char* description;
    node* target_node;
} event;

node* create_node(int val, operation op) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    new_node->value = val;
    new_node->next = NULL;
    new_node->op = op;
    return new_node;
}

event* create_event(time_t timestamp, char* desc, node* target_node) {
    event* new_event = (event*)malloc(sizeof(event));
    if (!new_event) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    new_event->timestamp = timestamp;
    new_event->description = desc;
    new_event->target_node = target_node;
    return new_event;
}

void log_events(node* head, char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        printf("File opening failed.\n");
        return;
    }

    node* current = head;
    while (current) {
        event* current_event = create_event(time(NULL), "Event description", current);

        // write to file
        fprintf(file, "%lu - %s\n", current_event->timestamp, current_event->description);

        free(current_event);
        current = current->next;
    }

    fclose(file);
}

void set_operation_commands(node** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        node* current_node = nodes[i];
        current_node->op.command = 'A' + i % 4;
    }
}

node* link_nodes(node** nodes, int num_nodes) {
    node* head = nodes[0];

    for (int i = 1; i < num_nodes; i++) {
        nodes[i]->next = nodes[i - 1]->next ? nodes[i - 1]->next : NULL;
        if (!nodes[i]->next) break;
        nodes[i] = nodes[i]->next;
    }

    return head;
}

int main() {
    int num_nodes = 5;

    node* nodes[num_nodes];
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = create_node(i, (operation)(i % 4));
    }

    set_operation_commands(nodes, num_nodes);

    node* head = link_nodes(nodes, num_nodes);

    log_events(head, "log.txt");

    // clean up
    for (int i = 0; i < num_nodes; i++) {
        free(nodes[i]);
    }

    return 0;
}
