#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_VALUE 10000
#define LOGGING_LEVEL 1

typedef struct {
    int key;
    int value;
} Record;

Record* records = NULL;
int num_records = 0;
int max_value = -1;
int min_value = INT_MAX;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(int level, const char* message) {
    if (level <= LOGGING_LEVEL) {
        printf("Log: %s\n", message);
    }
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && size > 0) {
        log_message(1, "Out of memory");
        // Clean up partially allocated resources
        free(ptr);
        return NULL;
    }
    return ptr;
}

void resize_records_array() {
    int new_capacity = num_records * 2 + 1;
    Record* new_records = (Record*) allocate_memory(new_capacity * sizeof(Record));
    if (!new_records) {
        log_message(1, "Out of memory");
        return;
    }
    memcpy(new_records, records, num_records * sizeof(Record));
    free(records);
    records = new_records;
}

void add_record(int key, int value) {
    pthread_mutex_lock(&lock);
    if (num_records >= MAX_RECORDS) {
        log_message(1, "Maximum number of records reached");
        pthread_mutex_unlock(&lock);
        return;
    }
    Record* record = &records[num_records++];
    record->key = key;
    record->value = value;
    max_value = fmax(max_value, value);
    min_value = fmin(min_value, value);
    pthread_mutex_unlock(&lock);
}

void delete_record(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            Record* record_to_delete = &records[i];
            memmove(&records[i], &records[i + 1], (num_records - i - 1) * sizeof(Record));
            free(record_to_delete);
            num_records--;
            max_value = fmax(max_value, records[i].value);
            min_value = fmin(min_value, records[i].value);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

int get_max_value() {
    return max_value;
}

int get_min_value() {
    return min_value;
}

void init_records(int range_start, int range_end) {
    records = (Record*) allocate_memory(MAX_RECORDS * sizeof(Record));
    if (!records) {
        log_message(1, "Out of memory");
        return;
    }
    num_records = 0;
    max_value = -1;
    min_value = INT_MAX;
    for (int i = range_start; i <= range_end; i++) {
        add_record(i, rand() % MAX_VALUE);
    }
}

void* thread_function(void* arg) {
    // Simulate concurrent access
    int num_iterations = 1000;
    for (int i = 0; i < num_iterations; i++) {
        int key = rand() % range_end + 1;
        add_record(key, rand() % MAX_VALUE);
        delete_record(key);
    }
    return NULL;
}

int main() {
    init_records(1, 100);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
