typedef struct record {
    int key;
    int value;
    struct record* prev;
    struct record* next;
} record;

record* create_record(int key, int value) {
    record* new_rec = (record*)malloc(sizeof(record));
    new_rec->key = key;
    new_rec->value = value;
    new_rec->prev = NULL;
    new_rec->next = NULL;
    return new_rec;
}

void free_records(record* head) {
    record* curr = head;
    while (curr != NULL) {
        record* next = curr->next;
        free(curr);
        curr = next;
    }
}

int main() {
    int max_elements = 10000; // default value
    int custom_seeding_value;
    int largest_integer = INT_MIN;

    FILE* file;
    file = fopen("input.txt", "r"); // open the input file

    if (file == NULL) {
        printf("Error opening file.\n");
        return -1;
    }

    record* head = NULL; // initialize linked list
    int key_count[1000] = {0}; // initialize key count array
    srand(custom_seeding_value); // seed the pseudo-random number generator

    int num_elements = 0;

    while (fscanf(file, "%d", &largest_integer) > 0 && num_elements < max_elements) {
        record* new_rec = create_record(largest_integer % 1000, rand() % 100);
        if (head == NULL || largest_integer > head->key) {
            // insert at the front of the linked list
            new_rec->next = head;
            if (head != NULL) head->prev = new_rec;
            head = new_rec;
        } else {
            record* curr = head;
            while (curr->next != NULL && largest_integer <= curr->next->key) {
                curr = curr->next;
            }
            new_rec->next = curr->next;
            if (new_rec->next != NULL) new_rec->next->prev = new_rec;
            new_rec->prev = curr;
            curr->next = new_rec;
        }
        key_count[largest_integer % 1000]++;
        num_elements++;
    }

    fclose(file);

    printf("Max integer: %d\n", largest_integer);
    return 0;
}
