// Define a structure for the BST node
typedef struct {
    long offset;
    float pressure;
    int event_type;
    struct node* left;
    struct node* right;
} Node;

// Function to create and initialize the BST
Node* create_BST(int size) {
    // Seed the pseudo-random number generator
    srand(time(NULL));

    // Initialize the root of the BST
    Node* root = NULL;

    for (int i = 0; i < size; i++) {
        Node* node = malloc(sizeof(Node));
        node->offset = rand() % 100000;
        node->pressure = rand() / (double)RAND_MAX;
        node->event_type = rand() % 5;

        // Insert the node into the BST
        if (!root) {
            root = node;
        } else {
            Node* current = root;
            while (1) {
                if (node->pressure < current->pressure) {
                    if (!current->left) {
                        current->left = node;
                        break;
                    }
                    current = current->left;
                } else {
                    if (!current->right) {
                        current->right = node;
                        break;
                    }
                    current = current->right;
                }
            }
        }
    }

    return root;
}

// Function to print the largest integer and highest pressure reading
void print_max_min(Node* root, int keys[], float pressures[], int event_types[]) {
    Node* max_node = NULL;
    float max_pressure = 0.0f;

    // Find the node with the maximum offset
    Node* current = root;
    while (1) {
        if (!current->left && !current->right) {
            if (current->pressure > max_pressure) {
                max_node = current;
                max_pressure = current->pressure;
            }
            break;
        } else if (current->right) {
            current = current->right;
        } else {
            current = current->left;
        }
    }

    printf("Largest integer: %d\n", keys[max_node->event_type]);
    printf("Highest pressure reading: %.2f\n", max_pressure);
}

int main() {
    int size = 100; // Input the desired size
    Node* root = create_BST(size);

    long offsets[size];
    int keys[size];
    float pressures[size];
    int event_types[size];

    // Initialize the arrays and store values in them
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % 10;
        pressures[i] = rand() / (double)RAND_MAX;
        event_types[i] = rand() % 5;
    }

    // Print the largest integer and highest pressure reading
    print_max_min(root, keys, pressures, event_types);

    return 0;
}
