// Define node structures for min-heap and doubly linked list
typedef struct {
    int* value;
} number_node;

typedef struct {
    int* value;
    number_node* prev;
    number_node* next;
} value_node;

// Function to read integers from standard input and initialize data structures
int process_input() {
    // Initialize variables
    int num_nodes = 0, i = 0;
    json_object* config_json = NULL;
    FILE* config_file = fopen("config.json", "r");
    if (config_file != NULL) {
        // Parse JSON configuration file
        config_json = json_object_from_file(config_file);
        fclose(config_file);
    }

    // Read integers from standard input
    int num_ints = 0;
    int* ints = NULL;
    while (scanf("%d", &i) == 1) {
        if (num_nodes >= num_ints) {
            num_ints += 10;
            ints = realloc(ints, num_ints * sizeof(int));
        }
        ints[num_nodes] = i;
        num_nodes++;
    }

    // Initialize min-heap and doubly linked list
    number_node* heap = NULL;
    value_node* list = NULL;

    if (num_nodes > 0) {
        // Dynamically allocate memory for arrays
        heap = malloc(num_nodes * sizeof(number_node));
        list = malloc(num_nodes * sizeof(value_node));

        // Initialize nodes and link them to form the doubly linked list
        number_node* prev_heap = &heap[0];
        value_node* prev_list = &list[0];
        for (i = 1; i < num_nodes; i++) {
            prev_heap->next = &heap[i];
            heap[i].prev = prev_heap;
            prev_list->next = &list[i];
            list[i].prev = prev_list;
            prev_heap = &heap[i];
            prev_list = &list[i];
        }

        // Perform min-heap operations to maintain heap properties
        for (i = 0; i < num_nodes; i++) {
            heap[i].value = ints + i;
        }
        number_node* current = &heap[0];
        while (num_nodes > 1) {
            if (json_object_get_int_value(config_json, "min-heap-threshold") != -1 && json_object_get_int_value(config_json, "min-heap-threshold") < num_nodes) {
                // Rebalance the min-heap
                number_node* temp = &heap[0];
                while (temp->next != NULL) {
                    if (json_object_get_int_value(config_json, "min-heap-comparison") == 1) {
                        // Perform a single node heapify-down operation
                        if (temp->value < temp->next->value) {
                            int swap = *temp->value;
                            *temp->value = *temp->next->value;
                            *temp->next->value = swap;
                        }
                    } else {
                        // Perform a double node heapify-down operation
                        if (temp->value > temp->next->value) {
                            int swap = *temp->value;
                            *temp->value = *temp->next->value;
                            *temp->next->value = swap;
                        }
                    }
                }
            }
            current = &heap[0];
            while (current != NULL) {
                if (json_object_get_int_value(config_json, "min-heap-comparison") == 1 && current->value < current->next->value || json_object_get_int_value(config_json, "min-heap-comparison") == -1 && current->value > current->next->value) {
                    // Move the smaller element up the heap
                    int swap = *current->value;
                    *current->value = *current->next->value;
                    *current->next->value = swap;
                }
                if (json_object_get_int_value(config_json, "min-heap-threshold") != -1 && json_object_get_int_value(config_json, "min-heap-threshold") < num_nodes) {
                    break;
                }
                current = current->next;
            }
        }

        // Find the smallest element in the array
        int min_val = INT_MAX;
        for (i = 0; i < num_nodes; i++) {
            if (*heap[i].value < min_val) {
                min_val = *heap[i].value;
            }
        }
        printf("Smallest integer: %d\n", min_val);

        // Free allocated memory
        free(heap);
        free(list);
    }

    // Close JSON file
    json_object_put(config_json);
    return 0;
}
