typedef struct record {
    int data;
    struct record* prev;
    struct record* next;
} record;

record* processImagesAndComputeHashesWithMetadata(char* directoryPath) {
    // Initialize variables
    DIR* dir;
    struct dirent* ent;
    record* head = NULL, *tail = NULL;
    int maxVal = 0, randomSeed = 12345; // Custom user-provided value for seeding pseudo-random number generator

    // Create a doubly linked list to store the records
    record* currentRecord = malloc(sizeof(record));
    currentRecord->data = rand_r(&randomSeed) % 100;
    currentRecord->prev = NULL;
    currentRecord->next = NULL;
    head = tail = currentRecord;

    // Iterate through the directory
    dir = opendir(directoryPath);
    if (dir == NULL) {
        // Handle error
        return NULL;
    }

    while ((ent = readdir(dir)) != NULL) {
        // Check file type and process accordingly
        if (ent->d_type == DT_REG || ent->d_type == DT_DIR) {
            char filePath[1024];
            strcpy(filePath, directoryPath);
            strcat(filePath, "/");
            strcat(filePath, ent->d_name);

            int fd = open(filePath, O_RDONLY);
            if (fd < 0) {
                // Handle error
                continue;
            }

            off_t offset = lseek(fd, 0, SEEK_END);
            char buffer[offset];
            read(fd, buffer, offset);

            // Process the image file
            for (int i = 0; i < offset; i++) {
                if ((buffer[i] >= '0' && buffer[i] <= '9') || (buffer[i] >= 'a' && buffer[i] <= 'z')) {
                    record* newRecord = malloc(sizeof(record));
                    newRecord->data = rand_r(&randomSeed) % 100;
                    newRecord->prev = tail;
                    newRecord->next = NULL;
                    if (tail != NULL) {
                        tail->next = newRecord;
                    } else {
                        head = newRecord;
                    }
                    tail = newRecord;
                }
            }

            close(fd);
        }
    }

    // Free allocated memory and return the largest integer value
    record* current = head;
    while (current != NULL) {
        if (current->data > maxVal) {
            maxVal = current->data;
        }
        current = current->next;
    }
    free(head);

    struct metadata_t {
        int max_val;
        char directory_path[1024];
    } metadata;

    metadata.max_val = maxVal;
    strcpy(metadata.directory_path, directoryPath);
    return &metadata;
}
