void generate_and_populate_records(long numOffsets, long numRecords, long minOffset, long maxOffset) {
    if (numOffsets < 0 || numRecords < 0) {
        printf("Warning: Invalid input. Setting default values.\n");
        numOffsets = 1;
        numRecords = 1;
    }

    if (minOffset > maxOffset) {
        minOffset = 0;
        maxOffset = 0;
