        offsets = (long*)malloc(numOffsets * sizeof(long));
        keys = (int*)malloc(numOffsets * sizeof(int));
        records = (struct record*)malloc(numRecords * RECORD_SIZE);

        // Generate and populate initial offset and key arrays
        for (long i = 0; i < numOffsets; i++) {
            long offset = random_in_range(minOffset, maxOffset);
            int key = random_in_range(0, INT_MAX);
            offsets[i] = offset;
            keys[i] = key;
        }

        // Populate record array with randomly selected offsets and keys
        for (long i = 0; i < numRecords; i++) {
            long new_offset = random_in_range(minOffset, maxOffset);
            int new_key = random_in_range(0, INT_MAX);
            records[i].offset = new_offset;
            records[i].key = new_key;
        }

        // Clean up
        free(offsets);
        free(keys);
    } catch (std::runtime_error& e) {
        printf("Error: %s\n", e.what());
        if (offsets != NULL)
            free(offsets);
        if (keys != NULL)
            free(keys);
        if (records != NULL)
            free(records);
    }
}

long random_in_range(long min, long max) {
    long range = max - min + 1;
    return rand() % range + min;
}
