// Function to generate and populate records with logging
void* generate_and_populate_records_with_logging(int numOffsets, int numRecords, long minOffset, long maxOffset, const char *filename) {
    // Check for invalid input
    if (numOffsets < 0 || numRecords < 0) {
        fprintf(stderr, "Error: Invalid number of offsets or records. Defaulting to zero.\n");
        numOffsets = 0;
        numRecords = 0;
    }

    // Check for maxOffset less than minOffset
    if (maxOffset < minOffset) {
        fprintf(stderr, "Error: Max offset cannot be less than min offset. Setting all offsets to 0.\n");
        maxOffset = 0;
        minOffset = 0;
    }

    // Randomly generate unique filenames
    srand(time(NULL));
    char baseName[255];
    strcpy(baseName, filename);
    int len = strlen(baseName);
    char* newBaseName = (char*)malloc((len + 5) * sizeof(char));
    sprintf(newBaseName, "%s_%012ld", baseName, (long)time(NULL));
    // Convert the original extension to a unique one
    char* newExt = (char*)malloc(9 * sizeof(char));
    strftime(newExt, 9, "%Y%m%d", localtime());
    strcat(newBaseName, ".");
    strcat(newBaseName, newExt);

    // Check for filename length exceeding 255 characters
    if (strlen(newBaseName) > 255) {
        fprintf(stderr, "Error: Filename exceeds maximum length. Truncating to 255 characters.\n");
        char* truncatedNewBaseName = (char*)malloc(256 * sizeof(char));
        strncpy(truncatedNewBaseName, newBaseName, 255);
        truncatedNewBaseName[255] = '\0';
        free(newBaseName);
        free(newExt);
        newBaseName = truncatedNewBaseName;
    }

    // Dynamically allocate memory for arrays
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    int* keys = (int*)malloc(numOffsets * sizeof(int));
    struct record {
        long offset;
        int key;
    }*records = (struct record*)malloc(numRecords * sizeof(struct record));

    // Initialize arrays
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = random_in_range(minOffset, maxOffset);
        keys[i] = rand() % 100; // Generate random key between 0 and 99
    }

    // Fill the second array of records with randomly selected elements from the first arrays
    for (int i = 0; i < numRecords; i++) {
        records[i].offset = offsets[random_in_range(0, numOffsets - 1)];
        records[i].key = keys[random_in_range(0, numOffsets - 1)];
    }

    // Free memory upon failure
    if (numRecords == 0) {
        free(offsets);
        free(keys);
        free(records);
        free(newBaseName);
        free(newExt);
    }

    return newBaseName;
}

// Structure to hold offset and key values
struct record {
    long offset;
    int key;
};
