    Record record;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct ActiveList {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} ActiveList;

typedef struct ArchiveTree {
    Node* root;
    pthread_mutex_t mutex;
} ArchiveTree;

void init_database(ActiveList* active, ArchiveTree* archive) {
    pthread_mutex_init(&active->mutex, NULL);
    active->head = NULL;
    active->tail = NULL;
    pthread_mutex_init(&archive->mutex, NULL);
    archive->root = NULL;
}

int insert_record(ActiveList* active, Record record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record = record;

    pthread_mutex_lock(&active->mutex);

    if (active->head == NULL) {
        active->head = active->tail = new_node;
    } else {
        active->tail->next = new_node;
        new_node->prev = active->tail;
        active->tail = new_node;
    }

    pthread_mutex_unlock(&active->mutex);

    return 0;
}

int retrieve_record(ActiveList* active, int key) {
    Node* current = active->head;

    pthread_mutex_lock(&active->mutex);

    while (current != NULL && current->record.key != key) {
        current = current->next;
    }

    if (current == NULL || current->record.key != key) {
        return -1; // record not found
    }

    pthread_mutex_unlock(&active->mutex);

    return 0;
}

int archive_record(ActiveList* active, ArchiveTree* archive, Record record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record = record;

    pthread_mutex_lock(&archive->mutex);

    if (archive->root == NULL) {
        archive->root = new_node;
    } else {
        // insert into balanced binary search tree
    }

    pthread_mutex_unlock(&archive->mutex);

    return 0;
}

int unarchive_record(ArchiveTree* archive, ActiveList* active, Record record) {
    Node* current = archive->root;

    pthread_mutex_lock(&archive->mutex);

    while (current != NULL && current->record.key != record.key) {
        current = current->next;
    }

    if (current == NULL || current->record.key != record.key) {
        return -1; // record not found
    }

    pthread_mutex_unlock(&archive->mutex);

    // move record from archive to active list

    return 0;
}

int bulk_insert_records(ActiveList* active, Record records[], int count) {
    for (int i = 0; i < count; i++) {
        insert_record(active, records[i]);
    }

    return 0;
}
