    // Allocate memory for offsets array
    long* offsets = (long*)malloc(numRecords * sizeof(long));

    // Allocate memory for keys array
    int* keys = (int*)malloc(numRecords * sizeof(int));

    // Create an array of record structures
    record* records = createRecords(numRecords, 1000);

    free(offsets);
    free(keys);
}

void freeMemory(record* records) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i].value != NULL) {
            free(records[i].value);
        }
    }

    free(records);
}

