    *strings = malloc(sizeof(char*) * (*num_strings = 0));
    *lengths = malloc(sizeof(size_t) * (*num_strings = 0));

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        size_t len = strlen(buffer);
        *strings = realloc(*strings, sizeof(char*) * (*num_strings + 1));
        *lengths = realloc(*lengths, sizeof(size_t) * (*num_strings + 1));

