void insertRecord(Record* newRecord) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->record = newRecord;
    newNode->prev = NULL;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
        tail = newNode;
    } else {
        tail->next = newNode;
        newNode->prev = tail;
        tail = newNode;
    }

