#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_OFFSETS 1000
#define MAX_KEYS 1000
#define MAX_TIMESTAMP 1000
#define MAX_LOG_ENTRIES 10000

typedef struct {
    int timestamp;
    char* user_id;
    int status_code;
} log_entry;

void manage_memory(int num_offsets, int num_keys) {
    // Allocate memory for offsets and keys arrays
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        printf("Error: Unable to allocate memory for offsets.\n");
        return;
    }

    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        printf("Error: Unable to allocate memory for keys.\n");
        return;
    }

    // Initialize pointers
    log_entry** log_entries = NULL;
    int num_log_entries = 0;

    // Main loop for allocating and populating log entries
    while (num_log_entries < MAX_LOG_ENTRIES) {
        int timestamp = rand() % 1000000; // Generate random timestamp within range [0, 1,000,000)
        char* user_id = (char*)malloc(20 * sizeof(char));
        sprintf(user_id, "User_%d", num_log_entries); // Create unique user ID
        int status_code = rand() % 100; // Generate random status code within range [0, 99)

        log_entry* log_entry = (log_entry*)malloc(sizeof(log_entry)); // Allocate memory for the struct
        if (!log_entry) {
            printf("Error: Unable to allocate memory for log entry.\n");
            continue;
        }

        log_entry->timestamp = timestamp; // Set timestamp and other fields
        log_entry->user_id = user_id;
        log_entry->status_code = status_code;

        // Add the new log entry to the array
        log_entries = (log_entry**)realloc(log_entries, ++num_log_entries * sizeof(log_entry*));
        if (!log_entries) {
            printf("Error: Unable to reallocate memory for log entries.\n");
            free(log_entry);
            continue;
        }

        log_entries[num_log_entries - 1] = &log_entry; // Update the pointer
    }

    // Free all allocated memory upon exit
    for (int i = 0; i < num_log_entries; ++i) {
        if (log_entries[i]->user_id) free(log_entries[i]->user_id);
        free(log_entries[i]);
    }
    free(log_entries);

    free(keys);
    free(offsets);
}

int main(int argc, char** argv) {
    int num_offsets = atoi(argv[1]); // Read number of offsets from command-line argument
    int num_keys = atoi(argv[2]); // Read number of keys from command-line argument

    if (num_offsets > MAX_OFFSETS || num_keys > MAX_KEYS) {
        printf("Error: Too many offsets or keys specified.\n");
        return 1;
    }

    manage_memory(num_offsets, num_keys);

    return 0;
}

