typedef struct record {
    int val;
} record;

void processAndStoreRecords(long offset, int range) {
    // Initialize pseudo-random number generator
    srand(time(NULL));

    // Allocate memory for arrays
    long* offsets = (long*)malloc((range + 1) * sizeof(long));
    int* keys = (int*)malloc((range + 1) * sizeof(int));
    record** records = (record**)malloc((range + 1) * sizeof(record*));

    // Initialize data structures
    ConcurrentHashMap<String, String> hashMap;
    LinkedList<record> linkedList;

    // Process records
    for (int i = 0; i <= range; i++) {
        long randomOffset = (long)rand() % offset;
        int randomKey = rand() % range;
        record* record = (record*)malloc(sizeof(record));
        record->val = rand() % range;

        // Compute MD5 hash for key
        unsigned char md5Hash[MD5_DIGEST_LENGTH];
        MD5_CTX mdContext;
        MD5_Init(&mdContext);
        MD5_Update(&mdContext, &randomKey, sizeof(int));
        MD5_Final(mdHash, &mdContext);

        // Store record in hashmap and linked list
        hashMap.put(String.valueOf(randomKey), Hex.encodeHexString(mdHash));
        linkedList.add(record);

        // Handle timeout
        if (/* check for timeout */) {
            free(offsets);
            free(keys);
            free(records);
            return HashMap<String, String>();
        }
    }

    // Release allocated memory
    free(offsets);
    free(keys);
    free(records);

    return hashMap;
}
