} record_t;

record_t **records = NULL;
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

// Initialize the library
void init_library() {
    if (records != NULL) return; // Library already initialized
    records = (record_t **)malloc(sizeof(record_t *));
    log_file = fopen("library.log", "a");
}

// Add a new record to the collection
void add_record(int key, long offset, int *status, int value) {
    pthread_mutex_lock(&lock);
    record_count++;
    records = realloc(records, record_count * sizeof(record_t *));
    records[record_count - 1] = (record_t *)malloc(sizeof(record_t));
    records[record_count - 1]->key = key;
    records[record_count - 1]->offset = offset;
    records[record_count - 1]->status = status;
    records[record_count - 1]->value = value;
    pthread_mutex_unlock(&lock);
}

// Remove a record from the collection
void remove_record(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i]->key == key) {
            free(records[i]);
            memmove(&records[i], &records[i + 1], (record_count - i - 1) * sizeof(record_t *));
            record_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Modify the value of a specific record
void modify_record(int key, int new_value) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i]->key == key) {
            records[i]->value = new_value;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

