#include "random.h"

typedef struct record {
    int key;
    int value;
    struct record* next;
    struct record* prev;
} record;

record* init_record(record* head, int max_size) {
    if (head == NULL) return head;

    for (int i = 0; i < max_size; i++) {
        record* new_node = (record*)malloc(sizeof(record));
        new_node->next = head->next;
        new_node->prev = head;
        head->next = new_node;
        if (i == 0) {
            head = new_node;
        } else {
            new_node->prev->next = new_node;
        }
    }
    return head;
}

void free_record(record* head) {
    record* temp = head;
    while (temp != NULL) {
        record* next_temp = temp->next;
        free(temp);
        temp = next_temp;
    }
}

int find_largest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void print_largest(record* head, int max_size) {
    record* temp = head;
    int largest = INT_MIN;
    for (int i = 0; i < max_size; i++) {
        if (temp->value > largest)
            largest = temp->value;
        temp = temp->next;
    }
    printf("Largest integer: %d\n", largest);
}

