    json_object* min_value_obj = json_object_object_get(config, "min_value");
    json_object* max_value_obj = json_object_object_get(config, "max_value");

    if (max_size_obj == NULL || min_value_obj == NULL || max_value_obj == NULL) {
        print_errors("Incomplete configuration file");
        return 1;
    }

    int config_max_size = json_object_get_int(max_size_obj);
    int config_min_value = json_object_get_int(min_value_obj);
    int config_max_value = json_object_get_int(max_value_obj);

    if (config_max_size <= 0 || config_min_value > config_max_value) {
        print_errors("Invalid configuration values");
        return 1;
    }

    // Initialize random number generator
    srand(config_min_value + (rand() % (config_max_value - config_min_value + 1)));

    // Read integers from standard input
