#include <time.h>
#include <pthread.h>

// Define a struct to represent a record with an int value
typedef struct {
    int value;
} Record;

// Function prototype for initializing and managing memory for dynamic records
Record* init_record_set(int initial_capacity, int min_value, int max_value);
void add_record(Record** record_set, int capacity, int new_value);
void free_record_set(Record** record_set, int capacity);

// Thread-safe mutex for concurrent access to the record set
pthread_mutex_t record_set_mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    // Example usage: Initialize and populate a dynamic record set with 10 initial records
    Record* record_set = init_record_set(10, 0, 100);
    for (int i = 0; i < 5; i++) {
        add_record(&record_set, 10, rand() % (max_value - min_value) + min_value);
    }
    // Print the record set values
    printf("Record Set Values: ");
    for (int i = 0; i < 10; i++) {
        printf("%d ", record_set[i].value);
    }
    printf("\n");

    // Clean up when done
    free_record_set(&record_set, 10);

    return 0;
}

// Initialize and manage memory for a dynamic set of records
Record* init_record_set(int initial_capacity, int min_value, int max_value) {
    Record* record_set = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!record_set) {
        // Handle allocation failure
        return NULL;
    }

    // Initialize each record with a unique random value within the specified range
    for (int i = 0; i < initial_capacity; i++) {
        record_set[i].value = rand() % (max_value - min_value) + min_value;
    }

    return record_set;
}

// Add a new record to the dynamic set with a unique random value within the specified range
void add_record(Record** record_set, int capacity, int new_value) {
    // Lock access to the record set for thread safety
    pthread_mutex_lock(&record_set_mutex);

    // Check if the record set needs to be resized due to growth
    if (capacity <= 0 || (*record_set)[capacity - 1].value != new_value) {
        // Reallocate memory with a larger capacity
        *record_set = (Record*)realloc(*record_set, (capacity + 1) * sizeof(Record));
        if (!*record_set) {
            // Handle allocation failure
            pthread_mutex_unlock(&record_set_mutex);
            return;
        }
    }

    (*record_set)[capacity].value = new_value;
    capacity++;

    // Unlock access to the record set for thread safety
    pthread_mutex_unlock(&record_set_mutex);
}

// Free memory resources allocated by the dynamic record set
void free_record_set(Record** record_set, int capacity) {
    if (*record_set) {
        free(*record_set);
        *record_set = NULL;
    }
}
