record* generateRandomRecordsAndStateList(int* states, int countStates, int* fsa, int start, int last) {
    // Initialize memory for arrays
    record* records = (record*)malloc(sizeof(record) * 100);
    if (!records) return NULL;

    long* offsets = (long*)malloc(sizeof(long) * 100);
    if (!offsets) {
        free(records);
        return NULL;
    }

    int* keys = (int*)malloc(sizeof(int) * 100);
    if (!keys) {
        free(records);
        free(offsets);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < 100; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
    }

    // Initialize record structures
    for (int i = 0; i < 100; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    int* stateList = NULL;
    int stateCount = 0;

    // Traverse FSA to find state list from start to last
    for (int i = start; i <= last; i++) {
        if (!fsa[i]) break; // End of valid state list
        if (stateCount >= 100) {
            // Reallocate memory for state list if it grows too large
            int* temp = (int*)realloc(stateList, sizeof(int) * (stateCount + 1));
            if (!temp) return NULL;
            stateList = temp;
        }
        stateList[stateCount++] = i;
    }

    // Ensure 'next' pointer of last state in list points to state list
    if (stateCount > 0) {
        fsa[stateList[stateCount - 1]] = stateList;
    }

    return records;
}
