#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int type;
    char description[256];
} Event;

typedef struct {
    pthread_mutex_t lock;
    unsigned long long size;
    Event **events;
} HashTable;

HashTable *create_hash_table(int size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->size = size;
    table->events = (Event **)calloc(size, sizeof(Event *));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_event(HashTable *table, int timestamp, int type) {
    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < table->size; i++) {
        if (!table->events[i]) {
            Event *event = (Event *)malloc(sizeof(Event));
            event->timestamp = timestamp;
            event->type = type;
            sprintf(event->description, "Event %d: Type %d at time %d", i, type, timestamp);
            table->events[i] = event;
            break;
        }
    }
    pthread_mutex_unlock(&table->lock);
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < table->size; i++) {
        if (table->events[i]) {
            free(table->events[i]);
        }
    }
    free(table->events);
    free(table);
}

