#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for key-value pairs
typedef struct {
    char* key;
    int value;
} Pair;

// Define a structure for the hash table
typedef struct {
    int size;
    int capacity;
    Pair** buckets;
    int numPairs;
    pthread_mutex_t lock;
} HashTable;

// Function to create a new hash table with a given size
HashTable* createHashTable(int size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->capacity = size * 2;
    ht->buckets = (Pair**)malloc(ht->capacity * sizeof(Pair*));
    for (int i = 0; i < ht->capacity; i++) {
        ht->buckets[i] = NULL;
    }
    ht->numPairs = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

// Function to insert a new key-value pair into the hash table
int insertPair(HashTable* ht, char* key, int value) {
    int index = hashFunction(key, ht->size);
    Pair* pair = (Pair*)malloc(sizeof(Pair));
    pair->key = strdup(key);
    pair->value = value;

    if (!ht->buckets[index]) {
        pthread_mutex_lock(&ht->lock);
        ht->buckets[index] = pair;
        pthread_mutex_unlock(&ht->lock);
    } else {
        // Handle collision
        Pair* current = ht->buckets[index];
        while (current) {
            if (strcmp(current->key, key) == 0) {
                free(current->key);
                free(pair);
                return -1; // Key already exists
            }
            current = ((Pair*)current)->next;
        }

        pair->next = ht->buckets[index];
        pthread_mutex_lock(&ht->lock);
        ht->buckets[index] = pair;
        pthread_mutex_unlock(&ht->lock);
    }

    return 0; // Insertion successful
}

// Function to resize the hash table
void resizeHashTable(HashTable* ht, int newSize) {
    HashTable* newHt = createHashTable(newSize);
    for (int i = 0; i < ht->capacity; i++) {
        Pair* current = ht->buckets[i];
        while (current) {
            insertPair(newHt, current->key, current->value);
            current = ((Pair*)current)->next;
        }
    }

    // Free old memory
    for (int i = 0; i < ht->capacity; i++) {
        Pair* current = ht->buckets[i];
        while (current) {
            Pair* next = ((Pair*)current)->next;
            free(current->key);
            free(current);
            current = next;
        }
    }

    pthread_mutex_destroy(&ht->lock);
    free(ht->buckets);
    free(ht);
    *ht = *newHt;
}

// Function to hash a key
int hashFunction(char* key, int size) {
    int sum = 0;
    for (int i = 0; i < strlen(key); i++) {
        sum += key[i];
    }
    return sum % size;
}

// Function to print the contents of the hash table
void printHashTable(HashTable* ht) {
    printf("Hash Table Contents:\n");
    for (int i = 0; i < ht->capacity; i++) {
        Pair* current = ht->buckets[i];
        while (current) {
            printf("(%s, %d)\n", current->key, current->value);
            current = ((Pair*)current)->next;
        }
    }
}

// Function to free the memory allocated by the hash table
void freeHashTable(HashTable* ht) {
    for (int i = 0; i < ht->capacity; i++) {
        Pair* current = ht->buckets[i];
        while (current) {
            Pair* next = ((Pair*)current)->next;
            free(current->key);
            free(current);
            current = next;
        }
    }

    pthread_mutex_destroy(&ht->lock);
    free(ht->buckets);
    free(ht);
}

int main() {
    int size = atoi(getenv("SIZE"));
    HashTable* ht = createHashTable(size);

    // Initialize random number generator
    srand(time(NULL));

    // Insert key-value pairs into the hash table
    for (int i = 0; i < 10; i++) {
        char* key = (char*)malloc((strlen("key") + 1) * sizeof(char));
        int value = rand() % 100;
        strcpy(key, "key");
        insertPair(ht, key, value);
    }

    // Print the contents of the hash table
    printHashTable(ht);

    // Free memory allocated by the hash table
    freeHashTable(ht);

    return 0;
}
