void process_ips(int num_ips, ip_entry *ips) {
    // Initialize a doubly linked list to store records
    record *head = NULL;
    record *tail = NULL;

    for (int i = 0; i < num_ips; i++) {
        ip_entry current_ip = ips[i];
        // Allocate memory for the record and initialize its fields
        record *new_record = (record *)malloc(sizeof(record));
        new_record->value = rand() % 1000;
        new_record->metadata = "Metadata";
        new_record->timestamp = time(NULL);
        new_record->next = NULL;

        if (head == NULL) {
            head = tail = new_record;
        } else {
            tail->next = new_record;
            tail = new_record;
        }

        // Perform reverse DNS resolution
        char *hostname = get_hostname(current_ip.original_ip);
        strcpy(new_record->metadata, hostname);

        free(hostname);
    }

    // Find and print the IP with the highest TTL value
    ip_entry *ip_with_highest_ttl = NULL;
    int highest_ttl = 0;

    record *current = head;
    while (current != NULL) {
        if (current->last_known_ttl > highest_ttl) {
            highest_ttl = current->last_known_ttl;
            ip_with_highest_ttl = &current->original_ip;
        }
        current = current->next;
    }

    printf("IP with the highest TTL: %s, TTL value: %d\n", ip_with_highest_ttl.original_ip, highest_ttl);

    // Free memory allocated for records
    while (head != NULL) {
        record *temp = head;
        head = head->next;
        free(temp);
    }
}

