DynamicArray* dynamic_array_create(int initial_size) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->data = (void**)calloc(initial_size, sizeof(void*));
    arr->capacity = initial_size;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
