typedef struct record {
    int value;
    struct record* prev;
    struct record* next;
} record;

record* create_record(int value) {
    record* new_rec = (record*)malloc(sizeof(record));
    new_rec->value = value;
    new_rec->prev = NULL;
    new_rec->next = NULL;
    return new_rec;
}

void free_records(record* head) {
    record* temp = head;
    while (temp != NULL) {
        record* next = temp->next;
        free(temp);
        temp = next;
    }
}

int main() {
    int size;
    printf("Enter the size of the array: ");
    scanf("%d", &size);

    if (size <= 0) {
        printf("Invalid size. Exiting...\n");
        return -1;
    }

    record* records = NULL;

    // Allocate memory for arrays
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));

    srand(time(NULL));  // Seed random number generator

    for (int i = 0; i < size; i++) {
        records = create_record(rand() % 100); // Initialize record values
        // Initialize offset and key arrays
        offsets[i] = i;
        keys[i] = rand() % 10;

        if (i > 0) {
            records->prev = &records[(i - 1)];
            records[(i - 1)].next = records;
        }

        records = records->next; // Update record pointer
    }

    free_records(records);  // Free allocated memory

    return 0;
}
