#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_PACKETS 1024
#define MAX_PACKET_SIZE 2048
#define MAX_THREADS 16

typedef struct {
    char buffer[MAX_PACKET_SIZE];
    int timestamp;
    uint8_t flags;
} packet_info;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore;
int packet_count = 0;
int unique_types = 0;
int total_size = 0;

void* enqueue_packet(void* arg) {
    struct sockaddr_in remote;
    socklen_t remote_len = sizeof(remote);
    int socket_fd = *(int*)arg;

    while (1) {
        packet_info packet;
        memset(&packet, 0, sizeof(packet));

        if (recvfrom(socket_fd, packet.buffer, MAX_PACKET_SIZE - 1, 0, (struct sockaddr*)&remote, &remote_len) <= 0) {
            break;
        }

        pthread_mutex_lock(&mutex);
        packet.timestamp = time(NULL);
        sem_post(&semaphore);
        pthread_mutex_unlock(&mutex);
    }

    close(socket_fd);
    free(arg);
    return NULL;
}

int main() {
    int socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("Socket creation failed");
        return -1;
    }

    struct sockaddr_in local;
    local.sin_family = AF_INET;
    local.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &local.sin_addr);

    if (bind(socket_fd, (struct sockaddr*)&local, sizeof(local)) < 0) {
        perror("Binding failed");
        return -2;
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        int* socket_arg = malloc(sizeof(int));
        *socket_arg = socket_fd;
        if (pthread_create(&threads[i], NULL, enqueue_packet, socket_arg) != 0) {
            perror("Thread creation failed");
            return -3;
        }
    }

    sem_init(&semaphore, 0, 0);

    while (1) {
        sem_wait(&semaphore);
        packet_info* packets = malloc(sizeof(packet_info) * MAX_PACKETS);
        int packet_index = 0;

        pthread_mutex_lock(&mutex);
        for (int i = 0; i < packet_count; i++) {
            packet_info* packet = &packets[packet_index++];
            packet->timestamp = total_size++;
            sem_post(&semaphore);
        }
        packet_info* packet = &packets[packet_index++];
        packet->flags |= 1;
        total_size++;

        pthread_mutex_unlock(&mutex);

        for (int i = 0; i < packet_index; i++) {
            // validate packet integrity and log errors or warnings
            printf("Packet %d: flags=%02x, timestamp=%d\n", i, packets[i].flags, packets[i].timestamp);
        }

        free(packets);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
