#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char file_name[256];
    char path[1024];
    time_t modification_time;
    size_t file_size;
} file_metadata;

file_metadata* process_file_paths(FILE* input) {
    // Initialize the pseudo-random number generator
    srand(time(NULL));

    // Initialize the cache
    int cache_size = 1000; // Default cache size
    file_metadata** cache = (file_metadata**)calloc(cache_size, sizeof(file_metadata*));
    int cache_count = 0;

    // Initialize the metadata array
    int capacity = 100; // Default capacity
    file_metadata* metadata = (file_metadata*)calloc(capacity, sizeof(file_metadata));
    int count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), input)) {
        // Parse the file path and extract the name and size
        char* token = strtok(line, "/ ");
        if (!token) continue;
        strcpy(metadata[count].file_name, token);
        token = strtok(NULL, " /");
        if (token) {
            strcpy(metadata[count].path, token);
            metadata[count].modification_time = time(NULL); // Initialize with current time
            metadata[count].file_size = rand() % 1024 * 1024 + 1; // Random file size between 1-1MB
            count++;
            if (count >= capacity) {
                capacity *= 2;
                file_metadata* new_metadata = (file_metadata*)realloc(metadata, capacity * sizeof(file_metadata));
                metadata = new_metadata;
            }
        }
    }

    // Cache the frequently accessed files
    for (int i = 0; i < count; i++) {
        cache[cache_count++] = &metadata[i];
        if (cache_count >= cache_size) {
            // Evict least recently used item from cache
            int evicted_index = -1;
            time_t max_time = 0;
            for (int j = 0; j < cache_count; j++) {
                if (cache[j]->modification_time > max_time) {
                    max_time = cache[j]->modification_time;
                    evicted_index = j;
                }
            }
            for (int k = evicted_index; k < cache_count - 1; k++) {
                cache[k] = cache[k + 1];
            }
            cache_count--;
        }
    }

    // Partially update the metadata
    for (int i = 0; i < count; i++) {
        if (rand() % 2) { // 50% chance to modify the file size
            metadata[i].file_size = rand() % 1024 * 1024 + 1;
        }
    }

    // Export the metadata to a CSV file
    FILE* output = fopen("output.csv", "w");
    if (output) {
        for (int i = 0; i < count; i++) {
            fprintf(output, "%s,%s,%lu,%zu\n", metadata[i].file_name, metadata[i].path, metadata[i].modification_time, metadata[i].file_size);
        }
        fclose(output);
    } else {
        printf("Error writing to output.csv\n");
    }

    // Free the memory
    for (int i = 0; i < count; i++) {
        free(metadata[i].file_name);
        free(metadata[i].path);
    }
    free(metadata);
    for (int i = 0; i < cache_count; i++) {
        free(cache[i]->file_name);
        free(cache[i]->path);
    }
    free(cache);

    return NULL;
}

int main() {
    FILE* input = fopen("input.txt", "r");
    process_file_paths(input);
    fclose(input);
    return 0;
}
