#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct file_info {
    char* filename;
    time_t last_modified;
    long file_size;
} file_info;

typedef struct node {
    file_info* info;
    struct node* prev;
    struct node* next;
} node;

void print_largest_file_size(node* head) {
    node* current = head;
    long largest = 0;

    while (current != NULL) {
        if (current->info->file_size > largest) {
            largest = current->info->file_size;
        }
        current = current->next;
    }

    printf("Largest file size: %ld bytes\n", largest);
}

void process_file_paths() {
    node* head = NULL;
    node* tail = NULL;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), stdin) != NULL) {
        file_info* info = (file_info*)malloc(sizeof(file_info));
        if (info == NULL) {
            printf("Memory allocation failed\n");
            return;
        }

        info->filename = malloc(strlen(buffer) + 1);
        strcpy(info->filename, buffer);

        // retrieve file metadata and populate 'info' fields
        time_t last_modified = get_file_last_modified(buffer);
        long file_size = get_file_size(buffer);

        info->last_modified = last_modified;
        info->file_size = file_size;

        node* new_node = (node*)malloc(sizeof(node));
        if (new_node == NULL) {
            printf("Memory allocation failed\n");
            return;
        }

        new_node->info = info;
        new_node->prev = tail;
        new_node->next = NULL;

        if (tail != NULL) {
            tail->next = new_node;
        } else {
            head = new_node;
        }

        tail = new_node;
    }

    // check for duplicate file names
    node* current = head;
    while (current != NULL) {
        node* temp = current;
        while (temp->next != NULL) {
            if (strcmp(temp->info->filename, temp->next->info->filename) == 0) {
                printf("Duplicate file name: %s\n", temp->info->filename);
            }
            temp = temp->next;
        }
        current = current->next;
    }

    // find and print the largest file size
    print_largest_file_size(head);

    // free all allocated memory
    node* current = head;
    while (current != NULL) {
        node* next = current->next;
        free(current->info->filename);
        free(current->info);
        free(current);
        current = next;
    }
}

int main() {
    process_file_paths();
    return 0;
}
