#define WRITE_LOCK_TIMEOUT 1

typedef struct {
    int key;
    int value;
    char* meta_string;
} record;

record** records = NULL;
int num_records = 0;

pthread_mutex_t write_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t read_lock = PTHREAD_RWLOCK_INITIALIZER;
pthread_cond_t cache_ready = PTHREAD_COND_INITIALIZER;

void* allocate_record(int key, int value) {
    record* new_record = (record*)malloc(sizeof(record));
    new_record->key = key;
    new_record->value = value;
    return new_record;
}

int insert_record(int key, int value) {
    pthread_mutex_lock(&write_lock);
    record* new_record = allocate_record(key, value);
    records[num_records] = new_record;
    num_records++;
    pthread_cond_signal(&cache_ready);
    pthread_mutex_unlock(&write_lock);
    return 0;
}

int delete_record(int key) {
    pthread_rwlock_wrlock(&read_lock);
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key) {
            free(records[i]);
            memmove(&records[i], &records[i + 1], (num_records - i - 1) * sizeof(record*));
            num_records--;
            break;
        }
    }
    pthread_rwlock_unlock(&read_lock);
    return 0;
}

record* find_record(int key) {
    pthread_rwlock_rdlock(&read_lock);
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key) {
            record* found_record = records[i];
            pthread_rwlock_unlock(&read_lock);
            return found_record;
        }
    }
    pthread_rwlock_unlock(&read_lock);
    return NULL;
}

void cache_records() {
    for (int i = 0; i < num_records && i < CACHE_SIZE; i++) {
        record* cached_record = find_record(i);
        if (!cached_record) break;
        // cache the record
    }
}
