use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use rand::Rng;

struct Record {
    key: u32,
    value: u32,
    meta: Option<(String, Box<dyn Any + Send>)>,
}

fn init_rng(seed: u32) -> Rng {
    let mut rng = rand::thread_rng();
    rng.setSeed(seed);
    rng
}

fn create_records(num_records: u32, min_value: u32, max_value: u32) -> Vec<Record> {
    (0..num_records).map(|_| {
        let key = init_rng(42).gen::<u32>();
        let value = init_rng(42).gen_range(min_value, max_value);
        let meta = Some(("some_meta".to_string(), Box::new("some_data")));
        Record { key, value, meta }
    }).collect()
}

fn main() {
    // Initialize the RNG with a custom seed
    let mut rng = init_rng(42);

    // Create a variable number of 'record' structures
    let num_records = 50_000_000;
    let min_value = 1;
    let max_value = 1000;
    let records = create_records(num_records, min_value, max_value);

    // Initialize the hash table and cache
    let mut hash_table = HashMap::new();
    let cache = Arc::new(Mutex::new(HashMap::new()));

    // Handle concurrent read and write operations
    for record in &records {
        // Lock the cache to prevent concurrent access
        let mut cache_guard = (cache.lock().unwrap()).entry(record.key);
        *cache_guard = Some(record.clone());
        // Simulate a write operation
        if rng.gen::<f32>() < 0.5 {
            *cache_guard = None;
        }
    }

    // Perform read operations and check the cache hit ratio
    let mut hits = 0;
    for record in &records {
        // Check the cache before performing a read
        match (cache.lock().unwrap()).get(&record.key) {
            Some(record_cache) => {
                println!("Cache hit! Record key: {}, value: {}", record.key, record_cache.value);
                hits += 1;
            }
            None => {
                println!("Cache miss. Record key: {}, value: {}", record.key, record.value);
            }
        }
    }

    // Calculate the cache hit ratio
    let cache_hit_ratio = (hits as f64) / records.len() as f64;
    println!("Cache hit ratio: {:.2}", cache_hit_ratio);
}
