// Define a record structure
typedef struct {
    int key;
    int value;
} Record;

// Define a node for the doubly linked list
typedef struct Node {
    Record* record;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to read integers from standard input and create arrays of long offset values, int keys, and records
void process_integers() {
    // Initialize variables
    int num_records = 0;
    int max_value = 0;

    // Read the number of records
    scanf("%d", &num_records);

    // Allocate memory for the arrays and linked list
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    Node* head = NULL;
    Node* tail = NULL;

    // Read integers from standard input and create records
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        Record record;
        record.key = rand() % 100 + 1; // Random key within the range [1, 100]
        record.value = rand() % 1000 + 1; // Random value within the range [1, 1000]

        offsets[i] = (long)record.value; // Store the record's value as a long offset
        keys[i] = record.key; // Store the record's key

        Node* node = (Node*)malloc(sizeof(Node));
        node->record = &record;
        node->prev = NULL;
        node->next = NULL;

        if (head == NULL) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    // Find and print the largest integer in the array
    int max_integer = 0;
    for (int i = 0; i < num_records; i++) {
        if (keys[i] > max_integer) {
            max_integer = keys[i];
        }
    }
    printf("Largest integer: %d\n", max_integer);

    // Serialize the data structure to a file
    FILE* file = fopen("data.txt", "wb");
    if (file == NULL) {
        // Handle error
    } else {
        Node* current = head;
        while (current != NULL) {
            fwrite(&current->record, sizeof(Record), 1, file);
            current = current->next;
        }
        fclose(file);
    }

    // Verify the integrity of the serialized data after deserialization
    FILE* file2 = fopen("data.txt", "rb");
    if (file2 == NULL) {
        // Handle error
    } else {
        Record record;
        while (fread(&record, sizeof(Record), 1, file2) == 1) {
            printf("%d %d\n", record.key, record.value);
        }
        fclose(file2);
    }

    // Deallocate memory
    free(offsets);
    free(keys);
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    process_integers();
    return 0;
}
