#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    char* word;
    int count;
} string_entry;

typedef struct node {
    char* value;
    struct node* left;
    struct node* right;
} node_t;

node_t* create_node(char* value) {
    node_t* node = (node_t*)malloc(sizeof(node_t));
    node->value = (char*)malloc(strlen(value)+1);
    strcpy(node->value, value);
    node->left = NULL;
    node->right = NULL;
    return node;
}

void free_node(node_t* node) {
    if(node == NULL)
        return;
    free(node->value);
    free(node);
}

void destroy_tree(node_t* root) {
    if(root == NULL)
        return;
    destroy_tree(root->left);
    destroy_tree(root->right);
    free_node(root);
}

node_t* insert_node(node_t* root, char* value) {
    if(root == NULL) {
        node_t* new_node = create_node(value);
        return new_node;
    }
    if(strcmp(value, root->value) < 0)
        root->left = insert_node(root->left, value);
    else if(strcmp(value, root->value) > 0)
        root->right = insert_node(root->right, value);
    return root;
}

node_t* find_longest_word(node_t* root) {
    node_t* longest = root;
    while(longest->right != NULL)
        longest = longest->right;
    return longest;
}

void print_tree(node_t* root) {
    if(root == NULL)
        return;
    print_tree(root->left);
    printf("%s\n", root->value);
    print_tree(root->right);
}

int main() {
    json_object* config = json_object_from_file("config.json");
    if(config == NULL) {
        printf("Error parsing configuration file.\n");
        return 1;
    }

    int table_size = json_object_get_int(config, "hash_table_size");
    double load_factor = json_object_get_double(config, "load_factor");
    int tree_balance_threshold = json_object_get_int(config, "tree_balance_threshold");

    node_t* root = NULL;

    char* line = NULL;
    size_t len = 0;
    FILE* file = fopen("input.txt", "r");
    if(file == NULL) {
        printf("Error opening input file.\n");
        return 1;
    }
    while(fgets(line, &len, file)) {
        // Parse string and insert into tree
        root = insert_node(root, line);
    }
    fclose(file);

    node_t* longest_word = find_longest_word(root);
    printf("Longest word: %s\n", longest_word->value);

    print_tree(root);

    destroy_tree(root);

    return 0;
}
