// Define a struct to represent user-defined objects
typedef struct {
    char* str;
    int val;
} Object;

// Define a struct to represent the hash table
typedef struct {
    size_t capacity;
    size_t size;
    Object** arr;
    pthread_mutex_t mutex;
} HashTable;

// Function to initialize the hash table with a specified capacity and seed the PRNG
HashTable* init_hash_table(size_t cap, unsigned int seed) {
    HashTable* ht = (HashTable*) malloc(sizeof(HashTable));
    ht->capacity = cap;
    ht->size = 0;
    ht->arr = (Object**)malloc(cap * sizeof(Object*));
    srand(seed);
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

// Function to insert an object into the hash table
void insert_object(HashTable* ht, char* str, int val) {
    size_t index = rand() % ht->capacity;
    while (ht->arr[index] != NULL) {
        index = (index + 1) % ht->capacity;
    }
    Object* obj = (Object*)malloc(sizeof(Object));
    obj->str = strdup(str);
    obj->val = val;
    ht->arr[index] = obj;
    pthread_mutex_lock(&ht->mutex);
    ht->size++;
    pthread_mutex_unlock(&ht->mutex);
}

// Function to remove an object from the hash table
void remove_object(HashTable* ht, char* str) {
    size_t i;
    for (i = 0; i < ht->capacity; i++) {
        if (ht->arr[i] != NULL && strcmp(ht->arr[i]->str, str) == 0) {
            pthread_mutex_lock(&ht->mutex);
            free(ht->arr[i]->str);
            free(ht->arr[i]);
            ht->size--;
            pthread_mutex_unlock(&ht->mutex);
            return;
        }
    }
}

// Function to print the contents of the hash table
void print_hash_table(HashTable* ht) {
    size_t i;
    for (i = 0; i < ht->capacity; i++) {
        if (ht->arr[i] != NULL) {
            printf("%s: %d\n", ht->arr[i]->str, ht->arr[i]->val);
        }
    }
}

int main() {
    // Example usage
    HashTable* ht = init_hash_table(16, 12345);
    insert_object(ht, "Hello", 42);
    insert_object(ht, "World", 21);
    print_hash_table(ht);
    remove_object(ht, "Hello");
    print_hash_table(ht);
    return 0;
}

