#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define MAX_SESSION_DATA 1024

typedef struct Session {
    int id;
    time_t expiration;
    char data[MAX_SESSION_DATA];
} Session;

typedef struct {
    int size;
    Session** sessions;
    pthread_mutex_t mutex;
} SessionTable;

SessionTable* session_table_init() {
    SessionTable* table = (SessionTable*)malloc(sizeof(SessionTable));
    table->size = MAX_SESSIONS;
    table->sessions = (Session**)calloc(MAX_SESSIONS, sizeof(Session*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void session_table_free(SessionTable* table) {
    for (int i = 0; i < table->size; i++) {
        free(table->sessions[i]);
    }
    free(table->sessions);
    free(table);
}

int session_id() {
    static int id = 1;
    return id++;
}

Session* session_new(int id, time_t expiration) {
    Session* session = (Session*)malloc(sizeof(Session));
    session->id = id;
    session->expiration = expiration;
    return session;
}

void session_free(Session* session) {
    free(session);
}

int session_add(SessionTable* table, int id, time_t expiration, char* data) {
    pthread_mutex_lock(&table->mutex);
    for (int i = 0; i < table->size; i++) {
        if (!table->sessions[i]) {
            Session* session = session_new(id, expiration);
            strcpy(session->data, data);
            table->sessions[i] = session;
            break;
        }
    }
    pthread_mutex_unlock(&table->mutex);
    return 0;
}

Session* session_get(SessionTable* table, int id) {
    pthread_mutex_lock(&table->mutex);
    for (int i = 0; i < table->size; i++) {
        if (table->sessions[i] && table->sessions[i]->id == id) {
            Session* session = table->sessions[i];
            pthread_mutex_unlock(&table->mutex);
            return session;
        }
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

int session_expire(SessionTable* table, time_t now) {
    int i;
    for (i = 0; i < table->size; i++) {
        if (table->sessions[i] && table->sessions[i]->expiration <= now) {
            free(table->sessions[i]);
            table->sessions[i] = NULL;
        }
    }
    return 0;
}

int main() {
    SessionTable* table = session_table_init();

    // Example usage:
    int id1 = session_id();
    time_t expiration1 = time(NULL) + 3600; // expire in 1 hour
    char* data1 = "example data";
    session_add(table, id1, expiration1, data1);

    Session* session = session_get(table, id1);
    if (session != NULL) {
        printf("Session %d found: %s\n", id1, session->data);
    } else {
        printf("Session %d not found.\n", id1);
    }

    // Clean up expired sessions
    time_t now = time(NULL);
    session_expire(table, now);

    // Release memory and resources
    session_table_free(table);

    return 0;
}
