// Define the record structure
typedef struct {
    int value;
    struct Record* next;
    struct Record* prev;
} Record;

// Function to initialize a random number generator
void srand_init(int seed) {
    time_t t = time(NULL);
    srand((unsigned int)t + seed);
}

// Function to generate a random integer within a specified range
int rand_int(int min, int max) {
    return (rand() % ((max - min) + 1)) + min;
}

// Function to create a new record with a random value
Record* new_record(int min_value, int max_value) {
    Record* r = (Record*)malloc(sizeof(Record));
    r->value = rand_int(min_value, max_value);
    r->next = NULL;
    r->prev = NULL;
    return r;
}

// Function to insert a record into the doubly linked list
void insert_record(Record** head, Record* new_record) {
    if (*head == NULL || new_record->value < (*head)->value) {
        new_record->next = *head;
        new_record->prev = NULL;
        *head = new_record;
    } else {
        Record* current = *head;
        while (current->next != NULL && current->next->value <= new_record->value) {
            current = current->next;
        }
        new_record->prev = current;
        new_record->next = current->next;
        if (new_record->next == NULL) {
            current->next = new_record;
        } else {
            new_record->next->prev = new_record;
        }
        current->next = new_record;
    }
}

// Function to remove a record from the doubly linked list
void remove_record(Record** head, Record* old_record) {
    if (*head == old_record) {
        *head = old_record->next;
    }
    if (old_record->prev != NULL) {
        old_record->prev->next = old_record->next;
    } else {
        *head = old_record->next;
    }
    if (old_record->next != NULL) {
        old_record->next->prev = old_record->prev;
    }
    free(old_record);
}

// Function to serialize the doubly linked list to a file
void serialize_records(Record* head, FILE* output_file) {
    Record* current = head;
    while (current != NULL) {
        fwrite(&current->value, sizeof(int), 1, output_file);
        current = current->next;
    }
}

// Function to deserialize the doubly linked list from a file
Record* deserialize_records(FILE* input_file) {
    int value;
    Record* head = NULL;
    Record* current = NULL;
    while (fread(&value, sizeof(int), 1, input_file) == 1) {
        Record* new_record = (Record*)malloc(sizeof(Record));
        new_record->value = value;
        if (head == NULL) {
            head = new_record;
            current = new_record;
        } else {
            current->next = new_record;
            new_record->prev = current;
            current = current->next;
        }
    }
    return head;
}

// Function to manage the complex data structure
void* manage_data_structure(void* arg) {
    // Initialize the random number generator
    srand_init(42);

    // Create a new record with a random value
    Record* new_record = new_record(1, 100);
    new_record->value = rand_int(1, 100);

    // Insert the new record into the doubly linked list
    insert_record(&head, new_record);

    // Remove an existing record from the doubly linked list
    remove_record(&head, old_record);

    // Serialize the doubly linked list to a file
    serialize_records(head, output_file);

    // Deserialize the doubly linked list from a file
    Record* deserialized_head = deserialize_records(input_file);

    return NULL;
}

int main() {
    // Initialize the complex data structure
    void* arg = NULL;

    // Create and manage multiple threads for concurrent access
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, &manage_data_structure, arg);
    }

    // Join the threads
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
