typedef struct {
    int key;
    char status; // 0: not processed, 1: processed
    size_t* offset;
} Record;

Record** create_collection(size_t size, unsigned int seed) {
    srand(seed);

    Record** collection = (Record**)malloc(size * sizeof(Record*));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for collection\n");
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        collection[i] = (Record*)malloc(sizeof(Record));
        if (!collection[i]) {
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);
            while (i--) {
                free(collection[i]);
            }
            free(collection);
            return NULL;
        }

        collection[i]->key = rand() % 100; // Initialize key
        collection[i]->status = 0;
        collection[i]->offset = malloc(sizeof(size_t));
        if (!collection[i]->offset) {
            fprintf(stderr, "Memory allocation failed for offset in record %zu\n", i);
            while (i--) {
                free(collection[i]);
            }
            free(collection);
            return NULL;
        }
    }

    return collection;
}

void destroy_collection(Record** collection, size_t size) {
    for (size_t i = 0; i < size; i++) {
        free(collection[i]->offset);
        free(collection[i]);
    }
    free(collection);
}
