#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to represent an item
typedef struct {
    char* name;
    int priority;
} Item;

// Define a structure to represent a node in the linked list
typedef struct Node {
    Item item;
    struct Node* next;
} Node;

// Function to create a new node with the given item
Node* createNode(Item item) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->item.name = item.name;
    newNode->item.priority = item.priority;
    newNode->next = NULL;
    return newNode;
}

// Function to add an item to the end of the list
void addItem(Node** head, Item item) {
    Node* newNode = createNode(item);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to retrieve an item by name
Item* getItemByName(Node* head, char* name) {
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->item.name, name) == 0) {
            return &current->item;
        }
        current = current->next;
    }
    return NULL;
}

// Function to remove an item by name
void removeItemByName(Node** head, char* name) {
    Node* current = *head;
    Node* previous = NULL;
    while (current != NULL) {
        if (strcmp(current->item.name, name) == 0) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to periodically check for and free unused memory
void garbageCollect(Node* head) {
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL) {
        previous = current;
        current = current->next;
    }
    while (previous != NULL) {
        previous = previous->next;
        free(previous);
    }
}

// Function to print the linked list
void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Name: %s, Priority: %d\n", current->item.name, current->item.priority);
        current = current->next;
    }
}

int main() {
    // Create a new linked list
    Node* head = NULL;

    // Add some items to the list
    addItem(&head, (Item){.name = "Item1", .priority = 1});
    addItem(&head, (Item){.name = "Item2", .priority = 2});
    addItem(&head, (Item){.name = "Item3", .priority = 3});

    // Print the list
    printList(head);

    // Retrieve an item by name
    Item* item = getItemByName(head, "Item2");
    if (item != NULL) {
        printf("Retrieved item: Name: %s, Priority: %d\n", item->name, item->priority);
    } else {
        printf("Item not found!\n");
    }

    // Remove an item by name
    removeItemByName(&head, "Item1");

    // Print the updated list
    printList(head);

    // Perform garbage collection
    garbageCollect(head);

    return 0;
}
