    if (!collection) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }
    for (size_t i = 0; i < size; i++) {
        collection[i].key = rand();
        collection[i].status = 0;
        collection[i].offset = -1;
    }
    return collection;
}

void* worker_thread(void* arg) {
    Record** records = (Record**)arg;
    for (size_t i = 0; i < *records; i++) {
        if ((*records)[i]->status == 0) {
            (*records)[i]->status = 1;
        } else {
            (*records)[i]->status = 0;
        }
    }
    return NULL;
}

void manage_collection(size_t size, Record** records) {
    pthread_t thread;
    int ret;

    if (pthread_create(&thread, NULL, worker_thread, &size) != 0) {
        fprintf(stderr, "Error: Unable to create worker thread.\n");
        return;
    }

    for (size_t i = 0; i < size; i++) {
        // Perform some operation on the collection
        printf("Collection at index %lu has key %d and status %d\n", i, records[i]->key, records[i]->status);
    }

    pthread_join(thread, NULL);

    for (size_t i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records);
}
