#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 1000000
#define EXPIRATION_TIME 60 // in seconds

typedef struct {
    int key;
    char* value;
    time_t expirationTime;
} cacheEntry;

typedef struct {
    pthread_mutex_t mutex;
    cacheEntry** entries;
    size_t size;
    time_t lastUpdate;
} cacheManager;

cacheManager* initCache() {
    cacheManager* cm = (cacheManager*)malloc(sizeof(cacheManager));
    cm->size = 0;
    cm->entries = (cacheEntry**)malloc(MAX_CACHE_SIZE * sizeof(cacheEntry*));
    pthread_mutex_init(&cm->mutex, NULL);
    return cm;
}

void put(cacheManager* cm, int key, char* value) {
    pthread_mutex_lock(&cm->mutex);

    // Check if the entry already exists
    for (size_t i = 0; i < cm->size; i++) {
        if (cm->entries[i]->key == key) {
            // Update existing entry
            free(cm->entries[i]->value);
            cm->entries[i]->value = value;
            cm->entries[i]->expirationTime = time(NULL) + EXPIRATION_TIME;
            break;
        }
    }

    // If the entry does not exist, add it to the cache
    if (cm->size >= MAX_CACHE_SIZE) {
        // Evict least recently used entry if the cache is full
        size_t evictedIndex = -1;
        time_t oldestTime = cm->entries[0]->expirationTime;
        for (size_t i = 0; i < cm->size; i++) {
            if (cm->entries[i]->expirationTime < oldestTime) {
                oldestTime = cm->entries[i]->expirationTime;
                evictedIndex = i;
            }
        }
        if (evictedIndex != -1) {
            free(cm->entries[evictedIndex]->value);
            memmove(&cm->entries[evictedIndex], &cm->entries[evictedIndex + 1], (cm->size - evictedIndex - 1) * sizeof(cacheEntry*));
            cm->size--;
        }
    }

    if (cm->size < MAX_CACHE_SIZE) {
        // Add new entry to the cache
        cm->entries[cm->size] = (cacheEntry*)malloc(sizeof(cacheEntry));
        cm->entries[cm->size]->key = key;
        cm->entries[cm->size]->value = value;
        cm->entries[cm->size]->expirationTime = time(NULL) + EXPIRATION_TIME;
        cm->size++;
    }

    pthread_mutex_unlock(&cm->mutex);
}

void get(cacheManager* cm, int key, char** value) {
    pthread_mutex_lock(&cm->mutex);

    for (size_t i = 0; i < cm->size; i++) {
        if (cm->entries[i]->key == key) {
            *value = cm->entries[i]->value;
            break;
        }
    }

    pthread_mutex_unlock(&cm->mutex);
}

void evictOldEntries(cacheManager* cm) {
    pthread_mutex_lock(&cm->mutex);

    for (size_t i = 0; i < cm->size; i++) {
        if (time(NULL) > cm->entries[i]->expirationTime) {
            // Evict stale entry
            free(cm->entries[i]->value);
            memmove(&cm->entries[i], &cm->entries[i + 1], (cm->size - i - 1) * sizeof(cacheEntry*));
            cm->size--;
        }
    }

    pthread_mutex_unlock(&cm->mutex);
}

void updateCacheEntriesFromExternalDataSource(cacheManager* cm) {
    // Asynchronous fetch and update cache entries from external data source
    // ...
}

void closeCache(cacheManager* cm) {
    for (size_t i = 0; i < cm->size; i++) {
        free(cm->entries[i]->value);
    }
    free(cm->entries);
    pthread_mutex_destroy(&cm->mutex);
    free(cm);
}
