#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <rand.h>

// Define structure for sensor
typedef struct {
    float temperature;
    char status;
    time_t timestamp;
} Sensor;

// Define structure for record
typedef struct {
    int value;
} Record;

// Function to dynamically allocate memory and initialize arrays
Sensor* allocate_and_init(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    Record* records = (Record*)malloc(size * sizeof(Record));
    float* temperatures = (float*)malloc(size * sizeof(float));
    Sensor* sensors = (Sensor*)malloc(size * sizeof(Sensor));

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        offsets[i] = i;
        keys[i] = rand() % 100;
        records[i].value = rand() % 100;
        temperatures[i] = (float)rand() / RAND_MAX;
    }

    // Initialize sensors
    for (int i = 0; i < size; i++) {
        sensors[i].temperature = temperatures[i];
        sensors[i].status = 'A';
        sensors[i].timestamp = time(NULL);
    }

    return sensors;
}

// Function to create doubly linked list of sensors
Sensor* create_list(Sensor* sensors, int size) {
    Sensor* head = (Sensor*)malloc(sizeof(Sensor));
    Sensor* tail = head;

    // Initialize linked list
    for (int i = 0; i < size; i++) {
        Sensor* node = (Sensor*)malloc(sizeof(Sensor));
        node->temperature = sensors[i].temperature;
        node->status = sensors[i].status;
        node->timestamp = sensors[i].timestamp;

        // Add node to linked list
        if (i == 0) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    return head;
}

// Function to update timestamp of each sensor using callback function
void update_timestamps(Sensor* sensors, int size, void (*callback)(Sensor*)) {
    for (int i = 0; i < size; i++) {
        // Calculate elapsed time since last update
        time_t elapsed_time = time(NULL) - sensors[i].timestamp;

        // Update timestamp using callback function
        callback(sensors + i);
    }
}

// Callback function to update timestamp of each sensor
void update_timestamp(Sensor* sensor) {
    sensor->timestamp = time(NULL);
}

// Function to process array of sensor data asynchronously using map()
Sensor* process_sensors(Sensor* sensors, int size) {
    return (Sensor*)map(sensors, size, [](Sensor* sensor) {
        // Perform asynchronous operation
        sleep(1); // Simulate asynchronous operation

        return sensor; // Return processed sensor
    });
}

int main() {
    int size = 5;
    Sensor* sensors = allocate_and_init(size);
    Sensor* head = create_list(sensors, size);

    // Update timestamps of each sensor using callback function
    update_timestamps(sensors, size, &update_timestamp);

    // Process array of sensor data asynchronously using map()
    Sensor* processed_sensors = process_sensors(sensors, size);

