record* init_list(int seed) {
    // Create a memory pool to optimize performance and reduce fragmentation
    void* memory_pool = malloc(1024 * 1024);  // Allocate 1MB of memory

    // Set the seed for generating random int values
    srand(seed);

    record* head = NULL;
    record* tail = NULL;

    return head;  // Return the initialized doubly linked list head
}

// Function to dynamically allocate and manage memory for complex data structure
void* my_malloc(size_t size) {
    // Check if the requested size is too large to fit within the available memory pool
    if (size > sizeof(memory_pool) / 1024) {
        // Handle edge case by allocating a new memory pool of sufficient size
        void* new_memory_pool = malloc(size * 1024);  // Allocate additional memory

        // Copy existing data from the old memory pool to the new one
        memcpy(new_memory_pool, memory_pool, sizeof(memory_pool));  // Copy existing data

        // Free the old memory pool and update the pointer to point to the new one
        free(memory_pool);
        memory_pool = new_memory_pool;
    }

    return memory_pool;  // Return a dynamically allocated block of memory with the requested size
}

// Free the memory pool after use to prevent leaks and maintain system stability
void free_memory_pool() {
    free(memory_pool);  // Free the memory pool

    // Clean up any remaining record structures from the doubly linked list
    while (head != NULL) {
        record* temp = head;
        head = head->next;

        if (temp->prev != NULL) {
            temp->prev->next = head;  // Update the next pointer of the previous node
        } else {
            tail = head;  // Set the new tail to the current head
        }

        free(temp);  // Free the record structure

    }
}

// Function to compute the MD5 hash for a given string using a standard library function
String md5_hash(String input) {
    MessageDigest md = null;
    try {
        md = MessageDigest.getInstance("MD5");
    } catch (NoSuchAlgorithmException e) {
        // Handle error by providing fallback or throwing an exception
        throw new RuntimeException(e);
    }

    byte[] bytes = input.getBytes();
    return hexStringFormat(md.digest(bytes));
}

// Helper function to format the MD5 hash as a hexadecimal string
String hexStringFormat(byte[] bytes) {
    StringBuilder sb = new StringBuilder();

    for (int i = 0; i < bytes.length; i++) {
        String hex = Integer.toHexString(0xFF & bytes[i]);

        // Convert each byte to two-character hexadecimal representation
        if (hex.length() == 1) {
            hex = "0" + hex;
        }

        sb.append(hex);
    }

    return sb.toString();
}

