// Define a hash table with chaining collision resolution
typedef struct {
    int size;
    record** buckets;
    pthread_mutex_t lock;
} hashtable;

// Initialize the hash table with a given size
hashtable* init_hashtable(int size) {
    hashtable* table = (hashtable*)malloc(sizeof(hashtable));
    table->size = size;
    table->buckets = (record**)malloc(size * sizeof(record*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Insert a record into the hash table
void insert_record(hashtable* table, int key, record* record) {
    int index = key % table->size;
    pthread_mutex_lock(&table->lock);
    if (!table->buckets[index]) {
        table->buckets[index] = (record*)malloc(sizeof(record));
    }
    table->buckets[index]->value = record->value;
    pthread_mutex_unlock(&table->lock);
}

// Lookup a record in the hash table
record* lookup_record(hashtable* table, int key) {
    int index = key % table->size;
    pthread_mutex_lock(&table->lock);
    if (table->buckets[index]) {
        return table->buckets[index];
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Define a function to handle cache operations
