['Here is the C code block that implements the described cache management system:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define metadata structure to track access patterns and usage metrics
typedef struct {
    int accesses;
    double avg_access_latency;
} Metadata;

// Define record structure containing a single integer value
typedef struct {
    int value;
} Record;

// Define cache entry structure with offset, key, and metadata
typedef struct {
    long offset;
    int key;
    Metadata metadata;
} CacheEntry;

// Define hash table structure using chaining and open addressing
typedef struct {
    CacheEntry** entries;
    int size;
    int num_entries;
    pthread_mutex_t mutex;
} HashTable;

// Initialize a new hash table with the given initial size
HashTable* init_hash_table(int initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->entries = (CacheEntry**)malloc(initial_size * sizeof(CacheEntry*));
    for (int i = 0; i < initial_size; i++) {
        table->entries[i] = NULL;
    }
    table->size = initial_size;
    table->num_entries = 0;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Hash a key using the FNV-1a hash function
int hash(int key, int size) {
    return (key ^ (key << 4)) & (size - 1);
}

// Resize the hash table when its load factor exceeds the specified threshold
void resize_hash_table(HashTable* table, double load_threshold) {
    if (table->num_entries / table->size > load_threshold) {
        int new_size = table->size * 2;
        CacheEntry** new_entries = (CacheEntry**)malloc(new_size * sizeof(CacheEntry*));
        for (int i = 0; i < new_size; i++) {
            new_entries[i] = NULL;
        }
        for (int i = 0; i < table->size; i++) {
            if (table->entries[i]) {
                int index = hash(table->entries[i]->key, new_size);
                while (new_entries[index]) {
                    index = (index + 1) % new_size;
                }
                new_entries[index] = table->entries[i];
            }
        }
        free(table->entries);
        table->entries = new_entries;
        table->size = new_size;
    }
}

// Add a record to the cache with the given key and value
void add_record(HashTable* table, int key, Record* record) {
    pthread_mutex_lock(&table->mutex);
    int index = hash(key, table->size);
    while (table->entries[index]) {
        index = (index + 1) % table->size;
    }
    table->entries[index] = (CacheEntry*)malloc(sizeof(CacheEntry));
    table->entries[index]->offset = (long)index;
    table->entries[index]->key = key;
    table->entries[index]->metadata.accesses = 0;
    table->entries[index]->record = record;
    table->num_entries++;
    pthread_mutex_unlock(&table->mutex);
}

// Remove a record from the cache by its key
void remove_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] && table->entries[i]->key == key) {
            free(table->entries[i]);
            table->num_entries--;
            table->entries[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

// Retrieve a record from the cache by its key
Record* get_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] && table->entries[i]->key == key) {
            table->entries[i]->metadata.accesses++;
            Record* record = table->entries[i]->record;
            pthread_mutex_unlock(&table->mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

// Clean up the cache by freeing inactive records and implementing tiered caching
void clean_up_cache(HashTable* table, int max_size) {
    // Remove inactive records from the cache
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] && !table->entries[i]->metadata.accesses) {
            free(table->entries[i]);
            table->num_entries--;
            table->entries[i] = NULL;
        }
    }

    // Implement tiered caching and lazy eviction
}

// Main function to initialize the cache system and manage concurrent operations
int main() {
    // Initialize the hash table with an initial size of 256 entries
    HashTable* table = init_hash_table(256);

    // Configure the maximum size of the hash table for memory cleanup
    int max_size = 1024;

    // Add records to the cache using the add_record function
    Record* record1 = (Record*)malloc(sizeof(Record));
    record1->value = 10;
    add_record(table, 1000, record1);
    Record* record2 = (Record*)malloc(sizeof(Record));
    record2->value = 20;
    add_record(table, 2000, record2);

    // Remove a record from the cache using the remove_record function
    remove_record(table, 2000);

    // Retrieve a record from the cache using the get_record function
    Record* retrieved_record = get_record(table, 1000);
    printf("Retrieved record value: %d\n", retrieved_record->value);

    // Clean up the cache by freeing inactive records and implementing tiered caching
    clean_up_cache(table, max_size);

    // Free memory allocated for the hash table and its entries
    free(table->entries);
    free(table);

    return 0;
}
