int generate_random_integer(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

void* insert_record(void* data) {
    int *record = malloc(RECORD_SIZE);
    *record = generate_random_integer(0, INT_MAX);
    pthread_mutex_lock(&record_collection.lock);
    record_collection.data = realloc(record_collection.data, (record_collection.capacity + 1) * RECORD_SIZE);
    record_collection.data[record_collection.capacity++] = *record;
    pthread_mutex_unlock(&record_collection.lock);
    free(record);
    return NULL;
}

void delete_record(int index) {
    if (index < 0 || index >= record_collection.capacity)
        return;

    pthread_mutex_lock(&record_collection.lock);
    memmove(&record_collection.data[index], &record_collection.data[index + 1],
            (record_collection.capacity - index - 1) * RECORD_SIZE);
    record_collection.capacity--;
    pthread_mutex_unlock(&record_collection.lock);
}

int search_record(int target_value) {
    for (size_t i = 0; i < record_collection.capacity; i++) {
        if (record_collection.data[i] == target_value)
            return i;
    }
    return -1;
}

