#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record_t;

typedef struct node {
    record_t *record;
    struct node* next;
} node_t;

node_t* create_node(record_t* rec) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    new_node->record = rec;
    new_node->next = NULL;
    return new_node;
}

void delete_node(node_t** head, node_t* node) {
    if (*head == node) {
        *head = node->next;
    }
    free(node);
}

void insert_record(node_t** head, record_t* rec) {
    node_t* new_node = create_node(rec);
    if (*head == NULL) {
        *head = new_node;
    } else {
        node_t* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

record_t* generate_record(int value_range_min, int value_range_max) {
    record_t* rec = (record_t*)malloc(sizeof(record_t));
    rec->value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    return rec;
}

void serialize_data(node_t* head, FILE* file) {
    node_t* current = head;
    while (current != NULL) {
        fwrite(&current->record->value, sizeof(int), 1, file);
        current = current->next;
    }
}

node_t* deserialize_data(FILE* file, long size) {
    node_t* head = NULL;
    for (long i = 0; i < size; i++) {
        record_t* rec = (record_t*)malloc(sizeof(record_t));
        fread(&rec->value, sizeof(int), 1, file);
        insert_record(&head, rec);
    }
    return head;
}

void* thread_func(void* arg) {
    pthread_mutex_lock(NULL); // No-op, as we're not using a mutex
    printf("Thread %ld is running...\n", (long)arg);
    pthread_exit(NULL); // No-op, as we're not using a pthread_exit
}

int main() {
    int value_range_min = 0;
    int value_range_max = 100;

    srand(time(NULL)); // Initialize the pseudo-random number generator

    node_t* head = NULL;

    for (long i = 0; i < 1000000; i++) { // Create a large dataset
        record_t* rec = generate_record(value_range_min, value_range_max);
        insert_record(&head, rec);
    }

    FILE* file = fopen("data.bin", "wb");
    serialize_data(head, file);
    fclose(file);

    return 0;
}
