// Hash table implementation using chaining
typedef struct _HashTableNode {
    WeatherRecord* record;
    struct _HashTableNode* next;
} HashTableNode;

typedef struct _HashTable {
    HashTableNode** buckets;
    int numBuckets;
    int size;
} HashTable;

