    HashTable* hashTable = (HashTable*)malloc(sizeof(HashTable));

    if (!hashTable) {
        return NULL;
    }

    hashTable->numBuckets = numBuckets;
    hashTable->size = 0;
    hashTable->buckets = (HashTableNode**)malloc(numBuckets * sizeof(HashTableNode*));

    for (int i = 0; i < numBuckets; i++) {
        hashTable->buckets[i] = NULL;
    }

    return hashTable;
}

void freeHashTable(HashTable* hashTable) {
    if (!hashTable) {
        return;
    }

    for (int i = 0; i < hashTable->numBuckets; i++) {
        HashTableNode* node = hashTable->buckets[i];

        while (node) {
            HashTableNode* next = node->next;

            free(node);
            node = next;
        }
    }

    free(hashTable->buckets);
    free(hashTable);
}

// Thread-safe locking mechanism using mutex
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insertRecord(HashTable* hashTable, WeatherRecord* record) {
    pthread_mutex_lock(&lock);

    int bucketIndex = (int)record->location.latitude * 100000 + record->location.longitude;
    HashTableNode* node = hashTable->buckets[bucketIndex];

    while (node) {
        if (node->record == record) {
            // Record already exists, update humidity
            node->record->humidity = record->humidity;
            break;
        }

        node = node->next;
    }

    if (!node) {
        HashTableNode* newNode = (HashTableNode*)malloc(sizeof(HashTableNode));

        if (!newNode) {
            // Handle memory allocation failure
        }

        newNode->record = record;
        newNode->next = hashTable->buckets[bucketIndex];

        hashTable->buckets[bucketIndex] = newNode;
    }

    pthread_mutex_unlock(&lock);
}

WeatherRecord* getRecord(HashTable* hashTable, Location location) {
    pthread_mutex_lock(&lock);

    int bucketIndex = (int)location.latitude * 100000 + location.longitude;
    HashTableNode* node = hashTable->buckets[bucketIndex];

    while (node) {
        if (node->record && memcmp(&node->record->location, &location, sizeof(Location)) == 0) {
            WeatherRecord* record = node->record;

            pthread_mutex_unlock(&lock);
            return record;
        }

        node = node->next;
    }

    pthread_mutex_unlock(&lock);

    // Record not found
    return NULL;
}

int main() {
    srand(time(NULL)); // Initialize pseudo-random number generator

    int numRecords = 10; // Change this value as needed

    WeatherRecord* records = createRecords(numRecords);

    HashTable* hashTable = createHashTable(1000); // Adjust the hash table size according to your needs

    for (int i = 0; i < numRecords; i++) {
        insertRecord(hashTable, &records[i]);
    }

    // Monitor system performance and identify bottlenecks

    freeRecords(records, numRecords);
    freeHashTable(hashTable);

    return 0;
}

