srand(42);

// Function to initialize the weather record system
void initWeatherRecordSystem(int numRecords) {
    // Initialize arrays for keys, offsets, and records
    int* keys = (int*)malloc(numRecords * sizeof(int));
    float* offsets = (float*)malloc(numRecords * sizeof(float));
    Record* records = (Record*)malloc(numRecords * sizeof(Record));

    // Initialize hash table with a reasonable initial size
    int TABLE_SIZE = 1000;
    int* table = (int*)malloc(TABLE_SIZE * sizeof(int));
    for (int i = 0; i < TABLE_SIZE; i++) {
        table[i] = -1; // Initialize table slots as invalid indices
    }

    // Generate humidity levels and initialize records
    for (int i = 0; i < numRecords; i++) {
        Location* location = &((Location*)malloc(sizeof(Location)));
        *location = (Location){i, i};
        Record record;
        int index = rand() % TABLE_SIZE;
        record.index = &index;
        records[i] = record;

        // Set humidity level within a specified range
        float humidityLevel = (float)(rand() % 80 + 20) / 100.0f;
        printf("Record %d: Location (%lf, %lf), Humidity Level %.2f\n", i, location->lat, location->lon, humidityLevel);

        // Insert record into hash table using the location coordinates as a key
        int key = (int)(location->lat * 1000000 + location->lon);
        int slot = key % TABLE_SIZE;
        if (table[slot] == -1) {
            table[slot] = i;
        } else {
            printf("Collision detected at slot %d! Using alternative index.\n", slot);
        }
    }

    // Clean up
    free(keys);
    free(offsets);
    free(table);
}

// Function to retrieve a weather record based on location coordinates
Record* getWeatherRecord(double lat, double lon) {
    Location location;
    location.lat = lat;
    location.lon = lon;

    int key = (int)(location.lat * 1000000 + location.lon);
    int slot = key % TABLE_SIZE;

    if (table[slot] == -1) {
        printf("No record found for location (%lf, %lf).\n", lat, lon);
        return NULL;
    }

    int recordIndex = table[slot];
    Record* record = &records[recordIndex];

    // Validate the record integrity
    if (*record.index < 0 || *record.index >= numRecords) {
        printf("Invalid record index detected! Returning a default error.\n");
        return NULL;
    }

    return record;
}

int main() {
    int numRecords = 100;
    initWeatherRecordSystem(numRecords);

    double lat, lon;

    while (scanf("%lf %lf", &lat, &lon) == 2) {
        Record* record = getWeatherRecord(lat, lon);
        if (record != NULL) {
            printf("Found weather record for location (%lf, %lf): Humidity Level %.2f\n", lat, lon, *(float*)record->index);
        }
    }

    return 0;
}
