typedef struct {
    float value;
    long timestamp;
    int identifier;
} Record;

// Define structure for metadata
typedef struct {
    char origin[256];
    long timestamp;
} Metadata;

// Define structure for event
typedef struct {
    char message[256];
    int severity;
} Event;

// Thread-safe, balanced binary search tree (BST) node
typedef struct Node {
    Record record;
    struct Node* left;
    struct Node* right;
} Node;

// Thread-safe, balanced binary search tree (BST)
Node* bst = NULL;

// Function to initialize BST with memory pool and random seed
void init_bst(int size, int seed) {
    // Pre-allocate memory pool
    void* mem_pool = malloc(size * sizeof(Node));
    if (!mem_pool) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize random number generator with user-provided seed
    srand(seed);

    // Initialize BST with root node
    Node* root = (Node*)malloc(sizeof(Node));
    root->record.value = rand() / (float)RAND_MAX;  // Initialize record value
    root->record.timestamp = time(NULL);            // Initialize timestamp
    root->record.identifier = 0;
    root->left = NULL;
    root->right = NULL;

    bst = root;
}

// Function to insert record into BST
void insert_record(Record* record) {
    Node* current = bst;
    Node* parent = NULL;

    while (current != NULL) {
        parent = current;
        if (record->timestamp < current->record.timestamp) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record = *record;
    new_node->left = NULL;
    new_node->right = NULL;

    if (parent == NULL) {
        bst = new_node;
    } else if (record->timestamp < parent->record.timestamp) {
        parent->left = new_node;
    } else {
        parent->right = new_node;
    }
}

// Function to retrieve record from BST
Record* get_record(long timestamp) {
    Node* current = bst;

    while (current != NULL) {
        if (timestamp == current->record.timestamp) {
            return &current->record;
        }

        if (timestamp < current->record.timestamp) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    // Record not found
    return NULL;
}

// Function to free memory pool and BST
void clean_up() {
    Node* temp = bst;
    while (temp != NULL) {
        Node* next = temp->left;
        free(temp);
        temp = next;
    }
}
