typedef struct record {
    int value;
    time_t timestamp;
} Record;

Record* record_new() {
    Record* r = (Record*)malloc(sizeof(Record));
    r->value = rand() % 100; // random values within a specified range
    r->timestamp = time(NULL);
    return r;
}

void record_free(Record* r) {
    free(r);
}

typedef struct node {
    Record* data;
    struct node* prev;
    struct node* next;
} Node;

Node* node_new(Record* data) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->data = data;
    n->prev = NULL;
    n->next = NULL;
    return n;
}

void node_free(Node* n) {
    record_free(n->data);
    free(n);
}

typedef struct list {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} List;

List* list_new() {
    List* l = (List*)malloc(sizeof(List));
    l->head = NULL;
    l->tail = NULL;
    pthread_mutex_init(&l->mutex, NULL);
    return l;
}

void list_free(List* l) {
    Node* temp = l->head;
    while (temp != NULL) {
        Node* next = temp->next;
        node_free(temp);
        temp = next;
    }
    free(l);
}

