    // Deserialize the JSON object back into a record
    Record* deserialized_r = (Record*)malloc(sizeof(Record));
    deserialized_r->value = json_object_get_int(json_object_object_get(jobj, "value"));
    deserialized_r->timestamp = (time_t)json_object_get_int(json_object_object_get(jobj, "timestamp"));

    // Free the JSON object
    json_object_put(jobj);

    return 0;
}
