    // Initialize memory pool
    size_t pool_size = 1024 * 1024; // 1MB
    void* pool = malloc(pool_size);

    if (!pool) {
        printf("Failed to initialize memory pool!\n");
        return;
    }

    // Initialize logging service
    FILE* log_file = fopen("load_data.log", "w");
    if (!log_file) {
        printf("Failed to open log file!\n");
        free(pool);
        return;
    }

    for (int i = 0; i < num_records; i++) {
        // Allocate memory for record
        Record* record = malloc(sizeof(Record));

        // Fill in random values
        record->offset = rand();
        record->key = rand() % 100;
        record->value = rand() % 10;

        // Allocate memory for data
        Data* data = malloc(sizeof(Data));

        // Fill in random values
        data->val = (double)rand() / RAND_MAX;
        strcpy(data->str, "random_string");

        // Update status field if data is missing or malformed
        if (!data->str[0]) {
            strcpy(data->str, "missing_value");
            // Log error
            fprintf(log_file, "Missing value at record %d!\n", i);
        }

        // Add to array of records and data
        *data_array = realloc(*data_array, (i + 1) * sizeof(Data*));
        (*data_array)[i] = data;
    }

    // Log memory allocation events and execution statistics
    fprintf(log_file, "Loaded %d records successfully!\n", num_records);
    fclose(log_file);

    free(pool);
}

