    // Allocate arrays of specified size
    double* doubles = (double*)malloc(numEntries * sizeof(double));
    char** chars = (char**)malloc(numEntries * sizeof(char*));
    entry* entries = (entry*)malloc(numEntries * sizeof(entry));

    if (!doubles || !chars || !entries) {
        return NULL;
    }

    // Initialize doubles and strings
    for (int i = 0; i < numEntries; i++) {
        double val = (double)(rand() % config->maxVal1 + config->minVal1);
        size_t strLen = rand() % config->maxStrLen + config->minStrLen;
        char* str = (char*)malloc(strLen * sizeof(char));
        if (!str) return NULL;

        sprintf(str, "%s%u", config->prefixes[rand() % config->numPrefixes], i);
        strcpy((char*)entries[i].str, str);

        entries[i].value = val;
        entries[i].length = strLen;
    }

    // Return arrays
    entry** result = (entry**)malloc(sizeof(entry*) * numEntries);
    for (int i = 0; i < numEntries; i++) {
        result[i] = &entries[i];
    }
    return result;
}
