#include <unistd.h>

// Define the node structure
typedef struct {
    char* data; // pointer to a variable-length string
    long offsets[1]; // fixed-size numerical array of offset values
} Node;

// Define the hash table structure
typedef struct {
    int size;
    Node** nodes;
} HashTable;

// Function prototypes
Node* create_node(int session_id);
HashTable* create_hash_table(int initial_size);
void insert_node(HashTable*, int session_id, char* data, long* offsets);
int lookup_node(HashTable*, int session_id);
void free_hash_table(HashTable*);

// Global logging framework
void log_error(const char* message) {
    printf("Error: %s\n", message);
}

void log_warning(const char* message) {
    printf("Warning: %s\n", message);
}

// Create a new node with the given session ID, data, and offset values
Node* create_node(int session_id) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        log_error("Failed to allocate memory for node");
        return NULL;
    }
    node->data = malloc(strlen("dummy") + 1); // initial dummy data
    node->offsets[0] = 0; // initialize offset values
    return node;
}

// Create a new hash table with the given initial size
HashTable* create_hash_table(int initial_size) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        log_error("Failed to allocate memory for hash table");
        return NULL;
    }
    table->size = initial_size;
    table->nodes = calloc(initial_size, sizeof(Node*));
    if (!table->nodes) {
        log_error("Failed to allocate memory for nodes array");
        free(table);
        return NULL;
    }
    return table;
}

// Insert a new node into the hash table with the given session ID, data, and offset values
void insert_node(HashTable* table, int session_id, char* data, long* offsets) {
    Node* node = create_node(session_id);
    if (!node) {
        log_error("Failed to allocate memory for node");
        return;
    }
    node->data = strdup(data); // copy the given data
    memcpy(node->offsets, offsets, sizeof(long));
    int bucket = session_id % table->size; // determine the hash table bucket
    if (table->nodes[bucket] != NULL) {
        log_warning("Hash table bucket already occupied");
        free_node(table->nodes[bucket]); // free the existing node
    }
    table->nodes[bucket] = node;
}

// Lookup a node in the hash table with the given session ID
int lookup_node(HashTable* table, int session_id) {
    int bucket = session_id % table->size; // determine the hash table bucket
    Node* node = table->nodes[bucket];
    if (node == NULL) {
        log_error("Node not found");
        return -1;
    }
    return session_id;
}

// Free a node and its associated memory
void free_node(Node* node) {
    free(node->data);
    free(node);
}

// Free the hash table and all its associated nodes and memory
void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Node* node = table->nodes[i];
        if (node != NULL) {
            free_node(node);
        }
    }
    free(table->nodes);
    free(table);
}
