// Function to create a new doubly linked list node with the given data
Node* newNode(record* data) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->data = *data;
    n->next = NULL;
    n->prev = NULL;
    return n;
}

// Function to add a new record to the end of the doubly linked list
void addRecord(Node** head, record* data) {
    Node* newNode = newNode(data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* last = *head;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = newNode;
        newNode->prev = last;
    }
}

// Function to remove a record from the doubly linked list
void removeRecord(Node** head, record* data) {
    Node* current = *head;
    while (current != NULL && current->data.value != data->value) {
        current = current->next;
    }
    if (current == NULL) return;

    // Remove node from the doubly linked list
    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        *head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    }

    free(current);
}

