    // Allocate memory for arrays
    int* packet_timestamps = malloc(packet_count * sizeof(int));
    char** source_ip_addresses = malloc(packet_count * sizeof(char *));
    char** destination_ip_addresses = malloc(packet_count * sizeof(char *));
    char** protocol_types = malloc(packet_count * sizeof(char *));
    int* payload_sizes = malloc(packet_count * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < packet_count; i++) {
        packet_timestamps[i] = time(NULL) % PACKET_TIMESTAMP_RESOLUTION;
        source_ip_addresses[i] = (char*)malloc(strlen("127.0.0.1") + 1);
        strcpy(source_ip_addresses[i], "127.0.0.1");
        destination_ip_addresses[i] = (char*)malloc(strlen("127.0.0.1") + 1);
        strcpy(destination_ip_addresses[i], "127.0.0.1");
        protocol_types[i] = (char*)malloc(strlen("TCP") + 1);
        strcpy(protocol_types[i], "TCP");
        payload_sizes[i] = rand() % 1024;
    }

    // Initialize bloom filter
    uint32_t* bloom_filter = malloc(MAX_BLOOM_FILTER_SIZE / sizeof(uint32_t));
    for (int i = 0; i < MAX_BLOOM_FILTER_SIZE / sizeof(uint32_t); i++) {
        bloom_filter[i] = 0;
    }

    return (void*)packet_timestamps;
}

// Function to free allocated memory
void free_network_traffic_monitoring_system(void* packet_timestamps) {
    // Deallocate memory for arrays
    int* packet_timestamps_ptr = packet_timestamps;
    for (int i = 0; i < packet_count; i++) {
        free(packet_timestamps_ptr[i]);
    }
    free(packet_timestamps);

    // Deallocate bloom filter
    free(bloom_filter);
}
