    // Allocate memory for the arrays
    double** largeDoubles = (double**)calloc(capacity, sizeof(double*));
    short* keys = (short*)malloc(capacity * sizeof(short));
    Data** customData = (Data**)malloc(capacity * sizeof(Data));

