        // Handle memory allocation failure
        free(largeDoubles);
        free(keys);
        free(customData);
        return;
    }

    // Initialize the arrays
    for (size_t i = 0; i < capacity; i++) {
        largeDoubles[i] = (double*)malloc(sizeof(double));
        keys[i] = -1; // Default key value

        customData[i]->value = NAN;
        customData[i]->key = -1;
        customData[i]->str = NULL;

        // Allocate memory for the string dynamically
        size_t strLen = 0;
        char* str = (char*)malloc(strLen + 1);
        if (!str) {
            // Handle string allocation failure
            free(largeDoubles);
            free(keys);
            free(customData);

            return;
        }

        // Initialize the string dynamically
        strcpy(str, "Default String");
        customData[i]->str = str;

        free(str);
    }
}
