int manage_memory(int num_entries) {
    int i;

    // Allocate arrays for data, short keys, and double values
    array_data = (data_t**)malloc(num_entries * sizeof(data_t*));
    array_short_keys = (short*)malloc(num_entries * sizeof(short));
    array_double_values = (double*)malloc(num_entries * sizeof(double));

    // Initialize arrays with null values for data structures
    for (i = 0; i < num_entries; i++) {
        array_data[i] = NULL;
    }

    return 0;
}

// Function to insert a new entry into the database system
