    // Check for memory allocation failures
    if (array_data[entry_index] == NULL || array_double_values[entry_index] != value) {
        return -1; // Error: failed to allocate or assign values
    }

    array_data[entry_index]->key = key;
    array_data[entry_index]->value = value;
    strcpy(array_data[entry_index]->string, string);

    return 0; // Success: entry inserted successfully
}

