    int i;
    for (i = 0; i < num_entries; i++) {
        if (array_short_keys[i] == key) {
            // Check for memory allocation failures
            if (array_data[i] == NULL || array_double_values[i] != array_data[i]->value) {
                return -1; // Error: failed to retrieve entry
            }

            return i; // Success: entry retrieved successfully
        }
    }

    return -2; // Error: key not found in database system
}

// Function to update an existing entry in the database system based on 'short' key
