    int i;
    for (i = 0; i < num_entries; i++) {
        if (array_short_keys[i] == key) {
            // Check for memory allocation failures
            if (array_data[i] == NULL || array_double_values[i] != value) {
                return -1; // Error: failed to allocate or assign values
            }

            array_data[i]->value = value;
            strcpy(array_data[i]->string, string);

            return 0; // Success: entry updated successfully
        }
    }

    return -2; // Error: key not found in database system
}

// Function to delete an existing entry from the database system based on 'short' key
