    int i;
    for (i = 0; i < num_entries; i++) {
        if (array_short_keys[i] == key) {
            // Check for memory allocation failures
            if (array_data[i] == NULL) {
                return -1; // Error: failed to deallocate memory
            }

            array_short_keys[i] = 0;
            array_double_values[i] = 0.0;
            free(array_data[i]->string);
            free(array_data[i]);

            return 0; // Success: entry deleted successfully
        }
    }

    return -2; // Error: key not found in database system
}

// Function to deallocate all resources upon completion or early termination
