    int i;
    for (i = 0; i < num_entries; i++) {
        if (array_data[i] != NULL) {
            free(array_data[i]->string);
            free(array_data[i]);
        }
    }

    free(array_short_keys);
    free(array_double_values);
    free(array_data);

    return 0;
}

