#include <stdlib.h>
#include <string.h>

typedef struct {
    double d;
    int i;
    char* s;
} data_t;

typedef struct {
    int size;
    data_t** elements;
} array_t;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // handle memory allocation failure
        return NULL;
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

data_t* data_create(double d, int i, const char* s) {
    data_t* data = (data_t*)my_malloc(sizeof(data_t));
    if (!data) return NULL;
    data->d = d;
    data->i = i;
    data->s = my_strdup(s);
    if (!data->s) {
        // handle memory allocation failure
        my_free(data);
        return NULL;
    }
    return data;
}

void data_destroy(data_t* data) {
    if (!data) return;
    my_free(data->s);
    my_free(data);
}

array_t* array_create(int size) {
    array_t* arr = (array_t*)my_malloc(sizeof(array_t));
    if (!arr) return NULL;
    arr->size = size;
    arr->elements = (data_t**)my_calloc(size, sizeof(data_t*));
    for (int i = 0; i < size; i++) {
        arr->elements[i] = NULL;
    }
    return arr;
}

void array_destroy(array_t* arr) {
    if (!arr) return;
    for (int i = 0; i < arr->size; i++) {
        data_destroy(arr->elements[i]);
    }
    my_free(arr->elements);
    my_free(arr);
}

data_t** array_get_array(array_t* arr, int index) {
    if (!arr || index >= arr->size) return NULL;
    return &arr->elements[index];
}

int main() {
    // Example usage
    data_t* data = data_create(3.14, 42, "Hello");
    array_t* arr = array_create(10);
    for (int i = 0; i < arr->size; i++) {
        arr->elements[i] = data;
    }
    // ...
    return 0;
}
