// Function to process the input list and manage memory
void process_input(int size) {
    // Check for invalid size input
    if (size <= 0) {
        printf("Invalid size. Aborting.\n");
        return;
    }

    // Initialize random number generator with user-provided custom value as seed
    srand(time(NULL));

    // Allocate memory for offset array, key array, and linked list
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    Node* head = NULL;
    Node* tail = NULL;

    // Process input data and create the linked list
    for (int i = 0; i < size; i++) {
        Record record;
        record.value = rand() % 100; // Initialize with random value within [0, 99]
        Node* node = (Node*)malloc(sizeof(Node));
        node->record = record;
        node->prev = NULL;
        node->next = NULL;

        if (head == NULL) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);

    // Callback mechanism for post-processing the sorted list of records
    void (*callback)(Node*) = NULL;

    if (callback != NULL) {
        Node* current = head;
        while (current != NULL) {
            callback(current);
            current = current->next;
        }
    }

    // Health-check mechanism to verify memory allocation and linked list integrity
    if (!is_memory_leak() && !is_linked_list_corrupted(head, tail)) {
