typedef struct linked_list {
    linked_list_node_t* head;
    pthread_mutex_t lock;
} linked_list_t;

void init_linked_list(linked_list_t* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int validate_packet_sequence(packet_t packet, linked_list_t* list) {
    if (packet.timestamp > MAX_SEQNUM || packet.timestamp < 0) {
        printf("Invalid sequence number: %u\n", packet.timestamp);
        return -1;
    }

    if (list->head == NULL || packet.timestamp != list->head->packet.timestamp + 1) {
        return 0; // valid or first packet in sequence
    } else {
        linked_list_node_t* current = list->head;
        while (current && current->packet.timestamp < packet.timestamp) {
            current = current->next;
        }

        if (current && current->packet.timestamp == packet.timestamp) {
            printf("Duplicate packet: %u\n", packet.timestamp);
            return -1; // duplicate packet
        } else {
            return 0; // valid packet, insert into list
        }
    }
}

void process_packet(packet_t packet, linked_list_t* list, void (*callback)(packet_t*, int)) {
    if (validate_packet_sequence(packet, list) == 0) {
        linked_list_node_t* new_node = malloc(sizeof(linked_list_node_t));
        new_node->packet = packet;
        new_node->next = list->head;
        pthread_mutex_lock(&list->lock);
        list->head = new_node;
        pthread_mutex_unlock(&list->lock);

        callback(&new_node->packet, 0);
    } else if (validate_packet_sequence(packet, list) < 0) {
        callback(&packet, -1);
    }
}

void* packet_processor(void* arg) {
