#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef enum {
    ALIVE,
    DECEASED
} Status;

typedef struct {
    char* name;
    int age;
    Status status;
} User;

// Tree node structure
typedef struct Node {
    User data;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new tree node
Node* newNode(User data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// Tree structure
typedef struct BST {
    Node* root;
} BST;

// Function to insert a new user into the tree
void insert(BST* bst, User data) {
    if (bst->root == NULL) {
        bst->root = newNode(data);
    } else {
        insertNode(bst->root, newNode(data));
    }
}

// Recursive function to insert a node into the tree
void insertNode(Node* node, Node* newNode) {
    if (strcmp(newNode->data.name, node->data.name) < 0) {
        if (node->left == NULL) {
            node->left = newNode;
        } else {
            insertNode(node->left, newNode);
        }
    } else {
        if (node->right == NULL) {
            node->right = newNode;
        } else {
            insertNode(node->right, newNode);
        }
    }
}

// Function to find a user in the tree
User* find(BST* bst, char* name) {
    Node* current = bst->root;
    while (current != NULL) {
        if (strcmp(current->data.name, name) == 0) {
            return &current->data;
        } else if (strcmp(current->data.name, name) < 0) {
            current = current->left;
        } else {
            current = current->right;
        }
    }
    return NULL;
}

// Function to update a user in the tree
void update(BST* bst, char* name, User data) {
    Node* node = find(bst, name);
    if (node != NULL) {
        node->data = data;
    } else {
        printf("User not found\n");
    }
}

// Function to remove a user from the tree
void remove(BST* bst, char* name) {
    Node* node = find(bst, name);
    if (node != NULL) {
        bst->root = removeNode(bst->root, &node->data);
    } else {
        printf("User not found\n");
    }
}

// Recursive function to remove a node from the tree
Node* removeNode(Node* node, User* data) {
    if (node == NULL) return node;

    if (strcmp(data->name, node->data.name) < 0) {
        node->left = removeNode(node->left, data);
    } else if (strcmp(data->name, node->data.name) > 0) {
        node->right = removeNode(node->right, data);
    } else {
        if (node->left == NULL) {
            Node* temp = node;
            node = node->right;
            free(temp);
        } else if (node->right == NULL) {
            Node* temp = node;
            node = node->left;
            free(temp);
        } else {
            Node* minNode = findMin(node->right);
            node->data = minNode->data;
            node->right = removeNode(node->right, &node->data);
        }
    }
    return node;
}

// Function to find the minimum node in the tree
Node* findMin(Node* node) {
    while (node->left != NULL) {
        node = node->left;
    }
    return node;
}
