    int node_id = rand() % hash_table->size;
    Node* node = hash_table->nodes[node_id];
    add_to_hash_table(node->sessions, session);
}

// Function to retrieve a session from the distributed hash table
Session* get_session(DistributedHashTable* hash_table, int id) {
    for (int i = 0; i < hash_table->size; i++) {
        Node* node = hash_table->nodes[i];
        Session* session = get_from_hash_table(node->sessions, id);
