#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <mysql/mysql.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record* record;
    struct Node* prev;
    struct Node* next;
} Node;

Node* loadAndProcessRecords(int size, MYSQL* conn) {
    srand(time(NULL));

    // Check for invalid size
    if (size <= 0) {
        printf("Invalid size. Aborting.\n");
        return NULL;
    }

    // Initialize the doubly linked list
    Node* head = NULL;
    Node* tail = NULL;

    // Dynamically allocate memory for records
    Record** records = (Record**)malloc(size * sizeof(Record*));

    if (!records) {
        printf("Memory allocation failed. Aborting.\n");
        return NULL;
    }

    // Initialize the list of records
    for (int i = 0; i < size; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            printf("Memory allocation failed. Aborting.\n");
            for (int j = 0; j <= i; j++)
                free(records[j]);
            free(records);
            return NULL;
        }
        // Generate random offset values
        records[i]->key = rand() % 100;
        records[i]->offset = rand() % 10000000;

        // Fetch metadata from external data source (MySQL)
        if (!fetchMetadataFromDB(conn, records[i])) {
            printf("Failed to fetch metadata. Aborting.\n");
            for (int j = 0; j <= i; j++)
                free(records[j]);
            free(records);
            return NULL;
        }
    }

    // Insert records into the doubly linked list
    for (int i = 0; i < size; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed. Aborting.\n");
            for (int j = 0; j <= i; j++)
                free(records[j]);
            free(records);
            return NULL;
        }
        node->record = records[i];
        node->prev = NULL;
        node->next = NULL;

        if (!head) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    // Clean up
    for (int i = 0; i < size; i++) {
        free(records[i]);
        records[i] = NULL;
    }
    free(records);
    return head;
}

// Helper function to fetch metadata from external data source (MySQL)
bool fetchMetadataFromDB(MYSQL* conn, Record* record) {
    // Connect to the MySQL database
    if (!mysql_query(conn, "SELECT * FROM employees WHERE id = ?")) {
        // Process the result set
        MYSQL_RES* result = mysql_use_result(conn);
        if (result) {
            MYSQL_ROW row;
            while ((row = mysql_fetch_row(result))) {
                record->name = row[0];
                record->city = row[1];
                record->address = row[2];
            }
            mysql_free_result(result);
        } else {
            // Handle the error
            printf("Failed to fetch metadata. Aborting.\n");
            return false;
        }
    } else {
        // Handle the error
        printf("Failed to connect to database. Aborting.\n");
        return false;
    }

    // Disconnect from the MySQL database
    mysql_free_result(result);
    return true;
}

