int insert_record(Record** head, Record* new_record) {
    if(*head == NULL || (*head)->key > new_record->key) { // New record is inserted at the front
        Record* temp = *head;
        *head = new_record;
        new_record->next = temp;
        return 1; // Successfully inserted a new record
    } else {
        Record* current = *head;
        while(current->next && current->next->key > new_record->key) {
            current = current->next;
        }
        if(current->next != NULL) {
            Record* temp = current->next;
            current->next = new_record;
            new_record->next = temp;
            return 1; // Successfully inserted a new record
        } else {
            return 0; // Unable to insert the record
        }
    }
}

void free_record(Record* record) {
    if(record) {
        if(record->metadata) {
            free(record->metadata);
        }
        free(record);
    }
