#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    void* record;
    void* metadata;
} Record;

Record* record_new(int key, long offset, void* record, void* metadata) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->record = record;
    new_record->metadata = metadata;
    return new_record;
}

void record_free(Record* record) {
    free(record);
}

typedef struct node {
    Record* record;
    struct node* prev;
    struct node* next;
} Node;

Node* node_new(Record* record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record = record;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void node_free(Node* node) {
    free(node);
}

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} List;

List* list_new() {
    List* new_list = (List*)malloc(sizeof(List));
    new_list->head = NULL;
    new_list->tail = NULL;
    pthread_mutex_init(&new_list->mutex, NULL);
    return new_list;
}

void list_free(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        node_free(current);
        current = next;
    }
    free(list);
}

void list_insert(List* list, Record* record) {
    Node* new_node = node_new(record);
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        new_node->prev = list->tail;
        list->tail->next = new_node;
        list->tail = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void list_remove(List* list, Record* record) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->record == record) {
            if (current->prev != NULL)
                current->prev->next = current->next;
            else
                list->head = current->next;
            if (current->next != NULL)
                current->next->prev = current->prev;
            else
                list->tail = current->prev;
            node_free(current);
            return;
        }
        current = current->next;
    }
}

void list_update(List* list, Record* old_record, Record* new_record) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->record == old_record) {
            current->record = new_record;
            return;
        }
        current = current->next;
    }
}

void list_query(List* list, time_t start_time, time_t end_time, void (*callback)(Record*)) {
    Node* current = list->head;
    while (current != NULL) {
        Record* record = current->record;
        time_t timestamp = record->timestamp;
        if ((start_time <= timestamp && timestamp <= end_time)) {
            callback(record);
        }
        current = current->next;
    }
}
