    for (int i = 0; i < numDialogFields; i++) {
        if (dialogFields[i].resourceId == resourceId && dialogFields[i].urlId == urlId) {
            // Send a message to the parent window with the field name
            SendMessageToParent("RefreshField", dialogFields[i].fieldName);

            // Update the dialog field with the result
            UpdateDialogField(dialogFields[i].fieldName, "Updated value");
        }
    }
}

int main() {
    int numNodes = 4;
    int initialCapacity = 10;

    Node* nodes = initHashTable(numNodes, initialCapacity);

    Session session1 = {1, 1643723400, 300, (char*)"Session metadata"};
    Session session2 = {2, 1643723500, 200, (char*)"Another session"};

    addSession(nodes, 0, &session1);
    addSession(nodes, 1, &session2);

    Session* retrievedSession = getSession(nodes, 1);
    if (retrievedSession != NULL) {
        printf("Retrieved session: %d, %ld, %d, %s\n", 
               retrievedSession->id, retrievedSession->timestamp, retrievedSession->duration, retrievedSession->metadata);
    }

    refreshDialogFields(123, 456);

