record* allocateRecords(int count) {
    record* records = (record*)malloc(count * RECORD_SIZE);
    for (int i = 0; i < count; i++) {
        records[i].key = rand() % 100;
        char* str = (char*)malloc(257); // dynamically allocate string
        int len = rand() % 256;
