            free(records[i].string);
        }
    }
    free(records);
}

void serializeRecords(const record* records, int count, FILE* file) {
    fwrite(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        fwrite(&records[i], RECORD_SIZE, 1, file);
    }
}

