    record* records = allocateRecords(count);
    for (int i = 0; i < count; i++) {
        fread(&records[i], RECORD_SIZE, 1, file);
    }
    return records;
}

void logMemoryUsage() {
    printf("Current memory usage: %ld bytes\n", sysconf(_SC_PAGESIZE) * getpagesize());
}
