#define TABLE_SIZE 1024
#define STRING_CAPACITY 256
#define MIN_CAPACITY 16

typedef struct {
    long offset;
    int key;
    char* value;
} record;

record** table;
int capacity;
int size;
pthread_mutex_t lock;

void custom_hash(record* r, int* hash) {
    *hash = (r->key + r->offset) % TABLE_SIZE;
}

int custom_collision_resolution(int hash1, int hash2) {
    return abs(hash1 - hash2);
}

record** init_table(int capacity) {
    record** table = malloc(sizeof(record*) * capacity);
    for (int i = 0; i < capacity; i++) {
        table[i] = NULL;
    }
    return table;
}

void free_records(record** records, int count) {
    for (int i = 0; i < count; i++) {
        if (records[i]->value != NULL) {
            free(records[i]->value);
        }
        free(records[i]);
    }
    free(records);
}

void resize_table(int new_capacity) {
    record** old_table = table;
    capacity = new_capacity;
    table = init_table(capacity);

    for (int i = 0; i < size; i++) {
        int hash = custom_hash(old_table[i], NULL);
        int collisions = custom_collision_resolution(hash, hash + size % capacity);
        record* temp = old_table[i];
        for (int j = 0; j <= collisions; j++) {
            if (table[(hash + j) % capacity] == NULL || table[hash + j] != temp) {
                table[hash + j] = temp;
                break;
            }
        }
    }

    free_records(old_table, size);
    size = 0;
}

void log_error(const char* message) {
    // Implement logging mechanism
    printf("Error: %s\n", message);
}

