#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

// Define the struct for file metadata
typedef struct {
    char filename[256];
    off_t fileSize;
    time_t modificationTime;
    uid_t ownerUid;
} file_metadata;

// Define a simple hash table implementation
typedef struct {
    int size;
    struct file_metadata **data;
    unsigned long *hashKeys;
} hashTable;

void initHashTable(hashTable *ht, int size) {
    ht->size = size;
    ht->data = (struct file_metadata **)malloc(size * sizeof(struct file_metadata *));
    ht->hashKeys = (unsigned long *)malloc(size * sizeof(unsigned long));
}

int insertHashTable(hashTable *ht, char* filename, struct file_metadata* data) {
    // Simple hash function using the filename
    unsigned long hashKey = 0;
    for(int i=0; i<strlen(filename); i++) {
        hashKey += (unsigned long)filename[i];
    }

    // Insert into the table
    int index = hashKey % ht->size;
    if(ht->data[index] == NULL || strcmp(filename, ht->data[index]->filename) < 0) {
        ht->data[index] = data;
        return 1; // insertion successful
    }
    return 0; // collision occurred
}

int deleteHashTable(hashTable *ht, char* filename) {
    unsigned long hashKey = 0;
    for(int i=0; i<strlen(filename); i++) {
        hashKey += (unsigned long)filename[i];
    }

    int index = hashKey % ht->size;
    if(ht->data[index] != NULL && strcmp(filename, ht->data[index]->filename) == 0) {
        free(ht->data[index]);
        ht->data[index] = NULL;
        return 1; // deletion successful
    }
    return 0; // not found
}

int findLargestFile(hashTable *ht) {
    int largestIndex = -1;
    off_t largestFileSize = 0;
    for(int i=0; i<ht->size; i++) {
        if(ht->data[i] != NULL && ht->data[i]->fileSize > largestFileSize) {
            largestIndex = i;
            largestFileSize = ht->data[i]->fileSize;
        }
    }
    return largestIndex;
}

void printLargestFile(hashTable *ht, int largestIndex) {
    if(largestIndex >= 0 && ht->data[largestIndex] != NULL) {
        printf("The largest file is %s with size %ld\n", ht->data[largestIndex]->filename, (long)ht->data[largestIndex]->fileSize);
    }
}

int main() {
    hashTable *ht = malloc(sizeof(hashTable));
    initHashTable(ht, 16); // Initialize the hash table

    char** filepaths = NULL;
    int numFiles = 0;

    FILE* input = stdin;
    char line[256];

    while(fgets(line, sizeof(line), input)) {
        // Parse file path from line
        char* filepath = strtok(line, "\n");
        if(filepath != NULL) {
            // Allocate memory for the file buffer and metadata
            size_t fileSize;
            struct stat sb;
            FILE* file = fopen(filepath, "rb");
            if(file == NULL || fstat(fileno(file), &sb) < 0) {
                // Handle error
                printf("Error processing file %s\n", filepath);
            } else {
                fileSize = sb.st_size;
                size_t bufferSz = fileSize + 1; // Add 1 for null terminator
                char* buffer = malloc(bufferSz * sizeof(char));
                if(file != NULL) {
                    fseek(file, 0, SEEK_SET);
                    fread(buffer, 1, fileSize, file);
                    fclose(file);

                    struct file_metadata* data = malloc(sizeof(struct file_metadata));
                    strcpy(data->filename, filepath);
                    data->fileSize = sb.st_size;
                    data->modificationTime = sb.st_mtime;
                    data->ownerUid = sb.st_uid;

                    // Insert into the hash table
                    if(insertHashTable(ht, filepath, data)) {
                        printf("File %s processed successfully\n", filepath);
                    } else {
                        printf("Collision occurred for file %s\n", filepath);
                    }
                } else {
                    printf("Error reading file %s\n", filepath);
                }

                free(buffer);
                free(data);

                numFiles++;
            }
        }
    }

    fclose(input);

    int largestIndex = findLargestFile(ht);
    if(largestIndex >= 0) {
        printLargestFile(ht, largestIndex);
    } else {
        printf("No files processed\n");
    }

    // Free all allocated memory
    for(int i=0; i<ht->size; i++) {
        free(ht->data[i]);
    }
    free(ht->data);
    free(ht->hashKeys);

    return 0;
}
