#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define structure for records
typedef struct {
    int key;
    int value;
    time_t timestamp;
} Record;

// Define the thread-safe linked list structure
typedef struct node {
    Record record;
    struct node* prev;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node* head = NULL;
Node* tail = NULL;

// Function to initialize a new record with random value within range
void initRecord(Record* record, int min, int max) {
    srand(time(NULL));
    record->value = rand() % (max - min + 1) + min;
}

// Function to create and initialize a new node
Node* createNode(Record* record) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    initRecord(&record, 0, 100); // Initialize with random value within range [0, 100]
    newNode->record = *record;
    newNode->prev = NULL;
    newNode->next = NULL;
    pthread_mutex_init(&newNode->lock, NULL);

    return newNode;
}

// Function to insert a new node at the beginning of the list
void insertHead(Node** head, Node* newNode) {
    pthread_mutex_lock(&newNode->lock);
    pthread_mutex_lock(&(*head)->lock);

    if (*head == NULL || (*head)->prev != NULL) {
        *head = newNode;
        newNode->next = *head;
        (*head)->prev = newNode;
        (*head)->next->prev = newNode;
    } else {
        newNode->next = *head;
        *head = newNode;
    }

    pthread_mutex_unlock(&(*head)->lock);
    pthread_mutex_unlock(&newNode->lock);
}

// Function to remove a node from the list
void removeNode(Node** head, Node* node) {
    if (node == NULL || node == *head) return;

    pthread_mutex_lock(&node->lock);

    if (node == *tail) {
        *tail = node->prev;
        node->prev->next = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    free(node);
    pthread_mutex_unlock(&node->lock);
}

// Function to garbage collect unused nodes
void garbageCollect(int threshold) {
    Node* current = head;
    while (current != NULL && current == tail) {
        if (current->record.value < threshold) {
            removeNode(&head, current);
        } else {
            break;
        }
        current = current->next;
    }
}

// Function to allocate and initialize an array of 'long' offset values
long* createOffsets(int size) {
    long* offsets = (long*)malloc(sizeof(long) * size);
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % (100000 - 1 + 1) + 1;
    }
    return offsets;
}

// Function to allocate and initialize an array of 'int' keys
int* createKeys(int size) {
    int* keys = (int*)malloc(sizeof(int) * size);
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % (100 - 1 + 1) + 1;
    }
    return keys;
}

// Function to allocate and initialize an array of 'record' structures
Record* createRecords(int size) {
    Record* records = (Record*)malloc(sizeof(Record) * size);
    for (int i = 0; i < size; i++) {
        initRecord(&records[i], 0, 100); // Initialize with random value within range [0, 100]
    }
    return records;
}

int main() {
    int size = 10; // Set the desired size of the linked list

    head = createNode(createRecords(size));
    tail = head;

    for (int i = 1; i < size; i++) {
        insertHead(&head, createNode(createRecords(1)));
    }

    garbageCollect(50); // Perform garbage collection every 50 records

    return 0;
}

