#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct node {
    void* data;
    size_t size;
    uint32_t flags;
    struct node* next;
} Node;

Node* create_node(size_t size) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->size = size;
    new_node->flags = 0;
    new_node->next = NULL;

    // Initialize data with random bytes
    uint8_t* random_data = (uint8_t*)malloc(size);
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        random_data[i] = rand() % 256;
    }
    new_node->data = random_data;

    return new_node;
}

Node* insert_node(Node** head, Node* node) {
    if (!head || !node) return NULL;

    if (*head == NULL) {
        *head = node;
        node->next = node; // Circular linked list
    } else {
        node->next = (*head)->next;
        (*head)->next = node;
    }

    return *head;
}

void delete_node(Node** head, Node* node) {
    if (!head || !node) return;

    if (node == *head) {
        if (node->next == node) { // Circular linked list with single element
            free(node->data);
            free(node);
            *head = NULL;
        } else {
            *head = node->next;
            node->next->prev = node->next; // Update prev pointer in circular linked list
            free(node->data);
            free(node);
        }
    } else if (node->next == node) { // Node is last in the list
        free(node->data);
        free(node);
    } else {
        Node* prev = *head;
        while (prev->next != node) prev = prev->next;
        prev->next = node->next;
        free(node->data);
        free(node);
    }
}

Node* traverse(Node* head, size_t size) {
    if (!head || !size) return NULL;

    Node* current = head;
    do {
        printf("Size: %zu, Flags: 0x%x, Data: %p\n", current->size, current->flags, current->data);
        current = current->next;
    } while (current != head && current->size == size);

    return current == head ? NULL : current;
}
