void* circular_buffer(int size) {
    message* buffer = (message*)calloc(size, sizeof(message));
    if (!buffer) return NULL;

    // Initialize each message's payload with a dynamically allocated array of characters
    for (int i = 0; i < size; i++) {
        char* string_id = (char*)malloc(32); // assume maximum sequence ID length is 31
        sprintf(string_id, "msg-%u", i);
        buffer[i].payload = string_id;
    }

    return buffer;
}

void* init_offset_array(int size) {
    size_t* offsets = (size_t*)calloc(size, sizeof(size_t));
    if (!offsets) return NULL;

    // Initialize each offset with a unique value
    for (int i = 0; i < size; i++) {
        offsets[i] = i;
    }

    return offsets;
}

