    // Initialize hash table and binary search tree
    HASH_TABLE *hash_table = init_hash_table(1000);
    BSTREE *bstree = init_bstree();

    // Allocate memory for array of double precision values
    double* arr = (double*)malloc(sizeof(double) * config.array_size);
    if (!arr) {
        LOG_ERROR("Failed to allocate memory for array");
        return;
    }

    // Initialize array with random values within specified range
    for (int i = 0; i < config.array_size; i++) {
        arr[i] = (double)rand() / RAND_MAX * (config.max_value - config.min_value) + config.min_value;
    }

    // Insert records into hash table and binary search tree
    for (int i = 0; i < config.array_size; i++) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            LOG_ERROR("Failed to allocate memory for record");
            return;
        }
        record->value = arr[i];
        insert_hash_table(hash_table, record);
        insert_bstree(bstree, record);
    }

    // Find and print smallest and largest values in array
    double min_value = find_min(arr, config.array_size);
    double max_value = find_max(arr, config.array_size);

    LOG_INFO("Smallest value: %f", min_value);
    LOG_INFO("Largest value: %f", max_value);

