// Function to process the stream of integers from network socket connection
void process_integers(int sockfd, int size, int seed) {
    // Initialize the arrays and linked list
    long* offsets = NULL;
    int* keys = NULL;
    record_t** records = NULL;

    // Initialize random number generator with custom seed
    srand(seed);

    // Process the stream of integers
    for (int i = 0; i < size; i++) {
        int val = rand_val(1, 100); // Generate a random value between 1 and 100
        // Handle potential duplicates by checking against existing keys
        if (!contains_key(keys, val)) {
            // Insert the new key-value pair into the linked list and arrays
            record_t* rec = (record_t*)malloc(sizeof(record_t));
            rec->value = val;
            records = (record_t**)realloc(records, sizeof(record_t*) * (i + 2));
            offsets = (long*)realloc(offsets, sizeof(long) * (i + 2));
            keys = (int*)realloc(keys, sizeof(int) * (i + 2));

            // Initialize the new record and update arrays
            records[i] = rec;
            offsets[i] = i;
            keys[i] = val;

            printf("Received integer: %d\n", val);
        }
    }

    // Filter and reorder the linked list nodes based on the value of the 'int' field in each record
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (records[i]->value > records[j]->value) {
                // Swap records
                record_t* temp = records[i];
                long temp_offset = offsets[i];
                int temp_key = keys[i];

                records[i] = records[j];
                offsets[i] = offsets[j];
                keys[i] = keys[j];

                records[j] = temp;
                offsets[j] = temp_offset;
                keys[j] = temp_key;
            }
        }
    }

    // Print the largest integer in the array
    printf("Largest integer: %d\n", get_largest_integer(keys, size));

    // Free allocated memory and print summary statistics
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);

    printf("Unique integers processed: %d\n", size);
    printf("Insertions performed: %d\n", size - 1);
    printf("Deletions performed: 0\n");
    printf("Maximum value found: %d\n", get_largest_integer(keys, size));

    return;
}

// Helper function to print the largest integer in the array
int get_largest_integer(int* keys, int size) {
    int max_val = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > max_val) {
            max_val = keys[i];
        }
    }
    return max_val;
}

// Helper function to check if a key already exists in the array
