#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <assert.h>

// Define a struct to represent a point with x and y coordinates
typedef struct {
    float x;
    float y;
} Point;

// Define a struct to represent a node in the balanced binary search tree (BST)
typedef struct Node {
    Point point;
    struct Node* left;
    struct Node* right;
} Node;

// Function to calculate the average y-value of all points in the BST
double avgYValue(Node* root) {
    double sum = 0.0;
    int count = 0;

    // Recursive function to traverse the tree and calculate the sum
    void dfs(Node* node, double& sum, int& count) {
        if (node == NULL)
            return;

        dfs(node->left, sum, count);
        sum += node->point.y;
        count++;
        dfs(node->right, sum, count);
    }

    // Calculate the average
    if (root == NULL)
        return 0.0;

    double avg = 0.0;

    // Initialize the cache with the initial value
    static double cachedAvgYValue = -1.0;
    static int cachedCount = 0;

    if (cachedAvgYValue != -1.0) {
        return cachedAvgYValue;
    }

    // Calculate and cache the average
    dfs(root, sum, count);
    avg = sum / count;
    cachedAvgYValue = avg;
    cachedCount = count;

    return avg;
}

// Function to initialize a balanced binary search tree (BST) with dynamic memory allocation
Node* initBST(int size) {
    Node* root = NULL;

    // Allocate memory for the BST nodes
    for (int i = 0; i < size; i++) {
        Point point;
        point.x = (float)i;
        // Initialize y-coordinate to a random value within a specified range
        point.y = (rand() % 100) / 100.0;

        Node* node = (Node*)malloc(sizeof(Node));
        if (node == NULL) {
            // Handle memory allocation failure
            return NULL;
        }

        node->point = point;
        node->left = node->right = NULL;

        if (root == NULL) {
            root = node;
        } else {
            Node* prev = root;

            while (1) {
                if (node->point.x < prev->point.x)
                    prev = prev->left;
                else
                    prev = prev->right;

                if (prev->left == NULL && prev->right == NULL) {
                    if (node->point.x < prev->point.x)
                        prev->left = node;
                    else
                        prev->right = node;
                    break;
                }
            }
        }
    }

    return root;
}

// Function to periodically update the set of points with new data from an external source
Node* updatePoints(Node* root, int newSize) {
    // Read new data from the external source
    // Validate and process the received data

    if (newSize > 0) {
        Node* newNode = initBST(newSize);

        // Update the BST with the new points
        Node* current = root;
        while (1) {
            if (current == NULL)
                break;

            if (newNode->point.x < current->point.x) {
                if (current->left == NULL) {
                    current->left = newNode;
                    break;
                }
                current = current->left;
            } else {
                if (current->right == NULL) {
                    current->right = newNode;
                    break;
                }
                current = current->right;
            }
        }

        // Free the original BST nodes
        Node* temp = root;
        while (temp != NULL) {
            Node* next = temp->left;
            free(temp);
            temp = next;
        }
        root = newNode;
    }

    return root;
}

int main() {
    srand(time(NULL));  // Initialize the random number generator

    int size = 10;  // Initial size of the point set
    Node* root = initBST(size);

    // Periodically update the point set with new data
    for (int i = 0; i < 5; i++) {
        int newSize = rand() % 20 + 1;  // Randomly generate the new size
        root = updatePoints(root, newSize);
    }

    double avgYValue = avgYValue(root);
    printf("Average y-value: %.2f\n", avgYValue);

    return 0;
}

