void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL && size > 0) {
        ptr = valloc(size);
    }
    return ptr;
}

void free_all_memory() {
    for (int i = 0; i < record_count; i++) {
        free(&records[i]);
    }
    free(records);
