void insert_record(int key, long offset, int value) {
    Record* new_record = my_malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;

    pthread_mutex_lock(&lock);

    if (record_count >= MAX_RECORDS) {
        printf("Error: Maximum number of records exceeded.\n");
        return;
    }

    // Check for duplicate keys
    for (int i = 0; i < record_count; i++) {
        if (new_record->key == records[i].key) {
            printf("Error: Duplicate key detected.\n");
            free(new_record);
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Insert new record
    Record* temp = &records[record_count];
    memcpy(temp, new_record, sizeof(Record));
    record_count++;

    pthread_mutex_unlock(&lock);
}

