#include <pthread.h>

#define RECORD_SIZE sizeof(struct record)
#define RANDOM_RANGE 1000

typedef struct {
    long offset;
    int key;
    int value;
} struct record;

void* allocateRecords(int numRecords, pthread_mutex_t* mutex) {
    void* records = malloc(numRecords * RECORD_SIZE);
    if (records == NULL) {
        LOG_ERROR("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    pthread_mutex_lock(mutex);
    for (int i = 0; i < numRecords; i++) {
        struct record* record = (struct record*) (records + i * RECORD_SIZE);
        record->offset = i;
        record->key = rand() % RANDOM_RANGE;
        record->value = rand() % RANDOM_RANGE;
    }
    pthread_mutex_unlock(mutex);

    return records;
}

void deallocateRecords(void* records, int numRecords) {
    free(records);
}

int main() {
    // Example usage
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    void* allocatedRecords = allocateRecords(10, &mutex);
    if (allocatedRecords == NULL) {
        return 1; // Allocation failed
    }

    // Use the allocated records...

    deallocateRecords(allocatedRecords, 10);

    return 0;
}
