#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct node {
    char* ptr;
    int index;
    double value;
} Node;

typedef struct event {
    Node* node;
    long timestamp;
} Event;

Node** nodes = NULL;
Event** events = NULL;
int numNodes = 0, numEvents = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && size > 0)
        printf("Memory allocation failed\n");
    return ptr;
}

void deallocate(void** arr) {
    for (int i = 0; i < numNodes; i++)
        free(arr[i]);
    free(arr);
}

void resize(int newSize) {
    Node** newNodes = (Node**)allocate(newSize * sizeof(Node*));
    Event** newEvents = (Event**)allocate(newSize * sizeof(Event*));

    for (int i = 0; i < newSize && i < numNodes; i++) {
        newNodes[i] = nodes[i];
        newEvents[i] = events[i];
    }

    deallocate((void**)&nodes);
    deallocate((void**)&events);

    nodes = newNodes;
    events = newEvents;

    pthread_mutex_lock(&lock);
    for (int i = numNodes; i < newSize; i++) {
        Node* newNode = (Node*)allocate(sizeof(Node));
        Event* newEvent = (Event*)allocate(sizeof(Event));

        newNode->ptr = NULL;
        newNode->index = -1;
        newNode->value = 0.0;

        newEvent->node = newNode;
        newEvent->timestamp = -1; // initialize with invalid timestamp

        nodes[i] = newNode;
        events[i] = newEvent;
    }
    pthread_mutex_unlock(&lock);

    numNodes = newSize;
}

Node* createNode(int index, double value) {
    Node* node = (Node*)allocate(sizeof(Node));
    node->index = index;
    node->value = value;
    return node;
}

void freeMemory() {
    deallocate((void**)&nodes);
    deallocate((void**)&events);

    numNodes = 0;
    numEvents = 0;
}

long getTimestamp() {
    static long prevTimestamp = -1;
    long currTimestamp;

    pthread_mutex_lock(&lock);
    currTimestamp = time(NULL);

    if (currTimestamp < prevTimestamp)
        printf("Warning: timestamp skipped, adjusting\n");

    pthread_mutex_unlock(&lock);

    return currTimestamp;
}

void addEvent(int index, double value) {
    pthread_mutex_lock(&lock);

    if (numEvents >= numNodes)
        resize(numNodes * 2); // grow by factor of two

    Node* node = createNode(index, value);
    Event* event = (Event*)allocate(sizeof(Event));
    event->node = node;
    event->timestamp = getTimestamp();

    nodes[numEvents] = node;
    events[numEvents]++) = event;

    pthread_mutex_unlock(&lock);

    numEvents++;
}

void printEvents() {
    for (int i = 0; i < numEvents; i++) {
        printf("Event %d: Node index = %d, value = %.2f, timestamp = %ld\n", i, events[i]->node->index, events[i]->node->value, events[i]->timestamp);
    }
}

int main() {
    // Example usage:
    addEvent(1, 3.14);
    addEvent(2, 2.71);
    printEvents();

    freeMemory();
    return 0;
}
