        profiles[i].age = -1;
        profiles[i].balance = 0.0;
    }

    return profiles;
}

// Function to handle transactions and update balances
void process_transactions(UserProfile* profiles, int num_profiles) {
    // Iterate through each profile and simulate a transaction
    for (int i = 0; i < num_profiles; i++) {
        if (!transaction(profiles[i].name, profiles[i].balance)) { // Simulate transaction
            printf("Transaction failed for user %s.\n", profiles[i].name);
            retry_transaction(profiles[i].name); // Retry the transaction
        } else {
            printf("Transaction successful for user %s.\n", profiles[i].name);
            update_balance(&profiles[i], 1.0); // Update balance
        }
    }
}

