    for (int i = 0; i < num_profiles; i++) {
        free(profiles[i].name); // Free each profile's name
    }
    free(profiles); // Free the array of profiles
}

// Function to simulate a transaction with the external payment processing library
bool transaction(const char* username, double amount) {
    // Call the payment processing library and handle its response
    return payment_process_transaction(username, amount);
}

// Function to retry a failed transaction
void retry_transaction(const char* username) {
    int retries = 0;

    while (retries < 3) { // Maximum of 3 retries
        if (!transaction(username, 1.0)) { // Simulate the transaction again
            printf("Transaction still failed after %d retries.\n", retries);
            return; // Abort retrying
        }

        break; // Transaction successful
    }

    printf("Maximum retries exceeded for user %s.\n", username);
}

