#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEASUREMENTS 1000000
#define RETENTION_PERIOD 300 // seconds

typedef struct {
    double value;
    time_t timestamp;
} Measurement;

typedef struct {
    float sensor_value;
    time_t timestamp;
} SensorMeasurement;

// Hash table structure
typedef struct {
    int size;
    pthread_mutex_t* mutex;
    Measurement** measurements;
} HashTable;

// Create a new hash table with the given size
HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->mutex = (pthread_mutex_t*)malloc(size * sizeof(pthread_mutex_t));
    table->measurements = (Measurement**)malloc(size * sizeof(Measurement*));
    for (int i = 0; i < size; i++) {
        pthread_mutex_init(&table->mutex[i], NULL);
        table->measurements[i] = NULL;
    }
    return table;
}

// Insert a new measurement into the hash table
void insert_measurement(HashTable* table, SensorMeasurement measurement) {
    int index = measurement.sensor_value % table->size;
    pthread_mutex_lock(&table->mutex[index]);
    Measurement* current = table->measurements[index];
    while (current != NULL && current->timestamp < measurement.timestamp) {
        Measurement* temp = current;
        current = current->next;
        free(temp);
    }
    Measurement* new_measurement = (Measurement*)malloc(sizeof(Measurement));
    new_measurement->value = measurement.sensor_value;
    new_measurement->timestamp = measurement.timestamp;
    new_measurement->next = current;
    table->measurements[index] = new_measurement;
    pthread_mutex_unlock(&table->mutex[index]);
}

// Remove measurements that are older than the retention period
void prune_measurements(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        pthread_mutex_lock(&table->mutex[i]);
        Measurement* current = table->measurements[i];
        while (current != NULL && current->timestamp + RETENTION_PERIOD * 1000 <= time(NULL)) {
            Measurement* temp = current;
            current = current->next;
            free(temp);
        }
        table->measurements[i] = current;
        pthread_mutex_unlock(&table->mutex[i]);
    }
}

// Print the contents of the hash table
void print_measurements(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        pthread_mutex_lock(&table->mutex[i]);
        Measurement* current = table->measurements[i];
        while (current != NULL) {
            printf("Sensor value: %f, timestamp: %ld\n", current->value, current->timestamp);
            current = current->next;
        }
        pthread_mutex_unlock(&table->mutex[i]);
    }
}

int main() {
    HashTable* table = create_hash_table(MAX_MEASUREMENTS);
    SensorMeasurement measurement1 = { 3.14f, time(NULL) };
    SensorMeasurement measurement2 = { 2.71f, time(NULL) - 1000 };
    insert_measurement(table, measurement1);
    insert_measurement(table, measurement2);
    prune_measurements(table);
    print_measurements(table);
    return 0;
}
