#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

// Define structure for Point
typedef struct {
    float x;
    float y;
} Point;

// Define structure for BST node
typedef struct Node {
    Point point;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new BST node
Node* createNode(Point p) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        return NULL;
    }
    newNode->point = p;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert a point into the BST
void insertPoint(Node** root, Point p) {
    Node* newNode = createNode(p);
    if (*root == NULL || (*root)->point.x > newNode->point.x) {
        *root = newNode;
    } else if ((*root)->point.x < newNode->point.x) {
        insertPoint(&((*root)->right), newNode->point);
    } else { // (*root)->point.x == newNode->point.x
        // Update y-coordinate of duplicate point
        newNode->point.y = (*root)->point.y;
    }
}

// Function to search for a point in the BST
Node* searchPoint(Node* root, float x) {
    if (root == NULL || root->point.x > x) {
        return NULL;
    } else if (root->point.x < x) {
        return searchPoint(root->right, x);
    } else { // root->point.x == x
        return root;
    }
}

// Function to free memory for the BST
void freeBST(Node** root) {
    Node* curr = *root;
    if (curr != NULL) {
        freeBST(&curr->left);
        freeBST(&curr->right);
        free(curr);
    }
    *root = NULL;
}

// Function to calculate average y-value of points in the BST
double calcAverageY(Node* root, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        Node* curr = root;
        while (curr != NULL && curr->point.x > i) {
            curr = curr->right;
        }
        if (curr != NULL && curr->point.x == i) {
            sum += curr->point.y;
        }
    }
    return sum / count;
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    // Create BST root node
    Node* root = NULL;

    // Initialize arrays for 'double' and 'struct Point' objects
    double* arrDouble = (double*)malloc(1000 * sizeof(double));
    Point* arrPoint = (Point*)malloc(1000 * sizeof(Point));

    // Populate arrays with random data
    for (int i = 0; i < 1000; i++) {
        arrDouble[i] = (double)rand() / RAND_MAX;
        arrPoint[i].x = (float)i;
        arrPoint[i].y = (float)rand() / RAND_MAX;
    }

    // Insert points into BST
    for (int i = 0; i < 1000; i++) {
        insertPoint(&root, arrPoint[i]);
    }

    // Calculate and print average y-value of points in the BST
    int count = 1000;
    double avgY = calcAverageY(root, count);
    printf("Average y-value: %f\n", avgY);

    // Free memory for arrays and BST
    free(arrDouble);
    free(arrPoint);
    freeBST(&root);

    return 0;
}
