    int num_strings;
    char*** strings = malloc(sizeof(char**) * num_strings);
    for (int i = 0; i < num_strings; i++) {
        strings[i] = malloc(sizeof(char*) * STR_LENGTH);
        fgets(strings[i], STR_LENGTH, stdin);

        // Trim newline character and null-terminate string
        strings[i][strlen(strings[i]) - 1] = '\0';
    }

    // Perform batch processing of input strings
    process_batch(num_strings, strings);

    return 0;
}
