void insert_hashtable(hashtable_t* htable, record_t* record) {
    uint64_t hash = record->data.value % htable->size;
    node_t* node = htable->buckets[hash];
    while (node != NULL && node->next != NULL) {
        node = node->next;
    }
    node->next = (node_t*)malloc(sizeof(node_t));
    node->next->data = *record;
    node->next->next = NULL;
}

