#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // attempt to allocate a smaller subset of the requested size
        for (size_t i = size / 2; i > 0; i /= 2) {
            ptr = realloc(NULL, i);
            if (ptr != NULL) break;
        }
        if (ptr == NULL) {
            printf("Memory allocation failed\n");
            return NULL;
        }
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

record* init_records(int num_records, int min_value, int max_value, int seed) {
    record* records = (record*)my_malloc(num_records * sizeof(record));
    if (records == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < num_records; i++) {
        int value = rand() % ((max_value + 1) - min_value) + min_value;
        records[i].value = value;
    }
    return records;
}
