typedef struct {
    int i;
    char data[16];
    double* ptr_double;
} record;

record** allocateMemory(int numRecords) {
    record** records = (record**)malloc(numRecords * sizeof(record*));

    if (!records) {
        printf("Memory allocation failed for records.\n");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i] = (record*)malloc(sizeof(record));

        if (!records[i]) {
            printf("Memory allocation failed for record %d.\n", i);
            for (int j = 0; j <= i; j++) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }
    }

    return records;
}

void deallocateMemory(record** records, int numRecords) {
    if (!records) return;

    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }

    free(records);
}

int main() {
