// Define data structures for records, items, and hash table entries
typedef struct {
    int id;
    float amount;
} record;

typedef struct node {
    record* transaction;
    struct node* next;
} item_node;

typedef struct {
    record* key;
    void* value;
} data_entry;

// Initialize JSON parser
json_object* config_json = NULL;

void process_transactions(int size, int num_items, record*** transactions) {
    // Create hash table and linked list
    json_object* load_factor_obj = json_object.GetObjectItem(config_json, "load_factor");
    float load_factor = atof(json_object_get_string(load_factor_obj));
    int load_factor_int = (int)(load_factor * 100);

    int resize_threshold = atoi(json_object_get_string(json_object.GetObjectItem(config_json, "resize_threshold")));
    char* memory_allocation_strategy = json_object_get_string(json_object.GetObjectItem(config_json, "memory_allocation_strategy"));

    // Initialize hash table and linked list based on configuration settings
    int num_buckets = (int)sqrt((double)size);
    data_entry** hash_table = (data_entry**)malloc(num_buckets * sizeof(data_entry*));
    for(int i = 0; i < num_buckets; i++) {
        hash_table[i] = (data_entry*)malloc(resize_threshold * sizeof(data_entry));
    }

    item_node* linked_list = NULL;
    record*** items = (record***)malloc(size * sizeof(record**));

    // Process transactions
    for(int i = 0; i < size; i++) {
        json_object* transaction_json = json_object.GetObjectItem(config_json, "transaction");
        record* transaction = (record*)malloc(sizeof(record));
        transaction->id = atoi(json_object_get_string(json_object.GetObjectItem(transaction_json, "id")));
        transaction->amount = atof(json_object_get_string(json_objectGetObjectItem(transaction_json, "amount")));

        // Add transaction to hash table and linked list
        int bucket_index = transaction->id % num_buckets;
        data_entry* entry = (data_entry*)malloc(sizeof(data_entry));
        entry->key = transaction;
        entry->value = NULL;

        if(hash_table[bucket_index] == NULL) {
            hash_table[bucket_index] = (data_entry*)malloc(resize_threshold * sizeof(data_entry));
        }
        int index = 0;
        while(index < resize_threshold && hash_table[bucket_index][index] != NULL) {
            index++;
        }
        hash_table[bucket_index][index] = entry;

        item_node* node = (item_node*)malloc(sizeof(item_node));
        node->transaction = transaction;
        node->next = linked_list;
        linked_list = node;

        // Add to array of items
        items[i] = &node->transaction;
    }

    // Print transaction with highest amount
    record*** max_amount_item = NULL;
    float max_amount = 0.0f;
    for(int i = 0; i < size; i++) {
        if(items[i]->amount > max_amount) {
            max_amount = items[i]->amount;
            max_amount_item = &items[i];
        }
    }

    printf("Transaction with highest amount: %d - %.2f\n", (*max_amount_item)->id, (*max_amount_item)->amount);

    // Free memory
    for(int i = 0; i < size; i++) {
        free(items[i]);
    }
    free(items);
    for(int i = 0; i < num_buckets; i++) {
        for(int j = 0; j < resize_threshold; j++) {
            free(hash_table[i][j].key);
            free(hash_table[i][j].value);
        }
        free(hash_table[i]);
    }
    free(hash_table);
    free(linked_list);

    // Exit
    return;
}
