#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct Record {
    int value;
    struct Record* next;
    struct Record* prev;
} Record;

// Define the linked list structure
typedef struct LinkedList {
    Record* head;
    Record* tail;
    int size;
} LinkedList;

// Function to initialize a new record with random value and return it
Record* createRecord(int min, int max) {
    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) {
        printf("Memory allocation failed\n");
        exit(-1);
    }
    rec->value = rand() % (max - min + 1) + min;
    rec->next = NULL;
    rec->prev = NULL;
    return rec;
}

// Function to create a new linked list and initialize it
LinkedList* createLinkedList(int size, int seed) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        printf("Memory allocation failed\n");
        exit(-1);
    }
    srand(seed);
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

// Function to insert a record at the head of the linked list
void insertRecord(LinkedList* list, Record* rec) {
    if (!list || !rec) {
        printf("Invalid input\n");
        return;
    }
    rec->next = list->head;
    if (list->head) {
        list->head->prev = rec;
    } else {
        list->tail = rec;
    }
    list->head = rec;
    list->size++;
}

// Function to delete a record from the linked list
void deleteRecord(LinkedList* list, Record* rec) {
    if (!list || !rec) {
        printf("Invalid input\n");
        return;
    }
    if (rec == list->head) {
        list->head = rec->next;
    } else if (rec == list->tail) {
        list->tail = rec->prev;
    }
    if (rec->next) {
        rec->next->prev = rec->prev;
    } else {
        list->head = rec->next;
    }
    if (rec->prev) {
        rec->prev->next = rec->next;
    } else {
        list->tail = rec->prev;
    }
    free(rec);
    list->size--;
}

// Function to filter and reorder the linked list based on key range
void filterAndReorder(LinkedList* list, int minKey, int maxKey) {
    if (!list || minKey > maxKey) {
        printf("Invalid input\n");
        return;
    }
    Record* current = list->head;
    Record* prev = NULL;
    while (current) {
        if (current->value < minKey || current->value > maxKey) {
            deleteRecord(list, current);
        } else if (prev && current->value < prev->value) {
            Record* temp = current->next;
            current->next = prev;
            prev->next = current;
            if (list->head == current) {
                list->head = current;
            }
            if (list->tail == current) {
                list->tail = current;
            }
            prev = current;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Function to find and print the largest integer in the array
void findMax(LinkedList* list) {
    if (!list) {
        printf("Linked list is empty\n");
        return;
    }
    Record* current = list->head;
    int max = current->value;
    while (current) {
        if (current->value > max) {
            max = current->value;
        }
        current = current->next;
    }
    printf("The largest integer is %d\n", max);
}

// Function to handle potential overflows when computing the hash value
int hash(int key) {
    return key % 31; // Replace with your actual hash function implementation
}

// Function to process input integers and perform necessary operations
void processIntegers(LinkedList* list, int size, int seed) {
    srand(seed);
    for (int i = 0; i < size; i++) {
        Record* rec = createRecord(1, 100); // Replace with your actual random value range
        if (!rec) {
            printf("Memory allocation failed\n");
            return;
        }
        int key = hash(rec->value);
        if (list && list->head && find(list->head, key)) {
            deleteRecord(list, rec);
            free(rec);
            continue; // Skip duplicates
        }
        insertRecord(list, rec);
    }
}

// Function to detect and handle potential overflows when computing the hash value
int main() {
    int size = 0;
    int seed = time(NULL); // Replace with your custom seed value
    printf("Enter the number of integers: ");
    scanf("%d", &size);
    LinkedList* list = createLinkedList(size, seed);
    processIntegers(list, size, seed);
    findMax(list);
    return 0;
}
