        timestamps[i] = time(NULL) + i;
        float val = pow(i, 2.0f); // calculate polynomial value
        floats[i] = val;

        entries[i] = (log_entry*)malloc(sizeof(log_entry));
        if (!entries[i]) {
            for (int j = 0; j < i; j++) {
                if (timestamps[j]) free((void*)timestamps[j]);
            }
            for (int j = 0; j < i; j++) {
                free((void*)entries[j]);
            }
            free(timestamps);
            free(floats);
            return NULL;
        }

        entries[i]->event_type = malloc(strlen("Event ") + 1);
        strcpy(entries[i]->event_type, "Event ");
        if (!entries[i]->event_type) {
            for (int j = 0; j < i; j++) {
                if (timestamps[j]) free((void*)timestamps[j]);
            }
            for (int j = 0; j < i; j++) {
                free((void*)entries[j]);
            }
            free(timestamps);
            free(floats);
            return NULL;
        }

        entries[i]->metadata = malloc(sizeof(int));
        if (!entries[i]->metadata) {
            for (int j = 0; j < i; j++) {
                if (timestamps[j]) free((void*)timestamps[j]);
            }
            for (int j = 0; j < i; j++) {
                free((void*)entries[j]);
            }
            free(timestamps);
            free(floats);
            return NULL;
        }

        entries[i]->timestamp = timestamps[i];
    }

    return entries;
}

void free_managed_memory(log_entry** entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        if (entries[i]->event_type) free((void*)entries[i]->event_type);
        free((void*)entries[i]->metadata);
        free(entries[i]);
    }

    for (int i = 0; i < num_entries; i++) {
        if (entries[i]) free((void*)entries[i]);
    }

    free(timestamps);
    free(floats);

    free(entries);
}
