memory_pool_t* initialize_memory_pool(size_t initial_capacity) {
    memory_pool_t* pool = (memory_pool_t*)malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->records = (record_t**)malloc(pool->capacity * sizeof(record_t*));
    pool->offset_index = (long*)malloc((pool->capacity + 1) * sizeof(long));
    for (int i = 0; i <= pool->capacity; i++) {
        pool->offset_index[i] = -1;
    }

    pthread_mutex_init(&pool->mutex, NULL);
    pool->count = 0;
    return pool;
}

void* allocate_record(memory_pool_t* pool) {
    record_t** new_records = (record_t**)malloc(pool->capacity * sizeof(record_t*));
    if (!new_records) return NULL;

    for (int i = 0; i < pool->count; i++) {
        new_records[i] = pool->records[i];
    }

    free(pool->records);
    pool->records = new_records;
    return &pool->records[pool->count++];
}

void deallocate_record(memory_pool_t* pool, record_t** record) {
    for (int i = 0; i < pool->capacity - 1; i++) {
        if (!record[i]) break;
    }

    free(record);
    for (int i = i + 1; i < pool->count; i++) {
        pool->records[i - 1] = pool->records[i];
        pool->offset_index[i] = pool->offset_index[i - 1];
    }

    pool->count--;
}

void resize_memory_pool(memory_pool_t* pool, size_t new_capacity) {
    memory_pool_t* new_pool = initialize_memory_pool(new_capacity);

    if (!new_pool) return;

    for (int i = 0; i < pool->count; i++) {
        record_t** record = &pool->records[i];
        *allocate_record(new_pool) = *record;
    }

    deallocate_record(pool, pool->records);

    *pool = *new_pool;
}

