void *my_malloc(size_t size) {
    // Calculate the total allocated memory
    static size_t total_allocated = 0;
    total_allocated += size;

    // Calculate the peak memory consumption
    static size_t peak_memory = 0;
    if (total_allocated > peak_memory)
        peak_memory = total_allocated;

    // Allocate and return the memory
    return malloc(size);
}

void my_free(void *ptr) {
    free(ptr);
}

// Define the function to manage cache
void cache_insert(Record *record) {
    // Check for cache fullness
    if (cache_count >= CACHE_SIZE) {
        // Evict the oldest record from the cache
        cache[0] = cache[cache_count - 1];
        cache_count--;
    }
    // Insert the new record in the cache
    cache[cache_count++] = *record;
}

Record *cache_search(int key) {
    for (int i = 0; i < cache_count; i++) {
        if (cache[i].key == key)
            return &cache[i];
    }
    return NULL;
}

// Define the function to manage memory pool
void resize_pool(size_t size) {
    // Check for memory pressure
    static size_t total_allocated = 0;
    static size_t peak_memory = 0;
    if (total_allocated + size > peak_memory * 2) {
        peak_memory += size;
        total_allocated += size;
        // Resize the memory pool and update statistics
        my_free(NULL);
    }
}

// Define the function to monitor memory usage
void log_memory_usage() {
