#define MAX_RECORDS 1000
#define MAX_DATASETS 10

typedef struct record {
    int key;
    long offset;
} Record;

typedef struct dataset {
    int id;
    Record *records;
    int num_records;
    pthread_mutex_t lock;
} Dataset;

Dataset datasets[MAX_DATASETS];
int num_datasets = 0;
pthread_mutex_t lock_all;

void init_dataset(int id) {
    if (num_datasets >= MAX_DATASETS) {
        printf("Error: Maximum number of datasets reached.\n");
        return;
    }
    datasets[num_datasets].id = id;
    datasets[num_datasets].records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    datasets[num_datasets].num_records = 0;
    pthread_mutex_init(&datasets[num_datasets].lock, NULL);
    pthread_mutex_lock(&lock_all);
    num_datasets++;
    pthread_mutex_unlock(&lock_all);
}

void validate_dataset(int id) {
    pthread_mutex_lock(&lock_all);
    for (int i = 0; i < num_datasets; i++) {
        if (datasets[i].id == id) {
            printf("Dataset %d exists.\n", id);
            return;
        }
    }
    printf("Error: Dataset %d does not exist.\n", id);
    pthread_mutex_unlock(&lock_all);
}

void merge_dataset(int from_id, int to_id) {
    pthread_mutex_lock(&lock_all);
    for (int i = 0; i < num_datasets; i++) {
        if (datasets[i].id == from_id) {
            Record *records = datasets[i].records;
            int j = 0;
            while (j < datasets[i].num_records) {
                datasets[to_id].records[datasets[to_id].num_records].key = records[j].key;
                datasets[to_id].records[datasets[to_id].num_records].offset = records[j].offset;
                j++;
                datasets[to_id].num_records++;
            }
            free(records);
            datasets[from_id].num_records = 0;
        }
    }
    pthread_mutex_unlock(&lock_all);
}

void reset_dataset(int id) {
    pthread_mutex_lock(&lock_all);
    for (int i = 0; i < num_datasets; i++) {
        if (datasets[i].id == id) {
            free(datasets[i].records);
            datasets[i].num_records = 0;
            return;
        }
    }
    printf("Error: Dataset %d does not exist.\n", id);
    pthread_mutex_unlock(&lock_all);
}

void* thread_func(void *arg) {
    int dataset_id = *(int *)arg;
    init_dataset(dataset_id);
    // perform operations on the dataset
    merge_dataset(dataset_id, 0); // merge with dataset 0
    reset_dataset(dataset_id);
    return NULL;
}

int main() {
    pthread_t threads[MAX_DATASETS];
    for (int i = 0; i < MAX_DATASETS; i++) {
        int *dataset_id = malloc(sizeof(int));
        *dataset_id = i;
        pthread_create(&threads[i], NULL, thread_func, dataset_id);
    }
    for (int i = 0; i < MAX_DATASETS; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
