    ImageMetadata metadata;
    struct Node* prev;
    struct Node* next;
} Node;

void processImagesAndComputeMetadata(char* dir_path, int max_images, int enable_parallel_processing) {
    // Initialize variables and data structures
    Node* head = NULL;
    Node* tail = NULL;
    ImageMetadata* metadata_array = (ImageMetadata*)calloc(max_images, sizeof(ImageMetadata));
    char buffer[BUFFER_SIZE];

    // Seed pseudo-random number generator with user-provided value
    srand(time(NULL));

    DIR* dir = opendir(dir_path);
    if (!dir) {
        printf("Error opening directory: %s\n", strerror(errno));
        return;
    }

    int image_count = 0;
    while (image_count < max_images && (struct dirent*)readdir(dir)) {
        // Read and parse each file
        char* file_path = malloc(strlen(dir_path) + strlen((struct dirent*)readdir(dir))->d_name + 2);
        sprintf(file_path, "%s/%s", dir_path, (struct dirent*)readdir(dir)->d_name);

        // Initialize metadata fields with random values
        metadata_array[image_count].width = rand() % 1000;
        metadata_array[image_count].height = rand() % 800;
        strcpy(metadata_array[image_count].compression, "JPEG");

        // Add record to linked list
        Node* new_node = malloc(sizeof(Node));
        new_node->metadata = metadata_array[image_count];
        new_node->prev = NULL;
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }

        image_count++;
    }
    closedir(dir);

    // Find and print metadata of the highest resolution image
    Node* current = head;
    ImageMetadata max_metadata = current->metadata;

    for (current = head; current != NULL; current = current->next) {
        if (current->metadata.width > max_metadata.width || (current->metadata.width == max_metadata.width && current->metadata.height > max_metadata.height)) {
            max_metadata = current->metadata;
        }
    }

    printf("Image with highest resolution: %dx%d, bit depth: %d, compression: %s\n", max_metadata.width, max_metadata.height, max_metadata.bit_depth, max_metadata.compression);

    // Free memory and data structures
    for (Node* node = head; node != NULL; ) {
        Node* next_node = node->next;
        free(node);
        node = next_node;
    }
    free(metadata_array);
}

