// Define a hash table to track frequency of file path accesses
typedef struct {
    unsigned long long key;
    int value;
    struct hashNode* next;
} HashNode;

// Function to process file paths and maintain linked list and hash table
void processFilePaths() {
    // Initialize linked list and hash table
    Node* head = NULL;
    HashNode* hashTable[100000];  // Assume max 100,000 unique file paths
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    int count = 0;
    while (1) {
        char line[256];
        fgets(line, sizeof(line), stdin);

        if (feof(stdin)) break;  // End of input

        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->path = strdup(line);
        newNode->timestamp = time(NULL);
        newNode->accessCount = 1;

        pthread_mutex_lock(&mutex);
        // Insert node into linked list
        if (head == NULL) head = newNode;
        else {
            Node* current = head;
            while (current->next != NULL) current = current->next;
            current->next = newNode;
        }

        // Update hash table
        int index = strlen(line);
        HashNode* currentHashNode = &hashTable[index];
        while (currentHashNode->next != NULL) currentHashNode = currentHashNode->next;
        currentHashNode->key = index;
        currentHashNode->value = 1;

        pthread_mutex_unlock(&mutex);

        // Periodic integration with external data source
        if (count++ % 100 == 0) {
            int result = integrateWithExternalSource();
            if (result < 0) {
                printf("Error integrating with external source\n");
                exit(-1);
            }
        }
    }

    // Find most frequently accessed file and print its path along with access count
    pthread_mutex_lock(&mutex);
    Node* current = head;
    int maxAccessCount = 0;
    char* mostFrequentFile = NULL;
    while (current != NULL) {
        if (current->accessCount > maxAccessCount) {
            maxAccessCount = current->accessCount;
            mostFrequentFile = current->path;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);

    printf("Most frequently accessed file: %s with access count %d\n", mostFrequentFile, maxAccessCount);
}

int main() {
    processFilePaths();
    return 0;
}
