#include <time.h>

typedef struct packet {
    unsigned int id;
    unsigned int seq_num;
    time_t timestamp;
    struct packet* next;
} Packet;

void process_packets(int num_packets) {
    srand(time(NULL)); // seed the PRNG

    Packet** packets = (Packet**)malloc(num_packets * sizeof(Packet*));
    for (int i = 0; i < num_packets; i++) {
        Packet* packet = (Packet*)malloc(sizeof(Packet));
        packet->id = rand();
        packet->seq_num = rand();
        packet->timestamp = time(NULL);
        packet->next = NULL;

        if (i > 0) {
            packets[i-1]->next = packet;
        }
        packets[i] = packet;
    }

    // print the packet with the highest sequence number
    Packet* max_packet = NULL;
    unsigned int max_seq_num = 0;
    for (int i = 0; i < num_packets; i++) {
        if (packets[i]->seq_num > max_seq_num) {
            max_packet = packets[i];
            max_seq_num = packets[i]->seq_num;
        }
    }
    printf("Packet with highest sequence number: id %u, seq_num %u, timestamp %ld\n", 
           max_packet->id, max_packet->seq_num, max_packet->timestamp);

    // free allocated memory
    for (int i = 0; i < num_packets; i++) {
        Packet* packet = packets[i];
        while (packet != NULL) {
            Packet* next = packet->next;
            free(packet);
            packet = next;
        }
    }
    free(packets);
}
