typedef struct {
    char* path;
    int timestamp;
} FileObject;

typedef struct Node {
    FileObject* fileObject;
    struct Node* next;
} Node;

Node* createNode(FileObject* fileObject) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->fileObject = fileObject;
    newNode->next = NULL;
    return newNode;
}

void freeNode(Node* node) {
    if (node == NULL)
        return;
    free(node->fileObject);
    free(node);
}

typedef struct {
    Node* head;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    return list;
}

void freeLinkedList(LinkedList* list) {
    while (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    free(list);
}

typedef struct {
    int* timestamps;
} TimestampMap;

TimestampMap* createTimestampMap(int capacity) {
    TimestampMap* map = (TimestampMap*)malloc(sizeof(TimestampMap));
    map->timestamps = (int*)malloc((capacity + 1) * sizeof(int));
    return map;
}

void freeTimestampMap(TimestampMap* map) {
    free(map->timestamps);
    free(map);
}

typedef struct {
    void** keys;
    int capacity;
} HashTable;

HashTable* createHashTable(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->keys = (void**)malloc((capacity + 1) * sizeof(void*));
    return table;
}

void freeHashTable(HashTable* table) {
    free(table->keys);
    free(table);
}

void processFilePaths(FILE* file, int capacity) {
    LinkedList* list = createLinkedList();
    TimestampMap* map = createTimestampMap(capacity);
    HashTable* table = createHashTable(capacity);

    srand(time(NULL));  // Initialize random number generator

    FileObject* fileObjects;
    Node* nodes;

    int i = 0, count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        FileObject* fileObject = (FileObject*)malloc(sizeof(FileObject));
        fileObject->path = strdup(buffer);
        fileObject->timestamp = rand() % 100;  // Random timestamp
        Node* node = createNode(fileObject);

        // Add to linked list and hash table
        if (list->head == NULL) {
            list->head = node;
        } else {
            nodes = list->head;
            while (nodes->next != NULL) {
                nodes = nodes->next;
            }
            nodes->next = node;
        }

        // Add to timestamp map
        int index = fileObject->timestamp % capacity;
        if (map->timestamps[index] == 0) {
            map->timestamps[index]++;
        } else {
            map->timestamps[index]++;
        }

        // Add to hash table
        int keyIndex = strlen(buffer);
        for (int j = 0; j < capacity; j++) {
            if (table->keys[j] == NULL || strcmp(buffer, (char*)table->keys[j]) < 0) {
                void** tempKeys = (void**)malloc((j + 1) * sizeof(void*));
                for (int k = 0; k <= j; k++) {
                    tempKeys[k] = table->keys[k];
                }
                free(table->keys);
                table->keys = tempKeys;
                table->keys[j] = buffer;
                break;
            }
        }

        // Update count
        i++;
    }

    printf("Most frequently accessed file path: %s\n", (char*)table->keys[0]);
    printf("Access count: %d\n", map->timestamps[0]);

    free(fileObjects);
    free(nodes);
    freeLinkedList(list);
    freeTimestampMap(map);
    freeHashTable(table);
}

int main() {
    processFilePaths(stdin, 100);  // Process file paths from standard input
    return 0;
}
