// Node structure
typedef struct node {
    double value;
    struct node* left;
    struct node* right;
} Node;

// Hash table structure
typedef struct {
    char* key;
    double value;
} KVPair;
typedef struct {
    size_t size;
    KVPair** data;
} HashTable;

// Balanced Binary Search Tree (BST) operations
Node* insert(Node* root, double value);
void deleteNode(Node** rootRef, Node* node);

// Function to find and print the largest number in the array
void printLargest(double* arr, size_t n);

// Helper function for concurrent access testing
void* concurrentAccess(void* arg);

int main() {
    // Read configuration file
    json_object* config = json_object_from_file("config.json");
    if (!config) {
        fprintf(stderr, "Error reading configuration file\n");
        return 1;
    }

    // Initialize BST and hash table with dynamic memory allocation
    Node* root = NULL;
    HashTable ht = {0};
    ht.data = (KVPair**)malloc(sizeof(KVPair*) * 10);

    // Initialize logging mechanism
    FILE* logFile = fopen("log.txt", "w");
    setvbuf(logFile, NULL, _IONLY, BUFSIZ);
    int verbosityLevel = 1; // Set to desired level (0: silent, 1: normal, 2: verbose)

    // Process dataset and populate BST and hash table
    size_t dataSize = json_object_size(config);
    double* dataArr = (double*)malloc(sizeof(double) * dataSize);
    for (size_t i = 0; i < dataSize; i++) {
        json_object* obj = json_object_object_get(config, i);
        if (!obj) continue;
        double value = json_real_object_get(obj, "value");
        // Add node to BST and insert into hash table
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->value = value;
        root = insert(root, value);
        KVPair* kv = (KVPair*)malloc(sizeof(KVPair));
        kv->key = (char*)malloc(strlen(json_object_get_string(obj, "key")) + 1);
        strcpy(kv->key, json_object_get_string(obj, "key"));
        kv->value = value;
        ht.data[ht.size++] = kv;
    }

    // Find and print the largest number in the array
    size_t n = dataSize;
    printLargest(dataArr, n);

    // Test concurrent access
    pthread_t threads[2];
    for (int i = 0; i < 2; i++) {
        pthread_create(&threads[i], NULL, concurrentAccess, &ht);
        sleep(1); // Simulate delay between thread creations
    }
    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free memory and close log file
    free(dataArr);
    for (size_t i = 0; i < ht.size; i++) {
        free(ht.data[i]->key);
        free(ht.data[i]);
    }
    free(ht.data);
    json_object_put(config);
    fclose(logFile);

    return 0;
}

// Node insertion and deletion functions
Node* insert(Node* root, double value) {
    if (root == NULL) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->value = value;
        newNode->left = newNode->right = NULL;
        return newNode;
    }
    if (value < root->value) {
        root->left = insert(root->left, value);
    } else if (value > root->value) {
        root->right = insert(root->right, value);
    }
    return root;
}

void deleteNode(Node** rootRef, Node* node) {
    // Implementation of BST deletion
}

// Helper function for concurrent access testing
void* concurrentAccess(void* arg) {
    HashTable* ht = (HashTable*)arg;
    // Simulate concurrent insertion and deletion
    for (size_t i = 0; i < ht->size / 2; i++) {
        KVPair* kv = ht->data[i];
        // Insertion: update key-value pair and rebalance BST
        kv->key = (char*)malloc(strlen("new_key") + 1);
        strcpy(kv->key, "new_key");
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->value = kv->value;
        root = insert(root, kv->value);

        // Deletion: remove key-value pair and rebalance BST
        free(kv->key);
        free(kv);
    }
    return NULL;
}
