    pthread_t threads[4];

    // Initialize random number generator
    srand(time(NULL));

    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transactions[i] = malloc(sizeof(Transaction));
    }

    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, transaction_manager, NULL);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        free(transactions[i]);
    }
}

void* transaction_manager(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);

        // Generate a new transaction and add it to the hash table and BST
        Transaction* new_transaction = malloc(sizeof(Transaction));
        strcpy(new_transaction->id, "Transaction");
        new_transaction->timestamp = time(NULL);
        new_transaction->amount = (double)rand() / RAND_MAX * AMOUNT_RANGE;
        new_transaction->status = 'A';

        // Add the transaction to the hash table
        int hash_value = (int)hash_function(new_transaction->id, hashtbl_size);
        HashNode* current_hash_node = hash_table + hash_value;
        while (current_hash_node && current_hash_node->data) {
            current_hash_node = current_hash_node->next;
        }
        current_hash_node->data = new_transaction;

        // Add the transaction to the BST
        BSTNode* current_bst_node = bst_root;
        while (current_bst_node) {
            if (new_transaction->timestamp < current_bst_node->data->timestamp) {
                break;
            } else if (new_transaction->timestamp > current_bst_node->data->timestamp) {
                if (!current_bst_node->left) {
                    current_bst_node->left = malloc(sizeof(BSTNode));
                    current_bst_node->left->data = new_transaction;
                    current_bst_node->left->right = NULL;
                    current_bst_node->left->left = NULL;
                    break;
                } else {
                    current_bst_node = current_bst_node->left;
                }
            } else {
                if (!current_bst_node->right) {
                    current_bst_node->right = malloc(sizeof(BSTNode));
                    current_bst_node->right->data = new_transaction;
                    current_bst_node->right->right = NULL;
                    current_bst_node->right->left = NULL;
                    break;
                } else {
                    current_bst_node = current_bst_node->right;
                }
            }
        }

        transactions_count++;

        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

int hash_function(char* str, int size) {
    int sum = 0;
    for (int i = 0; i < strlen(str); i++) {
        sum += (int)str[i];
    }
    return sum % size;
}
