Node* create_node(Transaction transaction) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->transaction = transaction;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void insert_node(Node** root, Transaction transaction) {
    if (*root == NULL) {
        *root = create_node(transaction);
    } else {
        Node* current = *root;
        while (1) {
            if (transaction.timestamp < current->transaction.timestamp) {
                if (current->left == NULL) {
                    current->left = create_node(transaction);
                    break;
                }
                current = current->left;
            } else {
                if (current->right == NULL) {
                    current->right = create_node(transaction);
                    break;
                }
                current = current->right;
            }
        }
    }
}

void free_tree(Node* root) {
    if (root != NULL) {
        free_tree(root->left);
        free_tree(root->right);
        free(root);
    }
