#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct node {
    double value;
    struct node* next;
    struct node* prev;
} Node;

Node* circular_list_init(int size, int min_val, int max_val) {
    if (size <= 0 || min_val >= max_val)
        return NULL;

    srand(time(NULL));
    Node* head = malloc(sizeof(Node));
    if (!head)
        return NULL;

    head->value = (double)(rand() % (max_val - min_val + 1)) + min_val;
    head->next = head; // Circular list
    head->prev = head;

    for (int i = 1; i < size; i++) {
        Node* node = malloc(sizeof(Node));
        if (!node)
            return NULL;

        node->value = (double)(rand() % (max_val - min_val + 1)) + min_val;
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
        head = node;
    }

    return head;
}

void circular_list_insert(Node** head, double value) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node)
        return;

    new_node->value = value;
    new_node->next = (*head)->next;
    new_node->prev = (*head);
    (*head)->next->prev = new_node;
    (*head)->next = new_node;
    *head = new_node;
}

void circular_list_remove(Node** head, double value) {
    Node* current = (*head);
    do {
        if (current->value == value) {
            current->next->prev = current->prev;
            current->prev->next = current->next;
            free(current);
            *head = (*head)->next;
            return;
        }
        current = current->next;
    } while (current != (*head));
}

void circular_list_traversal(Node* head) {
    Node* current = head;
    do {
        printf("%f\n", current->value);
        current = current->next;
    } while (current != head);
}

int main() {
    int size = 10;
    double min_val = 0.0, max_val = 1.0;
    Node* head = circular_list_init(size, (int)min_val, (int)max_val);

    if (!head)
        return -1;

    // Example usage
    circular_list_insert(&head, 0.5);
    circular_list_traversal(head);

    // Remove a node
    circular_list_remove(&head, 0.7);

    circular_list_traversal(head);

    free(head);

    return 0;
}

