// Define structure for session
typedef struct {
    char id[16];
    time_t timestamp;
    int status;
    struct node *preferences; // Linked list of key-value pairs
} Session;

// Define structure for preferences node
typedef struct node {
    char key[8];
    int value;
    struct node *next;
} Node;

// Function to create a new session
Session* create_session(const char* id, time_t timestamp) {
    Session* session = (Session*)malloc(sizeof(Session));
    strcpy(session->id, id);
    session->timestamp = timestamp;
    session->status = 'A'; // Active by default
    session->preferences = NULL; // Initialize preferences list
    return session;
}

// Function to add a preference to the session
void add_preference(Session* session, const char* key, int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    strcpy(new_node->key, key);
    new_node->value = value;
    new_node->next = session->preferences;
    session->preferences = new_node;
}

// Function to validate the integrity of data structures
int validate_session(Session* session) {
    if (!session || !session->id[0] || time(NULL) - session->timestamp > 60 * 60) {
        return 0; // Session is invalid or expired
    }
    Node* current = session->preferences;
    while (current) {
        if (!current->key[0] || current->value < 0 || current->value > 100) {
            return 0; // Preference is invalid
        }
        current = current->next;
    }
    return 1; // Session and preferences are valid
}

// Function to manage sessions
int manage_sessions(Session** sessions, int num_sessions) {
    time_t now = time(NULL);
    for (int i = 0; i < num_sessions; i++) {
        if (!validate_session(sessions[i])) {
            printf("Session %s is invalid or expired.\n", sessions[i]->id);
            continue;
        }
        Node* current = sessions[i]->preferences;
        while (current) {
            printf("Preference %s: %d\n", current->key, current->value);
            current = current->next;
        }
    }
}

int main() {
    // Initialize random number generator with custom seed
    srand(time(NULL));

    Session* sessions[10]; // Array to store session structures

    for (int i = 0; i < 5; i++) {
        char id[16];
        sprintf(id, "Session_%d", i);
        time_t timestamp = time(NULL) - rand() % 60 * 60;
        Session* session = create_session(id, timestamp);
        add_preference(session, "Preference1", rand() % 100);
        sessions[i] = session;
    }

    manage_sessions(sessions, 5);

    // Clean up memory
    for (int i = 0; i < 5; i++) {
        free(sessions[i]->preferences); // Free preference list
        free(sessions[i]); // Free session structure
    }
}
