    int* keys = ((int(*)[5])arrays)[0];
    Record** records = ((Record** (*)[5])arrays)[1];
    char** metadataTags = ((char** (*)[5])arrays)[2];
    FILE** auditLogs = ((FILE** (*)[5])arrays)[3];

    // Set values and timestamp for each record
    srand(time(NULL));
    for (int i = 0; i < 5; i++) {
