        records[i] = record;
    }
}

void validateFields(Record* record) {
    // Validate int and float fields
    if (record->value < 0 || record->value > 100) {
        printf("Invalid value: %d\n", record->value);
    }
    if (record->timestamp < 0.0f || record->timestamp > 1.0f) {
        printf("Invalid timestamp: %f\n", record->timestamp);
    }
}

void insertRecord(Record* record, void* arrays) {
    // Insert record into linked list
    Node* newNode = malloc(sizeof(Node));
    newNode->record = *record;
    newNode->next = NULL;

    // Update arrays
    ((long(*)[5])arrays)[0]++;
    ((int(*)[5])arrays)[1][((char*)records) - (char*)arrays] = record->value;
}

void updateRecord(Record* record, void* arrays) {
    // Update existing record in linked list
    Node* node = malloc(sizeof(Node));
    node->record = *record;
    node->next = NULL;

    // Update arrays
    ((long(*)[5])arrays)[0]++;
    ((int(*)[5])arrays)[1][((char*)records) - (char*)arrays] = record->value;
}

void deleteRecord(Record* record, void* arrays) {
    // Delete record from linked list
    Node* node = malloc(sizeof(Node));
    node->record = *record;
    node->next = NULL;

    // Update arrays
    ((long(*)[5])arrays)[0]--;
    ((int(*)[5])arrays)[1][((char*)records) - (char*)arrays] = record->value;
}

void* queryRecords(void* arrays, int keyRange, float timestampRange) {
    // Query records meeting specific criteria
    void* result = malloc(sizeof(void));
    Node* node = ((Node*)arrays);
    while (node != NULL) {
        Record* record = &node->record;
        if (keyRange[0] <= record->value && record->value <= keyRange[1]
            && timestampRange[0] <= record->timestamp
            && record->timestamp <= timestampRange[1]) {
            // Add record to result array
            void* resultRecord = malloc(sizeof(Record));
            *resultRecord = *record;
            result = (void*)resultRecord;
        }
    }
}

int main() {
    size_t size = 10;
    void* arrays = allocateArrays(size);
    initializeArrays(arrays);

    // Validate fields
    for (int i = 0; i < size; i++) {
        validateFields(((Record*)arrays)[i]);
    }

    // Insert record into linked list
    Record record;
    record.value = rand() % 100;
    record.timestamp = (float)srand();
    insertRecord(&record, arrays);

    // Update record in linked list
    updateRecord(&record, arrays);

    // Delete record from linked list
    deleteRecord(&record, arrays);

    // Query records meeting specific criteria
    int keyRange[2] = {0, 100};
    float timestampRange[2] = {0.0f, 1.0f};
    void* result = queryRecords(arrays, keyRange, timestampRange);

    return 0;
}

