// Define the node structure for the distributed hash table
typedef struct Node {
    char* key;
    int value;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to dynamically allocate memory and initialize a distributed hash table
void* createDistributedHashTable(int size, int seed) {
    // Initialize random number generator with custom seed
    srand(seed);

    // Dynamically allocate memory for the hash table
    void* hashTable = malloc(sizeof(Node*) * size);

    // Iterate through each node in the hash table
    for (int i = 0; i < size; i++) {
        Node* newNode = malloc(sizeof(Node));

        // Set a random value within the specified range for the node's value
        newNode->value = rand() % 100;

        // Initialize pointers for the doubly linked list
        newNode->prev = NULL;
        newNode->next = NULL;

        // Add the new node to the hash table
        Node** nodes = (Node**)hashTable;
        nodes[i] = newNode;
    }

    return hashTable;
}
