    priority_queue* pq = init_priority_queue(MAX_PRIORITY_QUEUE);

    // Read configuration file
    json_object* config = read_config_file("config.json");

    // Parse configuration file and initialize hash table and priority queue
    int load_factor = json_object_get_int(config, "load_factor");
    double priority_threshold = json_object_get_double(config, "priority_threshold");

    // Initialize and process transactions
    transaction_entry* transactions = (transaction_entry*)malloc(MAX_TRANSACTIONS * sizeof(transaction_entry));
    int num_transactions = 0;

    while (!feof(stdin)) {
        transaction_entry* transaction = (transaction_entry*)malloc(sizeof(transaction_entry));

        // Read transaction data from standard input
        fscanf(stdin, "%d %lf", &transaction->id, &transaction->amount);

        // Validate transaction integrity
        if (transaction->id < 1 || transaction->amount < 0.0) {
            // Log error and skip transaction
            error_log("Invalid transaction: ID = %d, Amount = %.2f", transaction->id, transaction->amount);
            free(transaction);
            continue;
        }

        // Add transaction to priority queue
        add_transaction(pq, transaction);

        num_transactions++;

        if (num_transactions >= MAX_TRANSACTIONS) {
            printf("Transaction limit reached. Aborting.\n");
            break;
        }
    }

    process_transactions(ht, pq);

    // Free all allocated memory
    free_hash_table(ht);
    free_priority_queue(pq);

    return 0;
}

