#include <string.h>
#include <time.h>

typedef struct Transaction {
    long timestamp;
    double amount;
} Transaction;

// Function prototypes
Transaction* addTransaction(Transaction* head, long timestamp, double amount);
Transaction* updateTransaction(Transaction* head, long timestamp, double amount);
Transaction* getTransaction(Transaction* head, long timestamp);

int main() {
    // Initialize the transaction list
    Transaction* head = NULL;

    // Add transactions
    head = addTransaction(head, 1643723400, 100.0);
    head = addTransaction(head, 1643723410, 200.0);

    // Update a transaction
    head = updateTransaction(head, 1643723400, 150.0);

    // Retrieve a transaction
    Transaction* trans = getTransaction(head, 1643723410);
    printf("Timestamp: %ld, Amount: %f\n", trans->timestamp, trans->amount);

    return 0;
}

// Function to add a new transaction
Transaction* addTransaction(Transaction* head, long timestamp, double amount) {
    // Create a new Transaction structure
    Transaction* newTrans = (Transaction*)malloc(sizeof(Transaction));
    newTrans->timestamp = timestamp;
    newTrans->amount = amount;

    if (head == NULL) {
        // If the list is empty, set the new transaction as the head
        head = newTrans;
    } else {
        // Find the last transaction in the list and add the new one after it
        Transaction* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newTrans;
    }

    return head;
}

// Function to update an existing transaction
Transaction* updateTransaction(Transaction* head, long timestamp, double amount) {
    // Find the transaction with the given timestamp and update its amount
    Transaction* current = head;
    while (current != NULL && current->timestamp != timestamp) {
        current = current->next;
    }
    if (current == NULL) {
        // If the transaction is not found, print an error message
        printf("Transaction not found: %ld\n", timestamp);
        return head;  // Return the original list
    } else {
        current->amount = amount;
    }

    return head;
}

// Function to retrieve a transaction by its timestamp
Transaction* getTransaction(Transaction* head, long timestamp) {
    // Find the transaction with the given timestamp and return it
    Transaction* current = head;
    while (current != NULL && current->timestamp != timestamp) {
        current = current->next;
    }
    if (current == NULL) {
        // If the transaction is not found, print an error message
        printf("Transaction not found: %ld\n", timestamp);
        return NULL;  // Return NULL to indicate failure
    } else {
        return current;  // Return the retrieved transaction
    }
}
