// Define structure for records
typedef struct {
    long offset;
    int key;
    struct record {
        int value;
        char status;
    } data;
} record_t;

// Define structure for hash table
typedef struct {
    size_t size;
    record_t** buckets;
} hash_table_t;

// Initialize hash table with given size
hash_table_t* init_hash_table(size_t size) {
    hash_table_t* ht = (hash_table_t*)malloc(sizeof(hash_table_t));
    ht->size = size;
    ht->buckets = (record_t**)malloc((size + 1) * sizeof(record_t*));
    for (size_t i = 0; i <= size; i++) {
        ht->buckets[i] = NULL;
    }
    return ht;
}

// Insert record into hash table
void insert_record(hash_table_t* ht, long offset, int key, int value, char status) {
    size_t index = (size_t)(offset % ht->size);
    record_t* rec = (record_t*)malloc(sizeof(record_t));
    rec->offset = offset;
    rec->key = key;
    rec->data.value = value;
    rec->data.status = status;
    if (!ht->buckets[index]) {
        ht->buckets[index] = rec;
    } else {
        record_t* prev = NULL;
        for (record_t** p = &ht->buckets[index]; *p; p = &(record_t*)((*p)->offset % (size_t)ht->size)) {
            if (((record_t)*(*p)).key == key) {
                free(rec);
                return;
            }
            prev = *p;
        }
        *p = rec;
    }
}

// Update record in hash table
void update_record(hash_table_t* ht, long offset, int value, char status) {
    size_t index = (size_t)(offset % ht->size);
    for (record_t** p = &ht->buckets[index]; *p; p = &(record_t*)((*p)->offset % (size_t)ht->size)) {
        if (((record_t)*(*p)).key == offset / ht->size) {
            ((record_t)*(*p))->data.value = value;
            ((record_t)*(*p))->data.status = status;
            return;
        }
    }
}

// Print records in hash table
void print_records(hash_table_t* ht) {
    for (size_t i = 0; i < ht->size; i++) {
        for (record_t** p = &ht->buckets[i]; *p; p = &(record_t*)((*p)->offset % (size_t)ht->size)) {
            printf("Offset: %ld, Key: %d, Value: %d, Status: %c\n", (*p)->offset, (*p)->key, (*p)->data.value, (*p)->data.status);
        }
    }
}

int main() {
    size_t capacity = 1000;
    record_t* records = (record_t*)malloc(capacity * sizeof(record_t));
    hash_table_t* ht = init_hash_table(10);

    // Insert and update records
    for (size_t i = 0; i < capacity; i++) {
        insert_record(ht, i, i, i + 1, 'A');
    }
    for (size_t i = 0; i < capacity / 2; i++) {
        update_record(ht, i * 2, i * 2 + 3, 'B');
    }

    // Print records
    print_records(ht);

    // Release memory
    free(records);
    free(ht->buckets);
    free(ht);

    return 0;
}
