    }

    // Free allocated memory
    free(hash_table);
    record_free(records);

    return 0;
}

void insert_record(int key, int value) {
    // Find available slot in hash table using open addressing
    int index = key % hash_table_size;
    while (hash_table[index] != -1 && hash_table[index] != key) {
        index = (index + 1) % hash_table_size;
    }

    if (hash_table[index] == -1) {
        // Insert new record into hash table
        hash_table[index] = key;
        hash_table_count++;

        // Resize hash table when necessary
        if (hash_table_count > hash_table_size * 0.8) {
            resize_hash_table();
        }
    } else {
        // Update existing record value in hash table
        hash_table[index] = value;
    }

    // Insert new record into records array
    records[record_count].key = key;
    records[record_count].value = value;
    record_count++;
}

void process_records() {
    for (int i = 0; i < hash_table_size; i++) {
        if (hash_table[i] != -1) {
            // Process record with frequency information
            log_event("Processing key %d, value %d\n", hash_table[i], records[hash_table_count].value);

            // Update cache lines and blocks
            // ...
        }
    }
}

void resize_hash_table() {
    int new_size = hash_table_size * 2;

    // Reallocate hash table memory
    unsigned int* new_hash_table = (unsigned int*)malloc(new_size * sizeof(unsigned int));

    for (int i = 0; i < hash_table_size; i++) {
        if (hash_table[i] != -1) {
            // Rehash existing records into new hash table
            int index = hash_table[i] % new_size;
            while (new_hash_table[index] != -1 && new_hash_table[index] != hash_table[i]) {
                index = (index + 1) % new_size;
            }

            if (new_hash_table[index] == -1) {
                new_hash_table[index] = hash_table[i];
            } else {
                // Update existing record value in new hash table
                new_hash_table[index] = value;
            }
        }
    }

    // Swap old and new hash tables
    unsigned int* temp = hash_table;
    hash_table = new_hash_table;
    new_hash_table = temp;

    free(temp);
}

void log_event(const char* message) {
    printf("%s\n", message);
