    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

// Function to add a record to the linked list
void addRecord(Node** head, Record* data) {
    Node* newNode = newNode(*data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        newNode->next = *head;
        (*head)->prev = newNode;
        *head = newNode;
    }
}

// Function to find the largest integer in the array
int findLargest(Node* head, int size) {
    Node* current = head;
    int max = current->data.value;
    while (current != NULL) {
        if (current->data.value > max) {
            max = current->data.value;
        }
        current = current->next;
    }
    return max;
}

// Function to free all allocated memory
void freeMemory(Node* head, int size) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    // Initialize the random number generator with a custom seed value
    initRNG(12345);

    // Parse the configuration file
    JSON_T config;
    int result = parseConfig("config.json", &config);
    if (result < 0) {
        printf("Error parsing configuration file: %s\n", json_strerror(result));
        return 1;
    }

    // Read integers from standard input
    int* array = NULL;
    int size = 0;
    while (fscanf(stdin, "%d", &size) == 1 && size > 0) {
        array = (int*)realloc(array, (size + 1) * sizeof(int));
        for (int i = 0; i < size; i++) {
            array[i] = randomInt(1, 100);
        }
    }

    // Create a doubly linked list to store records
    Node* head = NULL;
    for (int i = 0; i < size; i++) {
        Record record;
        record.key = i;
        record.value = array[i];
        addRecord(&head, &record);
    }

    // Find and print the largest integer in the array
    int max = findLargest(head, size);
    printf("The largest integer is: %d\n", max);

    // Free all allocated memory
    freeMemory(head, size);

    return 0;
}
