#define MAX_ADDRESS_LENGTH 50
#define MAX_LINKED_LIST_SIZE 1000

typedef struct {
    char* address;
    int last_used;
} Node;

Node* linked_list = NULL;
int linked_list_size = 0;

typedef struct {
    char* key;
    int frequency;
} MapEntry;

MapEntry** map = NULL;
int map_size = 0;

void process_addresses() {
    FILE* file = stdin;
    char line[MAX_ADDRESS_LENGTH];
    Node* current_node = NULL;
    MapEntry* current_map_entry = NULL;

    while (fgets(line, MAX_ADDRESS_LENGTH, file) != NULL) {
        // Process the address and add it to the linked list
        current_node = malloc(sizeof(Node));
        current_node->address = strdup(line);
        current_node->last_used = time(NULL);

        if (linked_list == NULL || linked_list_size >= MAX_LINKED_LIST_SIZE) {
            Node* new_list = malloc((MAX_LINKED_LIST_SIZE * 2 + 1) * sizeof(Node));
            memcpy(new_list, linked_list, linked_list_size * sizeof(Node));
            free(linked_list);
            linked_list = new_list;
        }

        if (linked_list_size > 0) {
            Node* prev_node = linked_list + linked_list_size - 1;
            current_node->address = realloc(current_node->address, strlen(prev_node->address) + 1);
            strcpy(current_node->address, prev_node->address);
        }

        linked_list[linked_list_size++] = *current_node;

        // Add the address to the map
        current_map_entry = malloc(sizeof(MapEntry));
        current_map_entry->key = strdup(line);
        current_map_entry->frequency = 1;

        if (map == NULL || map_size >= MAX_LINKED_LIST_SIZE) {
            MapEntry** new_map = malloc((MAX_LINKED_LIST_SIZE * 2 + 1) * sizeof(MapEntry*));
            memcpy(new_map, map, map_size * sizeof(MapEntry*));
            free(map);
            map = new_map;
        }

        if (map_size > 0) {
            MapEntry* prev_entry = map[map_size - 1];
            current_map_entry->key = realloc(current_map_entry->key, strlen(prev_entry->key) + 1);
            strcpy(current_map_entry->key, prev_entry->key);
        }

        if (map_size < MAX_LINKED_LIST_SIZE) {
            map[map_size++] = *current_map_entry;
        }
    }

    fclose(file);

    // Free all allocated memory
    for (int i = 0; i < linked_list_size; i++) {
        free(linked_list[i].address);
    }
    free(linked_list);

    for (int i = 0; i < map_size; i++) {
        free(map[i]->key);
    }
    free(map);
}
