typedef struct transaction {
    double amount;
    char description[256];
    time_t timestamp;
} transaction;

transaction* create_transaction(double amount, const char* description) {
    transaction* trans = (transaction*)malloc(sizeof(transaction));
    trans->amount = amount;
    strcpy(trans->description, description);
    return trans;
}

void free_transactions(transaction** transactions, int size) {
    for(int i = 0; i < size; i++) {
        if(transactions[i] != NULL) {
            free(transactions[i]);
        }
    }
    free(transactions);
}

transaction* add_transaction(transaction** transactions, int* size, double amount, const char* description) {
    transaction* new_trans = create_transaction(amount, description);
    *transactions = (transaction**)realloc(*transactions, (*size + 1) * sizeof(transaction*));
    (*transactions)[*size] = new_trans;
    (*size)++;
    return new_trans;
}

void find_highest_amount(void** transactions, int size) {
    transaction* highest_trans = NULL;
    double highest_amount = -INFINITY;

    for(int i = 0; i < size; i++) {
        if(transactions[i]->amount > highest_amount) {
            highest_amount = transactions[i]->amount;
            highest_trans = (transaction*)transactions[i];
        }
    }

    printf("Transaction with the highest amount: %f - %s\n", highest_trans->amount, highest_trans->description);
}

int main() {
    int socket_fd = 0;
    // Create socket here...

    int buffer_size = 256;
    char buffer[buffer_size];

    int size = 0;

    transaction** transactions = NULL;

    while(read(socket_fd, buffer, buffer_size) > 0) {
        double amount = atof(buffer);
        char* description = strtok(buffer, ", ");
        time_t timestamp = time(NULL);

        transaction* new_trans = add_transaction(&transactions, &size, amount, description);

        // Reset buffer for next read
        memset(buffer, '\0', buffer_size);
    }

    find_highest_amount(transactions, size);

    free_transactions(transactions, size);
    close(socket_fd);

    return 0;
}

