#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

#define MAX_MEMORY_USAGE 0.75
#define SYSTEM_MEMORY_THRESHOLD (1024 * 1024 * 750) // 750MB

typedef struct {
    int id;
    void* data; // pointer to external data source
} Vertex;

typedef struct {
    int from;
    int to;
    void* edge_data; // pointer to external data source
} Edge;

int total_memory_usage = 0;
int system_memory_available = SYSTEM_MEMORY_THRESHOLD;

void* allocate_vertex(int id) {
    if (total_memory_usage + sizeof(Vertex) > system_memory_available * MAX_MEMORY_USAGE) {
        return NULL; // insufficient memory
    }
    Vertex* vertex = malloc(sizeof(Vertex));
    vertex->id = id;
    total_memory_usage += sizeof(Vertex);
    return vertex;
}

void* allocate_edge(int from, int to) {
    if (total_memory_usage + sizeof(Edge) > system_memory_available * MAX_MEMORY_USAGE) {
        return NULL; // insufficient memory
    }
    Edge* edge = malloc(sizeof(Edge));
    edge->from = from;
    edge->to = to;
    total_memory_usage += sizeof(Edge);
    return edge;
}

void update_vertex(Vertex* vertex, void* data) {
    if (vertex->data != NULL) {
        free(vertex->data); // release previous memory
    }
    vertex->data = malloc(strlen((char*)data) + 1);
    strcpy((char*)vertex->data, (char*)data);
}

void update_edge(Edge* edge, void* data) {
    if (edge->edge_data != NULL) {
        free(edge->edge_data); // release previous memory
    }
    edge->edge_data = malloc(strlen((char*)data) + 1);
    strcpy((char*)edge->edge_data, (char*)data);
}

void deallocate_vertex(Vertex* vertex) {
    if (vertex->data != NULL) {
        free(vertex->data); // release memory
    }
    free(vertex); // release vertex struct itself
    total_memory_usage -= sizeof(Vertex);
}

void deallocate_edge(Edge* edge) {
    if (edge->edge_data != NULL) {
        free(edge->edge_data); // release memory
    }
    free(edge); // release edge struct itself
    total_memory_usage -= sizeof(Edge);
}
