void traverseAndPrintEntries(std::shared_ptr<Entry>& head) {
    for (std::shared_ptr<Entry> curr = head; curr != nullptr; curr = curr->next) {
        if (curr->isValid) {
            std::cout << "Key: " << curr->key << ", Status: Valid" << std::endl;
        }
    }
}

