#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    Record data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* createRecord(int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data.value = value;
    return node;
}

void freeRecords(Node** headRef, int size) {
    while (*headRef != NULL) {
        Node* temp = *headRef;
        *headRef = (*headRef)->next;
        free(temp);
    }
}

int findLargest(int* keys, long* offsets, Node* head, int size) {
    int largest = INT_MIN;
    Node* current = head;
    while (current != NULL) {
        if (keys[current->data.value] > largest)
            largest = keys[current->data.value];
        current = current->next;
    }
    return largest;
}

void serialize(Node* head, FILE* file) {
    Node* current = head;
    fwrite(&head, sizeof(Node), 1, file);
    while (current != NULL) {
        fwrite(&current->data.value, sizeof(int), 1, file);
        current = current->next;
    }
}

Node* deserialize(FILE* file) {
    Node* head = NULL;
    int size = 0;
    fread(&head, sizeof(Node), 1, file);
    while (fread(&size, sizeof(int), 1, file)) {
        for (int i = 0; i < size; i++) {
            Record record;
            fread(&record.value, sizeof(int), 1, file);
            Node* node = createRecord(record.value);
            if (head == NULL)
                head = node;
            else
                node->prev = head;
            head->next = node;
            head = node;
        }
    }
    return head;
}

void printRecords(Node* head) {
    while (head != NULL) {
        printf("%d ", head->data.value);
        head = head->next;
    }
    puts("");
}

int main(int argc, char** argv) {
    int size;
    FILE* file;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s [size]\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "%d", &size) != 1 || size <= 0) {
        fprintf(stderr, "Invalid size.\n");
        return 1;
    }

    if (fopen("serialized.bin", "wb") == NULL) {
        fprintf(stderr, "Failed to open file for serialization.\n");
        return 1;
    }

    Node* head = NULL;

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        Record record;
        record.value = rand() % 100 + 1;
        Node* node = createRecord(record.value);
        if (head == NULL)
            head = node;
        else
            node->prev = head;
        head->next = node;
    }

    printRecords(head);

    int largest = findLargest(NULL, NULL, head, size);

    printf("Largest integer: %d\n", largest);

    serialize(head, file);
    fclose(file);

    return 0;
}
