// Function to initialize a record with random value and temperature
Record* init_record(int min_value, int max_value) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->value = rand() % (max_value - min_value + 1) + min_value;
    record->temperature = (double)(rand() % 1000) / 10.0; // Generate a random temperature value
    return record;
