// Function to print the largest integer and temperature in their respective arrays
void print_max_values(int* integers, double* temperatures, int size) {
    int max_int = *integers;
    double max_temp = *temperatures;
    for (int i = 0; i < size; i++) {
        if (integers[i] > max_int) max_int = integers[i];
        if (temperatures[i] > max_temp) max_temp = temperatures[i];
    }
    printf("Largest integer: %d\n", max_int);
    printf("Largest temperature: %.2lf\n", max_temp);
}

