    if (!offsets) {
        printf("Failed to allocate memory for offsets array.\n");
        return;
    }

    // Initialize all elements in offsets to zero.
    for (int i = 0; i < n; i++) {
        offsets[i] = 0;
    }

    // Allocate memory for keys array
    int* keys = (int*)malloc(n * sizeof(int));

    if (!keys) {
        printf("Failed to allocate memory for keys array.\n");
        free(offsets);
        return;
    }

    // Initialize all elements in keys to zero.
    for (int i = 0; i < n; i++) {
        keys[i] = 0;
    }

    // Allocate memory for records array
    struct Record* records = (struct Record*)malloc(n * sizeof(struct Record));

    if (!records) {
        printf("Failed to allocate memory for records array.\n");
        free(offsets);
        free(keys);
        return;
    }

    // For each record in records, initialize the key field to a random value between 0 and n - 1 (inclusive).
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        records[i].key = rand() % n;
    }

    long unique_offset = 0;
    // Set the offset field of each record to a random value between 0 and MAX_OFFSET, ensuring no two records have the same offset value.
    for (int i = 0; i < n; i++) {
        while (1) {
            records[i].offset = rand() % (MAX_OFFSET + 1);
            int duplicate = 0;
            for (int j = 0; j < i; j++) {
                if (records[j].offset == records[i].offset) {
                    duplicate = 1;
                    break;
                }
            }
            if (!duplicate) {
                break;
            }
        }
    }

    // Return the pointer to the records array.
    return records;
}
