        char str[1024];
        for (int j = 0; j < 1024; j++) {
            if (text[i+j] == '\0') break;
            str[j] = text[i+j];
            str[j+1] = '\0';
        }
        entry_t* entry = create_entry(str, min_key++, NULL);
        for (int k = capacity; k > 0; k--) {
            if (list[k-1] == NULL) {
                list[k-1] = entry;
                break;
            }
        }
