#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct packet {
    int seq_num;
    time_t timestamp;
    struct packet* next;
} packet;

typedef struct hash_table {
    int bucket_size;
    char** keys;
    int** values;
    packet** buckets;
    int size;
} hash_table;

hash_table* init_hash_table(int bucket_size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    table->bucket_size = bucket_size;
    table->keys = (char**)malloc(bucket_size * sizeof(char*));
    table->values = (int**)malloc(bucket_size * sizeof(int*));
    table->buckets = (packet**)malloc(bucket_size * sizeof(packet*));
    table->size = 0;
    return table;
}

void insert_into_hash_table(hash_table* table, char* key, int value) {
    int hash = strlen(key) % table->bucket_size;
    packet* temp = table->buckets[hash];
    if (!temp) {
        table->buckets[hash] = (packet*)malloc(sizeof(packet));
        temp = table->buckets[hash];
    }
    while (temp->next) {
        temp = temp->next;
    }
    temp->seq_num = value;
    temp->timestamp = time(NULL);
    temp->next = NULL;
}

void process_packets(int packet_count, int* packet_ids, hash_table* table) {
    srand(packet_ids[0]);
    for (int i = 0; i < packet_count; i++) {
        packet* new_packet = (packet*)malloc(sizeof(packet));
        new_packet->seq_num = rand() % 1000;
        new_packet->timestamp = time(NULL);
        new_packet->next = NULL;

        // Initialize the array of packet identifiers
        if (!table->keys) {
            table->keys = (char**)malloc(packet_count * sizeof(char*));
            table->values = (int*)malloc(packet_count * sizeof(int));
        }
        strcpy(table->keys[i], "Packet_");
        itoa(new_packet->seq_num, table->values[i], 10);

        // Insert the packet into the hash table
        insert_into_hash_table(table, table->keys[i], new_packet->seq_num);
    }

    // Find and print the packet with the highest sequence number
    packet* max_packet = NULL;
    for (int i = 0; i < packet_count; i++) {
        if (!max_packet || new_packet->seq_num > max_packet->seq_num) {
            max_packet = new_packet;
        }
    }
    printf("Packet with the highest sequence number: seq_num=%d, timestamp=%ld\n", max_packet->seq_num, max_packet->timestamp);

    // Clean up and free all allocated memory
    for (int i = 0; i < packet_count; i++) {
        free(new_packet);
        new_packet = NULL;
    }
}

int main(int argc, char** argv) {
    int packet_count = atoi(argv[1]);
    int* packet_ids = (int*)malloc(packet_count * sizeof(int));
    // Initialize the hash table with the specified bucket size
    hash_table* table = init_hash_table(10);

    process_packets(packet_count, packet_ids, table);

    // Free all allocated memory
    for (int i = 0; i < table->size; i++) {
        free(table->keys[i]);
        free(table->values[i]);
    }
    free(table->keys);
    free(table->values);
    free(table->buckets);
    free(table);

    return 0;
}
