typedef struct profile_entry {
    char* name;
    char* email;
    time_t timestamp;
    char* status;
} profile_entry;

typedef struct task {
    time_t timestamp;
    char* status;
    int priority;
} task;

typedef struct follower_node {
    char* username;
    struct follower_node* next;
} follower_node;

void print_task(task t) {
    printf("Task: Timestamp - %ld, Status - %s, Priority - %d\n", t.timestamp, t.status, t.priority);
}

profile_entry* parse_profiles(const char* filename, int* count) {
    profile_entry* profiles = (profile_entry*)malloc(MAX_PROFILES * sizeof(profile_entry));
    json_object* root = json_object_from_file(filename);
    if (!root) return NULL;

    int i = 0;
    json_object_iter* iter;
    for(iter = json_object_iter_begin(root); iter != json_object_iter_end(root); iter = json_object_iter_next(iter)) {
        profile_entry* profile = &profiles[i];
        profile->name = strdup(json_object_get_string(iter->key));
        profile->email = strdup(json_object_get_string(json_object_object_get_string(root, "email")));
        profile->timestamp = json_object_get_int(iter->value);
        profile->status = strdup(json_object_get_string(iter->value));

        i++;
    }
    *count = i;
    free_json_object(root);
    return profiles;
}

task* parse_tasks(const char* filename, int* count) {
    task* tasks = (task*)malloc(MAX_TASKS * sizeof(task));
    json_object* root = json_object_from_file(filename);
    if (!root) return NULL;

    int i = 0;
    json_object_iter* iter;
    for(iter = json_object_iter_begin(root); iter != json_object_iter_end(root); iter = json_object_iter_next(iter)) {
        task* task = &tasks[i];
        task->timestamp = time(NULL);
        task->status = strdup(json_object_get_string(iter->value));
        task->priority = rand() % PRIORITY_RANGE;

        i++;
    }
    *count = i;
    free_json_object(root);
    return tasks;
}

follower_node* parse_followers(const char* filename, int* count) {
    follower_node* followers = (follower_node*)malloc(MAX_FOLLOWERS * sizeof(follower_node));
    json_object* root = json_object_from_file(filename);
    if (!root) return NULL;

    int i = 0;
    json_object_iter* iter;
    for(iter = json_object_iter_begin(root); iter != json_object_iter_end(root); iter = json_object_iter_next(iter)) {
        follower_node* follower = &followers[i];
        follower->username = strdup(json_object_get_string(iter->value));
        follower->next = NULL;

        i++;
    }
    *count = i;
    free_json_object(root);
    return followers;
}

void find_max_followers(profile_entry* profiles, int count) {
    profile_entry* max_follower = &profiles[0];
    for(int i = 1; i < count; i++) {
        if(profiles[i].name && strlen(profiles[i].name) > strlen(max_follower->name)) {
            max_follower = &profiles[i];
        }
    }
    printf("User with most followers: %s\n", max_follower->name);
}

task* find_max_priority(task* tasks, int count) {
    task* max_priority = &tasks[0];
    for(int i = 1; i < count; i++) {
        if(tasks[i].priority > max_priority->priority) {
            max_priority = &tasks[i];
        }
    }
    printf("Task with highest priority: %s\n", max_priority->status);
}

int main() {
    int profile_count;
    profile_entry* profiles = parse_profiles("profiles.json", &profile_count);

    int task_count;
    task* tasks = parse_tasks("tasks.json", &task_count);

    int follower_count;
    follower_node* followers = parse_followers("followers.json", &follower_count);

    find_max_followers(profiles, profile_count);
    find_max_priority(tasks, task_count);

    free(profiles);
    free(tasks);
    return 0;
}
