#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure to represent a record
typedef struct Record {
    int value;
    struct Record* next;
    struct Record* prev;
} Record;

// Function to initialize the random number generator
void initRNG() {
    srand(time(NULL));
}

// Function to generate a random integer within a specified range
int randInt(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Function to create a new record with a random value and insert it into the linked list
void addRecord(Record** head, Record** tail, int size) {
    Record* newRecord = malloc(sizeof(Record));
    if (newRecord == NULL) {
        return;
    }

    newRecord->value = randInt(0, 100); // Generate a random value within the specified range
    newRecord->next = NULL;
    newRecord->prev = *tail;

    if (*head != NULL) {
        (*head)->prev = &newRecord;
    }
    else {
        *head = newRecord;
    }

    *tail = newRecord;
}

// Function to remove a record from the linked list and free its memory
void removeRecord(Record** head, Record** tail) {
    if (*tail == NULL) {
        return;
    }

    Record* temp = *tail;
    *tail = temp->prev;

    if (temp->next != NULL) {
        temp->next->prev = *tail;
    }
    else {
        *head = *tail;
    }

    free(temp);
}

// Function to print the largest integer in the array
void findLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    printf("The largest integer is: %d\n", max);
}

// Function to serialize the data structure and write it to a file
void serializeRecords(Record* head, FILE* file) {
    // Serialize the linked list of records
    fwrite(&head, sizeof(Record), 1, file);

    // Serialize the array of 'long' offsets
    int offset = 0;
    while (head != NULL) {
        fwrite(&offset, sizeof(long), 1, file);
        head = head->next;
    }
}

// Function to deserialize the data structure from a file
Record* deserializeRecords(FILE* file) {
    Record* head = malloc(sizeof(Record));
    fread(&head, sizeof(Record), 1, file);

    // Deserialize the array of 'long' offsets
    int offset = 0;
    Record* current = head;
    while (fread(&offset, sizeof(long), 1, file) == 1) {
        current->value = offset; // Set the value to the deserialized offset
        current = current->next;
    }

    return head;
}

// Main function
int main() {
    int size;
    printf("Enter the size of the arrays: ");
    scanf("%d", &size);

    if (size <= 0) {
        printf("Invalid input. Please enter a positive integer.\n");
        return 1;
    }

    Record* head = NULL;
    Record* tail = NULL;

    // Initialize the random number generator
    initRNG();

    int* offsets = malloc(sizeof(int) * size);
    if (offsets == NULL) {
        printf("Failed to allocate memory for offsets.\n");
        return 1;
    }

    int* keys = malloc(sizeof(int) * size);
    if (keys == NULL) {
        printf("Failed to allocate memory for keys.\n");
        free(offsets);
        return 1;
    }

    // Initialize the arrays with random values
    for (int i = 0; i < size; i++) {
        offsets[i] = randInt(0, 100); // Generate a random offset within the specified range
        keys[i] = randInt(0, 100);     // Generate a random key within the specified range
    }

    int* records = malloc(sizeof(int) * size);
    if (records == NULL) {
        printf("Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        return 1;
    }

    // Initialize the array of records with random values
    for (int i = 0; i < size; i++) {
        records[i] = randInt(0, 100);     // Generate a random record value within the specified range
    }

    // Create a linked list of records
    head = NULL;
    tail = NULL;
    for (int i = 0; i < size; i++) {
        addRecord(&head, &tail, size);
    }

    // Print the largest integer in the array
    findLargest(records, size);

    // Serialize the data structure and write it to a file
    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        return 1;
    }

    serializeRecords(head, file);

    fclose(file);

    // Deserialize the data structure from the file
    file = fopen("data.bin", "rb");
    if (file == NULL) {
        printf("Failed to open file for reading.\n");
        return 1;
    }

    head = deserializeRecords(file);

    fclose(file);

    return 0;
}
