#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    time_t* timestamp;
} Record;

typedef struct Node {
    Record record;
    struct Node* prev;
    struct Node* next;
} Node;

Node* createRecord(int size, int min, int max) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->record.value = rand() % (max - min + 1) + min;
    node->timestamp = (time_t*)malloc(sizeof(time_t));
    *node->timestamp = time(NULL);

    node->prev = NULL;
    node->next = NULL;

    return node;
}

void freeRecord(Node* record) {
    if (!record) return;

    free(record->timestamp);
    free(record);

    return;
}

int insertNode(Node** head, Record* record) {
    Node* newNode = createRecord(1, 0, INT_MAX);
    if (!newNode) return -1;

    if (*head == NULL || (*head)->record.value > newNode->record.value) {
        newNode->next = *head;
        (*head)->prev = &newNode->next;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current && current->next && current->record.value < newNode->record.value) {
            current = current->next;
        }
        if (current->record.value > newNode->record.value) {
            newNode->prev = &current->prev;
            newNode->next = current;
            if (newNode->prev) newNode->prev->next = newNode;
            else *head = newNode;
            current->prev = &newNode;
        } else {
            current->next = newNode;
            newNode->prev = &current;
            newNode->next = NULL;
        }
    }

    return 0;
}

int deleteNode(Node** head, Record* record) {
    Node* current = *head;
    while (current && current->record.value != record->value) {
        current = current->next;
    }
    if (!current) return -1;

    if (current == *head) {
        *head = current->next;
        (*head)->prev = NULL;
    } else {
        current->prev->next = current->next;
        if (current->next) current->next->prev = current->prev;
        else current->prev->next = NULL;
    }

    freeRecord(current);

    return 0;
}

void printList(Node* head) {
    Node* current = head;
    while (current) {
        printf("Value: %d, Timestamp: %lu\n", current->record.value, *current->timestamp);
        current = current->next;
    }
}

int main() {
    int size;
    srand(time(NULL)); // Initialize pseudo-random number generator

    printf("Enter the size of the arrays: ");
    scanf("%d", &size);

    if (size <= 0) {
        printf("Invalid size. Please enter a positive integer.\n");
        return -1;
    }

    Node* head = NULL;

    for (int i = 0; i < size; i++) {
        Record record;
        // Initialize record fields
        record.value = rand() % 100 + 1;
        record.timestamp = (time_t*)malloc(sizeof(time_t));
        *record.timestamp = time(NULL);

        if (insertNode(&head, &record) == -1) {
            printf("Error inserting record.\n");
            return -1;
        }
    }

    printList(head);

    deleteNode(&head, &record); // Delete a specific record

    return 0;
}
