#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define MEM_LIMIT 1024 * 1024 * 500 // 500MB

// Custom hash function for mapping keys to records
unsigned int custom_hash(int key) {
    return (key * 1103515245 + 12345) % MAX_RECORDS;
}

// Record structure with initialized integer value
typedef struct record {
    int key;
    int value;
} Record;

// Hash table with dynamic resizing and chaining for collision resolution
typedef struct {
    Record **table;
    int capacity;
    int size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(int initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->table = (Record**)calloc(initial_capacity, sizeof(Record*));
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void resize_hash_table(HashTable* table) {
    int new_capacity = table->capacity * 2;
    Record** new_table = (Record**)realloc(table->table, sizeof(Record*) * new_capacity);
    for(int i = 0; i < table->size; i++) {
        new_table[i] = table->table[i];
    }
    free(table->table);
    table->table = new_table;
    table->capacity = new_capacity;
}

void insert_record(HashTable* table, int key) {
    unsigned int index = custom_hash(key);
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = rand() % 100; // Initialize with random value
    if(table->table[index] == NULL) {
        table->table[index] = record;
    } else {
        Record* prev_record = table->table[index];
        while(prev_record->next != NULL) {
            prev_record = prev_record->next;
        }
        prev_record->next = record;
    }
    table->size++;
}

Record* lookup_record(HashTable* table, int key) {
    unsigned int index = custom_hash(key);
    Record* current = table->table[index];
    while(current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
