// Define a custom data structure to store processed data
typedef struct {
    double value;
    int index;
} DataElement;

typedef struct Node {
    DataElement data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
} DoublyLinkedList;

// Function to generate a random alphanumeric string
char* generate_random_string(int length) {
    char* result = (char*)malloc((length + 1) * sizeof(char));
    for (int i = 0; i < length; i++) {
        if ((rand() % 2) == 0) {
            // Randomly choose between alphanumeric characters
            result[i] = (char)(('a' + (rand() % 26)));
        } else {
            result[i] = (char)(('0' + (rand() % 10)));
        }
    }
    result[length] = '\0';
    return result;
}

// Function to process and store data
void process_and_store_data(DoublyLinkedList* data_list, char* filename) {
    // Initialize the data list
    data_list->head = NULL;
    data_list->tail = NULL;

    // Extract base name and extension from the input filename
    char* base_name = strtok(filename, ".");
    char* file_extension = strtok(NULL, ".");

    // Generate a random alphanumeric string for the new filename
    int length = rand() % (5 - 10) + 5;
    char* random_string = generate_random_string(length);
    char* new_base_name = (char*)malloc((strlen(base_name) + strlen(random_string) + 1) * sizeof(char));
    strcpy(new_base_name, base_name);
    strcat(new_base_name, random_string);

    // Modify the file extension to include the current date
    time_t now = time(NULL);
    char* timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = '\0';
    char* new_file_extension = (char*)malloc((strlen(file_extension) + strlen(timestamp) + 1) * sizeof(char));
    strcpy(new_file_extension, file_extension);
    strcat(new_file_extension, timestamp);

    // Ensure the new filename does not exceed a total length of 255 characters
    if ((strlen(new_base_name) + strlen(new_file_extension)) > 255) {
        printf("Error: New filename exceeds maximum length.\n");
        return;
    }

    // Process and store data from the external source
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Unable to open file.\n");
        return;
    }
    double value;
    while (fscanf(file, "%lf", &value) == 1) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->data.value = value;
        // Validate the integrity of the data structure
        if (data_list->head == NULL || data_list->tail == NULL) {
            data_list->head = new_node;
            data_list->tail = new_node;
        } else {
            Node* current = data_list->head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
            new_node->prev = current;
            data_list->tail = new_node;
        }
    }
    fclose(file);

    // Free allocated memory upon function completion
    free(random_string);
    free(new_base_name);
    free(new_file_extension);
}
