#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the custom node structure
typedef struct {
    char* str;
    int val;
    struct node* next;
} record;

// Define the custom hash table structure
typedef struct {
    long capacity;
    long size;
    record** bucket;
    pthread_mutex_t lock;
} hashtable;

// Initialize a new record with given string and random value within range [min, max]
record* init_record(const char* str, int min, int max) {
    record* node = (record*)malloc(sizeof(record));
    node->str = strdup(str);
    node->val = rand() % (max - min + 1) + min;
    node->next = NULL;
    return node;
}

// Initialize a new hash table with given capacity
hashtable* init_hashtable(long capacity) {
    hashtable* table = (hashtable*)malloc(sizeof(hashtable));
    table->capacity = capacity;
    table->size = 0;
    table->bucket = (record**)calloc(capacity, sizeof(record*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Insert a record into the hash table with given key
void insert_hashtable(hashtable* table, int key, record* node) {
    long index = key % table->capacity;
    pthread_mutex_lock(&table->lock);
    if (table->bucket[index] == NULL) {
        table->bucket[index] = node;
    } else {
        record* prev = table->bucket[index];
        while (prev->next != NULL) {
            prev = prev->next;
        }
        prev->next = node;
    }
    pthread_mutex_unlock(&table->lock);
}

// Lookup a record in the hash table with given key
record* lookup_hashtable(hashtable* table, int key) {
    long index = key % table->capacity;
    pthread_mutex_lock(&table->lock);
    record* node = table->bucket[index];
    while (node != NULL && node->next != NULL) {
        if (node->val == key) {
            break;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
    return node;
}

// Serialize the hash table and record array to disk in a compact format
void serialize(hashtable* table, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return;
    }
    fwrite(&table->capacity, sizeof(long), 1, file);
    fwrite(&table->size, sizeof(long), 1, file);
    for (long i = 0; i < table->capacity; i++) {
        record* node = table->bucket[i];
        while (node != NULL) {
            fwrite(&node->val, sizeof(int), 1, file);
            fwrite(node->str, strlen(node->str) + 1, 1, file);
            node = node->next;
        }
    }
    fclose(file);
}

// Deserialize the hash table and record array from disk in a compact format
hashtable* deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;
    }
    hashtable* table = (hashtable*)malloc(sizeof(hashtable));
    fread(&table->capacity, sizeof(long), 1, file);
    fread(&table->size, sizeof(long), 1, file);
    table->bucket = (record**)calloc(table->capacity, sizeof(record*));
    for (long i = 0; i < table->capacity; i++) {
        record* node = NULL;
        while (fread(&node->val, sizeof(int), 1, file) == 1) {
            char buffer[1024];
            fread(buffer, strlen(buffer) + 1, 1, file);
            node->str = strdup(buffer);
            node->next = NULL;
            table->bucket[i] = node;
        }
    }
    fclose(file);
    return table;
}

int main() {
    // Initialize the random number generator with a timestamp seed
    srand(time(NULL));

    // Create a new hash table with capacity 1024
    hashtable* table = init_hashtable(1024);

    // Insert records into the hash table with given keys
    for (long i = 0; i < 10000; i++) {
        record* node = init_record("record", 1, 10);
        insert_hashtable(table, i, node);
    }

    // Lookup a record in the hash table with given key
    record* node = lookup_hashtable(table, 5);
    if (node != NULL) {
        printf("Found record: %s, val: %d\n", node->str, node->val);
    } else {
        printf("Record not found\n");
    }

    // Serialize the hash table and record array to disk
    serialize(table, "data.bin");

    // Deserialize the hash table and record array from disk
    hashtable* deserialized_table = deserialize("data.bin");

    // Cleanup memory management
    for (long i = 0; i < 1024; i++) {
        record* node = deserialized_table->bucket[i];
        while (node != NULL) {
            free(node->str);
            free(node);
            node = node->next;
        }
    }
    free(deserialized_table);

    return 0;
}
