        (*records)[i].data->key = (*keys)[i];
        (*records)[i].data->value = rand() % 100;

        // Initialize linked list node
        (*records)[i].next = NULL;
        (*records)[i].prev = NULL;
    }
}

// Function to free allocated memory
void cleanup(int* offset_values, int** keys, _node** records) {
    int i;
    for (i = 0; i < size; i++) {
        // Free record and linked list node
        free((*records)[i].data);

        if ((*records)[i].next != NULL)
            free((*records)[i].next);
    }

    // Free arrays
    free(*keys);
    free(*offset_values);
    free(*records);
}

int main() {
    int size;
    scanf("%d", &size);

    int* offset_values = (long*)malloc(size * sizeof(long));
