    public static void processAndHandleInput(String configJson) {
        JSONObject config = new JSONObject(configJson);

        // Initialize random number generator and other parameters
        Random rand = new Random();
        int seed = config.getInt("seed", 42);
        rand.setSeed(seed);
        int minRange = config.getInt("minRange", 0);
        int maxRange = config.getInt("maxRange", 100);

