                throw new Exception("Invalid size");
            }

            // Allocate memory based on input data and configuration settings
            offsetValues = new long[size];
            keys = new int[size];
            records = new Record[size];

            for (int i = 0; i < size; i++) {
                // Initialize record fields with random values within the specified range
                records[i] = new Record(rand.nextInt(maxRange - minRange + 1) + minRange);
            }
        } catch (Exception e) {
            // Handle parsing failures or incomplete configuration files
            System.out.println("Error: " + e.getMessage());
            return;
        }

        try {
            // Find and print the largest integer in the array using a helper function
            int maxInt = findMax(records);
            System.out.println("Largest integer: " + maxInt);

            // Compute and return the MD5 hash of the input string
            String md5Hash = computeMD5(configJson);
            System.out.println("MD5 hash: " + md5Hash);
        } catch (Exception e) {
            // Handle exceptions gracefully
            System.out.println("Error: " + e.getMessage());
        }

        try {
            // Free all allocated memory, minimizing potential resource leaks
            for (int i = 0; i < records.length; i++) {
                records[i] = null;
            }

            offsetValues = null;
            keys = null;
            records = null;
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
        }
    }

    public static int findMax(Record[] records) {
        int maxInt = 0;

        for (int i = 0; i < records.length; i++) {
            if (records[i].getInt() > maxInt) {
                maxInt = records[i].getInt();
            }
        }

        return maxInt;
    }

    public static String computeMD5(String inputStr) {
        try {
            // Use a standard library function to compute the MD5 hash
            Mac md5Hasher = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(inputStr.getBytes(), "HmacSHA256");
            md5Hasher.init(keySpec);
            byte[] md5Bytes = md5Hasher.doFinal(inputStr.getBytes());

            return bytesToHexString(md5Bytes);
        } catch (Exception e) {
            // Handle exceptions gracefully
            System.out.println("Error: " + e.getMessage());
            return null;
        }
    }

    public static String bytesToHexString(byte[] barray) {
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < barray.length; i++) {
            sb.append(String.format("%02X", barray[i]));
        }

        return sb.toString();
    }

    // Record class implementation
    public static class Record {
        private int val;

        public Record(int val) {
            this.val = val;
        }

        public int getInt() {
            return val;
        }
    }
