typedef struct {
    int max_offsets;
    int max_keys;
    long min_key;
    long max_key;
} Config;

Config config = {
    .max_offsets = 100,
    .max_keys = 1000,
    .min_key = 1,
    .max_key = 999
};

long* offsets;
int* keys;
struct record* records;

int create_records(Config* c) {
    long offset_count = c->max_offsets;
    int key_count = c->max_keys;
    int record_count = (c->max_offsets + c->max_keys - 1);

    // Allocate memory for arrays
    offsets = (long*)malloc(sizeof(long) * offset_count);
    keys = (int*)malloc(sizeof(int) * key_count);
    records = (struct record*)malloc(sizeof(struct record) * record_count);

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Initialize offsets
    for (long i = 0; i < offset_count; i++) {
        offsets[i] = i;
    }

    // Initialize keys
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(c->min_key, c->max_key);

    for (int i = 0; i < key_count; i++) {
        keys[i] = dis(gen);
    }

    // Initialize records
    for (long i = 0; i < record_count; i++) {
        records[i].offset = &offsets[i % offset_count];
        records[i].key = keys[i % key_count];
        records[i].accessed = false;
    }

    return record_count;
}

void free_records() {
    // Deallocate memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int record_count = create_records(&config);

    if (record_count == -1) {
        printf("Error creating records\n");
    } else {
        printf("Records created: %d\n", record_count);
    }

    free_records();

    return 0;
}
