entry* init_entries(int capacity) {
    return (entry*) malloc(capacity * sizeof(entry));
}

void add_entry(entry** entries, int* capacity, int* size, const char* id) {
    if (*size >= *capacity) {
        *capacity *= 2;
        *entries = realloc(*entries, *capacity * sizeof(entry));
    }

    item data = {0.0f, 0, false}; // default values

    for (int i = 0; i < *size; i++) {
        if (!strcmp(entries[i]->id, id)) {
            // Validate identifier
            printf("Duplicate ID: %s\n", id);
            return;
        }
    }

    entry* new_entry = &entries[*size];
    strcpy(new_entry->id, id);
    new_entry->data = data; // assign default values

    (*size)++;

    return;
}

entry* get_entry(entry** entries, int size, const char* id) {
    for (int i = 0; i < size; i++) {
        if (!strcmp(entries[i]->id, id)) {
            return &entries[i];
        }
    }

    printf("Entry not found: %s\n", id);
    return NULL;
}

void free_entries(entry** entries, int capacity) {
    free(entries);
}

int main() {
    // Example usage
    entry* entries = init_entries(10); // Initialize with 10 capacity
    int size = 0; // Initialize size to 0

    add_entry(&entries, &entries[0].capacity, &size, "id1");
    add_entry(&entries, &entries[0].capacity, &size, "id2");

    entry* found = get_entry(&entries, size, "id1");
    if (found) {
        printf("Entry: %s\n", found->id);
    }

    free_entries(entries, 20); // Free entries with updated capacity

    return 0;
}
