#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int key;
    int* value;
    int initialized;
} record;

int addRecord(record** records, int capacity, int key);
record* findRecord(record** records, int capacity, int key);

record* createRecord(int key) {
    record* newRecord = (record*)malloc(sizeof(record));
    if (!newRecord) return NULL;  // Handle allocation failure

    srand(time(NULL));  // Initialize random seed
    newRecord->value = malloc(sizeof(int));
    *newRecord->value = rand() % 100;  // Initialize value with a random int between 0 and 99
    newRecord->key = key;
    newRecord->initialized = 1;

    return newRecord;
}

int addRecord(record** records, int capacity, int key) {
    if (!records || !(*records)) return -1;  // Check for NULL pointer or empty record list

    if (capacity <= 0) return -2;  // Handle invalid capacity parameter

    for (int i = 0; *records[i]; i++) {
        if ((*records)[i]->key == key) return -3;  // Check for duplicate key
    }

    if (*(*records + capacity)) return -4;  // Check for exceeding maximum capacity

    record* newRecord = createRecord(key);
    if (!newRecord) return -5;  // Handle allocation failure

    (*records)[capacity] = newRecord;
    return capacity;  // Successful addition
}

record* findRecord(record** records, int capacity, int key) {
    for (int i = 0; *records[i]; i++) {
        if ((*records)[i]->key == key) return (*records)[i];
    }
    return NULL;  // Record not found
}

void freeRecords(record** records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (!(*records[i])) continue;

        free((*records)[i]->value);
        free((*records)[i]);
    }
    free(*records);  // Free the array of pointers
}
