record* allocateRecords(int count, int maxOffsetCount) {
    // Allocate memory for records
    record* records = (record*) malloc(count * sizeof(record));

    // Initialize offset array and set pointers to NULL
    long* offsets = (long*) malloc(maxOffsetCount * sizeof(long));
    for (int i = 0; i < maxOffsetCount; i++) {
        offsets[i] = -1;
    }

    return records;
}

void initRecords(record* records, int count, long* offsets) {
    // Initialize record values and set offset pointers
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % 100 + 1;
        records[i].offset = &offsets[i];
    }
}

void updateRecord(record* records, int key, int value) {
    // Find the corresponding record
    for (int i = 0; i < count; i++) {
        if (records[i].offset == &offsets[key]) {
            records[i].value = value;
            break;
        }
    }
}

void freeRecords(record* records, long* offsets) {
    // Free allocated memory
    free(records);
    free(offsets);
}

int main() {
    int count = 10; // Number of records to allocate
    int maxOffsetCount = 20; // Maximum number of offsets

    record* records = allocateRecords(count, maxOffsetCount);

    // Initialize records and offset values
    initRecords(records, count, offsets);

    // Update a record
    updateRecord(records, 5, 50);

    // Free allocated memory
    freeRecords(records, offsets);

    return 0;
}
