// Custom doubly linked list node structure
typedef struct Node {
    struct Node* prev;
    struct Record* record;
    struct Node* next;
} Node;

// Custom doubly linked list structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock; // Thread-safe access to the list
} List;

// Struct to represent a single record
typedef struct Record {
    long offset;
    int key;
    char fixed_field[RECORD_FIXED_SIZE];
    int event_count;
} Record;

// Function to dynamically allocate and manage memory for variable-sized collection of records
void* dynamic_record_collection(int batch_size, int min_event_count, int max_event_count) {
    // Initialize the list and record collection
    List record_list = { NULL, NULL, PTHREAD_MUTEX_INITIALIZER };
    Record** records = (Record**)malloc(batch_size * sizeof(Record*));

    // Generate random event counts for each record within specified range and tolerance
    srand(time(NULL));
    for (int i = 0; i < batch_size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->offset = i;
        record->key = i % 100; // Assign a unique key to each record
        record->event_count = min_event_count + rand() % (max_event_count - min_event_count) / TOLERANCE;
        strcpy(record->fixed_field, "Fixed Field"); // Initialize fixed field with default value

        // Add the record to the list and collection
        Node* node = (Node*)malloc(sizeof(Node));
        node->prev = NULL;
        node->record = record;
        node->next = NULL;

        if (!record_list.head) {
            record_list.head = node;
            record_list.tail = node;
        } else {
            node->prev = record_list.tail;
            record_list.tail->next = node;
            record_list.tail = node;
        }

        records[i] = record;
    }

    // Perform any necessary cleanup or processing on the record collection
    // ...

    return records; // Return the dynamically allocated and managed record collection
}

