#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <json-c/json.h>

// Define a record structure
typedef struct {
    int value;
} Record;

// Define a doubly linked list node
typedef struct Node {
    Record* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize the random number generator
void initRNG(long seed) {
    srand(seed);
}

// Function to generate a random integer within a range
int getRandom(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Function to create a new linked list node and initialize its record
Node* newNode(Record* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to add a new node to the front of the linked list
void addFront(Node** head, Node* node) {
    if (*head == NULL || node->data->value < (*head)->data->value) {
        node->prev = *head;
        *head = node;
    } else {
        node->next = (*head);
        (*head)->prev = node;
        *head = node;
    }
}

// Function to remove a node from the linked list
void removeNode(Node** head, Node* node) {
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        *head = node->next;
    }

    if (node->next != NULL) {
        node->next->prev = node->prev;
    }
    free(node);
}

// Function to print the largest integer in the array
void printLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("The largest integer is: %d\n", max);
}

// Function to read a JSON configuration file
void readConfig(json_object* config, long* seed, int* min, int* max) {
    json_object* rngSeed = json_object_object_get(config, "seed");
    json_object* valueRange = json_object_object_get(config, "value_range");

    if (rngSeed != NULL && json_object_get_type(rngSeed) == json_type_integer) {
        *seed = json_object_get_int(rngSeed);
    } else {
        printf("Error: 'seed' not found in the configuration file.\n");
    }

    if (valueRange != NULL && json_object_get_type(valueRange) == json_type_array) {
        json_object* minVal = json_object_array_get_idx(valueRange, 0);
        json_object* maxVal = json_object_array_get_idx(valueRange, 1);

        if (minVal != NULL && json_object_get_type(minVal) == json_type_integer)
            *min = json_object_get_int(minVal);
        else
            printf("Error: 'min' not found in the value range.\n");

        if (maxVal != NULL && json_object_get_type(maxVal) == json_type_integer)
            *max = json_object_get_int(maxVal);
        else
            printf("Error: 'max' not found in the value range.\n");
    } else {
        printf("Error: 'value_range' not found in the configuration file.\n");
    }
}

// Function to serialize the linked list to a file
void serialize(Node* head, FILE* file) {
    if (head == NULL)
        return;

    fwrite(&head->data->value, sizeof(int), 1, file);
    serialize(head->next, file);
}

// Function to deserialize the linked list from a file
Node* deserialize(FILE* file) {
    Node* head = NULL;
    Record* data = (Record*)malloc(sizeof(Record));
    while (fread(&data->value, sizeof(int), 1, file)) {
        Node* node = newNode(data);
        node->next = head;
        head = node;
        free(data);
        data = (Record*)malloc(sizeof(Record));
    }
    return head;
}

// Function to handle logging
void logMessage(const char* message, int verbosity) {
    if (verbosity > 0)
        printf("%s\n", message);
}

int main() {
    // Initialize the random number generator and linked list
    long seed = 0;
    int min = 1, max = 100;

    // Read the configuration file
    json_object* config = json_object_from_file("config.json");
    readConfig(config, &seed, &min, &max);
    json_object_free(config);

    // Initialize the linked list and allocate memory for the records
    Node* head = NULL;
    int size = 0;

    // Read the input integers from standard input
    while (scanf("%d", &min) == 1) {
        Record* data = (Record*)malloc(sizeof(Record));
        data->value = getRandom(min, max);
        addFront(&head, newNode(data));
        size++;
    }

    // Print the largest integer in the array
    printLargest((int*)malloc(size * sizeof(int)), size);

    // Serialize and deserialize the linked list to a file
    FILE* file = fopen("data.bin", "wb");
    serialize(head, file);
    fclose(file);
    head = deserialize(fopen("data.bin", "rb"));
    fclose(file);

    // Free allocated memory
    while (head != NULL) {
        removeNode(&head, head);
    }
    return 0;
}
