using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Security.Cryptography;

public class DynamicValueGenerator
{
    private readonly RandomNumberGenerator _rng = new CryptographicallySecureRandom();
    private int _minValue;
    private int _maxValue;

    public DynamicValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new InvalidOperationException("Invalid range");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GetFloatRandom()
    {
        return (float)_rng.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetIntRandom()
    {
        return _rng.Next(_minValue, _maxValue + 1);
    }

    public override string ToString()
    {
        return $"Min: {_minValue}, Max: {_maxValue}";
    }
}
