// Define a structure to represent UE context records
typedef struct {
    int ue_id;
    char* serving_cell; // pointer to dynamically allocated memory
    struct rrc_connection** connections;
    size_t connection_count;
} ue_context;

// Define a structure to represent the doubly linked list node
typedef struct {
    ue_context* data;
    struct node* prev;
    struct node* next;
} node;

// Function to initialize and return a new UE context record
ue_context* create_ue_context() {
    ue_context* ue = (ue_context*)malloc(sizeof(ue_context));
    srand(time(NULL)); // Seed the random number generator
    ue->ue_id = rand() % 100 + 1;
    ue->serving_cell = malloc(strlen("Serving Cell") + 1);
    strcpy(ue->serving_cell, "Serving Cell");
    ue->connections = NULL;
    ue->connection_count = 0;
    return ue;
}

// Function to free memory allocated for a UE context record
void free_ue_context(ue_context* ue) {
    if (ue == NULL)
        return;
    free(ue->serving_cell);
    free(ue);
}

// Function to create and return a new doubly linked list node
node* create_node() {
    node* n = (node*)malloc(sizeof(node));
    n->data = create_ue_context();
    n->prev = NULL;
    n->next = NULL;
    return n;
}

// Function to free memory allocated for a doubly linked list node
void free_node(node* n) {
    if (n == NULL)
        return;
    free_ue_context(n->data);
    free(n);
}

// Function to insert a new UE context record at the end of the list
node* insert_ue_context(node* head, ue_context* ue) {
    node* n = create_node();
    n->data = ue;
    if (head == NULL)
        return n; // This is the first node in the list
    else {
        node* current = head;
        while (current->next != NULL)
            current = current->next;
        current->next = n;
        n->prev = current;
        return head;
    }
}

// Function to remove a UE context record from the list
node* remove_ue_context(node* head, int ue_id) {
    if (head == NULL)
        return head; // The list is empty

    node* current = head;
    while (current != NULL && current->data->ue_id != ue_id) {
        current = current->next;
    }
    if (current == NULL || current->data->ue_id != ue_id)
        return head; // Not found

    if (current->prev == NULL)
        head = current->next; // This is the first node in the list
    else
        current->prev->next = current->next;
    if (current->next != NULL)
        current->next->prev = current->prev;
    return head;
}

// Function to print the contents of a UE context record
void print_ue_context(ue_context* ue) {
    printf("UE ID: %d\n", ue->ue_id);
    printf("Serving Cell: %s\n", ue->serving_cell);
    printf("Connection Count: %zu\n", ue->connection_count);
}

// Function to traverse the list of UE context records and print their contents
void print_ue_context_list(node* head) {
    node* current = head;
    while (current != NULL) {
        print_ue_context(current->data);
        current = current->next;
    }
}
