import threading
from collections import OrderedDict

class DynamicCache:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()
        self.disk_cache = {}

    def put(self, key, value):
        with self.lock:
            if key in self.cache:
                self.cache[key].state = 'VALID'
            else:
                self.cache[key] = {'value': value, 'state': 'VALID'}

    def get(self, key):
        with self.lock:
            if key not in self.cache:
                return None
            entry = self.cache[key]
            if entry['state'] == 'INVALID':
                return None
            return entry['value']

    def evict(self):
        with self.lock:
            for key in list(self.cache.keys()):
                entry = self.cache[key]
                if entry['state'] != 'VALID' or len(self.cache) > 1000:
                    del self.cache[key]

    def offload(self, key):
        with self.lock:
            if key not in self.cache:
                return
            value = self.cache.pop(key)
            self.disk_cache[key] = value

    def load_from_disk(self, key):
        with self.lock:
            if key in self.disk_cache:
                value = self.disk_cache.pop(key)
                self.put(key, value)

    def invalidate(self, key):
        with self.lock:
            if key in self.cache:
                self.cache[key]['state'] = 'INVALID'

    def cleanup(self):
        while True:
            try:
                self.evict()
                time.sleep(60)  # customizable cleanup frequency
            except Exception as e:
                print(f'Error: {e}')

class ThreadSafeOrderedList:
    def __init__(self):
        self.lock = threading.Lock()
        self.list = []

    def append(self, item):
        with self.lock:
            self.list.append(item)

    def pop(self):
        with self.lock:
            return self.list.pop()

    def extend(self, items):
        with self.lock:
            self.list.extend(items)

    def __len__(self):
        with self.lock:
            return len(self.list)
