        printf("Value: %.2lf, Timestamp: %d, Status: %s\n", t->value, t->timestamp, t->status);
    }
}

void init() {
    pthread_create(&cleanup_thread, NULL, &cleanup_function, NULL);
}

void cleanup() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < trans_count; i++) {
        Transaction* t = transactions[i];
        free(t);
        transactions[i] = NULL;
    }
    trans_count = 0;
    update_timer = 0;
    pthread_mutex_unlock(&lock);
}

void destroy() {
    pthread_join(cleanup_thread, NULL);
    cleanup();
