    RBTNode* node = (RBTNode*)malloc(sizeof(RBTNode));
    if (!node) return NULL;
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    node->parent = NULL;
    node->color = 1; // Initialize as red
    return node;
}

// Function to insert a new RBT node into the tree
void rbt_insert(RBTNode** root, SensorData data) {
    if (!*root) *root = rbt_create_node(data);
    else {
        RBTNode* current = *root;
        RBTNode* parent = NULL;
        while (current) {
            parent = current;
            if (data.timestamp < current->data.timestamp) current = current->left;
            else current = current->right;
