// Define the structure for each node
typedef struct Node {
    int key;
    void* data;
    struct Node* next;
} Node;

// Function to generate unique key based on timestamp
int generateKey() {
    time_t now = time(NULL);
    return (int)now;
}

// Function to create a new node with random integer in the linked list
Node* newNode(int rangeStart, int rangeEnd) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        // Handle memory allocation failure
        return NULL;
    }

    node->key = generateKey();
    node->data = (void*)malloc((rangeEnd - rangeStart + 1) * sizeof(int));
    int* dataArray = (int*)node->data;

    for (int i = 0; i < rangeEnd - rangeStart + 1; i++) {
        dataArray[i] = rand() % (rangeEnd - rangeStart) + rangeStart;
    }

    node->next = NULL;
    return node;
}

// Function to add a new node to the collection
void addChild(Node** head, Node* child) {
    if (!(*head)) {
        *head = child;
        return;
    }

    child->next = (*head);
    *head = child;
}

// Function to print the linked list of each node
void printNode(Node* node) {
    printf("Key: %d\n", node->key);
    int* dataArray = (int*)node->data;
    for (int i = 0; i < sizeof(int); i++) {
        printf("%d ", dataArray[i]);
    }
    printf("\n");
}

// Function to free the memory allocated for each node
void deleteNode(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    *head = NULL;
}

