Node* createGraphConfig(int size) {
    Node* graph = (Node*)malloc(sizeof(Node) * size);
    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < size; i++) {
        graph[i].id = i;
        graph[i].metadata = NULL;
        graph[i].edgeCount = 0;

        int neighborCount = rand() % 10 + 1; // Random number of neighbors
        for (int j = 0; j < neighborCount; j++) {
            int neighborId = rand() % size;
            Node* neighbor = &graph[neighborId];
            graph[i].neighbors[j] = neighbor;
        }
    }

    return graph;
}

void printGraph(Node* graph) {
    for (int i = 0; i < sizeof(graph) / sizeof(Node); i++) {
        printf("Node %d:\n", graph[i].id);

        int edgeCount = 0;
        for (int j = 0; j < 10; j++) {
            if (graph[i].neighbors[j] != NULL) {
                edgeCount++;
                printf("Neighbor: %d\n", graph[i].neighbors[j]->id);
            }
        }

        printf("Edge Count: %d\n", edgeCount);
    }
}

int traverseGraph(Node* node) {
    int count = 0;

    for (int i = 0; i < 10; i++) {
        if (node->neighbors[i] != NULL) {
            count++;
            traverseGraph(node->neighbors[i]); // Recursively traverse neighbors
        }
    }

    return count;
}
