// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the dynamic array type
typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
} DynamicArray;

// Function to create a new dynamic array
DynamicArray* dynamic_array_create(size_t initial_capacity) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    arr->records = calloc(initial_capacity, sizeof(Record));
    arr->capacity = initial_capacity;
    arr->size = 0;
    return arr;
}

// Function to insert a new record into the array
int dynamic_array_insert(DynamicArray* arr, Record* record) {
    if (arr->size >= arr->capacity) {
        // Resize the array if it's full
        size_t new_capacity = arr->capacity * 2;
        Record* new_records = realloc(arr->records, new_capacity * sizeof(Record));
        arr->records = new_records;
        arr->capacity = new_capacity;
    }
    arr->records[arr->size] = *record;
    arr->size++;
    return 0;
}

// Function to iterate over the array
void dynamic_array_iterate(const DynamicArray* arr, void (*callback)(const Record*)) {
    for (size_t i = 0; i < arr->size; i++) {
        callback(&arr->records[i]);
    }
}

// Function to release all allocated memory
void dynamic_array_free(DynamicArray* arr) {
    free(arr->records);
    free(arr);
}
