    // Initialize random seed
    srand(time(NULL));

    // Check for valid configuration parameters
    if (keyCount <= 0 || maxKey <= 0) {
        printf("Invalid configuration. Key count or maximum key value must be greater than zero.\n");
        return NULL;
    }

    record* records = (record*)malloc(keyCount * sizeof(record));
    int* keys = (int*)calloc(maxKey, sizeof(int));

    // Initialize random values for each record
    for (int i = 0; i < keyCount; i++) {
        int key = rand() % maxKey;
        while (key >= maxKey || containsKey(keys, key)) {
            key = rand() % maxKey;
        }
        records[i].key = key;
        records[i].offset = rand();
    }

    // Free unnecessary memory
    free(keys);

    return records;
}

int containsKey(int* keys, int key) {
    for (int i = 0; i < maxKey; i++) {
        if (keys[i] == key) {
            return 1;
        }
    }
    return 0;
}
