    char** strings = NULL;

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-c")) {
            i++;
            if (i >= argc) {
                fprintf(stderr, "Error: configuration file missing\n");
                return;
            }

            config_json = json_load_file(argv[i], JSON_NONE);
            if (!config_json) {
                fprintf(stderr, "Error: failed to load configuration file\n");
