#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

#define MAX_RECORDS 10000
#define RAND_RANGE 1000

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

typedef struct Node {
    Record record;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    int size;
    double loadFactor;
} HashTable;

void initializeRecord(Record* record) {
    srand(time(NULL));
    record->value = rand() % RAND_RANGE;
}

HashTable* createHashTable(int size, double loadFactor) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->loadFactor = loadFactor;
    table->buckets = (Node**)calloc(size, sizeof(Node*));
    return table;
}

void freeHashTable(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

void addRecord(HashTable* table, Record record) {
    int key = record.key;
    int index = key % table->size;
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->prev = NULL;
    node->next = table->buckets[index];
    if (table->buckets[index] != NULL) {
        table->buckets[index]->prev = node;
    } else {
        table->buckets[index] = node;
    }
}

void deleteRecord(HashTable* table, Record record) {
    int key = record.key;
    int index = key % table->size;
    Node* node = table->buckets[index];
    while (node != NULL && node->record.key != key) {
        node = node->next;
    }
    if (node == NULL) return; // Not found
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        table->buckets[index] = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    }
    free(node);
}

int main() {
    // Initialize the hash table
    HashTable* table = createHashTable(MAX_RECORDS, 0.5);

    // Add records to the hash table
    for (int i = 0; i < MAX_RECORDS; i++) {
        Record record;
        initializeRecord(&record);
        addRecord(table, record);
    }

    // Delete some records from the hash table
    int keyToDelete = rand() % MAX_RECORDS;
    deleteRecord(table, (Record){.key = keyToDelete, .offset = 0, .value = 0});

    // Free the hash table
    freeHashTable(table);

    return 0;
}
