int custom_hash(const char* str) {
    int hash = 0;
    while (*str != '\0') {
        hash += (int)*str;
        str++;
    }
    return hash % 1000; // map to the range of the array
}

node* create_node(char* string, int timestamp) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    new_node->string = (char*)malloc(strlen(string) + 1);
    strcpy(new_node->string, string);
    new_node->timestamp = timestamp;
    new_node->next = NULL;
    return new_node;
}

void free_node(node* node_to_free) {
    if (!node_to_free) {
        return;
    }
    free(node_to_free->string);
    free(node_to_free);
}

int main() {
    // Create a linked list
    node* head = create_node("Hello", 12345);
    head->next = create_node("World", 67890);

    // Implement hash table with chaining for efficient retrieval
    int key = custom_hash("Hello");
    node* temp = head;
    while (temp) {
        if (hash_table[key] && hash_table[key]->string == temp->string) {
            // Update timestamp or perform other operations as needed
            printf("Updated timestamp: %d\n", temp->timestamp);
        }
        temp = temp->next;
    }

    // Free allocated memory to prevent leaks and ensure integrity
    node* current = head;
    while (current) {
        node* next = current->next;
        free_node(current);
        current = next;
    }

    return 0;
}
