typedef struct sensor_data {
    long timestamp;
    float reading;
    char type;
} SensorData;

typedef struct sensor_list_node {
    SensorData data;
    struct sensor_list_node* prev;
    struct sensor_list_node* next;
} SensorListNode;

SensorListNode* head = NULL;

void add_sensor_data(long timestamp, float reading, char type) {
    SensorListNode* new_node = (SensorListNode*) malloc(sizeof(SensorListNode));
    if(new_node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    new_node->data.timestamp = timestamp;
    new_node->data.reading = (float)(rand() % 100); // Random value within the range [0, 100)
    new_node->data.type = type;

    if(head == NULL) {
        head = new_node;
    } else {
        SensorListNode* current = head;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
        new_node->next = NULL;
    }

    return;
}

void remove_sensor_data(long timestamp, char type) {
    SensorListNode* current = head;
    while(current != NULL) {
        if(current->data.timestamp == timestamp && current->data.type == type) {
            if(current->prev != NULL)
                current->prev->next = current->next;
            else
                head = current->next;

            if(current->next != NULL)
                current->next->prev = current->prev;

            free(current);
            return;
        }
        current = current->next;
    }

    printf("Data not found\n");
    return;
}

void print_sensor_data() {
    SensorListNode* current = head;
    while(current != NULL) {
        printf("Timestamp: %ld, Reading: %.2f, Type: %c\n", current->data.timestamp, current->data.reading, current->data.type);
        current = current->next;
    }
}

