// Define the 'record' structure
typedef struct {
    long offset;
    int key;
    int value;
} record_t;

// Define the node structure for the doubly linked list
typedef struct node {
    record_t data;
    struct node* prev;
    struct node* next;
} node_t;

// Define the hash table structure
typedef struct {
    unsigned int size;
    node_t** buckets;
} hash_table_t;

// Initialize a new hash table with a given size
hash_table_t* init_hash_table(unsigned int size) {
    hash_table_t* table = (hash_table_t*)malloc(sizeof(hash_table_t));
    table->size = size;
    table->buckets = (node_t**)calloc(size, sizeof(node_t*));
    return table;
}

// Insert a record into the hash table
void insert_record(hash_table_t* table, record_t* data) {
    // Calculate the hash value for the key
    unsigned int index = data->key % table->size;

    // Find the corresponding node in the list or create a new one if it doesn't exist
    node_t* node = table->buckets[index];
    while (node && node->data.key != data->key) {
        node = node->next;
    }
    if (!node) {
        node = (node_t*)malloc(sizeof(node_t));
        node->data = *data;
        node->prev = NULL;
        node->next = table->buckets[index];
        if (table->buckets[index]) {
            table->buckets[index]->prev = node;
        } else {
            table->buckets[index] = node;
        }
    }
}

// Remove a record from the hash table
void remove_record(hash_table_t* table, int key) {
    // Calculate the hash value for the key
    unsigned int index = key % table->size;

    // Find and remove the corresponding node in the list
    node_t* node = table->buckets[index];
    while (node && node->data.key != key) {
        node = node->next;
    }
    if (node) {
        if (node->prev) {
            node->prev->next = node->next;
        } else {
            table->buckets[index] = node->next;
        }
        if (node->next) {
            node->next->prev = node->prev;
        }
        free(node);
    }
}

// Lookup a record in the hash table
record_t* lookup_record(hash_table_t* table, int key) {
    // Calculate the hash value for the key
    unsigned int index = key % table->size;

    // Find and return the corresponding node in the list
    node_t* node = table->buckets[index];
    while (node && node->data.key != key) {
        node = node->next;
    }
    if (node) {
        return &node->data;
    } else {
        return NULL;
    }
}

// Define the caching mechanisms for recent transaction data
typedef struct {
    int size;
    record_t** cache;
} transaction_cache_t;

transaction_cache_t* init_transaction_cache(int size) {
    transaction_cache_t* cache = (transaction_cache_t*)malloc(sizeof(transaction_cache_t));
    cache->size = size;
    cache->cache = (record_t**)calloc(size, sizeof(record_t*));
    return cache;
}

// Insert a record into the transaction cache
void insert_transaction_cache(transaction_cache_t* cache, record_t* data) {
    // Calculate the index for the cache
    int index = data->key % cache->size;

    // Store the record in the cache
    cache->cache[index] = data;
}

// Remove a record from the transaction cache
void remove_transaction_cache(transaction_cache_t* cache, int key) {
    // Calculate the index for the cache
    int index = key % cache->size;

    // Remove the corresponding record from the cache
    if (cache->cache[index]) {
        free(cache->cache[index]);
        cache->cache[index] = NULL;
    }
}

