void refreshDialogFields(int size) {
    srand(time(NULL));

    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    record* records = (record*)malloc(size * sizeof(record));
    char** labels = (char**)malloc(size * sizeof(char*));
    FieldStatus* statuses = (FieldStatus*)malloc(size * sizeof(FieldStatus));
    time_t* timestamps = (time_t*)malloc(size * sizeof(time_t));

