        metadata->value = rand() % 100;
        metadata->minValue = 0;
        metadata->maxValue = 100;
        metadata->defaultValue = "Default";
        metadata->dataType = "Integer";

        records[i].metadata = metadata;
    }

    // Handle edge cases
    if (size <= 0) {
        free(offsets);
        free(keys);
        free(records);
        free(labels);
        free(statuses);
        free(timestamps);
        return;
    }

    // Thread-safe mechanism
    pthread_mutex_lock();
    for (int i = 0; i < size; i++) {
        // Concurrent access handling
        pthread_mutex_unlock();
        // Validation and logging
        if (records[i].value < records[i].minValue || records[i].value > records[i].maxValue) {
            printf("Error: Field value out of bounds.\n");
            continue;
        }
        // Memory management
        free(labels[i]);
        labels[i] = NULL;

        Metadata* metadata = records[i].metadata;
        if (metadata->defaultValue == NULL || strlen(metadata->defaultValue) <= 0) {
            printf("Warning: Default value is empty or null.\n");
        }
    }

    pthread_mutex_unlock();
}
