typedef struct HashTable {
    int size;
    int capacity;
    Node** buckets;
    pthread_mutex_t lock;
} Hashtable;

// Initialize the hash table with a given size and capacity
Hashtable* initHashTable(int size, int capacity) {
    Hashtable* ht = (Hashtable*)malloc(sizeof(Hashtable));
    ht->size = size;
    ht->capacity = capacity;
    ht->buckets = (Node**)calloc(capacity, sizeof(Node*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

// Add a node to the hash table
void addNode(Hashtable* ht, Node* node) {
    int index = node->identifier[0] % ht->capacity;
    pthread_mutex_lock(&ht->lock);
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
    pthread_mutex_unlock(&ht->lock);
}

// Find a node in the hash table
Node* findNode(Hashtable* ht, char* identifier) {
    int index = 0;
    Node* current = NULL;
    pthread_mutex_lock(&ht->lock);
    while (index < ht->capacity) {
        current = ht->buckets[index];
        if (current && strcmp(current->identifier, identifier) == 0) {
            break;
        }
        index++;
    }
    pthread_mutex_unlock(&ht->lock);
    return current;
}

// Initialize the linked list and hash table
void initListAndHashTable(int size, int capacity) {
