    double max_temp = *temperatures;

    for (int i = 0; i < size; i++) {
        if (integers[i] > max_int)
            max_int = integers[i];
        if (temps_size > 0 && temperatures[i] > max_temp)
            max_temp = temperatures[i];
    }
}

// Release allocated memory
void releaseMemory(Hashtable* ht) {
    for (int i = 0; i < ht->capacity; i++) {
        Node* current = ht->buckets[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(ht->buckets);
    free(ht);
}

