#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    int value;
    struct Record* next;
    struct Record* prev;
} Record;

Record* insert_record(Record** head, int key, int value) {
    Record* new_node = (Record*)malloc(sizeof(Record));
    if (!new_node) {
        return NULL; // Memory allocation failed
    }
    new_node->key = key;
    new_node->value = value;
    new_node->next = (*head);
    new_node->prev = (*head) ? (*head)->prev : NULL;

    if ((*head)) {
        (*head)->prev = new_node;
    } else {
        *head = new_node; // New node is the head of the list
    }

    return new_node;
}

void delete_record(Record** head, int key) {
    Record* current = *head;
    Record* previous = NULL;

    while (current && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (!current) return; // Key not found

    if (previous) {
        previous->next = current->next;
        if (current->next) {
            current->next->prev = previous;
        } else {
            *head = current->next;
        }
    } else {
        *head = current->next;
    }

    free(current);
}

void print_records(Record* head) {
    while (head) {
        printf("Key: %d, Value: %d\n", head->key, head->value);
        head = head->next;
    }
}
