#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <pthread.h>

// Define a struct for each sensor reading
typedef struct {
    long timestamp;
    float value;
    char type;
} SensorData;

// Define the doubly linked list node structure
typedef struct Node {
    SensorData data;
    struct Node* prev;
    struct Node* next;
} Node;

// Initialize the pseudo-random number generator
srand(time(NULL));

// Function to create a new sensor reading with random value
SensorData* createSensorData(char type) {
    SensorData* data = (SensorData*)malloc(sizeof(SensorData));
    data->timestamp = time(NULL);
    data->value = (float)(rand() / (double)RAND_MAX * 100.0); // Random float between 0 and 100
    data->type = type;
    return data;
}

// Function to add a new sensor reading to the doubly linked list
void addSensorData(Node** head, SensorData* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = *data;
    newNode->prev = NULL;
    newNode->next = *head;
    if (*head != NULL)
        (*head)->prev = &newNode->data;
    *head = &newNode->data;
}

// Function to print the sensor readings
void printSensorData(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Timestamp: %ld, Value: %f, Type: %c\n", current->data.timestamp, current->data.value, current->data.type);
        current = current->next;
    }
}

// Function to process sensor data concurrently
void* processSensorData(void* args) {
    Node** head = (Node**)args;
    while (1) {
        // Read from external data source and add new sensor readings
        SensorData* data = createSensorData('A'); // Replace 'A' with actual sensor type
        addSensorData(head, data);

        // Process the sensor readings concurrently
        pthread_yield();

        // Print the processed sensor readings
        printSensorData(*head);
    }
}

int main() {
    // Initialize the doubly linked list
    Node* head = NULL;

    // Create a thread to process sensor data concurrently
    pthread_t thread;
    pthread_create(&thread, NULL, &processSensorData, &head);

    // Simulate processing and decision-making
    while (1) {
        // Monitor memory usage and handle memory allocation failures
        printf("Memory usage: %f\n", (float)syssize() / 1024);
        if (serror()) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            break;
        }

        // Validate the integrity of the data structures
        Node* current = head;
