                break;
            }
            current = current->next;
        }

        // Flush log messages
        syslog(LOG_INFO, "Sensor data processed successfully.");
    }

    // Terminate the thread and free allocated memory
    pthread_cancel(thread);
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    return 0;
}
