// Define the structure for sensor records
typedef struct {
    long timestamp;
    float reading;
    char type;
} SensorRecord;

// Define the structure for a doubly linked list node
typedef struct {
    SensorRecord record;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize the sensor readings with random values
void initSensorReadings(Node** head_ref, int num_records) {
    // Initialize the pseudo-random number generator
    srand(time(NULL));

    // Allocate memory for the linked list and its nodes
    *head_ref = (Node*)malloc(sizeof(Node));
    Node* current = *head_ref;
    Node* last = *head_ref;

    for (int i = 1; i < num_records; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));

        // Initialize the sensor record with a random reading
        new_node->record.reading = (float)rand() / RAND_MAX;
        new_node->record.timestamp = time(NULL);
        new_node->record.type = 'A' + rand() % 26;  // Random sensor type

        // Update the linked list pointers
        last->next = new_node;
        new_node->prev = last;
        last = new_node;

        current->next = new_node;
        new_node->prev = current;
    }
}

// Function to add a new sensor record to the linked list
void addSensorRecord(Node** head_ref, SensorRecord* record) {
    Node* new_node = (Node*)malloc(sizeof(Node));

    // Initialize the sensor record with the given values
    new_node->record = *record;

    // Update the linked list pointers
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    Node* last = *head_ref;
    while (last->next != NULL) {
        last = last->next;
    }
    last->next = new_node;
    new_node->prev = last;
}

// Function to print the sensor records
void printSensorRecords(Node* head) {
    Node* current = head;

    while (current != NULL) {
        printf("Timestamp: %ld, Reading: %.2f, Type: %c\n", current->record.timestamp, current->record.reading, current->record.type);
        current = current->next;
    }
}

int main() {
    int num_records = 1000; // Number of sensor records
    Node* head = NULL;

    initSensorReadings(&head, num_records);

    // Add some more sensor records
    SensorRecord record1 = {time(NULL), (float)rand() / RAND_MAX, 'A' + rand() % 26};
    addSensorRecord(&head, &record1);

    SensorRecord record2 = {time(NULL), (float)rand() / RAND_MAX, 'B' + rand() % 26};
    addSensorRecord(&head, &record2);

    // Print the sensor records
    printSensorRecords(head);

    return 0;
}

