```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct for complex numbers
typedef struct {
    float real;
    float imag;
} Complex;

// Define a priority queue node structure
typedef struct {
    Complex value;
    int magnitude; // Magnitude of the complex number
    int index;     // Index in the original array
} Node;

// Function to compare two nodes based on their magnitudes
int compareNodes(const void* a, const void* b) {
    const Node* nodeA = (Node*)a;
    const Node* nodeB = (Node*)b;
    if (nodeA->magnitude < nodeB->magnitude)
        return -1;
    else if (nodeA->magnitude > nodeB->magnitude)
        return 1;
    else
        return 0;
}

// Function to initialize the priority queue
void initPriorityQueue(Node** heap, int* size) {
    *heap = NULL;
    *size = 0;
}

// Function to insert a complex number into the priority queue
void insert(Complex* value, Node** heap, int* size) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return; // Handle memory allocation failure

    node->value = *value;
    node->magnitude = sqrt(pow(node->value.real, 2) + pow(node->value.imag, 2)); // Calculate magnitude
    node->index = *size;

    if (*size == 0) {
        *heap = node;
    } else {
        Node* temp = *heap;
        Node* parent = NULL;
        while (temp && compareNodes(&temp->value, &node->value) < 0) {
            parent = temp;
            temp = temp->leftChild || temp->rightChild;
        }
        if (!parent) {
            node->leftChild = node->rightChild = NULL;
            *heap = node;
        } else if (compareNodes(&temp->value, &node->value) > 0) {
            node->leftChild = temp;
            temp->rightChild = node->rightChild;
            node->rightChild = NULL;
        } else {
            node->parent = temp;
            temp->rightChild = node;
            node->leftChild = temp->leftChild;
        }
    }

    (*size)++;
}

// Function to retrieve the complex number with the smallest magnitude from the priority queue
Complex* extractMin(Node** heap, int* size) {
    if (!(*heap)) return NULL; // Handle empty priority queue

    Complex* value = &((*heap)->value);
    Node* temp = *heap;

    if (temp->leftChild) {
        temp->parent->rightChild = temp->leftChild;
        temp->leftChild->parent = temp->parent;
        temp->parent = NULL;
    } else {
        while (!temp->leftChild && !temp->rightChild) {
            temp = temp->parent;
            if (temp == *heap) break;
        }
        if (temp->leftChild)
            temp->leftChild->parent = temp;
        else
            temp->rightChild->parent = temp;
    }

    free(temp);

    (*size)--;
    return value;
}

// Function to print the priority queue contents
void printHeap(Node* heap, int size) {
    for (int i = 0; i < size; i++) {
        printf("Magnitude: %f\n", sqrt(pow(heap[i].real, 2) + pow(heap[i].imag, 2)));
        printf("Real: %f, Imag: %f\n", heap[i].real, heap[i].imag);
    }
}
