// Linked list operations
void linked_list_insert(record** head, record* new_node) {
    if (*head == NULL || new_node->key < (*head)->key) {
        new_node->next = *head;
        new_node->prev = NULL;
        *head = new_node;
    } else {
        record* current = *head;
        while (current->next && current->next->key >= new_node->key)
            current = current->next;
        new_node->prev = current;
        new_node->next = current->next;
        current->next = new_node;
    }
}

record* linked_list_remove(record** head, record* node) {
    if (node->prev)
        node->prev->next = node->next;
    else
        *head = node->next;

    if (node->next)
        node->next->prev = node->prev;
    return node;
}

