#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure to represent a record with an integer value and a double timestamp
typedef struct {
    int value;
    double timestamp;
} Record;

// Hash table structure with resizing and rehashing support
typedef struct {
    Record** records; // Array of pointers to records
    size_t capacity; // Current capacity of the hash table
    size_t size; // Actual number of records in the hash table
} HashTable;

// Function to initialize a new hash table with a given initial capacity
HashTable* init_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    table->capacity = initial_capacity;
    table->size = 0;
    return table;
}

// Function to insert a new record into the hash table
void insert_record(HashTable* table, Record* record) {
    size_t index = record->value % table->capacity;
    while (table->records[index] != NULL) {
        // Handle collision by rehashing
        index = (index + 1) % table->capacity;
    }
    table->records[index] = record;
    table->size++;
}

// Function to delete a record from the hash table based on its value
void delete_record(HashTable* table, int value) {
    size_t index = value % table->capacity;
    while (table->records[index] != NULL && table->records[index]->value != value) {
        // Handle collision by rehashing and moving forward
        index = (index + 1) % table->capacity;
    }
    if (table->records[index] != NULL) {
        Record* record = table->records[index];
        table->records[index] = NULL;
        for (size_t i = 0; i < table->capacity; i++) {
            if (table->records[i] == record) {
                table->records[i] = NULL;
                break;
            }
        }
        free(record);
        table->size--;
    }
}

// Function to retrieve a record from the hash table based on its value
Record* get_record(HashTable* table, int value) {
    size_t index = value % table->capacity;
    while (table->records[index] != NULL && table->records[index]->value != value) {
        // Handle collision by rehashing and moving forward
        index = (index + 1) % table->capacity;
    }
    if (table->records[index] != NULL) {
        return table->records[index];
    }
    return NULL;
}

// Function to resize the hash table when it reaches its capacity
void resize_hash_table(HashTable* table, size_t new_capacity) {
    HashTable* new_table = init_hash_table(new_capacity);
    for (size_t i = 0; i < table->capacity; i++) {
        Record* record = table->records[i];
        while (record != NULL) {
            insert_record(new_table, record);
            record = record->next;
        }
    }
    for (size_t i = 0; i < table->capacity; i++) {
        free(table->records[i]);
    }
    free(table->records);
    table->records = new_table->records;
    table->capacity = new_capacity;
    table->size = new_table->size;
}

// Function to generate a random record with an integer value and a double timestamp
Record* generate_random_record() {
    Record* record = (Record*)malloc(sizeof(Record));
    srand(time(NULL)); // Initialize pseudo-random number generator
    record->value = rand() % 100; // Random integer value between 0 and 99
    record->timestamp = (double)rand() / RAND_MAX; // Random double timestamp between 0.0 and 1.0
    return record;
}

// Function to query the data structure using key-value pairs and timestamp-based queries
void query_data_structure(HashTable* table, int value, double timestamp) {
    Record* record = get_record(table, value);
    if (record != NULL && record->timestamp <= timestamp) {
        printf("Record found: Value = %d, Timestamp = %f\n", record->value, record->timestamp);
    } else {
        printf("Record not found or expired.\n");
    }
}

// Function to test the correctness of the data structure and query operations
void test_data_structure() {
    HashTable* table = init_hash_table(16); // Initialize hash table with an initial capacity of 16

    for (int i = 0; i < 100; i++) {
        Record* record = generate_random_record(); // Generate a random record
        insert_record(table, record); // Insert the record into the hash table
    }

    for (int i = 0; i < 100; i++) {
        Record* record = get_record(table, i % 100); // Retrieve a record from the hash table based on its value
        if (record != NULL) {
            printf("Record found: Value = %d, Timestamp = %f\n", record->value, record->timestamp);
        } else {
            printf("Record not found.\n");
        }
    }

    for (int i = 0; i < 100; i++) {
        delete_record(table, i % 100); // Delete a record from the hash table based on its value
    }

    free(table->records);
    free(table);
}

int main() {
    test_data_structure();
    return 0;
}
