    Node** new_buckets = (Node**)calloc(new_size, sizeof(Node*));
    for (int i = 0; i < ht->size; i++) {
        Node* node = ht->buckets[i];
        while (node) {
            int index = node->key[0] % new_size;
            Node* next = node->next;
            node->next = NULL;
            node->value->message = (char*)realloc(node->value->message, strlen(node->value->message) + 1);
            node->value->message[strcspn(node->value->message, "\0")] = '\0';
            node = next;
        }
    }
    free(ht->buckets);
    ht->size = new_size;
    ht->buckets = new_buckets;
}

// Function to add an entry to the hash table
void add_entry(HashTable* ht, char* key, LogEntry* value) {
    int index = strlen(key) % ht->size;
    Node* node = ht->buckets[index];
    while (node) {
        if (strcmp(node->key, key) == 0) {
            // Key already exists in the hash table
            free(node->value->message);
            free(node->value);
            free(node->key);
            free(node);
            return;
        }
        node = node->next;
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;
}

// Function to remove an entry from the hash table
void remove_entry(HashTable* ht, char* key) {
    int index = strlen(key) % ht->size;
    Node* node = ht->buckets[index];
    while (node) {
        if (strcmp(node->key, key) == 0) {
            // Key found in the hash table
            Node* temp = node;
            node = node->next;
            free(temp->key);
            free(temp->value->message);
            free(temp->value);
            free(temp);
            return;
        }
        node = node->next;
    }
}

