#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1000000

typedef struct {
    int value;
    long offset;
    int key;
} record_t;

record_t* create_records(int num_records, int max_key) {
    if (num_records <= 0 || max_key <= 0) {
        return NULL; // invalid input
    }

    int total_size = sizeof(record_t) * num_records;
    if (total_size > MAX_SIZE) {
        printf("Error: Requested memory exceeds maximum allowed.\n");
        return NULL;
    }

    record_t* records = (record_t*)malloc(total_size);
    if (!records) {
        printf("Memory allocation failed. Exiting...\n");
        return NULL;
    }

    srand(time(NULL)); // seed random number generator
    for (int i = 0; i < num_records; i++) {
        record_t* rec = &records[i];
        rec->value = rand() % 100; // random value within [0, 99]
        rec->offset = i * sizeof(record_t);
        rec->key = rand() % max_key; // random key within [0, max_key-1]
    }

    return records;
}

void free_records(record_t* records) {
    if (records) {
        free(records);
    }
}

int main() {
    int num_records = 10;
    int max_key = 100;

    record_t* records = create_records(num_records, max_key);

    // usage examples
    printf("Number of records: %d\n", num_records);
    for (int i = 0; i < num_records; i++) {
        record_t* rec = &records[i];
        printf("Record %d: value=%d, offset=0x%lx, key=%d\n",
               i, rec->value, rec->offset, rec->key);
    }

    free_records(records);

    return 0;
}
