#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <arpa/inet.h>

void processAndStoreRecords(long offset, int range) {
    // Initialize the record array with pseudo-random integers
    int* record = (int*)malloc(sizeof(int)*range);
    for (int i = 0; i < range; i++) {
        record[i] = rand() % 100;
    }

    // Compute the MD5 hash for each key and store the results
    ConcurrentHashMap<String, String>* map = new ConcurrentHashMap<>();
    for (int i = 0; i < range; i++) {
        char* key = (char*)malloc(strlen("record") + sizeof(int));
        sprintf(key, "record_%d", record[i]);
        uint8_t hash[16];
        MD5_CTX ctx;
        MD5Init(&ctx);
        MD5Update(&ctx, key, strlen(key) + 1);
        MD5Final(hash, &ctx);

        // Store the results in the ConcurrentHashMap
        map->put(new String(key), new String((char*)hash));

        free(key);
    }

    // Implement a timeout mechanism
    if (timeout exceeded) {
