#include <time.h>

#define MAX_SIZE 1024 * 1024 // 1MB
#define OFFSET_MAX 1000
#define KEY_MAX 256
#define RECORD_MAX 1000
#define RANDOM_SEED 42

typedef struct {
    int value;
    long offset;
    int key;
} record;

record* createRecords(int num, int* total_size) {
    int i;
    record* records = (record*)malloc(num * sizeof(record));

    if(records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for records.\n");
        return NULL;
    }

    for(i = 0; i < num; i++) {
        records[i].value = rand() % 100;
        records[i].offset = rand() % OFFSET_MAX;
        records[i].key = rand() % KEY_MAX;
    }

    *total_size += num * sizeof(record);
    return records;
}

int main(int argc, char* argv[]) {
    int num_records = 0;
    int total_size = 0;
    record* records;

    srand(time(NULL) + RANDOM_SEED); // seed random number generator

    if(argc < 2 || argc > 3) {
        fprintf(stderr, "Error: invalid number of command-line arguments.\n");
        return -1;
    }

    num_records = atoi(argv[1]);

    if(num_records <= 0) {
        fprintf(stderr, "Error: number of records must be a positive integer.\n");
        return -1;
    }

    if(num_records > MAX_SIZE / (sizeof(record))) {
        num_records = MAX_SIZE / (sizeof(record));
        printf("Warning: reduced number of records to avoid memory overflow.\n");
    }

    records = createRecords(num_records, &total_size);

    free(records); // deallocate memory

    return 0;
}
