```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure to represent a record
typedef struct {
    int timestamp;
    int value;
} Record;

// Structure to represent the data store
typedef struct {
    Record **records; // Array of records
    size_t capacity; // Maximum number of records
    size_t size; // Current number of records
    pthread_mutex_t lock; // Lock for thread-safe operations
} DataStore;

// Function to create a new data store with an initial capacity
DataStore* createStore(size_t capacity) {
    DataStore* ds = (DataStore*)malloc(sizeof(DataStore));
    ds->records = (Record**)malloc(capacity * sizeof(Record*));
    ds->capacity = capacity;
    ds->size = 0;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

// Function to insert a new key-value pair into the data store
void insertDataStore(DataStore* ds, int key, Record record) {
    pthread_mutex_lock(&ds->lock);

    if (ds->size >= ds->capacity * 0.7) { // Check for capacity utilization
        size_t newCapacity = ds->capacity * 2;
        ds->records = (Record**)realloc(ds->records, newCapacity * sizeof(Record*));
        ds->capacity = newCapacity;
    }

    Record** records = (Record**)malloc((ds->size + 1) * sizeof(Record*));
    for (int i = 0; i < ds->size; i++) {
        records[i] = ds->records[i];
    }
    free(ds->records);
    ds->records = records;

    ds->records[ds->size] = &record;
    ds->size++;

    pthread_mutex_unlock(&ds->lock);
}

// Function to remove a key-value pair from the data store
void removeDataStore(DataStore* ds, int key) {
    pthread_mutex_lock(&ds->lock);

    for (int i = 0; i < ds->size; i++) {
        if (ds->records[i]->timestamp == key) {
            Record** records = (Record**)malloc((ds->size - 1) * sizeof(Record*));
            for (int j = 0; j < i; j++) {
                records[j] = ds->records[j];
            }
            for (int j = i; j < ds->size - 1; j++) {
                records[j] = ds->records[j + 1];
            }
            free(ds->records);
            ds->records = records;
            ds->size--;
            break;
        }
    }

    pthread_mutex_unlock(&ds->lock);
}

// Function to print the contents of the data store
void printDataStore(DataStore* ds) {
    pthread_mutex_lock(&ds->lock);

    for (int i = 0; i < ds->size; i++) {
        printf("Key: %d, Timestamp: %d, Value: %d\n", i, ds->records[i]->timestamp, ds->records[i]->value);
    }

    pthread_mutex_unlock(&ds->lock);
}

// Function to release the data store and its resources
void freeDataStore(DataStore* ds) {
    pthread_mutex_lock(&ds->lock);

    for (int i = 0; i < ds->size; i++) {
        free(ds->records[i]);
    }
    free(ds->records);
    free(ds);

    pthread_mutex_unlock(&ds->lock);
}

int main() {
    DataStore* ds = createStore(10); // Create a new data store with an initial capacity of 10

    Record record1 = {1, 100};
    insertDataStore(ds, 0, record1); // Insert the first key-value pair
    Record record2 = {2, 200};
    insertDataStore(ds, 1, record2); // Insert the second key-value pair
    printDataStore(ds); // Print the contents of the data store

    removeDataStore(ds, 0); // Remove the first key-value pair
    printDataStore(ds); // Print the updated contents of the data store

    freeDataStore(ds); // Release the data store and its resources

    return 0;
}

```']

