#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* str;
    int val;
    long offset;
    int key;
} CustomStruct;

typedef struct Node {
    CustomStruct* data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* pool_head = NULL;
Node* pool_tail = NULL;

void init_pool(int size, int min_val, int max_val) {
    if (size <= 0 || min_val > max_val) return;

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        CustomStruct* data = (CustomStruct*)malloc(sizeof(CustomStruct));
        if (!data) return;

        int val = rand() % (max_val - min_val + 1) + min_val;
        char str[10];
        sprintf(str, "str-%d", i);
        data->str = strdup(str);
        data->val = val;
        data->offset = rand();
        data->key = i;

        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) return;

        node->data = data;
        node->prev = NULL;
        node->next = NULL;

        if (pool_head == NULL) pool_head = node;
        else pool_tail->next = node;
        pool_tail = node;
    }
}

CustomStruct* get_custom_struct(int key) {
    Node* curr = pool_head;
    while (curr) {
        if (curr->data->key == key) return curr->data;
        curr = curr->next;
    }
    return NULL;
}

void free_pool() {
    Node* curr = pool_head;
    while (curr) {
        Node* next = curr->next;
        free(curr->data->str);
        free(curr->data);
        free(curr);
        curr = next;
    }
    pool_head = NULL;
    pool_tail = NULL;
}

int main() {
    init_pool(10, 1, 1000);

    CustomStruct* cs = get_custom_struct(5);
    if (cs) printf("Found custom struct: %d\n", cs->val);

    free_pool();

    return 0;
}
