// Define hash table structure with chaining
typedef struct {
    Node** buckets;
    int size;
    pthread_mutex_t mutex;
} HashTable;

// Initialize and store data objects in a hash table using chaining
HashTable* init_hash_table(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = capacity;
    table->buckets = (Node**)calloc(table->size, sizeof(Node*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Compute float value for each object using string key and constant factor
float compute_value(const char* key, float factor) {
    // Implement mathematical formula here
    int key_len = strlen(key);
    float value = (key_len * 2.5f + factor) / (key_len * 1.3f + factor);
    return value;
}

// Create and store data object in hash table
void insert_data(HashTable* table, const char* key, int status) {
    pthread_mutex_lock(&table->mutex);

    int index = strlen(key) % table->size;
    Node* node = table->buckets[index];
    while (node) {
        if (!strcmp(node->obj->key, key)) {
            // Update existing object
            node->obj->status = status;
            pthread_mutex_unlock(&table->mutex);
            return;
        }
        node = node->next;
    }

    DataObject* obj = (DataObject*)malloc(sizeof(DataObject));
    obj->key = (char*)malloc(strlen(key) + 1);
    strcpy(obj->key, key);
    obj->value = compute_value(key, 0.5f);
    obj->status = status;

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->obj = obj;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->mutex);
}

// Concurrent access from multiple threads
