}

// Initialize and run concurrent threads
void run_concurrent_threads(HashTable* table) {
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Free allocated memory
void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node) {
            DataObject* obj = node->obj;
            free(obj->key);
            free(node);
            node = node->next;
        }
    }
    free(table->buckets);
    free(table);
}

