typedef struct {
    time_t timestamp;
    unsigned char* bytes;
    float value;
    void* config;
} DataStructure;

DataStructure* allocate_data_structure(size_t size) {
    DataStructure* data = (DataStructure*)malloc(sizeof(DataStructure));
    if (!data) return NULL;

    data->timestamp = time(NULL);
    data->bytes = (unsigned char*)malloc(size);
    data->value = 1.0f;
    data->config = NULL;

    return data;
}

void deallocate_data_structure(DataStructure* data) {
    if (data) {
        free(data->bytes);
        free(data);
    }
}

void manage_pool(int pool_size, int num_elements) {
    DataStructure** pool = (DataStructure**)malloc(pool_size * sizeof(DataStructure*));
    for (int i = 0; i < pool_size; i++) {
        pool[i] = allocate_data_structure(num_elements);
    }

    // Initialize the data structures
    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        unsigned char* bytes = (unsigned char*)malloc(num_elements);
        memcpy(bytes, &rand(), num_elements);
        pool[0]->bytes = bytes;
        pool[0]->value += i * 1.0f / num_elements;
    }

    // Manage the data structures
    for (int i = 0; i < pool_size; i++) {
        deallocate_data_structure(pool[i]);
    }
    free(pool);
}
