#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    struct record* prev;
    struct record* next;
} record;

record* insert(record* head, int value) {
    record* new_node = (record*)malloc(sizeof(record));
    if (!new_node) {
        return NULL; // out of memory
    }
    new_node->value = value;
    new_node->prev = NULL;
    new_node->next = head;
    if (head) {
        head->prev = &new_node;
    } else {
        new_node->prev = NULL;
    }
    head = new_node;
    return head;
}

record* delete(record* head, int value) {
    record* current = head;
    while (current && current->value != value) {
        current = current->next;
    }
    if (!current) {
        return head; // not found
    }
    if (current == head) {
        head = current->next;
    } else {
        current->prev->next = current->next;
    }
    if (current->next) {
        current->next->prev = current->prev;
    }
    free(current);
    return head;
}

void print_list(record* head) {
    record* current = head;
    while (current) {
        printf("%d ", current->value);
        current = current->next;
    }
    printf("\n");
}

record* create_linked_list(int size, int min_value, int max_value, int seed) {
    srand(seed);
    record* head = NULL;
    for (int i = 0; i < size; i++) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        head = insert(head, value);
    }
    return head;
}

void free_linked_list(record* head) {
    record* current = head;
    while (current) {
        record* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int size, min_value, max_value, seed;
    printf("Enter size: ");
    scanf("%d", &size);
    if (size <= 0) {
        return 0; // invalid size
    }
    printf("Enter minimum value: ");
    scanf("%d", &min_value);
    printf("Enter maximum value: ");
    scanf("%d", &max_value);
    printf("Enter seed: ");
    scanf("%d", &seed);

    record* head = create_linked_list(size, min_value, max_value, seed);
    print_list(head);

    free_linked_list(head);

    return 0;
}
