// Define the event types
enum EventType {TCP, UDP, HTTP, OTHER};

// Define the event structure
typedef struct {
    time_t timestamp;
    enum EventType type;
    char* metadata;
} Event;

// Define the linked list node structure
typedef struct Node {
    Event event;
    struct Node* next;
} Node;

// Define the hash table structure
typedef struct {
    int size;
    Node** buckets;
} HashTable;

// Function to initialize a new hash table with a given size
HashTable* init_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (Node**)calloc(size, sizeof(Node*));
    return table;
}

// Function to insert an event into the hash table and linked list
void insert_event(HashTable* table, Event event) {
    // Calculate the hash value for the event type
    int index = event.type % table->size;

    // Find the last node in the linked list for this event type
    Node* current = table->buckets[index];
    while (current && current->event.type == event.type) {
        current = current->next;
    }

    // Insert the new event at the end of the linked list
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->event = event;
    newNode->next = current;
    table->buckets[index] = newNode;
}

// Function to delete an event from the hash table and linked list
void delete_event(HashTable* table, Event event) {
    // Calculate the hash value for the event type
    int index = event.type % table->size;

    // Find the node containing the event in the linked list
    Node* current = table->buckets[index];
    Node* previous = NULL;
    while (current && current->event.type != event.type) {
        previous = current;
        current = current->next;
    }

    // If found, remove the node from the linked list and free its memory
    if (current) {
        if (previous) {
            previous->next = current->next;
        } else {
            table->buckets[index] = current->next;
        }
        free(current);
    }
}

// Function to retrieve an event from the hash table and linked list
Event* get_event(HashTable* table, enum EventType type) {
    // Calculate the hash value for the event type
    int index = type % table->size;

    // Find the node containing the event in the linked list
    Node* current = table->buckets[index];
    while (current && current->event.type != type) {
        current = current->next;
    }

    // If found, return a pointer to the event
    if (current) {
        return &current->event;
    } else {
        return NULL;
    }
}

// Function to free all allocated memory upon function exit
void cleanup(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Node* current = table->buckets[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}

