#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define a struct for record and event types
typedef struct {
    int id;
    int data;
} Record;

typedef struct {
    time_t timestamp;
    int status_code;
} Event;

// Define a struct for the doubly linked list node
typedef struct Node {
    Record record;
    struct Node* prev;
    struct Node* next;
} Node;

// Define a struct for the dynamic data store
typedef struct DataStore {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    int record_count;
    int event_count;
} DataStore;

// Function to initialize and return a new DataStore
DataStore* create_data_store() {
    DataStore* ds = (DataStore*)malloc(sizeof(DataStore));
    ds->head = NULL;
    ds->tail = NULL;
    pthread_mutex_init(&ds->mutex, NULL);
    ds->record_count = 0;
    ds->event_count = 0;
    return ds;
}

// Function to add a new record to the data store
void add_record(DataStore* ds) {
    Node* node = (Node*)malloc(sizeof(Node));
    // Initialize random value for first integer of each record
    srand(time(NULL)); // Seed with current system time
    node->record.id = rand() % 100; // Random value within range [0, 99]
    node->record.data = 10; // Second integer initialized to a constant
    node->prev = NULL;
    node->next = NULL;
    pthread_mutex_lock(&ds->mutex);
    if (ds->head == NULL) {
        ds->head = node;
        ds->tail = node;
    } else {
        node->prev = ds->tail;
        node->next = NULL;
        ds->tail->next = node;
        ds->tail = node;
    }
    ds->record_count++;
    pthread_mutex_unlock(&ds->mutex);
}

// Function to add a new event to the data store
void add_event(DataStore* ds) {
    Node* node = (Node*)malloc(sizeof(Node));
    // Initialize timestamp and status code for each event
    node->record.id = 0; // Set to zero or any other default value
    node->record.data = 10; // Second integer initialized to a constant
    node->event.timestamp = time(NULL); // Set current system time as the timestamp
    node->event.status_code = 1; // Initialize with a predefined status code
    node->prev = NULL;
    node->next = NULL;
    pthread_mutex_lock(&ds->mutex);
    if (ds->head == NULL) {
        ds->head = node;
        ds->tail = node;
    } else {
        node->prev = ds->tail;
        node->next = NULL;
        ds->tail->next = node;
        ds->tail = node;
    }
    ds->event_count++;
    pthread_mutex_unlock(&ds->mutex);
}

// Function to delete a record from the data store
void delete_record(DataStore* ds, int id) {
    Node* current = ds->head;
    while (current != NULL) {
        if (current->record.id == id) {
            if (current->prev == NULL) {
                // Record is at head of list
                ds->head = current->next;
            } else if (current->next == NULL) {
                // Record is at tail of list
                ds->tail = current->prev;
                ds->tail->next = NULL;
            } else {
                // Record is in middle of the list
                current->prev->next = current->next;
                current->next->prev = current->prev;
            }
            free(current);
            if (ds->record_count > 0) {
                ds->record_count--;
            }
            return;
        }
        current = current->next;
    }
}

// Function to delete an event from the data store
void delete_event(DataStore* ds, int timestamp) {
    Node* current = ds->head;
    while (current != NULL) {
        if (current->event.timestamp == timestamp) {
            if (current->prev == NULL) {
                // Event is at head of list
                ds->head = current->next;
            } else if (current->next == NULL) {
                // Event is at tail of list
                ds->tail = current->prev;
                ds->tail->next = NULL;
            } else {
                // Event is in middle of the list
                current->prev->next = current->next;
                current->next->prev = current->prev;
            }
            free(current);
            if (ds->event_count > 0) {
                ds->event_count--;
            }
            return;
        }
        current = current->next;
    }
}

// Function to perform batch processing of records and events
void batch_process(DataStore* ds, int num_records, int num_events) {
    for (int i = 0; i < num_records; i++) {
        add_record(ds);
    }
    for (int i = 0; i < num_events; i++) {
        add_event(ds);
    }
}

// Function to print the data store contents
void print_data_store(DataStore* ds) {
    Node* current = ds->head;
    while (current != NULL) {
        if (current->record.id > 0) { // Print only records with non-zero IDs
            printf("Record ID: %d, Data: %d\n", current->record.id, current->record.data);
        } else { // Print event information
            printf("Event Timestamp: %ld, Status Code: %d\n", (long)current->event.timestamp, current->event.status_code);
        }
        current = current->next;
    }
}

// Function to destroy the data store and free allocated memory
void destroy_data_store(DataStore* ds) {
    Node* current = ds->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&ds->mutex);
}

int main() {
    DataStore* ds = create_data_store();
    // Perform batch operations, add records and events
    batch_process(ds, 5, 3);

    // Print the data store contents
    print_data_store(ds);

    // Destroy the data store
    destroy_data_store(ds);

    return 0;
}

