#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the metadata flag structure
typedef enum {
    FLAG_NORMAL,
    FLAG_DELETED
} record_metadata_t;

// Define the 'record' structure
typedef struct {
    long offset;
    int key;
    int value;
    time_t timestamp;
    record_metadata_t flag;
} record_t;

// Define the custom hash table node structure
typedef struct {
    int key;
    record_t* record;
    struct {
        struct hash_node* next;
        struct hash_node* prev;
    } links;
} hash_node_t;

// Define the custom hash table structure
typedef struct {
    unsigned int size;
    hash_node_t** buckets;
    pthread_mutex_t lock;
} hash_table_t;

// Initialize the hash table
hash_table_t* hash_table_init(unsigned int initial_size) {
    hash_table_t* table = malloc(sizeof(hash_table_t));
    table->size = initial_size;
    table->buckets = malloc(table->size * sizeof(hash_node_t*));
    for (unsigned int i = 0; i < table->size; i++) {
        table->buckets[i] = NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Insert a record into the hash table
void hash_table_insert(hash_table_t* table, int key, record_t* record) {
    unsigned int index = key % table->size;
    hash_node_t* node = malloc(sizeof(hash_node_t));
    node->key = key;
    node->record = record;
    node->links.next = NULL;
    node->links.prev = NULL;

    if (table->buckets[index] == NULL) {
        table->buckets[index] = node;
    } else {
        hash_node_t* current = table->buckets[index];
        while (current != NULL && current->key < key) {
            current = current->links.next;
        }
        node->links.next = current;
        if (current != NULL) {
            current->links.prev = &node->links;
        } else {
            table->buckets[index] = node;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

// Delete a record from the hash table
void hash_table_delete(hash_table_t* table, int key) {
    unsigned int index = key % table->size;
    hash_node_t* current = table->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            if (current->links.next != NULL) {
                current->links.prev->links.next = current->links.next;
                if (current->links.next != NULL) {
                    current->links.next->links.prev = &current->links.prev->links;
                } else {
                    table->buckets[index] = current->links.next;
                }
            } else {
                table->buckets[index] = current->links.next;
            }
            free(current);
            pthread_mutex_unlock(&table->lock);
            return;
        }
        current = current->links.next;
    }
}

// Define the doubly linked list node structure
typedef struct {
    record_t* record;
    struct {
        struct node* next;
        struct node* prev;
    } links;
} node_t;

// Initialize the doubly linked list
node_t* list_init() {
    return NULL;
}

// Insert a record into the doubly linked list
void list_insert(node_t** head, record_t* record) {
    node_t* new_node = malloc(sizeof(node_t));
    new_node->record = record;
    new_node->links.next = *head;
    if (*head != NULL) {
        (*head)->links.prev = &new_node->links;
    }
    *head = new_node;
}

// Delete a record from the doubly linked list
void list_delete(node_t** head, record_t* record) {
    node_t* current = *head;
    while (current != NULL) {
        if (current->record == record) {
            if (current->links.next != NULL) {
                current->links.prev->links.next = current->links.next;
                if (current->links.next != NULL) {
                    current->links.next->links.prev = &current->links.prev->links;
                } else {
                    *head = current->links.next;
                }
            } else {
                *head = current->links.next;
            }
            free(current);
            return;
        }
        current = current->links.next;
    }
}

// Define the data store structure
typedef struct {
    hash_table_t* hash_table;
    node_t* record_list_head;
} data_store_t;

// Initialize the data store
data_store_t* data_store_init(unsigned int initial_hash_table_size) {
    data_store_t* store = malloc(sizeof(data_store_t));
    store->hash_table = hash_table_init(initial_hash_table_size);
    store->record_list_head = list_init();
    return store;
}

// Insert a record into the data store
void data_store_insert(data_store_t* store, int key, record_t* record) {
    hash_table_insert(store->hash_table, key, record);
    list_insert(&store->record_list_head, record);
}

// Delete a record from the data store
void data_store_delete(data_store_t* store, int key) {
    hash_table_delete(store->hash_table, key);
    list_delete(&store->record_list_head, NULL);
}

// Define the persistence interface structure
typedef struct {
    int interval;
    void (*persist)(data_store_t*, time_t);
} persistence_interface_t;

// Initialize the persistence interface
persistence_interface_t* persistence_init(int interval) {
    return malloc(sizeof(persistence_interface_t));
}

