typedef struct {
    float value;
    char name[20];
    void* ptr;
} ComplexData;

ComplexData** hashTable = NULL;

int initHashTable(int size) {
    if (size <= 0) return -1; // validate size
    hashTable = (ComplexData**)malloc(size * sizeof(ComplexData*));
    for (int i = 0; i < size; i++) {
        hashTable[i] = NULL;
    }
    return 0;
}

void freeHashTable() {
    if (hashTable) {
        for (int i = 0; i < sizeof(hashTable)/sizeof(ComplexData*); i++) {
            ComplexData* data = hashTable[i];
            while (data) {
                void* ptr = data->ptr;
                free(ptr);
                ComplexData* next = data->next;
                free(data);
                data = next;
            }
        }
        free(hashTable);
    }
}

int addData(ComplexData* data) {
    int hash = 0;
    char* str = data->name;
    while (*str) {
        hash += *str;
        str++;
    }
    int index = hash % sizeof(hashTable)/sizeof(ComplexData*);
    if (!hashTable[index]) {
        hashTable[index] = (ComplexData*)malloc(sizeof(ComplexData));
        hashTable[index]->next = NULL;
    } else {
        ComplexData* current = hashTable[index];
        while (current->next) {
            current = current->next;
        }
        current->next = (ComplexData*)malloc(sizeof(ComplexData));
        current->next->next = NULL;
    }
    return 0;
}

int main() {
    srand(time(NULL)); // seed random number generator
    int size = 10; // initialize with a specified number of objects
    if (initHashTable(size) < 0) {
        printf("Error: Invalid size\n");
        return -1;
    }
    for (int i = 0; i < size; i++) {
        ComplexData* data = (ComplexData*)malloc(sizeof(ComplexData));
        data->value = (float)(rand() / (double)RAND_MAX);
        strcpy(data->name, "Object_"); // initialize char array with a unique string
        addData(data);
    }
    // usage example:
    // printf("%f %s\n", hashTable[index]->data.value, hashTable[index]->data.name);

    freeHashTable();
    return 0;
}
