// Initialize the memory pool with a given size
void* init_memory_pool(size_t size) {
    void* pool = malloc(size);
    if (!pool) {
        return NULL;
    }
    memset(pool, 0, size);
    return pool;
}

// Allocate memory from the pool and initialize it
void* alloc_from_pool(size_t size) {
    void* ptr = malloc(size);
    if (ptr) {
        bzero(ptr, size);
    }
    return ptr;
}

