    for (int i = 0; i < count; i++) {
        record* new_rec = (record*)alloc_from_pool(sizeof(record));
        if (!new_rec) {
            return NULL;
        }
        new_rec->id = rand() % 100; // Set a random ID
        if (!head) {
            head = new_rec;
        } else {
            record* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_rec;
        }
    }
    return head;
}

