void insertRecord(record* record, struct node** head_ref, struct node** tail_ref) {
    // Create a new node with the given record
    struct node* newNode = (struct node*)malloc(sizeof(struct node));
    newNode->data = *record;
    newNode->prev = NULL;
    newNode->next = NULL;

    // If the list is empty, set both head and tail to the new node
    if (*head_ref == NULL) {
        *head_ref = newNode;
        *tail_ref = newNode;
    } else {
        (*tail_ref)->next = newNode;
        newNode->prev = *tail_ref;
        *tail_ref = newNode;
    }
}

// Function to remove a record from the doubly linked list
void removeRecord(record* record, struct node** head_ref, struct node** tail_ref) {
    // Find the record in the list
    struct node* current = *head_ref;
    while (current != NULL && current->data != *record) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Record not found!\n");
        return;
    }

    // Remove the record from the list
    if (current == *head_ref) {
        *head_ref = current->next;
    } else {
        current->prev->next = current->next;
    }
    if (current == *tail_ref) {
        *tail_ref = current->prev;
    } else {
        current->next->prev = current->prev;
    }

    free(current);
}

// Function to update a record in the doubly linked list
void updateRecord(record* oldRecord, record* newRecord, struct node** head_ref, struct node** tail_ref) {
