hashmap* create_hash_map(uint32_t max_capacity) {
    hashmap* h = (hashmap*)malloc(sizeof(hashmap));
    if (!h) return NULL;

    h->capacity = max_capacity;
    h->size = 0;
    h->keys = (int*)malloc(sizeof(int) * max_capacity);
    h->offsets = (long*)malloc(sizeof(long) * max_capacity);
    h->records = (record**)malloc(sizeof(record*) * max_capacity);

    pthread_mutex_init(&h->lock, NULL);

    return h;
}

void free_hash_map(hashmap* h) {
    if (!h) return;

    pthread_mutex_unlock(&h->lock);

    free(h->keys);
    free(h->offsets);
    for (uint32_t i = 0; i < h->capacity; i++) {
        free(h->records[i]);
    }
    free(h->records);
    free(h);
}

