// Node structure containing double value, char array of variable length, and next node reference
typedef struct {
    double value;
    char* data;
    struct Node* next;
} Node;

// Custom memory pool for efficient allocation
void* custom_malloc(size_t size) {
    // Implement your custom memory pool logic here
    return malloc(size);
}

// Linked list iterator supporting traversal in both forward and reverse directions
typedef struct {
    Node* current;
    int direction; // 0: forward, 1: backward
} Iterator;

// Function to initialize and maintain the linked list
void* manage_dynamic_list() {
    Node* head = NULL;
    int size = 0;
    int capacity = 10; // initial capacity

    // Custom memory pool for node allocation
    void* (*malloc_func)(size_t) = custom_malloc;

    // Function to dynamically allocate and initialize nodes
    Node* create_node(double value, char* data) {
        Node* node = (Node*) malloc_func(sizeof(Node));
        node->value = value;
        node->data = (char*) malloc_func(strlen(data) + 1);
        strcpy(node->data, data);
        node->next = NULL;
        return node;
    }

    // Function to append a new node at the end of the list
    void append(Node** head_ref, double value, char* data) {
        Node* node = create_node(value, data);

        if (*head_ref == NULL || (*head_ref)->value < value) {
            node->next = *head_ref;
            *head_ref = node;
        } else {
            Node* current = *head_ref;
            while (current->next && current->next->value >= value)
                current = current->next;

            node->next = current->next;
            current->next = node;
        }
    }

    // Function to remove a node from the list
    void remove(Node** head_ref, double value) {
        if (*head_ref == NULL || (*head_ref)->value != value)
            return;

        Node* temp = *head_ref;
        *head_ref = (*head_ref)->next;
        free(temp);
    }

    // Function to iterate over the linked list
    Iterator create_iterator(Node* head, int direction) {
        Iterator it;
        it.current = head;
        it.direction = direction;
        return it;
    }

    // Forward iteration function
    void forward_iterate(Iterator* it) {
        if (it->direction == 0) {
            while (it->current != NULL && it->current->next != NULL)
                it->current = it->current->next;
        } else {
            Node* current = it->current;
            while (current != NULL && current->next != NULL)
                current = current->next;

            if (current == NULL) {
                it->direction = 1;
                it->current = head;
            }
        }
    }

    // Reverse iteration function
    void reverse_iterate(Iterator* it) {
        if (it->direction == 1) {
            Node* current = it->current;
            while (current != NULL && current->next != NULL)
                current = current->next;

            if (current == NULL) {
                it->direction = 0;
                it->current = head;
            }
        } else {
            while (it->current != NULL && it->current->next != NULL)
                it->current = it->current->next;
        }
    }

    // Cleanup function to release allocated resources
    void cleanup(Node* head) {
        Node* current = head;
        while (current != NULL) {
            Node* next = current->next;
            free(current->data);
            free(current);
            current = next;
        }
    }

    return &head; // or return the iterator if you prefer
}
