    table->bucket_count = initial_bucket_count;
    table->entry_count = 0;
    table->load_factor = 0.5; // default load factor
    table->buckets = (Entry**)calloc(table->bucket_count, sizeof(Entry*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

size_t hash_function(const char *key) {
    size_t result = 0;
    for (const char *p = key; *p != '\0'; p++) {
        result = (result << 5) + *p;
    }
    return result % 1024; // adjust the size based on your requirements
}

void hash_table_insert(HashTable* table, const char *key, Value value) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key);
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->key = strdup(key);
    entry->value = value;
    if (table->buckets[index] == NULL) {
        table->buckets[index] = entry;
    } else {
        // handle collision
    }
    table->entry_count++;
    pthread_mutex_unlock(&table->mutex);
}

