long randLong(int min, int max) {
    return (long) (min + (double)(max-min)*rand()/(RAND_MAX+1.0));
}

// Function to initialize and manage record array
void initRecordArray(long size, Record** records) {
    // Initialize arrays for metadata and expiry flags
    Metadata* metadata = malloc(size * sizeof(Metadata));
    unsigned char* expiryFlags = malloc(size * sizeof(unsigned char));

    // Initialize pseudo-random number generator
    srand(time(NULL));

    // Iterate through each record to generate random value and timestamp
    for (long i = 0; i < size; i++) {
        Record* record = malloc(sizeof(Record));
        record->key = randLong(1, 100);
        record->value = randLong(1, 100);
        record->timestamp = time(NULL);
        Metadata metadataTmp;
        // Initialize metadata attributes
        metadataTmp.attr1 = randLong(1, 100);
        metadataTmp.attr2 = malloc(randLong(1, 10) * sizeof(char));
        for (int j = 0; j < randLong(1, 10); j++) {
            metadataTmp.attr2[j] = 'a' + rand() % 26;
        }
        record->metadata = metadataTmp;
        // Initialize expiry flag to not expired
        record->expiry_flag = 0;

        // Update linked list and metadata arrays
        record->prev = NULL;
        record->next = records[i];
        if (i > 0) {
            records[i-1]->next = record;
        } else {
            *records = record;
        }
        metadata[i] = metadataTmp;
        expiryFlags[i] = 0;
    }

    // Free allocated memory
    free(metadata);
    free(expiryFlags);
}

int main() {
    long size;
    Record* records;

    printf("Enter the number of records: ");
    scanf("%ld", &size);

    initRecordArray(size, &records);

    return 0;
