    int reference_count;
} Record;

typedef struct metadata {
    // add fields as needed
} Metadata;

typedef struct dependency {
    // add fields as needed
} Dependency;

// Thread-safe doubly linked list node
typedef struct node {
    Record *record;
    struct node *prev, *next;
} Node;

Record **records = NULL;
Node *head = NULL, *tail = NULL;
int record_count = 0;

void init_records(int size) {
    int i;
    srand(time(NULL));
    records = (Record **)malloc(size * sizeof(Record *));
    for (i = 0; i < size; i++) {
        Record *record = (Record *)malloc(sizeof(Record));
        record->value = rand() % 100 + 1;
        record->timestamp = time(NULL);
        record->reference_count = 1;
        records[i] = record;
    }
}

void insert_record(int value, int timestamp) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->record = (Record *)malloc(sizeof(Record));
    new_node->record->value = value;
    new_node->record->timestamp = timestamp;
    new_node->record->reference_count = 1;
    if (head == NULL) {
        head = new_node;
        tail = new_node;
    } else {
        Node *prev_node = head;
        while (prev_node->next != NULL && prev_node->next->record->value < value)
            prev_node = prev_node->next;
        new_node->prev = prev_node;
        if (prev_node == tail) {
            tail = new_node;
        } else {
            new_node->next = prev_node->next;
            prev_node->next = new_node;
        }
    }
}

void delete_record(Record *record) {
    Node *node = head;
    while (node != NULL && node->record != record)
        node = node->next;
    if (node == NULL)
        return; // not found
    if (node->prev != NULL)
        node->prev->next = node->next;
    else
        head = node->next;
    if (node->next != NULL)
        node->next->prev = node->prev;
    else
        tail = node->prev;
    free(record);
}

void validate_records() {
    Node *node = head;
    while (node != NULL) {
        Record *record = node->record;
        if (record->reference_count < 1)
            printf("Invalid record reference count: %d\n", record->reference_count);
        node = node->next;
    }
}

int main() {
    // Initialize the records
    init_records(5);

    // Insert a new record
    insert_record(50, time(NULL));

    // Delete an existing record
    delete_record(records[0]);

    // Validate the records
    validate_records();

    return 0;
}
