void generate_and_populate_records(long numOffsets, long numRecords, long minOffset, long maxOffset, const char *filename) {
    // Custom random number generator
    long random_in_range(long min, long max) {
        if (min > max) return 0;
        return min + rand() % (max - min + 1);
    }

    int key = 0;
    long offset = 0;

    // Initialize the file name
    char base_name[255], ext[5];
    sscanf(filename, "%[^.].%s", base_name, ext);

