    record_t *offsets = (record_t *)malloc(numOffsets * sizeof(record_t));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets.\n");
        exit(1);
    }

    record_t *keys = (record_t *)malloc(numOffsets * sizeof(record_t));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        free(offsets);
        exit(1);
    }

    // Initialize the offsets and keys arrays
    for (int i = 0; i < numOffsets; i++) {
        offset = random_in_range(minOffset, maxOffset);
        key = rand() % 100; // Generate a random key between 0 and 99

        offsets[i].offset = offset;
        offsets[i].key = key;

        keys[i] = offsets[i];
    }

    record_t *records = (record_t *)malloc(numRecords * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    // Populate the records array
    for (int i = 0; i < numRecords; i++) {
        offset = random_in_range(minOffset, maxOffset);
        key = rand() % 100;

        records[i].offset = offset;
        records[i].key = key;
    }

    free(offsets);
    free(keys);

    // Modify the file name and create a new file
