#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} log_level;

typedef struct {
    int i;
    float f;
    char c;
    bool b;
} data_unit;

typedef struct {
    time_t timestamp;
    log_level level;
    char* message;
} log_entry;

void process_records(int num_records) {
    // Allocate memory for the data structures
    data_unit** data_units = (data_unit**)malloc(num_records * sizeof(data_unit*));
    log_entry** log_entries = (log_entry**)malloc(num_records * sizeof(log_entry*));

    // Initialize the data units and log entries
    for (int i = 0; i < num_records; i++) {
        data_units[i] = (data_unit*)malloc(sizeof(data_unit));
        log_entries[i] = (log_entry*)malloc(sizeof(log_entry));

        // Initialize the data unit fields
        data_units[i]->i = i;
        data_units[i]->f = (float)i;
        data_units[i]->c = (char)(i % 256);
        data_units[i]->b = i % 2 == 0;

        // Initialize the log entry fields
        log_entries[i]->timestamp = time(NULL);
        log_entries[i]->level = i % 4;
        log_entries[i]->message = malloc(strlen("Record ") + strlen(itoa(i)) + 1);
        sprintf(log_entries[i]->message, "Record %d", i);

        // Process the record
        printf("Processing record %d...\n", i);
    }

    // Free the memory
    for (int i = 0; i < num_records; i++) {
        free(data_units[i]);
        free(log_entries[i]->message);
        free(log_entries[i]);
    }
    free(data_units);
    free(log_entries);

    printf("Records processed successfully.\n");
}

int main() {
    int num_records;
    printf("Enter the number of records to process: ");
    scanf("%d", &num_records);

    process_records(num_records);

    return 0;
}
