#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <random>
#include "third_party_logging_library.h"

// Define a structure to represent a data_unit
typedef struct {
    int integer_field;
    float float_field;
    char character_field;
} data_unit;

// Function to dynamically manage an array of data_units
void* DynamicDataManager(int size, bool async) {
    // Allocate memory for the array of data_units
    data_unit* units = (data_unit*) malloc(size * sizeof(data_unit));

    if (!units) {
        LOG_ERROR("Memory allocation failed");
        return NULL;
    }

    if (async) {
        // Initialize each data_unit with random values within specified ranges
        std::random_device rd;
        std::mt19937 mt(rd());
        std::uniform_int_distribution<int> int_dist(0, 100);
        std::uniform_real_distribution<float> float_dist(0.0f, 1.0f);

        for (int i = 0; i < size; i++) {
            units[i].integer_field = int_dist(mt);
            units[i].float_field = float_dist(mt);
            units[i].character_field = 'a' + rand() % 26;
        }
    }

    return (void*) units;
}

// Function to deallocate the array of data_units
void FreeDataUnits(void* ptr) {
    if (!ptr) {
        LOG_ERROR("Invalid pointer");
        return;
    }

    free(ptr);
}
