#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
} record_t;

record_t* create_records(int count, size_t max_memory) {
    if (count <= 0 || max_memory <= 0) return NULL;

    // Calculate the total memory required
    size_t total_memory = sizeof(record_t) * count + sizeof(int) * count;

    // Check against maximum allowed memory
    if (total_memory > max_memory) {
        printf("Error: Memory exceeds limit.\n");
        return NULL;
    }

    record_t* records = (record_t*)malloc(total_memory);
    if (!records) {
        printf("Error: Out of memory.\n");
        return NULL;
    }

    // Initialize the records
    for (int i = 0; i < count; i++) {
        records[i].key = rand() % 100;
    }

    return records;
}

void print_records(record_t* records, int count) {
    printf("Records:\n");
    for (int i = 0; i < count; i++) {
        printf("%d\n", records[i].key);
    }
}
