    int num_records = 1000;
    int max_memory = 1024 * 1024; // 1MB
    int key_array_size = 100;
    int offset_array_size = 100;

    record_t** records = (record_t**)my_malloc(num_records * sizeof(record_t*));
    for (int i = 0; i < num_records; i++) {
        records[i] = (record_t*)my_malloc(sizeof(record_t));
    }

    int* keys = (int*)my_malloc(key_array_size * sizeof(int));
    long* offsets = (long*)my_malloc(offset_array_size * sizeof(long));

    // Initialize arrays
    for (int i = 0; i < key_array_size; i++) {
        keys[i] = i;
    }
    for (int i = 0; i < offset_array_size; i++) {
        offsets[i] = i * 100000L;
    }

    // Generate random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i]->key = rand() % key_array_size;
        records[i]->offset = rand() % offset_array_size * 100000L;
    }

    // Log memory usage and errors
    printf("Memory used: %zu bytes\n", sizeof(record_t) * num_records);
    if (rand() % 2 == 0) {
        printf("Error occurred during allocation!\n");
    } else {
        printf("Allocation successful.\n");
    }

    // Clean up
    for (int i = 0; i < num_records; i++) {
        my_free(records[i]);
    }
    my_free(keys);
    my_free(offsets);

    return 0;
}
