    srand(t);

    for (int i = 0; i < num_records; i++) {
        records[i].key = rand();
    }
}

// Function to initialize and validate memory allocation for arrays
void init_memory_arrays(long** offset_values, int* keys, int num_records) {
    // Calculate required size for each array based on num_records
    long offset_values_size = sizeof(long) * (num_records + 1);
    int keys_size = sizeof(int) * (num_records);

    // Allocate memory for arrays using validated allocation sizes
    *offset_values = (long*)malloc(offset_values_size);
    *keys = (int*)malloc(keys_size);

    if (*offset_values == NULL || *keys == NULL) {
        printf("Memory allocation failed!\n");
    }
}

// Function to implement adaptive memory allocation strategies for 'record' structures
void init_record_array(record_t** records, int num_records) {
    // Calculate required size for record array based on num_records
    int record_size = sizeof(record_t) * (num_records);

    // Allocate memory for record array using validated allocation size
    *records = (record_t*)malloc(record_size);

    if (*records == NULL) {
        printf("Memory allocation failed!\n");
    }
}

